/**
 * Gym zone mastery: 10 route trainers + arena champion badge.
 */

import {
    ARENAS,
    ZONE_ID_TO_ARENA_ID,
} from '../../constants/balance/arenasTrainers.ts';
import type { GameRuntime } from '../types/game.js';

type ArenaEntry = { badge?: string; requiredBadge?: string; requiredZone?: number; [key: string]: unknown };

function getGymZoneProgress(game: GameRuntime, zoneId: number): { trainersDefeated?: number } | undefined {
    const progress = game.zoneProgress;
    if (!progress) return undefined;
    return progress[zoneId] ?? progress[String(zoneId)];
}

function getGymArenaBadgeKey(zoneId: number): string | null {
    const arenaId = ZONE_ID_TO_ARENA_ID[zoneId];
    if (arenaId == null) return null;
    const arena = (ARENAS as Record<string, ArenaEntry>)[String(arenaId)];
    return arena?.badge ? String(arena.badge) : null;
}

function hasGameBadge(game: GameRuntime, badgeKey: string): boolean {
    return (typeof game.hasBadge === 'function')
        ? game.hasBadge(badgeKey)
        : !!(game.badges && game.badges[badgeKey] === true);
}

/** Gym zone id linked to an arena (inverse of ZONE_ID_TO_ARENA_ID). */
export function getGymZoneIdForArenaId(arenaId: string | number): number | null {
    const targetArenaId = Number(arenaId);
    if (!Number.isFinite(targetArenaId)) return null;
    const entry = Object.entries(ZONE_ID_TO_ARENA_ID).find(([, aId]) => Number(aId) === targetArenaId);
    return entry ? Number(entry[0]) : null;
}

/** Route phase complete: 10 gym trainers defeated (champion not required). */
export function isGymRouteCompleteLogic(game: GameRuntime, zoneId: number): boolean {
    const gymProgress = getGymZoneProgress(game, zoneId);
    return (Number(gymProgress?.trainersDefeated) || 0) >= 10;
}

/**
 * Arena requiredZone gate. When requiredZone is the arena's own gym hub (Kalos/Alola),
 * only the route (10 trainers) is required — not full mastery with champion badge.
 */
export function meetsArenaRequiredZoneGate(
    game: GameRuntime,
    arenaId: string | number,
    requiredZone: number,
    isZoneMastered: (zoneId: number) => boolean,
): boolean {
    const gymZoneId = getGymZoneIdForArenaId(arenaId);
    if (gymZoneId != null && requiredZone === gymZoneId) {
        return isGymRouteCompleteLogic(game, requiredZone);
    }
    return isZoneMastered(requiredZone);
}

/** Gym route mastery: 10 trainers defeated and arena champion badge earned. */
export function isGymZoneMasteredLogic(game: GameRuntime, zoneId: number): boolean {
    if (!isGymRouteCompleteLogic(game, zoneId)) return false;
    const badgeKey = getGymArenaBadgeKey(zoneId);
    if (!badgeKey) return false;
    return hasGameBadge(game, badgeKey);
}

/** Whether the player has the arena champion badge for a gym zone. */
export function hasGymChampionBadgeForZoneLogic(game: GameRuntime, zoneId: number): boolean {
    const badgeKey = getGymArenaBadgeKey(zoneId);
    if (!badgeKey) return false;
    return hasGameBadge(game, badgeKey);
}

/** Champion fight is available (route done + arena unlock gates met). */
export function isGymChampionAccessibleForZoneLogic(
    game: GameRuntime,
    zoneId: number,
    isZoneMastered: (zoneId: number) => boolean,
): boolean {
    if (!isGymRouteCompleteLogic(game, zoneId)) return false;
    const arenaId = ZONE_ID_TO_ARENA_ID[zoneId];
    if (arenaId == null) return false;
    const arena = (ARENAS as Record<string, ArenaEntry>)[String(arenaId)];
    if (!arena) return false;
    if (arena.requiredBadge && !hasGameBadge(game, String(arena.requiredBadge))) return false;
    if (arena.requiredZone != null) {
        const reqZone = Number(arena.requiredZone);
        if (!Number.isFinite(reqZone)
            || !meetsArenaRequiredZoneGate(game, arenaId, reqZone, isZoneMastered)) {
            return false;
        }
    }
    return true;
}
