interface ZoneDef {
    name: string;
    maxTier?: number;
    isGym?: boolean;
    isFinal?: boolean;
    requiredBosses?: number;
    requiredEpics?: number;
}

const ZONES_MAP = ZONES as Record<number, ZoneDef>;

const ZONE_RADAR_BADGE_IMG = 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/silph-scope.png';

function resolveAdjacentAreaButtonState(
    game: GameRuntime,
    adjacentZoneId: number | null,
): { zoneId: number | null; enabled: boolean } {
    if (adjacentZoneId == null) return { zoneId: null, enabled: false };
    const enabled = typeof game.isZoneUnlocked === 'function' && game.isZoneUnlocked(adjacentZoneId, true);
    return { zoneId: adjacentZoneId, enabled };
}

function resolvePreviousAreaButtonState(
    game: GameRuntime,
    currentZone: number,
): { zoneId: number | null; enabled: boolean } {
    return resolveAdjacentAreaButtonState(game, _getPreviousAreaZoneIdInRegion(currentZone));
}

function resolveNextAreaButtonState(
    game: GameRuntime,
    currentZone: number,
): { zoneId: number | null; enabled: boolean } {
    return resolveAdjacentAreaButtonState(game, getNextProgressionZoneInRegionLogic(game, currentZone));
}

function renderAdjacentAreaButton(
    game: GameRuntime,
    action: 'goToPreviousZone' | 'goToNextZone',
    i18nKey: string,
    fallback: string,
    state: { zoneId: number | null; enabled: boolean },
): string {
    const { zoneId, enabled } = state;
    const disabledAttr = enabled ? '' : ' disabled';
    const dataArg = zoneId != null ? ` data-arg="${zoneId}"` : '';
    return `<button class="zone-details-btn" data-action="${action}"${dataArg}${disabledAttr}>${uiText(i18nKey, fallback, undefined, game)}</button>`;
}

function renderPreviousAreaButton(game: GameRuntime, currentZone: number): string {
    return renderAdjacentAreaButton(
        game,
        'goToPreviousZone',
        'zone.previousAreaButton',
        'Previous area',
        resolvePreviousAreaButtonState(game, currentZone),
    );
}

function renderNextAreaButton(game: GameRuntime, currentZone: number): string {
    return renderAdjacentAreaButton(
        game,
        'goToNextZone',
        'zone.nextAreaButton',
        'Next area',
        resolveNextAreaButtonState(game, currentZone),
    );
}

function renderAcademyCoursesButton(game: GameRuntime, currentZone: number): string {
    if (currentZone !== 805 && currentZone !== 862) return '';
    if (currentZone === 862 && typeof game.isAcademyAdvancedHubUnlocked === 'function' && !game.isAcademyAdvancedHubUnlocked()) {
        return '';
    }
    return `<button class="zone-details-btn" data-action="openAcademyCoursesModal">${uiText('zone.academyCoursesButton', 'Academy Courses', undefined, game)}</button>`;
}

function resolveZoneRuntime(
    gameRef?: GameRuntime | null,
    zoneIdRef?: number | null,
): { game: GameRuntime | null; currentZone: number } {
    const game = gameRef != null ? gameRef : null;
    const currentZone = zoneIdRef != null
        ? zoneIdRef
        : (game && game.currentZone != null
            ? game.currentZone
            : moduleCurrentZone);
    return { game, currentZone };
}

/** Espèces comptées dans X/Y maîtrise zone (aligné sur getProgressionMasteryPokemonInZoneLogic ; hors légendaires naturels). */
export function speciesNamesForZoneMasteryCount(game: GameRuntime, zoneId: number): string[] {
    const all = getProgressionMasteryPokemonInZoneLogic(game, zoneId);
    if (!all || !all.length) return [];
    const leg = RARITY.LEGENDARY ?? 'legendary';
    const nonLeg = all.filter(name => typeof game.getNaturalRarity === 'function' && game.getNaturalRarity(name) !== leg);
    return nonLeg.length ? nonLeg : all.slice();
}

function buildGymMasteryObjectivesHtml(
    game: GameRuntime,
    zoneId: number,
    progress: { trainersDefeated?: number },
): string {
    const trainersDefeated = progress.trainersDefeated || 0;
    const trainersComplete = trainersDefeated >= 10;
    const championComplete = hasGymChampionBadgeForZoneLogic(game, zoneId);
    const championLabel = uiText('zone.championLabel', 'Champion:', undefined, game).replace(/:$/, '');
    return `
        <div class="zone-objective" style="flex: 1; min-width: 150px;">
            <span class="zone-objective-label">${uiText('zone.trainersLabel', 'Dresseurs', undefined, game)}</span>
            <span class="zone-objective-progress ${trainersComplete ? '' : 'incomplete'}">
                ${trainersDefeated}/10
            </span>
        </div>
        <div class="zone-objective" style="flex: 1; min-width: 150px;">
            <span class="zone-objective-label">${championLabel}</span>
            <span class="zone-objective-progress ${championComplete ? '' : 'incomplete'}">
                ${championComplete ? '1/1' : '0/1'}
            </span>
        </div>`;
}

export function formatLegendaryCooldownClock(ms: number): string {
    if (ms <= 0) return '';
    const s = Math.ceil(ms / 1000);
    const m = Math.floor(s / 60);
    const r = s % 60;
    return m + ':' + (r < 10 ? '0' : '') + r;
}

/**
 * @param {unknown} [gameRef]
 */
export function refreshZoneTierModalLegendaryCooldowns(gameRef?: GameRuntime | null): void {
    const grid = document.getElementById('zoneTierModalGrid');
    const { game } = resolveZoneRuntime(gameRef, undefined);
    if (!grid || !game) return;
    grid.querySelectorAll('[data-zone-tier-cd]').forEach(el => {
        const name = el.getAttribute('data-zone-tier-cd');
        if (!name) return;
        const until = Number(game.legendaryWildCooldownUntil?.[name]);
        const rem = Number.isFinite(until) ? Math.max(0, until - Date.now()) : 0;
        el.textContent = rem > 0
            ? uiText('zone.legendaryCooldown', 'Wild respawn: {time}', { time: formatLegendaryCooldownClock(rem) }, game)
            : '';
        const card = el.closest('.creature-card') as HTMLElement | null;
        if (card) card.style.opacity = rem > 0 ? '0.55' : '';
    });
}

