/**
 * Met à jour l'affichage des infos de zone (maîtrise, mode tour, etc.)
 * @param {unknown} [gameRef]
 * @param {number} [zoneIdRef] — si omis, utilise game.currentZone ou globalThis.currentZone
 */
export function updateZoneInfo(
    gameRef?: import('../types/game.js').GameRuntime | null,
    zoneIdRef?: number | null,
): void {
    const zoneSelectorDiv = document.querySelector('.zone-selector');
    const zoneInfoDiv = document.getElementById('zoneInfo');
    if (!zoneSelectorDiv || !zoneInfoDiv) return;

    const { game, currentZone } = resolveZoneRuntime(gameRef, zoneIdRef);

    // --- MODE SUBWAY ---
    if (game && game.subwayState && game.subwayState.isActive) {
        if (zoneSelectorDiv.classList.contains('tower-mode')) {
            zoneSelectorDiv.classList.remove('tower-mode');
        }
        const subwayText = formatSubwayZoneLabel(game);
        zoneInfoDiv.innerHTML = subwayText;
        if (game) game.currentZoneName = subwayText;
        return;
    }

    // --- MODE CHAMPIONS TOWER ---
    if (game && game.championsTowerState && game.championsTowerState.isActive) {
        zoneSelectorDiv.classList.add('tower-mode');
        const label = typeof game.getChampionsTowerProgressLabel === 'function'
            ? game.getChampionsTowerProgressLabel()
            : uiText('champions.title', 'Champions Tower', undefined, game);
        zoneInfoDiv.innerHTML = label;
        if (game) game.currentZoneName = label;
        return;
    }

    // --- MODE TOUR ---
    if (game && game.towerState && game.towerState.isActive) {
        zoneSelectorDiv.classList.add('tower-mode');
        const floor = game.towerState.currentFloor;
        const towerBossEvery = BALANCE.TOWER_ENEMY ? BALANCE.TOWER_ENEMY.BOSS_FLOOR_INTERVAL : 10;
        let floorText = uiText('zone.towerFloor', 'BATTLE TOWER - FLOOR {floor}', { floor }, game);
        if (floor % towerBossEvery === 0) floorText = uiText('zone.towerMajorBoss', 'MAJOR BOSS - FLOOR {floor}', { floor }, game);
        else if (floor % 5 === 0) floorText = uiText('zone.towerEliteTrainer', 'ELITE TRAINER - FLOOR {floor}', { floor }, game);
        zoneInfoDiv.innerHTML = floorText;
        if (game) game.currentZoneName = floorText;
        return;
    }

    // --- MODE ZONE ---
    if (zoneSelectorDiv.classList.contains('tower-mode')) {
        zoneSelectorDiv.classList.remove('tower-mode');
    }

    const zone = ZONES_MAP[currentZone] ?? null;
    const localizedZoneName = zone
        ? ((game && typeof game.getLocalizedZoneName === 'function')
            ? game.getLocalizedZoneName(currentZone, zone.name)
            : zone.name)
        : '';
    if (game) game.currentZoneName = localizedZoneName;
    const zoneKey = String(currentZone);
    if (!game || !game.zoneProgress || !game.zoneProgress[zoneKey]) {
        if (zone && zoneInfoDiv) zoneInfoDiv.textContent = uiText('zone.currentZone', 'Current zone: {name}', { name: localizedZoneName }, game);
        return;
    }

    const progress = game.zoneProgress[zoneKey];
    if (!zone) return;
    if (isTransitHubZoneLogic(game, currentZone)) {
        const htmlTransit = `
            <div class="zone-objective">
                <div>
                    ${renderPreviousAreaButton(game, currentZone)}
                    <span class="zone-objective-label">${localizedZoneName}</span>
                    <button class="zone-details-btn" data-action="showZoneTierModal">${uiText('zone.detailsButton', 'Details', undefined, game)}</button>
                    ${renderAcademyCoursesButton(game, currentZone)}
                    ${renderNextAreaButton(game, currentZone)}
                </div>
            </div>
        `;
        if (zoneInfoDiv) zoneInfoDiv.innerHTML = htmlTransit;
        return;
    }
    const maxTier = zone.maxTier || 50;
    const tiersInZone = progress.pokemonTiers || {};

    const masterySpecies = speciesNamesForZoneMasteryCount(game, currentZone);
    const totalPokemon = masterySpecies.length;
    const pokemonAtMaxTier = masterySpecies.filter(name => getZonePokemonTier(tiersInZone, name) >= maxTier).length;

    // Zones gym : résumé dresseurs (détail dresseurs + champion dans le modal)
    if (zone && zone.isGym && !zone.isFinal) {
        const trainersDefeated = progress.trainersDefeated || 0;
        const masteryComplete = isGymZoneMasteredLogic(game, currentZone);
        const htmlGym = `
            <div class="zone-objective">
                <div>
                    ${renderPreviousAreaButton(game, currentZone)}
                    <span class="zone-objective-label">${uiText('zone.trainersLabel', 'Dresseurs', undefined, game)}</span>
                    <button class="zone-details-btn" data-action="showZoneTierModal">${uiText('zone.detailsButton', 'Details', undefined, game)}</button>
                    ${renderAcademyCoursesButton(game, currentZone)}
                    ${renderNextAreaButton(game, currentZone)}
                </div>
                <span class="zone-objective-progress ${masteryComplete ? '' : 'incomplete'}">
                    ${trainersDefeated}/10
                </span>
            </div>
        `;
        if (zoneInfoDiv) zoneInfoDiv.innerHTML = htmlGym;
        return;
    }

    let bossScore = 0, bossMax = 0;
    if ((zone.requiredBosses ?? 0) > 0) {
        bossMax = 1;
        if ((progress.bossesDefeated || 0) >= (zone.requiredBosses ?? 0)) bossScore = 1;
    }

    let epicScore = 0, epicMax = 0;
    if ((zone.requiredEpics ?? 0) > 0) {
        epicMax = 1;
        if ((progress.epicsDefeated || 0) >= (zone.requiredEpics ?? 0)) epicScore = 1;
    }

    const currentTotal = pokemonAtMaxTier + bossScore + epicScore;
    const maxTotal = totalPokemon + bossMax + epicMax;
    const masteryComplete = currentTotal >= maxTotal && maxTotal > 0;

    const html = `
        <div class="zone-objective">
            <div>
                ${renderPreviousAreaButton(game, currentZone)}
                <span class="zone-objective-label">${uiText('zone.masteryLabel', 'Mastery', undefined, game)}</span>
                <button class="zone-details-btn" data-action="showZoneTierModal">${uiText('zone.detailsButton', 'Details', undefined, game)}</button>
                ${renderNextAreaButton(game, currentZone)}
            </div>
            <span class="zone-objective-progress ${masteryComplete ? '' : 'incomplete'}">
                ${currentTotal}/${maxTotal}
            </span>
        </div>
    `;

    if (zoneInfoDiv) zoneInfoDiv.innerHTML = html;
}

/**
 * Affiche le modal de progression des tiers de zone.
 * @param {unknown} [gameRef]
 * @param {number} [zoneIdRef]
 */
export async function showZoneTierModal(
    gameRef?: import('../types/game.js').GameRuntime | null,
    zoneIdRef?: number | null,
): Promise<void> {
    const { game, currentZone } = resolveZoneRuntime(gameRef, zoneIdRef);
    if (!game) return;

    const zone = ZONES_MAP[currentZone];
    if (!zone) return;
    const pokemonInZone = game.getReachablePokemonInZone(currentZone);
    const progress = game.zoneProgress[currentZone];
    if (!progress) return;
    const tiersInZone = progress.pokemonTiers || {};
    const maxTier = zone.maxTier || 50;
    const masteryRequiredNames = speciesNamesForZoneMasteryCount(game, currentZone);
    const masteryRequiredSet = new Set(masteryRequiredNames);

    await awaitLazyModalReady('zoneTierModal');

    const modal = document.getElementById('zoneTierModal');
    const title = document.getElementById('zoneTierModalTitle');
    const grid = document.getElementById('zoneTierModalGrid');

    if (!modal || !title || !grid) {
        if (game) game.isZoneTierModalOpen = false;
        return;
    }

    const localizedZoneName = (game && typeof game.getLocalizedZoneName === 'function')
        ? game.getLocalizedZoneName(currentZone, zone.name)
        : zone.name;
    title.textContent = uiText('zone.modalProgress', 'Progress - {zone}', { zone: localizedZoneName }, game);
    grid.innerHTML = '';

    if (zone.isGym && !zone.isFinal) {
        grid.innerHTML = `<div style="grid-column: 1 / -1; display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 10px;">${buildGymMasteryObjectivesHtml(game, currentZone, progress)}</div>`;
        modal.classList.add('show');
        game.isZoneTierModalOpen = true;
        return;
    }

    let bossHTML = '';
    let epicHTML = '';

    const requiredBosses = zone.requiredBosses ?? 0;
    if (requiredBosses > 0) {
        const currentBosses = progress.bossesDefeated || 0;
        const bossComplete = currentBosses >= requiredBosses;
        bossHTML = `
            <div class="zone-objective" style="flex: 1; min-width: 150px;">
                <span class="zone-objective-label">${uiText('zone.bossLabel', 'Boss', undefined, game)}</span>
                <span class="zone-objective-progress ${bossComplete ? '' : 'incomplete'}">
                    ${currentBosses}/${requiredBosses}
                </span>
            </div>`;
    }

    const requiredEpics = zone.requiredEpics ?? 0;
    if (requiredEpics > 0) {
        const currentEpics = progress.epicsDefeated || 0;
        const epicComplete = currentEpics >= requiredEpics;
        epicHTML = `
            <div class="zone-objective" style="flex: 1; min-width: 150px;">
                <span class="zone-objective-label">${uiText('zone.epicsLabel', 'Epics', undefined, game)}</span>
                <span class="zone-objective-progress ${epicComplete ? '' : 'incomplete'}">
                    ${currentEpics}/${requiredEpics}
                </span>
            </div>`;
    }

    if (bossHTML || epicHTML) {
        grid.innerHTML = `<div style="grid-column: 1 / -1; display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 10px;">${bossHTML}${epicHTML}</div>`;
    }

    if (!pokemonInZone || pokemonInZone.length === 0) {
        if (!bossHTML && !epicHTML) grid.innerHTML = `<p>${uiText('shop.noAccessiblePokemon', 'No accessible Pokemon.', undefined, game)}</p>`;
        modal.classList.add('show');
        game.isZoneTierModalOpen = true;
        return;
    }

    const legRarity = RARITY.LEGENDARY ?? 'legendary';
    const hasZoneRadar = typeof game.getMasteryBonus === 'function' && (game.getMasteryBonus('pokedex_radar') || 0) > 0;
    const zoneRadarSelected = hasZoneRadar && typeof game.getZoneRadarTargets === 'function'
        ? new Set(game.getZoneRadarTargets())
        : new Set<string>();

    if (hasZoneRadar) {
        const hint = document.createElement('div');
        hint.className = 'zone-tier-radar-hint';
        hint.style.gridColumn = '1 / -1';
        hint.textContent = uiText(
            'zone.radarClickHint',
            'Click a Pokémon to target it on the zone radar.',
            undefined,
            game,
        );
        grid.appendChild(hint);
    }

    pokemonInZone.forEach((pokemonName: string) => {
        const displayPokemonName = uiPokemonName(game, pokemonName);
        const currentTier = getZonePokemonTier(tiersInZone, pokemonName);
        const percent = Math.min(100, (currentTier / maxTier) * 100);
        const spriteUrl = getPokemonSpriteUrl(pokemonName, false, false);
        const isMaxed = currentTier >= maxTier;
        const isLegendarySpecies = typeof game.getNaturalRarity === 'function' && game.getNaturalRarity(pokemonName) === legRarity;
        const isOptionalForZoneMastery = !masteryRequiredSet.has(pokemonName);
        const cdUntil = Number(game.legendaryWildCooldownUntil && game.legendaryWildCooldownUntil[pokemonName]);
        const cdRem = Number.isFinite(cdUntil) ? Math.max(0, cdUntil - Date.now()) : 0;
        const onLegendaryCd = isLegendarySpecies && cdRem > 0;

        const isRadarSelected = hasZoneRadar && zoneRadarSelected.has(pokemonName);

        const card = document.createElement('div');
        card.className = 'creature-card';
        if (hasZoneRadar) {
            card.classList.add('creature-card--radar-selectable');
            card.setAttribute('data-action', 'toggleZoneRadarTarget');
            card.setAttribute('data-arg', pokemonName);
            card.setAttribute('role', 'button');
            card.setAttribute('tabindex', '0');
        }
        if (onLegendaryCd) card.style.opacity = '0.55';
        if (isMaxed) {
            card.style.borderColor = "#22c55e";
            card.style.background = "#f0fdf4";
        }

        const radarBadge = isRadarSelected
            ? `<img src="${ZONE_RADAR_BADGE_IMG}" class="zone-tier-radar-badge" alt="">`
            : '';

        const noMasteryLine = isOptionalForZoneMastery
            ? `<div class="zone-tier-no-mastery">${uiText('zone.legendaryNoMastery', 'Not required for zone mastery', undefined, game)}</div>`
            : '';
        const cdLine = isLegendarySpecies
            ? `<div data-zone-tier-cd="${pokemonName}" style="font-size: 10px; color: #b45309; font-weight: bold; margin-top: 4px; min-height: 14px;">${
                onLegendaryCd
                    ? uiText('zone.legendaryCooldown', 'Wild respawn: {time}', { time: formatLegendaryCooldownClock(cdRem) }, game)
                    : ''
            }</div>`
            : '';

        card.innerHTML = `
            ${radarBadge}
            <img src="${spriteUrl}" alt="${displayPokemonName}" class="team-slot-sprite">
            <div class="team-slot-name">${displayPokemonName}</div>
            ${noMasteryLine}
            <div class="zone-tier-label${isMaxed ? ' zone-tier-label--maxed' : ''}">
                ${uiText('zone.tierLabel', 'Tier {current}/{max}', { current: currentTier, max: maxTier }, game)}
            </div>
            <div class="tier-progress-bar">
                <div class="tier-progress-fill" style="width: ${percent}%; background: ${isMaxed ? '#16a34a' : ''}"></div>
            </div>
            ${cdLine}
        `;
        grid.appendChild(card);
    });

    if (game._zoneTierModalCooldownInterval) {
        clearInterval(game._zoneTierModalCooldownInterval);
        game._zoneTierModalCooldownInterval = null;
    }
    const needsCdTick = pokemonInZone.some((n: string) => typeof game.getNaturalRarity === 'function' && game.getNaturalRarity(n) === legRarity);
    if (needsCdTick) {
        const intervalId = setInterval(() => {
            if (!game.isZoneTierModalOpen) {
                clearInterval(intervalId);
                game._zoneTierModalCooldownInterval = null;
                return;
            }
            refreshZoneTierModalLegendaryCooldowns(game);
        }, 1000);
        game._zoneTierModalCooldownInterval = intervalId;
    }

    modal.classList.add('show');
    game.isZoneTierModalOpen = true;
}

// Zone tier modal closing is now handled by GameFacade (CLOSE_MODAL handler in commandHandlers.ts)
