/**
 * Lifetime economy counters for stats UI and achievements.
 * Wallet changes go through game.pokedollars; call these explicitly per flow.
 */

import type { GameRuntime } from '../types/game.js';

function safeAmount(amount: unknown): number {
  const n = Math.floor(Number(amount) || 0);
  return n > 0 ? n : 0;
}

export function recordPokedollarsEarned(game: GameRuntime, amount: unknown): void {
  const delta = safeAmount(amount);
  if (delta <= 0) return;
  if (!game.stats || typeof game.stats !== 'object') {
    game.stats = { totalPokedollarsEarned: delta, totalPokedollarsSpent: 0 } as GameRuntime['stats'];
  }
  game.stats.totalPokedollarsEarned = (Number(game.stats.totalPokedollarsEarned) || 0) + delta;
  if (typeof game.checkAchievements === 'function') {
    game.checkAchievements('totalPokedollarsEarned');
  }
}

export function recordPokedollarsSpent(game: GameRuntime, amount: unknown): void {
  const delta = safeAmount(amount);
  if (delta <= 0) return;
  if (!game.stats || typeof game.stats !== 'object') {
    game.stats = { totalPokedollarsEarned: 0, totalPokedollarsSpent: delta } as GameRuntime['stats'];
  }
  game.stats.totalPokedollarsSpent = (Number(game.stats.totalPokedollarsSpent) || 0) + delta;
}
