/**
 * @file typeHuntKantoEligibility.ts
 * Classic Type Hunt: only offer types with enough distinct species in the Kanto region pool.
 */

import { ZONE_POKEMON as _ZONE_POKEMON } from '../../constants/balance/zonesAndPacing.ts';

const ZONE_POKEMON = _ZONE_POKEMON as Record<number, unknown>;
import { POKEMON_POOL, POKEMON_PRIMARY_TYPES, POKEMON_SECONDARY_TYPES, TYPES } from '../../constants/core.ts';
import {
    _getZoneFishingEntries,
    _getZoneWaterEntries,
    _zoneEntryToName,
} from '../../zoneMasterySpecies.ts';
import type { ZonePokemonEntry, ZonePokemonPool } from '../types/game.js';

/** Minimum distinct Kanto-accessible species required to offer a Type Hunt for that type. */
export const TYPE_HUNT_MIN_KANTO_SPECIES = 5;

export const KANTO_ZONE_ID_MIN = 1;
export const KANTO_ZONE_ID_MAX = 46;

/**
 * Types expected to be excluded from classic Type Hunt while only Kanto (zones 1–46) counts.
 * Maintenance reference — actual eligibility is computed from live zone data.
 */
export const EXPECTED_EXCLUDED_TYPE_HUNT_TYPES = [
    'dark',
    'ghost',
    'dragon',
    'steel',
    'fairy',
    'fighting',
] as const;

let kantoSpeciesCache: ReadonlySet<string> | null = null;
let eligibleTypesCache: string[] | null = null;

function collectSpeciesNamesInZone(zoneId: number): string[] {
    const zoneData = ZONE_POKEMON[zoneId] as unknown;
    if (!zoneData) return [];

    if (Array.isArray(zoneData)) {
        const allArray = (zoneData as unknown[])
            .map((entry) => _zoneEntryToName(entry as string | { name?: string }))
            .concat(
                _getZoneWaterEntries(zoneData, zoneId).map((entry) =>
                    _zoneEntryToName(entry as string | { name?: string }),
                ),
            )
            .concat(
                _getZoneFishingEntries(zoneData, zoneId).map((entry) =>
                    _zoneEntryToName(entry as string | { name?: string }),
                ),
            );
        return [...new Set(allArray.filter(Boolean))];
    }

    if (typeof zoneData === 'object') {
        let all: string[] = [];
        const zd = zoneData as ZonePokemonPool;
        if (zd.land) {
            all = all.concat(
                Array.isArray(zd.land)
                    ? zd.land.map((e: ZonePokemonEntry) => _zoneEntryToName(e))
                    : [_zoneEntryToName(zd.land)],
            );
        }
        const waterEntries = _getZoneWaterEntries(zoneData, zoneId);
        if (waterEntries.length) {
            all = all.concat(
                waterEntries.map((e) => _zoneEntryToName(e as string | { name?: string })),
            );
        }
        const fishingEntries = _getZoneFishingEntries(zoneData, zoneId);
        if (fishingEntries.length) {
            all = all.concat(
                fishingEntries.map((e) => _zoneEntryToName(e as string | { name?: string })),
            );
        }
        return [...new Set(all.filter(Boolean))];
    }

    return [];
}

/** All species in Kanto zone tables (land + surf + fishing), zones 1–46. */
export function getKantoRegionSpeciesNames(): ReadonlySet<string> {
    if (kantoSpeciesCache) return kantoSpeciesCache;
    const names = new Set<string>();
    for (let z = KANTO_ZONE_ID_MIN; z <= KANTO_ZONE_ID_MAX; z++) {
        for (const n of collectSpeciesNamesInZone(z)) {
            if (n) names.add(n);
        }
    }
    kantoSpeciesCache = names;
    return names;
}

/** Primary type resolution aligned with Game.findTypeForPokemon (pool first, then POKEMON_PRIMARY_TYPES). */
export function resolveSpeciesPrimaryType(name: string): string {
    if (!name) return TYPES.NORMAL;

    for (const pool of Object.values(POKEMON_POOL)) {
        for (const [type, names] of Object.entries(pool)) {
            if (Array.isArray(names) && names.includes(name)) return type;
        }
    }

    if (POKEMON_PRIMARY_TYPES[name]) return POKEMON_PRIMARY_TYPES[name];
    return TYPES.NORMAL;
}

export function speciesHasElementalType(name: string, typeLower: string): boolean {
    const req = String(typeLower || '').toLowerCase().trim();
    if (!req || !name) return false;
    const primary = resolveSpeciesPrimaryType(name).toLowerCase();
    const secondary = String(POKEMON_SECONDARY_TYPES[name] || '').toLowerCase();
    return primary === req || secondary === req;
}

export function countKantoAccessibleSpeciesForType(typeLower: string): number {
    const req = String(typeLower || '').toLowerCase().trim();
    if (!req) return 0;
    let count = 0;
    for (const species of getKantoRegionSpeciesNames()) {
        if (speciesHasElementalType(species, req)) count++;
    }
    return count;
}

export function getEligibleClassicTypeHuntTypes(): string[] {
    if (eligibleTypesCache) return eligibleTypesCache.slice();
    const eligible: string[] = [];
    for (const type of Object.values(TYPES)) {
        if (countKantoAccessibleSpeciesForType(type) >= TYPE_HUNT_MIN_KANTO_SPECIES) {
            eligible.push(type);
        }
    }
    eligible.sort();
    eligibleTypesCache = eligible;
    return eligible.slice();
}

export function isClassicTypeHuntTypeEligible(requiredType: string): boolean {
    const req = String(requiredType || '').toLowerCase().trim();
    if (!req) return false;
    return countKantoAccessibleSpeciesForType(req) >= TYPE_HUNT_MIN_KANTO_SPECIES;
}

/** Clears memoized Kanto pool (tests only). */
export function _resetTypeHuntKantoEligibilityCacheForTests(): void {
    kantoSpeciesCache = null;
    eligibleTypesCache = null;
}
