/**
 * @file dynamaxLogic.ts
 * Dynamax Band state (Galar).
 */

import {
    GALAR_DYNAMAX_BADGE_IDS,
    clampDynamaxUpgradeLevel,
    DYNAMAX_UPGRADE_MAX_LEVEL,
    getDynamaxUpgradeMoneyCost,
    getDynamaxUpgradeStoneCost,
    isGalarDynamaxBadgeId,
} from '../../constants/balance/dynamax.ts';
import {
    CLASSIC_EVOLUTION_STONE_KEYS,
    EVOLUTION_SPECIAL_ITEM_IDS,
    getOrphanEvolutionInventoryItems,
    getReferencedEvolutionItemKeys,
    isEvolutionInventoryItem,
} from '../../constants/evolutions.ts';
import type { GameRuntime } from '../types/game.js';
import type { DynamaxCombatState, DynamaxState } from '../types/game/state.js';

let cachedUpgradeItemKeys: string[] | null = null;

function clampNonNegInt(raw: unknown): number {
    const n = Math.floor(Number(raw) || 0);
    if (!Number.isFinite(n) || n < 0) return 0;
    return n;
}

/** Wallet Pokédollars (game field is `pokedollars`, not `money`). */
export function getDynamaxWallet(game: GameRuntime): number {
    return Math.max(0, Number(game.pokedollars) || 0);
}

function setDynamaxWallet(game: GameRuntime, amount: number): void {
    game.pokedollars = Math.max(0, Math.floor(Number(amount) || 0));
}

export function createDefaultDynamaxState(): DynamaxState {
    return {
        unlocked: false,
        configured: false,
        introShown: false,
        upgradeLevel: 0,
        upgradeMoneyProgress: 0,
        upgradeItemsProgress: 0,
    };
}

export function normalizeDynamaxState(raw: unknown): DynamaxState {
    const base = createDefaultDynamaxState();
    if (!raw || typeof raw !== 'object') return base;
    const o = raw as Record<string, unknown>;
    return {
        unlocked: o.unlocked === true,
        configured: o.configured === true,
        introShown: o.introShown === true,
        upgradeLevel: clampDynamaxUpgradeLevel(o.upgradeLevel),
        upgradeMoneyProgress: clampNonNegInt(o.upgradeMoneyProgress),
        upgradeItemsProgress: clampNonNegInt(o.upgradeItemsProgress),
    };
}

export function getDynamaxState(game: GameRuntime): DynamaxState {
    if (!game.dynamaxState || typeof game.dynamaxState !== 'object') {
        game.dynamaxState = createDefaultDynamaxState();
    }
    const state = game.dynamaxState;
    state.upgradeLevel = clampDynamaxUpgradeLevel(state.upgradeLevel);
    state.upgradeMoneyProgress = clampNonNegInt(state.upgradeMoneyProgress);
    state.upgradeItemsProgress = clampNonNegInt(state.upgradeItemsProgress);
    return state;
}

export function getDynamaxUpgradeLevel(game: GameRuntime): number {
    return clampDynamaxUpgradeLevel(getDynamaxState(game).upgradeLevel);
}

export function isDynamaxBandUnlocked(game: GameRuntime): boolean {
    return getDynamaxState(game).unlocked === true;
}

export function unlockDynamaxBand(game: GameRuntime): boolean {
    const state = getDynamaxState(game);
    if (state.unlocked) return false;
    state.unlocked = true;
    return true;
}

export function confirmDynamaxBand(game: GameRuntime): boolean {
    const state = getDynamaxState(game);
    if (!state.unlocked) return false;
    if (state.configured) return false;
    state.configured = true;
    state.introShown = true;
    return true;
}

export function isDynamaxBandConfigured(game: GameRuntime): boolean {
    return getDynamaxState(game).configured === true;
}

/** All inventory keys that can be spent on a Dynamax Band upgrade. */
export function listDynamaxUpgradeItemKeys(): string[] {
    if (cachedUpgradeItemKeys) return cachedUpgradeItemKeys;
    const keys = new Set<string>();
    for (const k of CLASSIC_EVOLUTION_STONE_KEYS) keys.add(k);
    for (const k of EVOLUTION_SPECIAL_ITEM_IDS) keys.add(k);
    for (const k of getReferencedEvolutionItemKeys()) keys.add(k);
    for (const k of getOrphanEvolutionInventoryItems()) keys.add(k);
    cachedUpgradeItemKeys = [...keys].filter((k) => isEvolutionInventoryItem(k)).sort();
    return cachedUpgradeItemKeys;
}

export function isDynamaxUpgradeItem(itemKey: string): boolean {
    return isEvolutionInventoryItem(itemKey);
}

export type DynamaxUpgradeBlockReason =
    | 'locked'
    | 'not_configured'
    | 'max_level'
    | 'bad_stone'
    | 'no_money'
    | 'no_stones'
    | null;

export interface DynamaxUpgradePreview {
    currentLevel: number;
    nextLevel: number | null;
    maxLevel: number;
    moneyCost: number | null;
    /** Evolution items to deposit for next level. */
    stoneCost: number | null;
    canUpgrade: boolean;
    blockReason: DynamaxUpgradeBlockReason;
}

export interface DynamaxUpgradeProgress {
    moneyPct: number;
    itemsPct: number;
    /** Already deposited toward next money cost (not wallet). */
    moneyHave: number;
    moneyNeed: number | null;
    /** Already deposited toward next item cost (not inventory). */
    itemsHave: number;
    itemsNeed: number | null;
    atMax: boolean;
}

function clampPct(have: number, need: number): number {
    if (need <= 0) return 1;
    return Math.max(0, Math.min(1, have / need));
}

export function getDynamaxUpgradePreview(game: GameRuntime): DynamaxUpgradePreview {
    const currentLevel = getDynamaxUpgradeLevel(game);
    const maxLevel = DYNAMAX_UPGRADE_MAX_LEVEL;
    if (!isDynamaxBandUnlocked(game)) {
        return {
            currentLevel,
            nextLevel: null,
            maxLevel,
            moneyCost: null,
            stoneCost: null,
            canUpgrade: false,
            blockReason: 'locked',
        };
    }
    if (!isDynamaxBandConfigured(game)) {
        return {
            currentLevel,
            nextLevel: null,
            maxLevel,
            moneyCost: null,
            stoneCost: null,
            canUpgrade: false,
            blockReason: 'not_configured',
        };
    }
    if (currentLevel >= maxLevel) {
        return {
            currentLevel,
            nextLevel: null,
            maxLevel,
            moneyCost: null,
            stoneCost: null,
            canUpgrade: false,
            blockReason: 'max_level',
        };
    }
    const moneyCost = getDynamaxUpgradeMoneyCost(currentLevel);
    const stoneCost = getDynamaxUpgradeStoneCost(currentLevel);
    return {
        currentLevel,
        nextLevel: currentLevel + 1,
        maxLevel,
        moneyCost,
        stoneCost,
        canUpgrade: true,
        blockReason: null,
    };
}

export function getDynamaxUpgradeProgress(game: GameRuntime): DynamaxUpgradeProgress {
    const preview = getDynamaxUpgradePreview(game);
    const state = getDynamaxState(game);
    const moneyHave = clampNonNegInt(state.upgradeMoneyProgress);
    const itemsHave = clampNonNegInt(state.upgradeItemsProgress);
    if (preview.blockReason === 'max_level' || preview.nextLevel == null) {
        return {
            moneyPct: 1,
            itemsPct: 1,
            moneyHave,
            moneyNeed: null,
            itemsHave,
            itemsNeed: null,
            atMax: true,
        };
    }
    const moneyNeed = preview.moneyCost ?? 0;
    const itemsNeed = preview.stoneCost ?? 0;
    return {
        moneyPct: clampPct(moneyHave, moneyNeed),
        itemsPct: clampPct(itemsHave, itemsNeed),
        moneyHave,
        moneyNeed,
        itemsHave,
        itemsNeed,
        atMax: false,
    };
}

/**
 * Deposit wallet money toward the next upgrade. Returns amount deposited.
 */
export function contributeDynamaxUpgradeMoney(game: GameRuntime, maxAmount?: number): number {
    const preview = getDynamaxUpgradePreview(game);
    if (!preview.canUpgrade || preview.moneyCost == null) return 0;
    const state = getDynamaxState(game);
    const have = clampNonNegInt(state.upgradeMoneyProgress);
    const remaining = Math.max(0, preview.moneyCost - have);
    if (remaining <= 0) return 0;
    const wallet = getDynamaxWallet(game);
    const cap = maxAmount == null ? remaining : Math.max(0, Math.floor(Number(maxAmount) || 0));
    const take = Math.min(remaining, wallet, cap);
    if (take <= 0) return 0;
    setDynamaxWallet(game, wallet - take);
    state.upgradeMoneyProgress = have + take;
    return take;
}

/**
 * Deposit evolution items from one inventory key toward the next upgrade.
 * Returns qty deposited.
 */
export function contributeDynamaxUpgradeItems(
    game: GameRuntime,
    itemKey: string,
    maxAmount?: number,
): number {
    const preview = getDynamaxUpgradePreview(game);
    if (!preview.canUpgrade || preview.stoneCost == null) return 0;
    if (!isDynamaxUpgradeItem(itemKey)) return 0;
    const state = getDynamaxState(game);
    const have = clampNonNegInt(state.upgradeItemsProgress);
    const remaining = Math.max(0, preview.stoneCost - have);
    if (remaining <= 0) return 0;
    if (!game.items || typeof game.items !== 'object') game.items = {};
    const owned = Math.max(0, Math.floor(Number(game.items[itemKey]) || 0));
    const cap = maxAmount == null ? remaining : Math.max(0, Math.floor(Number(maxAmount) || 0));
    const take = Math.min(remaining, owned, cap);
    if (take <= 0) return 0;
    const left = owned - take;
    if (left <= 0) delete game.items[itemKey];
    else game.items[itemKey] = left;
    state.upgradeItemsProgress = have + take;
    return take;
}

/** If both deposit meters are full, level up and reset progress. */
export function tryCompleteDynamaxUpgrade(game: GameRuntime): boolean {
    const preview = getDynamaxUpgradePreview(game);
    if (!preview.canUpgrade || preview.moneyCost == null || preview.stoneCost == null || preview.nextLevel == null) {
        return false;
    }
    const state = getDynamaxState(game);
    if (clampNonNegInt(state.upgradeMoneyProgress) < preview.moneyCost) return false;
    if (clampNonNegInt(state.upgradeItemsProgress) < preview.stoneCost) return false;
    state.upgradeLevel = preview.nextLevel;
    state.upgradeMoneyProgress = 0;
    state.upgradeItemsProgress = 0;
    return true;
}

/**
 * Deposit as much money + selected item as possible toward the next level.
 * Levels up automatically when both meters fill.
 * Allowed during combat. Caller handles toast/save/UI.
 */
export function tryUpgradeDynamaxBand(game: GameRuntime, itemKey: string): boolean {
    const preview = getDynamaxUpgradePreview(game);
    if (!preview.canUpgrade) return false;
    if (!isDynamaxUpgradeItem(itemKey)) return false;

    const beforeLevel = getDynamaxUpgradeLevel(game);
    const moneyTaken = contributeDynamaxUpgradeMoney(game);
    const itemsTaken = contributeDynamaxUpgradeItems(game, itemKey);
    const leveled = tryCompleteDynamaxUpgrade(game);

    return leveled || moneyTaken > 0 || itemsTaken > 0 || getDynamaxUpgradeLevel(game) > beforeLevel;
}

export interface DynamaxDepositSelection {
    money?: number;
    items?: Record<string, number>;
}

/**
 * Deposit an explicit money amount + per-item quantities toward the next level.
 */
export function depositDynamaxUpgrade(
    game: GameRuntime,
    selection: DynamaxDepositSelection,
): { ok: boolean; moneyTaken: number; itemsTaken: number; leveled: boolean } {
    const preview = getDynamaxUpgradePreview(game);
    if (!preview.canUpgrade) {
        return { ok: false, moneyTaken: 0, itemsTaken: 0, leveled: false };
    }

    let moneyTaken = 0;
    let itemsTaken = 0;
    const moneySel = Math.max(0, Math.floor(Number(selection.money) || 0));
    if (moneySel > 0) {
        moneyTaken = contributeDynamaxUpgradeMoney(game, moneySel);
    }
    const items = selection.items ?? {};
    for (const [key, rawQty] of Object.entries(items)) {
        const qty = Math.max(0, Math.floor(Number(rawQty) || 0));
        if (qty <= 0) continue;
        itemsTaken += contributeDynamaxUpgradeItems(game, key, qty);
    }
    const leveled = tryCompleteDynamaxUpgrade(game);
    const ok = leveled || moneyTaken > 0 || itemsTaken > 0;
    return { ok, moneyTaken, itemsTaken, leveled };
}

export function canAffordDynamaxUpgrade(
    game: GameRuntime,
    itemKey: string,
): { ok: true } | { ok: false; reason: DynamaxUpgradeBlockReason } {
    const preview = getDynamaxUpgradePreview(game);
    if (!preview.canUpgrade || preview.moneyCost == null || preview.stoneCost == null) {
        return { ok: false, reason: preview.blockReason ?? 'max_level' };
    }
    if (!isDynamaxUpgradeItem(itemKey)) {
        return { ok: false, reason: 'bad_stone' };
    }
    const progress = getDynamaxUpgradeProgress(game);
    const moneyRemaining = Math.max(0, preview.moneyCost - progress.moneyHave);
    const itemsRemaining = Math.max(0, preview.stoneCost - progress.itemsHave);
    const wallet = getDynamaxWallet(game);
    const owned = Number(game.items?.[itemKey]) || 0;

    if (moneyRemaining <= 0 && itemsRemaining <= 0) return { ok: true };
    if (moneyRemaining > 0 && wallet > 0) return { ok: true };
    if (itemsRemaining > 0 && owned > 0) return { ok: true };
    if (moneyRemaining > 0 && wallet <= 0) return { ok: false, reason: 'no_money' };
    return { ok: false, reason: 'no_stones' };
}

/** Zone wild combat only — not tower, arena, subway, gym trainers. */
export function isDynamaxZoneCombat(game: GameRuntime): boolean {
    if (game.towerState?.isActive) return false;
    if (game.arenaState?.active) return false;
    if (game.gymTrainerState?.active) return false;
    if (game.subwayState?.isActive) return false;
    return true;
}

export function createDefaultDynamaxCombatState(): DynamaxCombatState {
    return {
        active: false,
        usedThisCombat: false,
        remainingMs: 0,
        durationMs: 0,
        timerLastTickAt: null,
    };
}

/** Slider resolution for Pokédollars deposit UI (avoids huge HTML range max). */
export const DYNAMAX_MONEY_SLIDER_NORM_MAX = 1000;

export function moneyNormToAmount(norm: number, moneyMax: number): number {
    const n = Math.max(0, Math.min(DYNAMAX_MONEY_SLIDER_NORM_MAX, Math.floor(Number(norm) || 0)));
    const max = Math.max(0, Math.floor(Number(moneyMax) || 0));
    if (max <= 0 || n <= 0) return 0;
    if (n >= DYNAMAX_MONEY_SLIDER_NORM_MAX) return max;
    return Math.floor((n / DYNAMAX_MONEY_SLIDER_NORM_MAX) * max);
}

export function moneyAmountToNorm(amount: number, moneyMax: number): number {
    const a = Math.max(0, Math.floor(Number(amount) || 0));
    const max = Math.max(0, Math.floor(Number(moneyMax) || 0));
    if (max <= 0 || a <= 0) return 0;
    if (a >= max) return DYNAMAX_MONEY_SLIDER_NORM_MAX;
    return Math.max(0, Math.min(
        DYNAMAX_MONEY_SLIDER_NORM_MAX,
        Math.round((a / max) * DYNAMAX_MONEY_SLIDER_NORM_MAX),
    ));
}

export function countGalarDynamaxBadges(game: GameRuntime): number {
    let count = 0;
    for (const id of GALAR_DYNAMAX_BADGE_IDS) {
        const has = typeof game.hasBadge === 'function'
            ? game.hasBadge(id)
            : !!game.badges?.[id];
        if (has) count += 1;
    }
    return count;
}

export function syncDynamaxFromGalarBadges(game: GameRuntime): void {
    const meadow = typeof game.hasBadge === 'function'
        ? game.hasBadge('meadow')
        : !!game.badges?.meadow;
    if (meadow) unlockDynamaxBand(game);
}

export function onGalarGymBadgeWon(game: GameRuntime, badgeKey: string): void {
    if (!badgeKey || badgeKey === 'maitre_galar') return;
    if (!isGalarDynamaxBadgeId(badgeKey)) return;
    unlockDynamaxBand(game);
}
