/**
 * Dynamic dust shop pricing (escalating costs per purchase).
 */

export const DUST_SHOP_ESCALATION_MULT = 1.1;

/** Shop catalog keys with +10% cost per prior purchase. */
export const ESCALATING_DUST_SHOP_KEYS = new Set([
    'armorite_ore',
    'talent_reroll',
    'talent_choice',
    'prism_iv_shop',
]);

export function isEscalatingDustShopKey(shopKey: string): boolean {
    return ESCALATING_DUST_SHOP_KEYS.has(shopKey);
}

export function getDustShopItemCost(
    baseCost: number,
    shopKey: string,
    purchaseCounts: Record<string, number> | null | undefined,
): number {
    const base = Math.max(0, Math.floor(Number(baseCost) || 0));
    if (!isEscalatingDustShopKey(shopKey)) return base;
    const n = Math.max(0, Math.floor(Number(purchaseCounts?.[shopKey]) || 0));
    return Math.floor(base * Math.pow(DUST_SHOP_ESCALATION_MULT, n));
}

export function getNextEscalatingDustShopCost(
    baseCost: number,
    shopKey: string,
    purchaseCounts: Record<string, number> | null | undefined,
): number {
    const base = Math.max(0, Math.floor(Number(baseCost) || 0));
    if (!isEscalatingDustShopKey(shopKey)) return base;
    const n = Math.max(0, Math.floor(Number(purchaseCounts?.[shopKey]) || 0)) + 1;
    return Math.floor(base * Math.pow(DUST_SHOP_ESCALATION_MULT, n));
}
