const MILTANK_FARM_FORCE_PUBLISH = { force: true } as const;

function isMiltankFarmModalDomOpen(): boolean {
    if (typeof document === 'undefined') return false;
    const modal = document.getElementById('miltankFarmModal');
    if (!modal?.classList || typeof modal.classList.contains !== 'function') return false;
    return modal.classList.contains('show');
}

function isBerryTreeModalDomOpen(): boolean {
    if (typeof document === 'undefined') return false;
    const modal = document.getElementById('berryTreeModal');
    if (!modal?.classList || typeof modal.classList.contains !== 'function') return false;
    return modal.classList.contains('show');
}

function hasBerryCombineInProgress(game: GameRuntime): boolean {
    const pending = game.miltankFarmState?.berryTree?.pendingCombine;
    if (!pending) return false;
    return Date.now() < pending.completesAt;
}

function shouldLiveRefreshMiltankFarmUi(game: GameRuntime): boolean {
    const pendingAttacks = game.miltankFarmState?.pendingThreatAttacks?.length ?? 0;
    return !!game.miltankFarmViewActive
        || isMiltankFarmModalDomOpen()
        || isBerryTreeModalDomOpen()
        || hasBerryCombineInProgress(game)
        || !!(game.gymTrainerState?.active && game.gymTrainerState.isFarmThreat)
        || pendingAttacks > 0;
}

function publishMiltankFarmAfterMutation(): void {
    publishMiltankFarmChanged(MILTANK_FARM_FORCE_PUBLISH);
}

function farmText(
    game: GameRuntime,
    key: string,
    fallbackFr: string,
    fallbackEn: string,
    vars: Record<string, string | number> = {},
): string {
    const lang = game && typeof game.normalizeLanguage === 'function'
        ? game.normalizeLanguage(game.language)
        : 'fr';
    const i18nKey = `miltankFarm.log.${key}`;
    if (typeof game.t === 'function') {
        const translated = game.t(i18nKey, vars);
        if (translated && translated !== i18nKey) return translated;
    }
    let out = lang === 'en' ? fallbackEn : fallbackFr;
    for (const [k, v] of Object.entries(vars)) {
        out = out.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v));
    }
    return out;
}

function ensureMiltankFarmState(game: GameRuntime): MiltankFarmState {
    if (!game.miltankFarmState || typeof game.miltankFarmState !== 'object') {
        game.miltankFarmState = createDefaultMiltankFarmState(Date.now());
    }
    repairInvalidPastureCreatures(game);
    normalizeMiltankFarmState(game.miltankFarmState);
    return game.miltankFarmState;
}

function kalosPastureQuestDone(game: GameRuntime): boolean {
    const completed = game.completedStoryQuests;
    return Array.isArray(completed) && completed.includes('story_kalos_miltank_pasture');
}

function buildFarmThreatContext(game: GameRuntime): FarmThreatTickContext {
    return {
        teamRocketUnlocked: !!(game.unlockedFeatures?.teamRocketTab),
        pastureQuestCompleted: kalosPastureQuestDone(game),
    };
}

function guardianDisplayName(creature: CreatureData | null | undefined): string {
    return creature?.name?.trim() || 'Gardien';
}

function repelledIncidentLogText(
    game: GameRuntime,
    state: MiltankFarmState,
    pulse: FarmIncidentPulse,
): string {
    const guardian = getGuardianForPastureUid(state, pulse.pastureUid);
    const guardianName = guardianDisplayName(guardian);
    if (pulse.repelledThreat === 'rocket') {
        return farmText(
            game,
            'guardianRepelledRocket',
            '{guardian} a repoussé Team Rocket !',
            '{guardian} repelled Team Rocket!',
            { guardian: guardianName },
        );
    }
    if (pulse.repelledThreat === 'predator') {
        return farmText(
            game,
            'guardianRepelledPredator',
            '{guardian} a repoussé un {predator} !',
            '{guardian} repelled a {predator}!',
            { guardian: guardianName, predator: pulse.predatorSpecies ?? 'predator' },
        );
    }
    return farmText(
        game,
        'guardianRepelled',
        'Le gardien a repoussé la menace !',
        'The guardian repelled the threat!',
    );
}

function trackRepelledIncidents(game: GameRuntime, count: number): void {
    if (count <= 0) return;
    if (typeof game.checkAchievements === 'function') {
        if (!game.stats || typeof game.stats !== 'object') game.stats = {} as GameRuntime['stats'];
        const sc = game.stats as unknown as Record<string, number>;
        sc.miltankFarmIncidentsRepelled = (Number(sc.miltankFarmIncidentsRepelled) || 0) + count;
        game.checkAchievements('miltankFarmIncidentsRepelled');
    }
    if (typeof game.checkSpecialQuests === 'function') {
        for (let i = 0; i < count; i++) {
            game.checkSpecialQuests('miltank_farm_incident_repelled');
        }
    }
}

function toastRepelledIncidents(
    game: GameRuntime,
    state: MiltankFarmState,
    repelled: FarmIncidentPulse[],
): void {
    if (repelled.length === 0) return;
    if (repelled.length === 1) {
        toast.show({ message: repelledIncidentLogText(game, state, repelled[0]!), type: 'success' });
        return;
    }
    const uniquePastures = new Set(repelled.map((p) => p.pastureUid));
    const firstGuardian = getGuardianForPastureUid(state, repelled[0]!.pastureUid);
    const guardianName = uniquePastures.size > 1
        ? farmText(game, 'guardiansCollective', 'Tes gardiens', 'Your guardians')
        : guardianDisplayName(firstGuardian);
    toast.show({
        message: farmText(
            game,
            'guardianRepelledMany',
            '{guardian} a repoussé {count} menaces !',
            '{guardian} repelled {count} threats!',
            { guardian: guardianName, count: repelled.length },
        ),
        type: 'success',
    });
}

function logFarmIncidents(game: GameRuntime, pulses: FarmIncidentPulse[]): void {
    const state = game.miltankFarmState;
    const repelled = pulses.filter((p) => p.type === 'repelled');
    const others = pulses.filter((p) => p.type !== 'repelled');

    if (repelled.length > 0 && state) {
        for (const pulse of repelled) {
            logMessage(repelledIncidentLogText(game, state, pulse));
        }
        trackRepelledIncidents(game, repelled.length);
        toastRepelledIncidents(game, state, repelled);
    }

    for (const pulse of others) {
        if (pulse.type === 'predator') {
            logMessage(farmText(
                game,
                'predatorAttack',
                'Un {predator} a blessé une Miltank ! Production réduite.',
                'A {predator} injured a Miltank! Production reduced.',
                { predator: pulse.predatorSpecies ?? 'predator' },
            ));
        } else if (pulse.type === 'rocket') {
            logMessage(farmText(
                game,
                'rocketTheft',
                'Team Rocket a volé {qty} lait !',
                'Team Rocket stole {qty} milk!',
                { qty: pulse.milkStolen ?? 0 },
            ));
        }
        enqueueFarmThreatIncidentModal(game, pulse);
    }
}

const farmThreatIncidentModalQueue: FarmIncidentPulse[] = [];

function enqueueFarmThreatIncidentModal(game: GameRuntime, pulse: FarmIncidentPulse): void {
    if (pulse.type !== 'predator' && pulse.type !== 'rocket') return;
    farmThreatIncidentModalQueue.push(pulse);
    presentNextFarmThreatIncidentModal(game);
}

function presentNextFarmThreatIncidentModal(game: GameRuntime): void {
    const state = game.miltankFarmState;
    if (!state) return;
    if (state.pendingIncidentAlert) return;
    const pulse = farmThreatIncidentModalQueue[0];
    if (!pulse) return;
    setFarmIncidentAlert(state, pulse);
    publishMiltankFarmAfterMutation();
    void openMiltankFarmModalForPastureLogic(game, pulse.pastureUid);
}

export function dismissMiltankFarmIncidentAlertLogic(game: GameRuntime): void {
    const state = game.miltankFarmState;
    if (!state?.pendingIncidentAlert) return;
    clearFarmIncidentAlert(state);
    if (farmThreatIncidentModalQueue.length > 0) {
        farmThreatIncidentModalQueue.shift();
    }
    publishMiltankFarmAfterMutation();
    presentNextFarmThreatIncidentModal(game);
}

/** @internal Vitest */
export function resetFarmThreatIncidentModalQueueForTests(): void {
    farmThreatIncidentModalQueue.length = 0;
}

function logSpawnedThreatApproaches(game: GameRuntime, approaches: FarmThreatApproach[]): void {
    if (approaches.length === 0) return;
    for (const approach of approaches) {
        const message = approach.type === 'rocket'
            ? farmText(
                game,
                'threatApproachRocket',
                'Team Rocket approche le pâturage !',
                'Team Rocket is approaching the pasture!',
            )
            : farmText(
                game,
                'threatApproachPredator',
                '{species} approche le pâturage !',
                '{species} is approaching the pasture!',
                { species: approach.species },
            );
        logMessage(message);
        toast?.info?.(message);
    }
}

function isMiltankInUltimateSlot(game: GameRuntime, uid: string): boolean {
    const ult = game.ultimateSlot;
    return !!(ult && ult.uid && String(ult.uid) === uid);
}

function adjustActiveIndexOnTeamRemove(game: GameRuntime, removedIndex: number): void {
    if (removedIndex === game.activeCreatureIndex) {
        game.activeCreatureIndex = removedIndex === 0 ? 1 : 0;
    } else if (removedIndex < game.activeCreatureIndex) {
        game.activeCreatureIndex--;
    }
}

function getPastureRosterArray(
    game: GameRuntime,
    source: PastureRosterSource,
): CreatureData[] | null {
    if (source === 'storage') return Array.isArray(game.storage) ? game.storage : null;
    if (source === 'team') return Array.isArray(game.playerTeam) ? game.playerTeam : null;
    return Array.isArray(game.pension) ? game.pension : null;
}

function removePastureRosterCreature(
    game: GameRuntime,
    source: PastureRosterSource,
    index: number,
): CreatureData | null {
    const arr = getPastureRosterArray(game, source);
    if (!arr || index < 0 || index >= arr.length) return null;
    const creature = arr[index] as CreatureData | undefined;
    if (!creature) return null;
    if (source === 'team') adjustActiveIndexOnTeamRemove(game, index);
    arr.splice(index, 1);
    return creature;
}

