export function feedMiltankFarmLogic(game: GameRuntime, itemKey?: string): boolean {
    const state = ensureMiltankFarmState(game);
    if (!state.unlocked) return false;
    const entry = getSelectedPastureEntry(state);
    if (!entry) return false;
    const name = getPastureEntryDisplayName(game, state, entry);
    const req = entry.currentRequest;
    const key = itemKey || req?.itemKey;
    if (!key || !req) {
        logMessage(farmText(
            game,
            'noRequest',
            '{name} n\'a pas de demande active.',
            '{name} has no active request.',
            { name },
        ));
        return false;
    }
    const owned = Math.max(0, Number(game.items?.[key]) || 0);
    if (owned < req.qty) {
        logMessage(farmText(
            game,
            'notEnough',
            'Pas assez d\'objets pour nourrir {name}.',
            'Not enough items to feed {name}.',
            { name },
        ));
        return false;
    }

    tickMiltankFarmLogic(game);
    const feedXpBonus = Math.floor(game.getMasteryBonus?.('pasture_feed_xp_bonus') || 0);
    const result = applyMiltankFeed(state, entry.uid, key, Date.now(), Math.random, feedXpBonus);
    if (!result.ok) {
        if (result.reason === 'too_full') {
            logMessage(farmText(
                game,
                'tooFull',
                '{name} est rassasiée. Attends un peu avant de la nourrir.',
                '{name} is full. Wait a bit before feeding again.',
                { name },
            ));
        } else {
            logMessage(farmText(
                game,
                'wrongItem',
                'Ce n\'est pas ce que {name} demande.',
                'That is not what {name} asked for.',
                { name },
            ));
        }
        return false;
    }

    game.items[key] = owned - req.qty;
    if (game.items[key] <= 0) delete game.items[key];

    const itemDef = (ALL_ITEMS as Record<string, Record<string, unknown>>)[key];
    const itemName = typeof game.getLocalizedItemName === 'function'
        ? game.getLocalizedItemName(key, String(itemDef?.name ?? key), itemDef)
        : String(itemDef?.name ?? key);

    logMessage(farmText(
        game,
        result.xpGained && result.xpGained > 0 ? 'fedWithXp' : 'fed',
        result.xpGained && result.xpGained > 0
            ? '{name} savoure {item} ! +{xp} XP — production boostée.'
            : '{name} savoure {item} ! Production boostée.',
        result.xpGained && result.xpGained > 0
            ? '{name} enjoys the {item}! +{xp} XP — production boosted.'
            : '{name} enjoys the {item}! Production boosted.',
        { item: itemName, name, xp: result.xpGained ?? 0 },
    ));
    if (result.entryLevelUp) {
        logMessage(farmText(
            game,
            'levelUp',
            '{name} monte au niveau {level} ! +1 point de talent.',
            '{name} reached level {level}! +1 talent point.',
            { level: result.entryLevel ?? entry.level, name },
        ));
        logMessage(farmText(
            game,
            'farmLevelUp',
            'Niveau {level} — +1 point de talent !',
            'Level {level} — +1 talent point!',
            { level: result.entryLevel ?? entry.level },
        ));
        const modalOpen = typeof document !== 'undefined'
            && document.getElementById('miltankFarmModal')?.classList.contains('show');
        if (!modalOpen && toast?.info) {
            toast.info(
                farmText(game, 'levelUpToastTitle', 'Ferme Écrémeuh', 'Miltank Farm'),
                farmText(
                    game,
                    'levelUpToast',
                    'Niveau {level} — +1 point de talent !',
                    'Level {level} — +1 talent point!',
                    { level: result.entryLevel ?? entry.level },
                ),
            );
        }
    }

    if (typeof game.checkSpecialQuests === 'function') {
        game.checkSpecialQuests('miltank_farm_feed');
        syncMiltankPastureQuestProgress(game);
    }
    if (typeof game.checkAchievements === 'function') {
        if (!game.stats || typeof game.stats !== 'object') game.stats = {} as GameRuntime['stats'];
        const sc = game.stats as unknown as Record<string, number>;
        sc.miltankFarmFeeds = (Number(sc.miltankFarmFeeds) || 0) + 1;
        game.checkAchievements('miltankFarmFeeds');
    }
    notifyBagChanged(game);
    publishMiltankFarmAfterMutation();
    game.saveGame?.();
    return true;
}

