export function rerollMiltankFarmRequestLogic(
    game: GameRuntime,
    pastureUid?: string,
): boolean {
    const state = ensureMiltankFarmState(game);
    if (!state.unlocked) return false;
    tickMiltankFarmLogic(game);
    const uid = pastureUid || state.selectedPastureUid;
    const entry = getPastureEntryByUid(state, uid);
    if (!entry) return false;
    setSelectedPastureUid(state, uid);
    const now = Date.now();
    resetMiltankRequestRerollDailyIfNeeded(state);
    const cost = getMiltankRequestRerollCost(state.requestRerollCountToday ?? 0);
    if ((Number(game.pokedollars) || 0) < cost) {
        logMessage(farmText(game, 'rerollPoor', 'Pas assez de Pokédollars.', 'Not enough Pokédollars.'));
        return false;
    }
    game.pokedollars = (Number(game.pokedollars) || 0) - cost;
    recordPokedollarsSpent(game, cost);
    state.requestRerollCountToday = (state.requestRerollCountToday ?? 0) + 1;
    entry.currentRequest = null;
    ensureMiltankFarmRequestForEntry(
        entry,
        entry.level,
        now,
        Math.random,
        getUnlockedBerryKeysForMiltankRequests(state),
    );
    logMessage(farmText(
        game,
        'rerolled',
        '{name} a une nouvelle envie !',
        '{name} has a new craving!',
        { name: getPastureEntryDisplayName(game, state, entry) },
    ));
    publishMiltankFarmAfterMutation();
    game.saveGame?.();
    return true;
}

export function healPastureDebuffLogic(game: GameRuntime, itemKey: string): boolean {
    const state = ensureMiltankFarmState(game);
    if (!state.unlocked) return false;
    if (getPastureHealReductionPct(itemKey) == null) return false;

    const entry = getSelectedPastureEntry(state);
    if (!entry) return false;
    const name = getPastureEntryDisplayName(game, state, entry);

    const owned = Math.max(0, Number(game.items?.[itemKey]) || 0);
    if (owned < 1) {
        logMessage(farmText(
            game,
            'healNoItem',
            'Pas assez de potions.',
            'Not enough potions.',
        ));
        return false;
    }

    tickMiltankFarmLogic(game);
    const now = Date.now();
    const lang = game && typeof game.normalizeLanguage === 'function'
        ? game.normalizeLanguage(game.language)
        : 'fr';
    const result = applyPastureDebuffHeal(state, entry.uid, itemKey, now);
    if (!result.ok) {
        if (result.reason === 'no_debuff') {
            logMessage(farmText(
                game,
                'healNoDebuff',
                '{name} n\'est pas blessée.',
                '{name} is not injured.',
                { name },
            ));
        }
        return false;
    }

    game.items[itemKey] = owned - 1;
    if (game.items[itemKey] <= 0) delete game.items[itemKey];
    notifyBagChanged(game);

    if (result.removed) {
        logMessage(farmText(
            game,
            'healCured',
            '{name} est guérie ! Production normale.',
            '{name} is healed! Production back to normal.',
            { name },
        ));
    } else {
        logMessage(farmText(
            game,
            'healSuccess',
            '{name} se remet — blessure réduite de {time}.',
            '{name} recovers — injury reduced by {time}.',
            {
                name,
                time: formatFarmDuration(result.reducedMs, lang as 'fr' | 'en'),
            },
        ));
    }

    publishMiltankFarmAfterMutation();
    maybePublishMiltankFarmLiveRefresh(game);
    game.saveGame?.();
    return true;
}

