export function assignMiltankToPastureLogic(
    game: GameRuntime,
    source: PastureRosterSource,
    index: number,
): boolean {
    const state = ensureMiltankFarmState(game);
    if (!state.unlocked) return false;

    const arr = getPastureRosterArray(game, source);
    if (!arr || index < 0 || index >= arr.length) return false;

    const creature = arr[index] as CreatureData | undefined;
    if (!creature) return false;

    const uid = String(creature.uid || '');
    if (!uid) return false;

    if (isMiltankInUltimateSlot(game, uid)) {
        logMessage(farmText(
            game,
            'inUltimate',
            'Ce Miltank est en slot ultime — retire-le d\'abord.',
            'This Miltank is in the ultimate slot — remove it first.',
        ));
        return false;
    }

    const validation = validatePastureAssign(state, creature);
    if (!validation.ok) {
        logPastureAssignReject(game, validation.reason);
        return false;
    }

    const removed = removePastureRosterCreature(game, source, index);
    if (!removed) return false;

    state.pastureCreatures = state.pastureCreatures ?? [];
    if (validation.slot === 'normal') {
        state.pastureCreatures.unshift(removed);
    } else {
        state.pastureCreatures.push(removed);
    }
    normalizeMiltankFarmState(state);
    const entry = getPastureEntryByUid(state, uid);
    if (entry) ensureMiltankFarmRequestForEntry(entry, entry.level, Date.now());

    logMessage(farmText(
        game,
        'assigned',
        '{name} rejoint le pâturage !',
        '{name} joined the pasture!',
        { name: removed.name || 'Miltank' },
    ));

    const assignedCount = (state.pastureCreatures ?? []).length;
    if (assignedCount >= 2 && !state.uiHintsSeen?.secondPastureCare) {
        if (!state.uiHintsSeen || typeof state.uiHintsSeen !== 'object') {
            state.uiHintsSeen = {};
        }
        state.uiHintsSeen.secondPastureCare = true;
        logMessage(farmText(
            game,
            'secondPastureCareHint',
            'Investir en Soin sur ce Miltank réduit l\'attente entre les repas et accélère sa montée de niveau.',
            'Investing in Care on this Miltank shortens wait between feeds and speeds leveling.',
        ));
    }

    if (typeof game.checkAchievements === 'function') {
        if (!game.stats || typeof game.stats !== 'object') game.stats = {} as GameRuntime['stats'];
        const sc = game.stats as unknown as Record<string, number>;
        sc.miltankFarmPastureAssigned = (Number(sc.miltankFarmPastureAssigned) || 0) + 1;
        game.checkAchievements('miltankFarmPastureAssigned');
    }

    if (typeof game.updateStorageDisplay === 'function') game.updateStorageDisplay();
    if (typeof game.updateTeamDisplay === 'function') game.updateTeamDisplay();
    if (typeof game.updatePensionDisplay === 'function') game.updatePensionDisplay();
    if (source === 'team' && typeof game.calculateTeamStats === 'function') game.calculateTeamStats();
    publishMiltankFarmAfterMutation();
    game.saveGame?.();
    return true;
}

/** @deprecated Use assignMiltankToPastureLogic(game, 'storage', index). */
export function assignMiltankToPastureFromStorageLogic(game: GameRuntime, storageIndex: number): boolean {
    return assignMiltankToPastureLogic(game, 'storage', storageIndex);
}

export function parsePastureAssignArg(arg: string | number): { source: PastureRosterSource; index: number } | null {
    if (typeof arg === 'number' || /^\d+$/.test(String(arg))) {
        return { source: 'storage', index: Number(arg) };
    }
    const parts = String(arg).split(':');
    if (parts.length !== 2) return null;
    const source = parts[0] as PastureRosterSource;
    if (source !== 'storage' && source !== 'team' && source !== 'pension') return null;
    const index = parseInt(parts[1] ?? '', 10);
    if (Number.isNaN(index)) return null;
    return { source, index };
}

export function unassignMiltankFromPastureLogic(game: GameRuntime, uid: string): boolean {
    const state = ensureMiltankFarmState(game);
    if (!state.unlocked) return false;
    if (uid === NARRATIVE_MILTANK_UID) return false;

    const creatures = state.pastureCreatures ?? [];
    const idx = creatures.findIndex((c) => c && String(c.uid) === uid);
    if (idx < 0) return false;

    const creature = creatures.splice(idx, 1)[0];
    if (!creature) return false;

    unassignGuardianFromPastureLogic(game, uid);

    game.storage = game.storage ?? [];
    game.storage.push(creature);
    normalizeMiltankFarmState(state);

    logMessage(farmText(
        game,
        'unassigned',
        '{name} quitte le pâturage.',
        '{name} left the pasture.',
        { name: creature.name || 'Miltank' },
    ));

    if (typeof game.updateStorageDisplay === 'function') game.updateStorageDisplay();
    publishMiltankFarmAfterMutation();
    game.saveGame?.();
    return true;
}

export function unassignMiltankFromPastureIfPresent(game: GameRuntime, uid: string): void {
    if (!uid || !game.miltankFarmState?.unlocked) return;
    const creatures = game.miltankFarmState.pastureCreatures ?? [];
    if (!creatures.some((c) => c && String(c.uid) === uid)) return;
    unassignMiltankFromPastureLogic(game, uid);
}

export type GuardianAssignRejectReason =
    | 'not_canid'
    | 'invalid_pasture'
    | 'already_guardian'
    | 'in_pasture'
    | 'pasture_has_guardian'
    | 'guardians_locked';

function logGuardianAssignReject(game: GameRuntime, reason: GuardianAssignRejectReason): void {
    const messages: Record<GuardianAssignRejectReason, [string, string]> = {
        not_canid: [
            'Seuls les Pokémon canidés peuvent garder le pâturage.',
            'Only canine Pokémon can guard the pasture.',
        ],
        invalid_pasture: [
            'Ce Miltank n\'est pas au pâturage.',
            'This Miltank is not in the pasture.',
        ],
        already_guardian: [
            'Ce Pokémon garde déjà un autre Miltank.',
            'This Pokémon is already guarding another Miltank.',
        ],
        in_pasture: [
            'Un Miltank au pâturage ne peut pas être gardien.',
            'A pasture Miltank cannot also be a guardian.',
        ],
        pasture_has_guardian: [
            'Ce Miltank a déjà un gardien.',
            'This Miltank already has a guardian.',
        ],
        guardians_locked: [
            'Les gardiens se débloquent avec la quête pâturage du Village Pokémon.',
            'Guardians unlock with the Pokemon Village pasture quest.',
        ],
    };
    const keys: Record<GuardianAssignRejectReason, string> = {
        not_canid: 'guardianNotCanid',
        invalid_pasture: 'guardianInvalidPasture',
        already_guardian: 'guardianAlreadyAssigned',
        in_pasture: 'guardianInPasture',
        pasture_has_guardian: 'guardianPastureFull',
        guardians_locked: 'guardianLocked',
    };
    const [fr, en] = messages[reason];
    logMessage(farmText(game, keys[reason], fr, en));
}

function isCreatureInPasture(state: MiltankFarmState, uid: string): boolean {
    return (state.pastureCreatures ?? []).some((c) => c && String(c.uid) === uid);
}

function isCreatureGuardianElsewhere(state: MiltankFarmState, uid: string, pastureUid: string): boolean {
    return (state.guardianAssignments ?? []).some(
        (a) => a.pastureUid !== pastureUid && a.creature && String(a.creature.uid) === uid,
    );
}

export function assignGuardianToPastureLogic(
    game: GameRuntime,
    pastureUid: string,
    source: PastureRosterSource,
    index: number,
): boolean {
    const state = ensureMiltankFarmState(game);
    if (!state.unlocked) return false;
    const threatCtx = buildFarmThreatContext(game);
    if (!areGuardiansUnlocked(state, threatCtx)) {
        logGuardianAssignReject(game, 'guardians_locked');
        return false;
    }

    const entry = state.pastureEntries?.find((e) => e.uid === pastureUid);
    if (!entry) {
        logGuardianAssignReject(game, 'invalid_pasture');
        return false;
    }

    if (getGuardianForPastureUid(state, pastureUid)) {
        logGuardianAssignReject(game, 'pasture_has_guardian');
        return false;
    }

    const arr = getPastureRosterArray(game, source);
    if (!arr || index < 0 || index >= arr.length) return false;

    const creature = arr[index] as CreatureData | undefined;
    if (!creature) return false;

    const uid = String(creature.uid || '');
    if (!uid) return false;

    if (!isGuardianSpecies(creature)) {
        logGuardianAssignReject(game, 'not_canid');
        return false;
    }

    if (isMiltankInUltimateSlot(game, uid)) {
        logMessage(farmText(
            game,
            'inUltimate',
            'Ce Pokémon est en slot ultime — retire-le d\'abord.',
            'This Pokémon is in the ultimate slot — remove it first.',
        ));
        return false;
    }

    if (isCreatureInPasture(state, uid)) {
        logGuardianAssignReject(game, 'in_pasture');
        return false;
    }

    if (isCreatureGuardianElsewhere(state, uid, pastureUid)) {
        logGuardianAssignReject(game, 'already_guardian');
        return false;
    }

    const removed = removePastureRosterCreature(game, source, index);
    if (!removed) return false;

    state.guardianAssignments = state.guardianAssignments ?? [];
    state.guardianAssignments.push({ pastureUid, creature: removed });
    normalizeMiltankFarmState(state);

    logMessage(farmText(
        game,
        'guardianAssigned',
        '{name} garde {target} !',
        '{name} is guarding {target}!',
        { name: String(removed.name || removed.species || 'Guardian'), target: getPastureEntryDisplayName(game, state, entry) },
    ));

    if (typeof game.checkAchievements === 'function') {
        if (!game.stats || typeof game.stats !== 'object') game.stats = {} as GameRuntime['stats'];
        const sc = game.stats as unknown as Record<string, number>;
        sc.miltankFarmGuardianAssigned = (Number(sc.miltankFarmGuardianAssigned) || 0) + 1;
        game.checkAchievements('miltankFarmGuardianAssigned');
    }
    if (typeof game.checkSpecialQuests === 'function') {
        game.checkSpecialQuests('miltank_farm_guardian_assigned');
    }

    if (typeof game.updateStorageDisplay === 'function') game.updateStorageDisplay();
    if (typeof game.updateTeamDisplay === 'function') game.updateTeamDisplay();
    if (typeof game.updatePensionDisplay === 'function') game.updatePensionDisplay();
    if (source === 'team' && typeof game.calculateTeamStats === 'function') game.calculateTeamStats();
    publishMiltankFarmAfterMutation();
    game.saveGame?.();
    return true;
}

export function parseGuardianAssignArg(
    arg: string,
): { pastureUid: string; source: PastureRosterSource; index: number } | null {
    const parts = String(arg).split(':');
    if (parts.length !== 3) return null;
    const pastureUid = parts[0] ?? '';
    const source = parts[1] as PastureRosterSource;
    if (!pastureUid || (source !== 'storage' && source !== 'team' && source !== 'pension')) return null;
    const index = parseInt(parts[2] ?? '', 10);
    if (Number.isNaN(index)) return null;
    return { pastureUid, source, index };
}

export function unassignGuardianFromPastureLogic(game: GameRuntime, pastureUid: string): boolean {
    const state = ensureMiltankFarmState(game);
    if (!state.unlocked) return false;

    const assignments = state.guardianAssignments ?? [];
    const idx = assignments.findIndex((a) => a.pastureUid === pastureUid);
    if (idx < 0) return false;

    const assignment = assignments.splice(idx, 1)[0];
    const creature = assignment?.creature;
    if (!creature) return false;

    game.storage = game.storage ?? [];
    game.storage.push(creature);
    state.guardianAssignments = assignments;
    normalizeMiltankFarmState(state);

    logMessage(farmText(
        game,
        'guardianUnassigned',
        '{name} ne garde plus le pâturage.',
        '{name} is no longer guarding the pasture.',
        { name: String(creature.name || creature.species || 'Guardian') },
    ));

    if (typeof game.updateStorageDisplay === 'function') game.updateStorageDisplay();
    publishMiltankFarmAfterMutation();
    game.saveGame?.();
    return true;
}

export function unassignGuardianIfPresent(game: GameRuntime, uid: string): void {
    if (!uid || !game.miltankFarmState?.unlocked) return;
    const assignments = game.miltankFarmState.guardianAssignments ?? [];
    const match = assignments.find((a) => a.creature && String(a.creature.uid) === uid);
    if (!match) return;
    unassignGuardianFromPastureLogic(game, match.pastureUid);
}

const VALID_TALENT_BRANCHES = new Set<MiltankFarmTalentBranch>(['production', 'milk_potency', 'care']);

export function investMiltankFarmTalentLogic(game: GameRuntime, branchKey: string): boolean {
    const state = ensureMiltankFarmState(game);
    if (!state.unlocked) return false;
    const branch = branchKey as MiltankFarmTalentBranch;
    if (!VALID_TALENT_BRANCHES.has(branch)) return false;

    const entry = getSelectedPastureEntry(state);
    if (!entry) return false;

    if (!investMiltankFarmTalentForEntry(entry, branch)) {
        logMessage(farmText(
            game,
            'talentNoPoints',
            'Aucun point de talent disponible ou branche au maximum.',
            'No talent points available or branch at max rank.',
        ));
        return false;
    }

    normalizeMiltankFarmState(state);
    if (branch === 'care') {
        if (!state.uiHintsSeen || typeof state.uiHintsSeen !== 'object') {
            state.uiHintsSeen = {};
        }
        state.uiHintsSeen.secondPastureCare = true;
    }
    if (branch === 'milk_potency') {
        syncVitaminEfficiencyFromMilkPotency(game);
        if (typeof game.updatePlayerStatsDisplay === 'function') game.updatePlayerStatsDisplay();
    }
    logMessage(farmText(
        game,
        'talentInvested',
        'Talent amélioré : {branch}.',
        'Talent upgraded: {branch}.',
        { branch: branchKey },
    ));
    publishMiltankFarmAfterMutation();
    game.saveGame?.();
    return true;
}

export function isMiltankFarmUnlocked(game: GameRuntime): boolean {
    return !!(game.miltankFarmState?.unlocked || game.unlockedFeatures?.miltankFarm);
}

/** True when the Kalos farm onboarding modal should be shown. */
export function shouldShowMiltankFarmIntro(game: GameRuntime): boolean {
    if (game.miltankFarmIntroShown) return false;
    return isMiltankFarmUnlocked(game);
}

export function showMiltankFarmUnlockModal(game: GameRuntime): boolean {
    if (!game || typeof game.t !== 'function') return false;
    if (typeof document === 'undefined' || !document.body) return false;
    if (typeof narrativeManager.showInfoModal !== 'function') return false;

    const title = game.t('miltankFarm.unlockModalTitle', 'Ferme Écrémeuh débloquée !');
    const body = game.t(
        'miltankFarm.unlockModalBody',
        'La Route 12 cache un pâturage paisible. Ouvre la ferme depuis la carte de zone et nourris Écrémeuh une fois.',
    );
    narrativeManager.showInfoModal(game, title, body);
    return true;
}

function showMiltankFarmUnlockFallbackToast(game: GameRuntime): void {
    toast?.info?.(
        game.t('miltankFarm.unlockModalTitle', 'Ferme Écrémeuh débloquée !'),
        game.t(
            'miltankFarm.unlockModalBody',
            'La Route 12 cache un pâturage paisible. Ouvre la ferme depuis la carte de zone et nourris Écrémeuh une fois.',
        ),
    );
}

export function maybeShowMiltankFarmIntro(game: GameRuntime): void {
    if (!shouldShowMiltankFarmIntro(game)) return;

    const finalizeIntro = (): void => {
        if (!shouldShowMiltankFarmIntro(game)) return;
        if (showMiltankFarmUnlockModal(game)) {
            game.miltankFarmIntroShown = true;
            publishMiltankFarmChanged();
            game.saveGame?.({ immediate: true, reason: 'miltank_farm_intro' });
            return;
        }
        showMiltankFarmUnlockFallbackToast(game);
        game.miltankFarmIntroShown = true;
        publishMiltankFarmChanged();
        game.saveGame?.({ immediate: true, reason: 'miltank_farm_intro' });
    };

    if (typeof requestAnimationFrame === 'function') {
        requestAnimationFrame(() => requestAnimationFrame(finalizeIntro));
        return;
    }
    setTimeout(finalizeIntro, 0);
}

type GameCtor = { prototype: Record<string, unknown> };

export function applyMiltankFarmIntroSystem(GameClass: GameCtor): void {
    GameClass.prototype.maybeShowMiltankFarmIntro = function (this: GameRuntime): void {
        maybeShowMiltankFarmIntro(this);
    };

    GameClass.prototype.catchUpMiltankFarmIntroOnLoad = function (this: GameRuntime): void {
        maybeShowMiltankFarmIntro(this);
    };
}
