/**
 * CT (TM) compatibility — single table loaded from autogen/ctCompatibility.json.
 * Source of truth: data/autogen/roster-machine-by-move.json (see data/autogen/README.md).
 */

let ctTable: Record<string, string[]> | null = null;

export function isCtCompatibilityLoaded(): boolean {
    return ctTable !== null;
}

export function getCtCompatibilityTable(): Record<string, string[]> | null {
    return ctTable;
}

export function initCtCompatibility(data: Record<string, string[]>): void {
    ctTable = data;
    const g = globalThis as unknown as Record<string, unknown>;
    g.CT_COMPATIBILITY = data;
    g.canLearnCT = canLearnCT;
    if (typeof window !== 'undefined') {
        (window as unknown as Record<string, unknown>).CT_COMPATIBILITY = data;
        (window as unknown as Record<string, unknown>).canLearnCT = canLearnCT;
    }
}

export function normalizeCTLookupKey(value: string): string {
    return String(value || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/[\u0153]/g, 'oe')
        .replace(/[\u00E6]/g, 'ae')
        .replace(/[\u2019`\u00B4]/g, "'")
        .replace(/[_-]/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
        .toLowerCase();
}

function inCompatList(list: string[] | undefined, pokemonName: string): boolean {
    if (!Array.isArray(list)) return false;
    if (list.includes(pokemonName)) return true;
    const normalizedPokemon = normalizeCTLookupKey(pokemonName);
    return list.some((name) => normalizeCTLookupKey(name) === normalizedPokemon);
}

export function canLearnCT(pokemonName: string, moveName: string): boolean {
    if (!pokemonName || !moveName || !ctTable) return false;

    const normalizedMove = normalizeCTLookupKey(moveName);

    const exact = ctTable[moveName];
    if (inCompatList(exact, pokemonName)) return true;

    const matchedKey = Object.keys(ctTable).find(
        (name) => normalizeCTLookupKey(name) === normalizedMove,
    );
    if (matchedKey && inCompatList(ctTable[matchedKey], pokemonName)) return true;

    return false;
}

if (typeof globalThis !== 'undefined') {
    (globalThis as unknown as Record<string, unknown>).canLearnCT = canLearnCT;
}
