/**
 * Coalesce quest panel snapshot rebuilds off the 1 Hz game tick.
 */

import type { GameRuntime } from '../types/game.js';

type DisplayRefreshFn = (game: GameRuntime) => void;

let pendingGame: GameRuntime | null = null;
let scheduled = false;
let refreshImpl: DisplayRefreshFn | null = null;

function flush(): void {
  scheduled = false;
  const game = pendingGame;
  pendingGame = null;
  if (game && refreshImpl) refreshImpl(game);
}

function scheduleFlush(): void {
  if (scheduled) return;
  scheduled = true;
  const ric = typeof requestIdleCallback === 'function' ? requestIdleCallback : null;
  if (ric) {
    ric(flush, { timeout: 120 });
  } else if (typeof requestAnimationFrame === 'function') {
    requestAnimationFrame(flush);
  } else {
    setTimeout(flush, 0);
  }
}

/** Register the legacy display refresh (avoids questSystem ↔ scheduler circular import at init). */
export function registerQuestsDisplayRefresh(fn: DisplayRefreshFn): void {
  refreshImpl = fn;
}

/** Cancel a pending idle refresh (sync display already reflects latest state). */
export function cancelPendingQuestsDisplayRefresh(): void {
  pendingGame = null;
  scheduled = false;
}

export function scheduleQuestsDisplayRefresh(
  game: GameRuntime,
  opts?: { immediate?: boolean },
): void {
  if (opts?.immediate) {
    pendingGame = null;
    scheduled = false;
    refreshImpl?.(game);
    return;
  }
  pendingGame = game;
  scheduleFlush();
}

/** @internal Vitest only */
export function resetScheduleQuestsDisplayRefreshForTests(): void {
  pendingGame = null;
  scheduled = false;
}
