import type { GameRuntime } from '../types/game.ts';
import { uiText } from '../ui/i18n.ts';

export function formatSubwayZoneLabel(game: GameRuntime | null | undefined): string {
    const wagon = game?.subwayState?.wagonIndex ?? 1;
    const battle = game?.subwayState?.currentBattle ?? 1;
    return uiText(
        'zone.subwayWagon',
        'BATTLE SUBWAY - WAGON {wagon} - BATTLE {battle}/7',
        { wagon, battle },
        game,
    );
}
