/**
 * Team synergy detection (TEAM_SYNERGIES) shared by combat, quests, and UI.
 */
import type { GameRuntime } from '../types/game.js';
import {
    countActiveTeamSynergies,
    hasActiveTeamSynergy as hasActiveTeamSynergyEval,
    type TeamSynergyMember,
} from './teamSynergyEvaluation.ts';

export type { TeamSynergyMember } from './teamSynergyEvaluation.ts';

export function countActiveTeamSynergiesFromTeam(
    team: TeamSynergyMember[] | null | undefined,
    game?: GameRuntime | null,
): number {
    return countActiveTeamSynergies(team, game);
}

export function hasActiveTeamSynergy(
    team: TeamSynergyMember[] | null | undefined,
    game?: GameRuntime | null,
): boolean {
    return hasActiveTeamSynergyEval(team, game);
}

export function hasActiveTeamSynergyOnGame(game: {
    playerTeam?: TeamSynergyMember[] | null;
}): boolean {
    return hasActiveTeamSynergy(game.playerTeam, game as GameRuntime);
}
