/**
 * Species rarity for captured Pokémon (not encounter-tier rarity on boss/epic enemies).
 */

import { RARITY } from '../../constants/core.ts';
import type { GameRuntime } from '../types/game.js';

export function speciesRarityForCapture(game: GameRuntime, speciesName: string): string {
    if (typeof game.getNaturalRarity === 'function') {
        return game.getNaturalRarity(speciesName);
    }
    return RARITY.COMMON;
}
