/**
 * Pure helpers for game.unlockedNatures (family nature unlock registry).
 */
import { getAllNatureIds, isValidNatureId, normalizeNatureId } from '../../constants/balance/natures.ts';
import { moveUnlockKey } from './pokemonLearnset.ts';
import type { GameRuntime } from '../types/game.js';

export function natureUnlockKey(creatureName: string): string {
    return moveUnlockKey(creatureName);
}

export function normalizeUnlockedNatureList(sourceNatures: string[]): string[] {
    const seen = new Set<string>();
    const cleaned: string[] = [];
    (sourceNatures || []).forEach((natureId: string) => {
        const normalized = normalizeNatureId(natureId);
        if (!isValidNatureId(normalized)) return;
        if (seen.has(normalized)) return;
        seen.add(normalized);
        cleaned.push(normalized);
    });
    return cleaned;
}

export function unlockedNaturesForCreature(game: GameRuntime, creatureName: string): string[] {
    const registryKey = natureUnlockKey(creatureName);
    if (!registryKey) return [];
    const raw = game.unlockedNatures?.[registryKey];
    if (!Array.isArray(raw)) return [];
    return normalizeUnlockedNatureList(raw);
}

export function mergeUnlockedNaturesRegistry(
    existing: Record<string, string[]> | null | undefined,
    equippedByRegistryKey: Record<string, string[]>,
): Record<string, string[]> {
    const merged: Record<string, string[]> = {};

    const addToKey = (rawKey: string, natures: string[]) => {
        const key = natureUnlockKey(rawKey) || rawKey;
        if (!merged[key]) merged[key] = [];
        normalizeUnlockedNatureList(natures).forEach((natureId) => {
            if (!merged[key].includes(natureId)) merged[key].push(natureId);
        });
    };

    if (existing && typeof existing === 'object') {
        Object.keys(existing).forEach((key) => {
            const raw = existing[key];
            if (!Array.isArray(raw) || raw.length === 0) return;
            addToKey(key, raw);
        });
    }

    Object.keys(equippedByRegistryKey).forEach((key) => {
        const raw = equippedByRegistryKey[key];
        if (!Array.isArray(raw) || raw.length === 0) return;
        addToKey(key, raw);
    });

    const result: Record<string, string[]> = {};
    Object.keys(merged).forEach((key) => {
        const list = normalizeUnlockedNatureList(merged[key] ?? []);
        if (list.length > 0) result[key] = list;
    });
    return result;
}

export function getRemainingUnlockableNatureIds(unlocked: string[]): string[] {
    const unlockedSet = new Set(normalizeUnlockedNatureList(unlocked));
    return getAllNatureIds().filter((id) => !unlockedSet.has(id));
}
