/**
* @file narrativeManager.ts
* Professor Chen Narrative Engine — intro, milestones, tutorials.
* Handles dialogue triggers, fake/real starter choice, and achievement unlock.
* Depends: narrativeData.ts, toastManager (toast), game (Game), Creature, TYPES, RARITY.
*/

import type { GameRuntime, QuestData } from './src/types/game.js';
import type { CreatureData } from './src/types/creature.js';
import { CHEN_SPRITE_URL, narrativeData, narrativeDataEN, NARRATIVE_FAKE_STARTERS, NARRATIVE_REAL_STARTERS, NARRATIVE_REAL_STARTERS_EN, NARRATIVE_MILESTONES, NARRATIVE_UGLY_REVEAL_TEXT } from './narrativeData.ts';
import { coerceStr } from './src/lib/coerceStr.ts';
import { STORY_QUESTS } from './constants/storyQuests.ts';
import { TYPES, RARITY } from './constants/core.ts';
import { Creature } from './Creature.ts';
import { toast } from './toastManager.ts';
import { logMessage } from './src/ui/modals.ts';
import { switchTab } from './src/ui/navigation.ts';
import { escapeHtml } from './formatters.ts';
import { localizePokemonName } from './constants/pokemonNameI18n.ts';
import {
    getQuestDisplayTitle,
    getQuestDisplayDescription,
    getQuestDisplayDialogue,
} from './questSystem.ts';

interface NarrativeState {
    introComplete: boolean;
    starterChoice: string | null;
    milestonesSeen: number[];
    phase: string;
    suppressNextStoryQuestIntro?: boolean;
    billionComplete?: boolean;
}

interface NarrativeSaveData {
    introComplete: boolean;
    starterChoice: string | null;
    milestonesSeen: number[];
}

interface BindDataParams {
    speaker?: string;
    title?: string;
    text?: string;
    rewards?: string;
    extraHtml?: string;
    indicator?: string;
    actions?: BindAction[];
    choiceCallback?: ((btn: HTMLElement) => void) | null;
    actionCallback?: ((action: BindAction, idx: string) => void) | null;
    boxClass?: string;
    epicHtml?: string;
}

interface BindAction {
    text: string;
    class?: string;
    id?: string;
}

interface StarterPoolOption {
    key: string;
    name?: string;
    displayName?: string;
}

interface NarrativeStrings {
    INTRO: string;
    INTRO_PARTS: string[];
    INFLATION_RANT: string;
    INFLATION_RANT_PARTS: string[];
    POST_CHOICE_RANT: string;
    POST_CHOICE_RANTPARTS: string[];
    POST_CHOICE_STARTER_RECEIVED: string;
    MILESTONE_10K: string;
    MILESTONE_100K: string;
    MILESTONE_1M: string;
    BILLION_INTRO: string;
    BILLION_INTRO_PARTS: string[];
}

interface StoryDef {
    id: string;
    title?: string;
    description?: string;
    dialogue?: string;
    rewardsHtml?: string;
}

type RuntimeStoryQuest = QuestData & {
    questType?: string;
    claimed?: boolean;
    dialogue?: string;
};

export class NarrativeManager {
    state: NarrativeState;
    overlay: HTMLElement | null;
    epicAnimationTimeout: ReturnType<typeof setTimeout> | null;
    postChoicePartIndex: number;
    introPartIndex: number;
    inflationPartIndex: number;
    postChoiceDelayTimeout: ReturnType<typeof setTimeout> | null;
    firstStoryQuestTimeout: ReturnType<typeof setTimeout> | null;
    narrativeStatsBlurResizeHandler: (() => void) | null;
    POST_CHOICE_DELAY_MS: number;
    FIRST_STORY_QUEST_DELAY_MS: number;
    currentChoiceCallback: ((btn: HTMLElement) => void) | null;
    currentActionCallback: ((idx: string) => void) | null;

    constructor() {
        this.state = {
            introComplete: false,
            starterChoice: null,
            milestonesSeen: [],
            phase: 'idle'
        };
        this.overlay = null;
        this.epicAnimationTimeout = null;
        this.postChoicePartIndex = 0;
        this.introPartIndex = 0;
        this.inflationPartIndex = 0;

        this.postChoiceDelayTimeout = null;
        this.firstStoryQuestTimeout = null;
        this.narrativeStatsBlurResizeHandler = null;

        this.POST_CHOICE_DELAY_MS = 5000;
        this.FIRST_STORY_QUEST_DELAY_MS = 1500;

        this.currentChoiceCallback = null;
        this.currentActionCallback = null;
    }

    static getTotalStats(game: GameRuntime | null): number {
        if (!game || !game.playerMainStats) return 0;
        const s = game.playerMainStats;
        return (s.hp || 0) + (s.attack || 0) + (s.spattack || 0) + (s.defense || 0) + (s.spdefense || 0) + (s.speed || 0);
    }

    getSaveData(): NarrativeSaveData {
        return {
            introComplete: this.state.introComplete,
            starterChoice: this.state.starterChoice,
            milestonesSeen: [...this.state.milestonesSeen]
        };
    }

    loadSaveData(data: NarrativeSaveData | null): void {
        if (!data) return;
        this.state.introComplete = data.introComplete === true;
        this.state.starterChoice = data.starterChoice || null;
        this.state.milestonesSeen = Array.isArray(data.milestonesSeen) ? data.milestonesSeen : [];
    }

    getLang(game: GameRuntime | null): string {
        if (!game || typeof game.normalizeLanguage !== 'function') return 'fr';
        return game.normalizeLanguage(game.language);
    }

    tr(game: GameRuntime | null, key: string, fallbackFr: string, fallbackEn: string, vars: Record<string, unknown> = {}): string {
        if (game && typeof game.t === 'function' && key) {
            const translated = game.t(key, vars);
            if (translated && translated !== key) return translated;
        }
        const tpl = this.getLang(game) === 'en' ? fallbackEn : fallbackFr;
        const localizedVars = (typeof localizeTemplateSubstitutionVars === 'function' && game)
            ? localizeTemplateSubstitutionVars(game, vars)
            : vars;
        return String(tpl || '').replace(/\{(\w+)\}/g, (_, k: string) => (localizedVars[k] != null ? coerceStr(localizedVars[k]) : ''));
    }

    getNarrativeData(game: GameRuntime | null): NarrativeStrings {
        if (this.getLang(game) === 'en') {
            if (narrativeDataEN && typeof narrativeDataEN === 'object') return narrativeDataEN;
        }
        return narrativeData;
    }

    getStarterPools(_game: GameRuntime | null): { fakeStarters: StarterPoolOption[]; realStarters: StarterPoolOption[] } {
        const realStarters = (this.getLang(_game) === 'en' && Array.isArray(NARRATIVE_REAL_STARTERS_EN) && NARRATIVE_REAL_STARTERS_EN.length > 0)
            ? NARRATIVE_REAL_STARTERS_EN
            : NARRATIVE_REAL_STARTERS;
        return { fakeStarters: NARRATIVE_FAKE_STARTERS, realStarters };
    }

    getStarterDisplayName(game: GameRuntime | null, starterKey: string): string {
        const pools = this.getStarterPools(game);
        const found = (pools.realStarters || []).find(s => s && s.key === starterKey);
        if (found) return found.displayName || found.name || String(starterKey || '');
        if (starterKey === 'weedle') return this.tr(game, '', 'Chenipan', 'Weedle');
        if (starterKey === 'caterpie') return this.tr(game, '', 'Aspicot', 'Caterpie');
        return String(starterKey || '');
    }

    getPokemonDisplayName(game: GameRuntime | null, name: string): string {
        const raw = String(name || '');
        if (!raw) return raw;
        const lang = this.getLang(game);
        return localizePokemonName(raw, lang);
    }

    ensureOverlay(): void {
        if (this.overlay) return;
        this.overlay = document.createElement('div');
        this.overlay.id = 'narrativeOverlay';
        this.overlay.className = 'narrative-overlay js-modal-overlay';

        const url = CHEN_SPRITE_URL;
        const img = url ? `<img src="${url}" alt="Chen" class="narrative-chen-sprite" onerror="this.style.display='none'; if(this.nextElementSibling) this.nextElementSibling.classList.add('narrative-chen-fallback-visible');">` : '';
        const fallback = '<span class="narrative-chen-fallback">👨‍🔬</span>';

        this.overlay.innerHTML = `
           <div class="narrative-dialogue js-modal-content" id="narrativeDialogueBox">
               <div class="narrative-dialogue-inner" id="narrativeInnerBox">
                   <div class="narrative-chen-column" id="narrativeChenSprite">
                       ${img}${fallback}
                   </div>
                   <div class="narrative-content-column">
                       <div class="narrative-speaker" id="narrativeSpeaker">Professor Chen</div>
                       <div class="narrative-story-quest-title" id="narrativeTitle" style="display:none;"></div>
                       <div class="narrative-text" id="narrativeText"></div>
                       <div class="narrative-quest-rewards-title" id="narrativeRewardsTitle" style="display:none;">Rewards received</div>
                       <div class="narrative-quest-rewards" id="narrativeRewards" style="display:none;"></div>
                       <div class="narrative-starters" id="narrativeExtraContainer" style="display:none;"></div>
                       <div class="narrative-page-indicator" id="narrativePageIndicator" style="display:none;"></div>
                       <div class="narrative-actions" id="narrativeActionsContainer"></div>
                   </div>
               </div>
               <div id="narrativeEpicContainer" style="display:none; width:100%;"></div>
           </div>
       `;
        document.body.appendChild(this.overlay);

        document.getElementById('narrativeActionsContainer')!.addEventListener('click', (e) => {
            const btn = (e.target as HTMLElement).closest('button');
            if (btn && this.currentActionCallback) {
                this.currentActionCallback(btn.dataset.actionId!);
            }
        });

        document.getElementById('narrativeExtraContainer')!.addEventListener('click', (e) => {
            const btn = (e.target as HTMLElement).closest('.narrative-starter-btn');
            if (btn instanceof HTMLElement && this.currentChoiceCallback) {
                this.currentChoiceCallback(btn);
            }
        });
    }

    bindData({ speaker = "", title = "", text = "", rewards = "", extraHtml = "", indicator = "", actions = [], choiceCallback = null, actionCallback = null, boxClass = "", epicHtml = "" }: BindDataParams): void {
        this.ensureOverlay();
        const gameRef = (typeof window !== 'undefined' && window.game) ? window.game : null;
        const effectiveSpeaker = speaker || this.tr(gameRef, '', 'Professeur Chen', 'Professor Chen');

        const box = document.getElementById('narrativeDialogueBox')!;
        box.className = 'narrative-dialogue js-modal-content ' + boxClass;

        const innerBox = document.getElementById('narrativeInnerBox')!;
        const epicBox = document.getElementById('narrativeEpicContainer')!;

        if (epicHtml) {
            if (this.overlay) this.overlay.classList.remove('narrative-game-modal-overlay');
            innerBox.style.display = 'none';
            epicBox.innerHTML = epicHtml;
            epicBox.style.display = 'block';
            return;
        } else {
            innerBox.style.display = 'flex';
            epicBox.style.display = 'none';
            epicBox.innerHTML = '';
        }

        if (this.overlay) {
            const bc = String(boxClass || '');
            const useGameModalChrome = bc.includes('narrative-game-modal')
                || bc.includes('narrative-story-quest')
                || bc.includes('narrative-billion');
            if (useGameModalChrome) this.overlay.classList.add('narrative-game-modal-overlay');
            else this.overlay.classList.remove('narrative-game-modal-overlay');
        }

        const elSpeaker = document.getElementById('narrativeSpeaker')!;
        if (effectiveSpeaker) { elSpeaker.textContent = effectiveSpeaker; elSpeaker.style.display = 'block'; } else elSpeaker.style.display = 'none';

        const elTitle = document.getElementById('narrativeTitle')!;
        if (title) { elTitle.innerHTML = title; elTitle.style.display = 'block'; } else elTitle.style.display = 'none';

        const elText = document.getElementById('narrativeText')!;
        if (text) { elText.innerHTML = text; elText.style.display = 'block'; } else elText.style.display = 'none';

        const elRewardsTitle = document.getElementById('narrativeRewardsTitle')!;
        const elRewards = document.getElementById('narrativeRewards')!;
        if (elRewardsTitle) elRewardsTitle.textContent = this.tr(gameRef, '', 'Recompenses recues', 'Rewards received');
        if (rewards) {
            elRewards.innerHTML = rewards;
            elRewards.style.display = 'block';
            elRewardsTitle.style.display = 'block';
        } else {
            elRewards.style.display = 'none';
            elRewardsTitle.style.display = 'none';
        }

        const elExtra = document.getElementById('narrativeExtraContainer')!;
        if (extraHtml) {
            elExtra.innerHTML = extraHtml;
            elExtra.style.display = 'flex';
            this.currentChoiceCallback = choiceCallback;
        } else {
            elExtra.style.display = 'none';
            this.currentChoiceCallback = null;
        }

        const elInd = document.getElementById('narrativePageIndicator')!;
        if (indicator) { elInd.textContent = indicator; elInd.style.display = 'block'; } else elInd.style.display = 'none';

        const elActions = document.getElementById('narrativeActionsContainer')!;
        if (actions && actions.length > 0) {
            elActions.innerHTML = actions.map((a, i) => `<button type="button" class="${escapeHtml(a.class || 'narrative-continue-btn')}" data-action-id="${i}" id="${escapeHtml(a.id || '')}">${escapeHtml(a.text)}</button>`).join('');
            elActions.style.display = 'block';
            this.currentActionCallback = (idx) => {
                const action = actions[Number(idx)];
                if (actionCallback && action) actionCallback(action, idx);
            };
        } else {
            elActions.innerHTML = '';
            elActions.style.display = 'none';
            this.currentActionCallback = null;
        }
    }

    closeOverlay(): void {
        if (this.postChoiceDelayTimeout) { clearTimeout(this.postChoiceDelayTimeout); this.postChoiceDelayTimeout = null; }
        if (this.firstStoryQuestTimeout) { clearTimeout(this.firstStoryQuestTimeout); this.firstStoryQuestTimeout = null; }

        if (this.overlay) {
            this.overlay.classList.remove('narrative-open');
            this.overlay.classList.remove('narrative-game-modal-overlay');
        }
        this.setNarrativeStatsHighlight(false);
        this.state.phase = 'idle';
    }

    private getNarrativeHeaderElement(): HTMLElement | null {
        return document.querySelector('.header-afk-stack > .header')
            || document.querySelector('.game-container .header')
            || document.querySelector('.header');
    }

    private updateNarrativeStatsBlurInset(): void {
        const header = this.getNarrativeHeaderElement();
        if (!header) {
            document.documentElement.style.removeProperty('--narrative-stats-blur-top');
            return;
        }
        const bottom = Math.max(0, Math.ceil(header.getBoundingClientRect().bottom));
        document.documentElement.style.setProperty('--narrative-stats-blur-top', `${bottom}px`);
    }

    private setNarrativeStatsHighlight(active: boolean): void {
        if (active) {
            if (document.body) document.body.classList.add('narrative-stats-visible');
            this.updateNarrativeStatsBlurInset();
            if (!this.narrativeStatsBlurResizeHandler) {
                this.narrativeStatsBlurResizeHandler = () => this.updateNarrativeStatsBlurInset();
                window.addEventListener('resize', this.narrativeStatsBlurResizeHandler);
            }
            return;
        }
        if (document.body) document.body.classList.remove('narrative-stats-visible');
        document.documentElement.style.removeProperty('--narrative-stats-blur-top');
        if (this.narrativeStatsBlurResizeHandler) {
            window.removeEventListener('resize', this.narrativeStatsBlurResizeHandler);
            this.narrativeStatsBlurResizeHandler = null;
        }
    }

    startIntro(game: GameRuntime): void {
        if (this.state.introComplete) return;
        this.state.phase = 'intro';
        this.introPartIndex = 0;
        this.inflationPartIndex = 0;
        this.renderIntroContent(game, false);
        this.overlay!.classList.add('narrative-open');
    }

    renderIntroContent(game: GameRuntime, isRealChoice: boolean): void {
        const data = this.getNarrativeData(game);
        const starters = isRealChoice ? NARRATIVE_REAL_STARTERS : NARRATIVE_FAKE_STARTERS;
        const spriteBase = 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/versions/generation-v/black-white/';
        const parts: string[] = isRealChoice ? (data.INFLATION_RANT_PARTS || [data.INFLATION_RANT]) : (data.INTRO_PARTS || [data.INTRO]);
        const partIndex = isRealChoice ? this.inflationPartIndex : this.introPartIndex;
        const isLastPart = partIndex >= parts.length - 1;
        const text = parts[partIndex] ?? parts[parts.length - 1] ?? '';

        let extraHtml = '';
        if (isLastPart) {
            extraHtml = starters.map(s => `
               <button type="button" class="narrative-starter-btn ${isRealChoice ? 'narrative-real' : 'narrative-fake'}" data-key="${s.key}" data-name="${s.name}" data-sprite-id="${s.spriteId}">
                   <img src="${spriteBase}${s.spriteId}.png" alt="${this.getPokemonDisplayName(game, s.displayName || s.name || '')}">
                   <span>${this.getPokemonDisplayName(game, s.displayName || s.name || '')}</span>
               </button>
           `).join('');
        }

        this.bindData({
            boxClass: 'narrative-game-modal',
            text: this.escapeHtml(text),
            indicator: isLastPart ? "" : `${partIndex + 1} / ${parts.length}`,
            extraHtml: extraHtml,
            actions: isLastPart ? [] : [{ text: this.tr(game, '', 'Suivant', 'Next'), class: 'narrative-next-btn' }],
            actionCallback: () => this.onIntroSlideNext(game, isRealChoice),
            choiceCallback: (btn) => this.onStarterClick(game, btn, isRealChoice)
        });
    }

    onIntroSlideNext(game: GameRuntime, isRealChoice: boolean): void {
        if (isRealChoice) {
            this.inflationPartIndex++;
            this.renderIntroContent(game, true);
        } else {
            this.introPartIndex++;
            this.renderIntroContent(game, false);
        }
    }

    onStarterClick(game: GameRuntime, btn: HTMLElement, isRealChoice: boolean): void {
        if (isRealChoice) {
            this.confirmRealStarter(game, btn.dataset.key!, btn.dataset.name!);
        } else {
            this.showInflationRant(game);
        }
    }

    showInflationRant(game: GameRuntime): void {
        this.state.phase = 'inflation_rant';
        this.renderIntroContent(game, true);
    }

    giveStarterToPlayer(game: GameRuntime): void {
        if (!game || !Array.isArray(game.playerTeam)) return;
        const creatureName = this.state.starterChoice === 'weedle' ? 'Weedle' : 'Caterpie';
        const displayName = this.state.starterChoice === 'weedle' ? 'Chenipan' : 'Aspicot';
        const creatureType = this.state.starterChoice === 'weedle' ? TYPES.POISON : TYPES.BUG;
        type StarterCreature = CreatureData & {
            isStarter?: boolean;
            ivHP?: number;
            ivAttack?: number;
            ivDefense?: number;
            ivSpAttack?: number;
            ivSpDefense?: number;
            ivSpeed?: number;
            recalculateStats?: () => void;
            heal?: () => void;
        };
        const starter = new Creature(creatureName, creatureType, 1, RARITY.COMMON, false) as StarterCreature;
        starter.isStarter = true;
        starter.ivHP = 8;
        starter.ivAttack = 8;
        starter.ivDefense = 8;
        starter.ivSpAttack = 8;
        starter.ivSpDefense = 8;
        starter.ivSpeed = 8;
        starter.recalculateStats?.();
        starter.heal?.();
        game.playerTeam.push(starter);
        game._suppressPokedollarsTracking = true;
        game.pokedollars = 0;
        game._suppressPokedollarsTracking = false;
        game.eggs.common = 0;
        if (!game.items) game.items = {};
        game.items['pokeball'] = 5;
        logMessage(this.tr(
            game,
            '',
            'Professeur Chen vous a confie {creature} ({display}) !',
            'Professor Chen entrusted you with {creature} ({display})!',
            { creature: creatureName, display: displayName }
        ));
        toast.success(
            this.tr(game, '', 'Starter recu !', 'Starter received!'),
            this.tr(game, '', '{name} rejoint votre equipe.', '{name} joins your team.', { name: displayName })
        );
        if (typeof game.updateDisplay === 'function') {
            game.updateDisplay(['team', 'zone', 'quests', 'shop', 'eggs', 'visibility']);
        }
    }

    confirmRealStarter(game: GameRuntime, key: string, _creatureName: string): void {
        if (this.state.starterChoice) return;
        this.state.starterChoice = key;
        this.state.phase = 'post_choice';
        this.giveStarterToPlayer(game);
        this.startGameEngineOnly(game);
        this.postChoicePartIndex = 0;
        this.renderPostChoiceContent(game);
    }

    startGameEngineOnly(game: GameRuntime): void {
        if (!game) return;
        if (typeof game.setupEggHandler === 'function') game.setupEggHandler();
        if (typeof game.setupIncubatorHandler === 'function') game.setupIncubatorHandler();
        game.lastTickTime = Date.now();
        if (typeof game.updateZoneSelector === 'function') game.updateZoneSelector();
        if (typeof game.updateDisplay === 'function') {
            game.updateDisplay(['team', 'zone', 'quests', 'shop', 'eggs', 'visibility']);
        }
        if (typeof game.startGameLoop === 'function') game.startGameLoop();
    }

    renderPostChoiceContent(game: GameRuntime): void {
        const data = this.getNarrativeData(game);
        const parts: string[] = data.POST_CHOICE_RANTPARTS || [data.POST_CHOICE_RANT];
        const totalSlides = 1 + (parts ? parts.length : 0);
        if (!parts || parts.length === 0) {
            this.finishIntro(game);
            return;
        }
        const partIndex = Math.min(this.postChoicePartIndex, totalSlides - 1);
        this.postChoicePartIndex = partIndex;
        const isLastPart = partIndex >= totalSlides - 1;
        const displayName = this.state.starterChoice === 'weedle' ? 'Chenipan' : 'Aspicot';
        const starterReceivedTpl = (data.POST_CHOICE_STARTER_RECEIVED
            || this.tr(game, '', 'Voila, {starter} est a toi !', 'Here you go, {starter} is yours!', { starter: displayName }))
            .replace('{starter}', displayName);
        const text = partIndex === 0 ? starterReceivedTpl : (parts[partIndex - 1] ?? parts[parts.length - 1] ?? '');

        const isStatsSlide = (partIndex === 3 && parts.length >= 3);
        this.setNarrativeStatsHighlight(isStatsSlide);

        this.bindData({
            boxClass: 'narrative-game-modal',
            text: this.escapeHtml(text),
            indicator: `${partIndex + 1} / ${totalSlides}`,
            actions: [{
                text: isLastPart
                    ? this.tr(game, '', "C'est parti !", "Let's go!")
                    : this.tr(game, '', 'Suivant', 'Next'),
                class: isLastPart ? 'narrative-continue-btn' : 'narrative-next-btn'
            }],
            actionCallback: () => isLastPart ? this.finishIntro(game) : this.onPostChoiceNext(game)
        });

        if (isStatsSlide) {
            requestAnimationFrame(() => {
                requestAnimationFrame(() => {
                    const header = this.getNarrativeHeaderElement();
                    if (header && typeof header.scrollIntoView === 'function') {
                        header.scrollIntoView({ block: 'start', behavior: 'smooth', inline: 'nearest' });
                    }
                    this.updateNarrativeStatsBlurInset();
                });
            });
        }
    }

    onPostChoiceNext(game: GameRuntime): void {
        const data = this.getNarrativeData(game);
        const parts = data.POST_CHOICE_RANTPARTS || [data.POST_CHOICE_RANT];
        const totalSlides = 1 + (parts ? parts.length : 0);
        const delaySlideIndex = 2;
        if (this.postChoicePartIndex === delaySlideIndex && totalSlides > delaySlideIndex + 1) {
            this.closeOverlay();
            if (this.postChoiceDelayTimeout) clearTimeout(this.postChoiceDelayTimeout);
            this.postChoiceDelayTimeout = setTimeout(() => {
                this.postChoiceDelayTimeout = null;
                if (!game) return;
                this.postChoicePartIndex = delaySlideIndex + 1;
                this.renderPostChoiceContent(game);
                if (this.overlay) this.overlay.classList.add('narrative-open');
            }, this.POST_CHOICE_DELAY_MS);
            return;
        }
        this.postChoicePartIndex++;
        this.renderPostChoiceContent(game);
    }

    finishIntro(game: GameRuntime): void {
        if (!game || !Array.isArray(game.playerTeam)) return;
        const alreadyHasStarter = game.playerTeam.length > 0 && !!this.state.starterChoice;
        if (!alreadyHasStarter) this.giveStarterToPlayer(game);

        this.state.introComplete = true;
        this.state.suppressNextStoryQuestIntro = true;
        this.closeOverlay();

        game.setupEggHandler();
        game.setupIncubatorHandler();
        game.lastTickTime = Date.now();
        game.updateZoneSelector();
        game.updateDisplay(['team', 'zone', 'quests', 'shop', 'eggs', 'visibility']);
        game.startGameLoop();
        if (typeof game.resetBalanceTelemetrySession === 'function') {
            game.resetBalanceTelemetrySession('narrative_intro_finish');
        }

        game.generateQuest();
        game.nextQuestTimer = 60000;

        this.scheduleFirstStoryQuestIntro(game);
        game.startAutoSave();
        game.saveGame();
    }

    scheduleFirstStoryQuestIntro(game: GameRuntime): void {
        if (this.firstStoryQuestTimeout) clearTimeout(this.firstStoryQuestTimeout);
        this.firstStoryQuestTimeout = setTimeout(() => {
            this.firstStoryQuestTimeout = null;
            if (game) this.showFirstStoryQuestIfAny(game);
        }, this.FIRST_STORY_QUEST_DELAY_MS);
    }

    showFirstStoryQuestIfAny(game: GameRuntime): void {
        if (!game || !game.quests) return;
        const storyQuest = game.quests.find((q) => {
            const row = q as RuntimeStoryQuest;
            return row.questType === 'STORY' && !row.claimed;
        });
        if (!storyQuest) return;

        const fallbackDef = Object.values(STORY_QUESTS).find((d) => d.id === storyQuest.id) ?? null;

        const storyAsQuest = storyQuest as unknown as import('./questSystem.ts').Quest;
        const titleRaw = getQuestDisplayTitle(game, storyAsQuest);
        const descRaw = getQuestDisplayDescription(game, storyAsQuest);
        const dialogueRaw = getQuestDisplayDialogue(game, storyAsQuest);
        const localizedStoryDef: StoryDef = {
            id: coerceStr(storyQuest.id),
            title: coerceStr(titleRaw),
            description: coerceStr(descRaw),
            dialogue: coerceStr(dialogueRaw),
        };

        this.state.suppressNextStoryQuestIntro = false;
        switchTab('quests');
        this.showStoryQuestIntro(game, localizedStoryDef);
    }

    checkMilestones(game: GameRuntime): void {
        if (!game) return;
        const total = NarrativeManager.getTotalStats(game);
        const data = this.getNarrativeData(game);

        for (const m of NARRATIVE_MILESTONES) {
            if (total >= m.value && !this.state.milestonesSeen.includes(m.value)) {
                this.state.milestonesSeen.push(m.value);
                const msg = data[m.key as keyof NarrativeStrings];
                if (typeof msg === 'string') this.showMilestoneModal(game, m.value, msg);
                if (game.saveGame) game.saveGame();
            }
        }
    }

    showInfoModal(game: GameRuntime, title: string, message: string): void {
        this.bindData({
            title: this.escapeHtml(title || this.tr(game, '', 'Information', 'Information')),
            text: this.escapeHtml(message || ''),
            boxClass: 'narrative-game-modal narrative-story-quest',
            actions: [{ text: this.tr(game, '', 'OK', 'OK'), class: "narrative-continue-btn" }],
            actionCallback: () => {
                this.closeOverlay();
                if (game && typeof game.saveGame === 'function') game.saveGame();
            }
        });
        this.overlay!.classList.add('narrative-open');
    }

    showMilestoneModal(game: GameRuntime, _value: number, message: string): void {
        this.bindData({
            boxClass: 'narrative-game-modal',
            text: this.escapeHtml(message),
            actions: [{ text: this.tr(game, '', 'OK', 'OK'), class: "narrative-continue-btn" }],
            actionCallback: () => {
                this.closeOverlay();
                if (game && game.saveGame) game.saveGame();
            }
        });
        this.overlay!.classList.add('narrative-open');
    }

    startBillionFinale(game: GameRuntime): void {
        if (this.state.billionComplete) return;
        this.state.billionComplete = true;
        this.state.phase = 'billion_intro';
        const data = this.getNarrativeData(game);
        const spriteBase = 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/versions/generation-v/black-white/';

        const optionsHtml = NARRATIVE_FAKE_STARTERS.map(s => `
           <button type="button" class="narrative-starter-btn" data-key="${s.key}">
               <img src="${spriteBase}${s.spriteId}.png" alt="${this.getPokemonDisplayName(game, s.name)}">
               <span>${this.getPokemonDisplayName(game, s.name)}</span>
           </button>
       `).join('');

        this.bindData({
            text: this.escapeHtml(data.BILLION_INTRO),
            extraHtml: optionsHtml,
            boxClass: 'narrative-game-modal narrative-billion',
            choiceCallback: () => this.onBillionStarterClick(game)
        });
        this.overlay!.classList.add('narrative-open');
    }

    onBillionStarterClick(game: GameRuntime): void {
        if (this.state.phase !== 'billion_intro') return;
        this.state.phase = 'billion_epic';
        const epicLabel = this.tr(game, '', 'LEGENDAIRE', 'LEGENDARY');
        const pokemonLabel = this.tr(game, '', 'Pokemon', 'Pokemon');

        this.bindData({
            epicHtml: `
               <div class="narrative-epic-fx">
                   <div class="narrative-epic-particles"></div>
                   <div class="narrative-epic-shake"></div>
                   <div class="narrative-epic-text">✨ ${this.escapeHtml(epicLabel)} ✨</div>
               </div>
           `,
            boxClass: 'narrative-epic'
        });

        const uglyText = NARRATIVE_UGLY_REVEAL_TEXT;

        this.epicAnimationTimeout = setTimeout(() => {
            this.epicAnimationTimeout = null;
            this.state.phase = 'billion_reveal';

            this.bindData({
                epicHtml: `
                   <div class="narrative-ugly-box">
                       <div class="narrative-ugly-title">${this.escapeHtml(pokemonLabel)}</div>
                       <div class="narrative-ugly-stats">${this.escapeHtml(uglyText)}</div>
                   </div>
               `,
                boxClass: 'narrative-reveal'
            });
            setTimeout(() => this.finishBillionFinale(game), 2500);
        }, 3500);
    }

    finishBillionFinale(game: GameRuntime): void {
        if (this.epicAnimationTimeout) { clearTimeout(this.epicAnimationTimeout); this.epicAnimationTimeout = null; }
        this.closeOverlay();
        if (game.saveGame) game.saveGame();
    }

    showStoryQuestCompletionSummary(game: GameRuntime, data: StoryDef, onContinue?: () => void): void {
        if (!data) return;
        const title = this.escapeHtml(data.title || this.tr(game, '', 'Quete terminee', 'Quest completed'));
        const desc = this.escapeHtml(data.description || '');
        const descPlain = String(data.description || '').trim();
        const dialoguePlain = String(data.dialogue || '').trim();
        const dialogue = data.dialogue ? this.escapeHtml(data.dialogue) : '';

        let finalDesc = desc;
        if (dialogue && dialoguePlain && dialoguePlain !== descPlain) {
            finalDesc += `<p class="narrative-quest-dialogue">"${dialogue}"</p>`;
        }

        this.bindData({
            speaker: this.tr(game, '', 'Quete terminee', 'Quest completed'),
            title: title,
            text: finalDesc,
            rewards: data.rewardsHtml || '',
            boxClass: 'narrative-game-modal narrative-story-quest narrative-quest-completion',
            actions: [{ text: this.tr(game, '', 'Continuer', 'Continue'), class: "narrative-continue-btn" }],
            actionCallback: () => {
                this.closeOverlay();
                if (typeof onContinue === 'function') onContinue();
            }
        });
        this.overlay!.classList.add('narrative-open');
    }

    showStoryQuestIntro(game: GameRuntime, storyDef: StoryDef): void {
        if (!storyDef) return;
        this.ensureOverlay();
        const title = storyDef.title || this.tr(game, '', 'Quete', 'Quest');
        const dialogue = storyDef.dialogue || storyDef.description || '';

        this.bindData({
            title: this.escapeHtml(title),
            text: this.escapeHtml(dialogue),
            boxClass: 'narrative-game-modal narrative-story-quest',
            actions: [{ text: this.tr(game, '', 'Compris', 'Understood'), class: "narrative-continue-btn" }],
            actionCallback: () => {
                this.closeOverlay();
                if (storyDef.id === 'story_shop_improvements') {
                    switchTab('boutique');
                    if (typeof switchShopSubTab === 'function') switchShopSubTab('pokedollars');
                } else {
                    switchTab('quests');
                }
            }
        });
        this.overlay!.classList.add('narrative-open');
    }

    escapeHtml(str: string): string {
        if (!str) return '';
        const div = document.createElement('div');
        div.textContent = str;
        return div.innerHTML;
    }
}

const narrativeManager = new NarrativeManager();
if (typeof globalThis !== 'undefined') {
    (globalThis as { narrativeManager?: NarrativeManager; NarrativeManager?: typeof NarrativeManager }).narrativeManager = narrativeManager;
    (globalThis as { NarrativeManager?: typeof NarrativeManager }).NarrativeManager = NarrativeManager;
}
if (typeof window !== 'undefined') {
    window.narrativeManager = narrativeManager as unknown as NonNullable<typeof window.narrativeManager>;
}
export { narrativeManager };
