/**
 * Team Aqua / Magma story battles (Hoenn layout v3).
 * Uses the zone-rival combat pipeline; unlocked while the linked story quest is active.
 */

export type FactionEncounterMeta = {
    zoneId: number;
    rivalKey: string;
    spriteKey: string;
    displayName: string;
    flavor: { fr: string; en: string };
    faction: 'aqua' | 'magma';
    /** Arena whose gym-trainer level/stats formula applies to this grunt. */
    arenaId: number;
    /** Story quest id (e.g. story_hoenn_aqua_rusturf) — encounter visible only while quest is active. */
    unlockWhenStoryQuest: string;
    teamArchetypes: Array<{ picks: string[]; pickOne?: boolean }>;
    /** Bonus level on top of gym-trainer roll (faction grunt). */
    levelOffset?: number;
    /** Bonus stat multiplier on top of gym-trainer formula (faction grunt). */
    statMultiplier?: number;
    rewards?: {
        pokedollarsMult?: number;
        balls?: Record<string, number>;
        combatTickets?: number;
    };
};

