/**
 * @file src/lib/farmThreatCombatPause.ts
 * Suspend / resume active combat while an interactive farm threat fight runs.
 */

import { Creature } from '../../Creature.ts';
import type { CreatureData } from '../types/creature.js';
import type { GameRuntime } from '../types/game.js';
import { syncMegaTimerWithCombatState } from './megaEvolutionCombat.ts';
import { syncDynamaxTimerWithCombatState } from './dynamaxCombat.ts';

export type PausedCombatMode = 'wild' | 'tower' | 'subway' | 'arena' | 'gymTrainer';

export interface GymTrainerPausedSnapshot {
    active: boolean;
    currentIndex: number;
    trainerName?: string;
    trainerSpriteUrl?: string;
    isRival?: boolean;
    isZoneRival?: boolean;
    rivalRewards?: unknown;
    rivalZoneId?: unknown;
    rivalEncounterKey?: string;
    teamSnapshots: CreatureData[];
}

export interface PausedCombatBackup {
    mode: PausedCombatMode;
    combatState: 'fighting' | 'starting';
    activeCreatureIndex: number;
    lastCombatTime: number;
    faintedIndices: number[];
    faintedUids: string[];
    currentPlayerCreatureUid: string | null;
    enemySnapshot: CreatureData | null;
    enemyIndex?: number;
    championIndex?: number;
    gymTrainerSnapshot?: GymTrainerPausedSnapshot;
}

/** @deprecated Use PausedCombatBackup */
export type PausedWildCombatBackup = PausedCombatBackup;

export type GameWithPausedCombatForFarmThreat = GameRuntime & {
    _pausedCombatForFarmThreat?: PausedCombatBackup | null;
};

/** @deprecated Use GameWithPausedCombatForFarmThreat */
export type GameWithPausedWildCombat = GameWithPausedCombatForFarmThreat;

function snapshotCreature(creature: CreatureData | null | undefined): CreatureData | null {
    if (!creature) return null;
    if (typeof creature.serialize === 'function') {
        return creature.serialize();
    }
    return JSON.parse(JSON.stringify(creature)) as CreatureData;
}

function restoreCreature(data: CreatureData): CreatureData {
    return Creature.deserialize(data) as CreatureData;
}

function applySnapshotToTeamEnemy(teamEnemy: CreatureData, snapshot: CreatureData): void {
    teamEnemy.currentHp = snapshot.currentHp;
    if (snapshot.actionGauge != null) teamEnemy.actionGauge = snapshot.actionGauge;
    if (snapshot.berserkStacks != null) teamEnemy.berserkStacks = snapshot.berserkStacks;
    if (snapshot.sentinelleStacks != null) teamEnemy.sentinelleStacks = snapshot.sentinelleStacks;
    if (snapshot.ultimateCharge != null) teamEnemy.ultimateCharge = snapshot.ultimateCharge;
    if (snapshot.ultimateActive != null) teamEnemy.ultimateActive = snapshot.ultimateActive;
    if (snapshot.megaGauge != null) teamEnemy.megaGauge = snapshot.megaGauge;
    if (snapshot.mainAccountCurrentHp != null) teamEnemy.mainAccountCurrentHp = snapshot.mainAccountCurrentHp;
    if (typeof teamEnemy.clearStatusEffect === 'function') {
        teamEnemy.clearStatusEffect();
    }
    if (snapshot.statusEffect?.type) {
        teamEnemy.statusEffect = { ...snapshot.statusEffect };
    }
}

function resumeEnemyFromBackup(game: GameRuntime, backup: PausedCombatBackup): void {
    if (backup.mode === 'gymTrainer' && backup.gymTrainerSnapshot) {
        game.gymTrainerState = restoreGymTrainerState(backup.gymTrainerSnapshot);
        const idx = backup.enemyIndex ?? game.gymTrainerState.currentIndex ?? 0;
        game.gymTrainerState.currentIndex = idx;
        const teamEnemy = game.gymTrainerState.team?.[idx] ?? null;
        if (teamEnemy && backup.enemySnapshot) {
            applySnapshotToTeamEnemy(teamEnemy, backup.enemySnapshot);
            game.currentEnemy = teamEnemy;
        } else {
            game.currentEnemy = teamEnemy;
        }
        return;
    }
    if (backup.mode === 'tower' && game.towerState?.isActive) {
        const idx = backup.enemyIndex ?? game.towerState.currentEnemyIndex ?? 0;
        game.towerState.currentEnemyIndex = idx;
        const teamEnemy = game.towerState.enemyTeam?.[idx] ?? null;
        if (teamEnemy && backup.enemySnapshot) {
            applySnapshotToTeamEnemy(teamEnemy, backup.enemySnapshot);
            game.currentEnemy = teamEnemy;
        } else {
            game.currentEnemy = teamEnemy;
        }
        return;
    }
    if (backup.mode === 'subway' && game.subwayState?.isActive) {
        const idx = backup.enemyIndex ?? game.subwayState.currentEnemyIndex ?? 0;
        game.subwayState.currentEnemyIndex = idx;
        const teamEnemy = game.subwayState.enemyTeam?.[idx] ?? null;
        if (teamEnemy && backup.enemySnapshot) {
            applySnapshotToTeamEnemy(teamEnemy, backup.enemySnapshot);
            game.currentEnemy = teamEnemy;
        } else {
            game.currentEnemy = teamEnemy;
        }
        return;
    }
    if (backup.mode === 'arena' && game.arenaState?.active) {
        const idx = backup.championIndex ?? game.arenaState.currentChampionIndex ?? 0;
        game.arenaState.currentChampionIndex = idx;
        const teamEnemy = game.arenaState.championTeam?.[idx] ?? null;
        if (teamEnemy && backup.enemySnapshot) {
            applySnapshotToTeamEnemy(teamEnemy, backup.enemySnapshot);
            game.currentEnemy = teamEnemy;
        } else {
            game.currentEnemy = teamEnemy;
        }
        return;
    }
    if (backup.enemySnapshot) {
        game.currentEnemy = restoreCreature(backup.enemySnapshot);
    } else {
        game.currentEnemy = null;
    }
}

function snapshotGymTrainerState(
    gts: NonNullable<GameRuntime['gymTrainerState']>,
): GymTrainerPausedSnapshot {
    const team = Array.isArray(gts.team) ? gts.team : [];
    return {
        active: !!gts.active,
        currentIndex: Math.max(0, Math.floor(Number(gts.currentIndex) || 0)),
        trainerName: gts.trainerName,
        trainerSpriteUrl: gts.trainerSpriteUrl,
        isRival: gts.isRival,
        isZoneRival: gts.isZoneRival,
        rivalRewards: gts.rivalRewards,
        rivalZoneId: gts.rivalZoneId,
        rivalEncounterKey: gts.rivalEncounterKey,
        teamSnapshots: team.map((c) => snapshotCreature(c)).filter((c): c is CreatureData => c != null),
    };
}

function restoreGymTrainerState(snapshot: GymTrainerPausedSnapshot): NonNullable<GameRuntime['gymTrainerState']> {
    return {
        active: snapshot.active,
        currentIndex: snapshot.currentIndex,
        trainerName: snapshot.trainerName,
        trainerSpriteUrl: snapshot.trainerSpriteUrl,
        isRival: snapshot.isRival,
        isZoneRival: snapshot.isZoneRival,
        rivalRewards: snapshot.rivalRewards,
        rivalZoneId: snapshot.rivalZoneId,
        rivalEncounterKey: snapshot.rivalEncounterKey,
        team: snapshot.teamSnapshots.map((c) => restoreCreature(c)),
    };
}

function getPausedBackup(game: GameRuntime): PausedCombatBackup | null {
    const g = game as GameWithPausedCombatForFarmThreat;
    return g._pausedCombatForFarmThreat ?? null;
}

function setPausedBackup(game: GameRuntime, backup: PausedCombatBackup | null): void {
    (game as GameWithPausedCombatForFarmThreat)._pausedCombatForFarmThreat = backup;
}

export function getActiveCombatModeForFarmPause(game: GameRuntime): PausedCombatMode | null {
    if (game.gymTrainerState?.active && game.gymTrainerState.isFarmThreat) return null;
    if (game.combatState !== 'fighting' && game.combatState !== 'starting') return null;

    if (game.gymTrainerState?.active && !game.gymTrainerState.isFarmThreat) return 'gymTrainer';
    if (game.towerState?.isActive) return 'tower';
    if (game.subwayState?.isActive) return 'subway';
    if (game.arenaState?.active) return 'arena';
    return 'wild';
}

export function hasPausedCombatForFarmThreat(game: GameRuntime): boolean {
    return !!getPausedBackup(game);
}

/** @deprecated Use hasPausedCombatForFarmThreat */
export function hasPausedWildCombat(game: GameRuntime): boolean {
    return hasPausedCombatForFarmThreat(game);
}

export function canSuspendCombatForFarmThreat(game: GameRuntime): boolean {
    return getActiveCombatModeForFarmPause(game) != null;
}

/** @deprecated Use canSuspendCombatForFarmThreat */
export function canSuspendWildCombatForFarmThreat(game: GameRuntime): boolean {
    return canSuspendCombatForFarmThreat(game);
}

export function suspendCombatForFarmThreat(game: GameWithPausedCombatForFarmThreat): boolean {
    if (getPausedBackup(game)) return true;

    const mode = getActiveCombatModeForFarmPause(game);
    if (!mode) return false;

    const backup: PausedCombatBackup = {
        mode,
        combatState: game.combatState as 'fighting' | 'starting',
        activeCreatureIndex: Math.max(0, Math.floor(Number(game.activeCreatureIndex) || 0)),
        lastCombatTime: Number(game.lastCombatTime) || Date.now(),
        faintedIndices: Array.from(game.faintedThisCombat || []),
        faintedUids: Array.from(game.faintedUidsThisCombat || []).map(String),
        currentPlayerCreatureUid: game.currentPlayerCreature?.uid != null
            ? String(game.currentPlayerCreature.uid)
            : null,
        enemySnapshot: snapshotCreature(game.currentEnemy),
    };

    if (mode === 'tower') {
        backup.enemyIndex = Math.max(0, Math.floor(Number(game.towerState?.currentEnemyIndex) || 0));
    } else if (mode === 'subway') {
        backup.enemyIndex = Math.max(0, Math.floor(Number(game.subwayState?.currentEnemyIndex) || 0));
    } else if (mode === 'arena') {
        backup.championIndex = Math.max(0, Math.floor(Number(game.arenaState?.currentChampionIndex) || 0));
    } else if (mode === 'gymTrainer' && game.gymTrainerState) {
        backup.gymTrainerSnapshot = snapshotGymTrainerState(game.gymTrainerState);
        backup.enemyIndex = Math.max(0, Math.floor(Number(game.gymTrainerState.currentIndex) || 0));
    }

    setPausedBackup(game, backup);
    game.currentEnemy = null;
    if (mode === 'gymTrainer') {
        game.gymTrainerState = null;
    }
    return true;
}

/** @deprecated Use suspendCombatForFarmThreat */
export function suspendWildCombatForFarmThreat(game: GameWithPausedCombatForFarmThreat): boolean {
    return suspendCombatForFarmThreat(game);
}

export function clearPausedCombatForFarmThreat(game: GameWithPausedCombatForFarmThreat): void {
    setPausedBackup(game, null);
}

/** @deprecated Use clearPausedCombatForFarmThreat */
export function clearPausedWildCombat(game: GameWithPausedCombatForFarmThreat): void {
    clearPausedCombatForFarmThreat(game);
}

function restoreActivePlayerCreature(game: GameRuntime, backup: PausedCombatBackup): void {
    const team = Array.isArray(game.playerTeam) ? game.playerTeam : [];
    const byUid = backup.currentPlayerCreatureUid
        ? team.find((c) => String(c?.uid) === backup.currentPlayerCreatureUid)
        : null;
    const byIndex = team[backup.activeCreatureIndex];
    const active = (byUid?.isAlive?.() ? byUid : null)
        ?? (byIndex?.isAlive?.() ? byIndex : null);
    if (active) {
        game.currentPlayerCreature = active;
        game.activeCreatureIndex = team.indexOf(active);
        return;
    }
    if (typeof game.getFirstAliveCreature === 'function') {
        game.currentPlayerCreature = game.getFirstAliveCreature();
        if (game.currentPlayerCreature) {
            game.activeCreatureIndex = team.indexOf(game.currentPlayerCreature);
        }
    }
}

export function resumePausedCombatForFarmThreat(game: GameWithPausedCombatForFarmThreat): boolean {
    const backup = getPausedBackup(game);
    if (!backup) return false;

    setPausedBackup(game, null);

    game.combatState = backup.combatState;
    game.activeCreatureIndex = backup.activeCreatureIndex;
    game.lastCombatTime = backup.lastCombatTime;
    game.faintedThisCombat = new Set(backup.faintedIndices);
    game.faintedUidsThisCombat = new Set(backup.faintedUids);

    resumeEnemyFromBackup(game, backup);

    restoreActivePlayerCreature(game, backup);

    syncMegaTimerWithCombatState(game);
    syncDynamaxTimerWithCombatState(game);
    if (typeof game.updateTeamDisplay === 'function') {
        game.updateTeamDisplay();
    }

    if (typeof game.updateCombatDisplay === 'function') {
        game.updateCombatDisplay();
    }
    return true;
}

/** @deprecated Use resumePausedCombatForFarmThreat */
export function resumePausedWildCombat(game: GameWithPausedCombatForFarmThreat): boolean {
    return resumePausedCombatForFarmThreat(game);
}
