/**
 * Offline zone combat pacing — ultra-faithful wall-clock budget from live ATB + action delays.
 */

import { BALANCE } from '../../constants/balance/balance.js';
import { GAME_SPEEDS } from '../../constants/balance/zonesAndPacing.js';

/** Ignore bogus gaps (first combat, clock skew, long AFK with tab open). */
export const OFFLINE_COMBAT_CYCLE_CAP_MS = 5 * 60 * 1000;

const VISUAL_DELAY_BASE_MS = 500;
/** Live blocked turn skip delay (executeCreatureTurnLogic setTimeout 300ms). */
export const BLOCKED_TURN_DELAY_MS = 300;
const CALIBRATION_MIN = 0.85;
const CALIBRATION_MAX = 1.15;
/** When sim wall time exceeds live fight median, allow stronger downward calibration. */
const CALIBRATION_SLOW_SIM_MIN = 0.5;
const CALIBRATION_MIN_SAMPLES = 3;
export const LIVE_DEBIT_MIN_SAMPLES = 3;
export const SIM_WALL_HISTORY_MAX = 5;

export interface SimPacingSnapshot {
    wallMs: number;
    playerActions: number;
    enemyActions: number;
    simTurns: number;
}

export const LIVE_WIN_HISTORY_MAX = 10;
export const SIM_COST_ROLLING_MAX = 10;

export interface OfflineEntryPaceInput {
    /** Last zone live victories only (never sim costs). */
    recentLiveWinDurations: number[];
    spawnDelayMs: number;
    combatStartDelayMs: number;
    minPlayerActions?: number;
    defaultCycleMs?: number;
}

/** @deprecated Use recentLiveWinDurations */
export type OfflineEntryPaceInputLegacy = OfflineEntryPaceInput & {
    recentCombatDurations?: number[];
};

export interface OfflineEntryPaceResult {
    entryPaceMs: number;
    /** Pessimistic cold-start floor (spawn + start + min player actions). */
    floorCycleMs: number;
    /** Minimum plausible cycle (spawn + start + one live action). */
    ohkoFloorMs: number;
    medianWinMs: number;
}

export interface OfflineCombatCostInput {
    spawnDelayMs: number;
    combatStartDelayMs: number;
    simWallMs: number;
    calibrationRatio?: number;
}

/** Live ATB: deltaMs so sim timeJump matches gauge fill in updateATBLogic. */
export function convertSimTimeJumpToWallMs(
    timeJump: number,
    playerSpeed: number,
    enemySpeed: number,
    threshold: number = BALANCE.ATB_ACTION_THRESHOLD,
    baseTurnTime: number = GAME_SPEEDS.BASE_TURN_TIME
): number {
    if (!Number.isFinite(timeJump) || timeJump <= 0) return 0;
    const maxSpeed = Math.max(playerSpeed, enemySpeed, 0.001);
    const th = Math.max(threshold, 1);
    return Math.floor((timeJump * baseTurnTime * maxSpeed) / th);
}

/** PRE + ANIM + VISUAL between actions (live executeCreatureTurnLogic). */
export function perLiveActionDelayMs(): number {
    const pre = GAME_SPEEDS.PRE_ATTACK_DELAY ?? 200;
    const anim = GAME_SPEEDS.ANIMATION_LOCK ?? 200;
    return pre + anim + VISUAL_DELAY_BASE_MS;
}

export function createSimPacingState(): SimPacingSnapshot {
    return {
        wallMs: 0,
        playerActions: 0,
        enemyActions: 0,
        simTurns: 0,
    };
}

export function accumulateSimTimeJump(
    pacing: SimPacingSnapshot,
    timeJump: number,
    playerSpeed: number,
    enemySpeed: number
): void {
    pacing.wallMs += convertSimTimeJumpToWallMs(timeJump, playerSpeed, enemySpeed);
}

export function accumulateSimActionDelay(pacing: SimPacingSnapshot, isPlayer: boolean): void {
    pacing.wallMs += perLiveActionDelayMs();
    if (isPlayer) pacing.playerActions += 1;
    else pacing.enemyActions += 1;
}

export function accumulateSimBlockedTurnDelay(pacing: SimPacingSnapshot): void {
    pacing.wallMs += BLOCKED_TURN_DELAY_MS;
}

/** Turn consumed without attack (miss, dodge) — partial visual gap like live ATB gate. */
export function accumulateSimMissTurnDelay(pacing: SimPacingSnapshot): void {
    pacing.wallMs += VISUAL_DELAY_BASE_MS;
}

function medianOf(values: number[]): number {
    if (!values.length) return 0;
    const sorted = [...values].sort((a, b) => a - b);
    const mid = Math.floor(sorted.length / 2);
    if (sorted.length % 2 === 1) return sorted[mid];
    return (sorted[mid - 1] + sorted[mid]) / 2;
}

/**
 * Resolves wall-clock combat cycle ms to record after a zone victory (wins only).
 */
export function resolveCombatCycleDurationMs(
    now: number,
    lastCombatTime: number | undefined | null,
    combatStartTime: number | undefined | null,
    capMs: number = OFFLINE_COMBAT_CYCLE_CAP_MS
): number | null {
    let cycleMs = 0;
    if (lastCombatTime != null && Number.isFinite(lastCombatTime)) {
        cycleMs = now - Number(lastCombatTime);
    }
    if (cycleMs > 0 && cycleMs < capMs) {
        return cycleMs;
    }
    if (combatStartTime != null && Number.isFinite(combatStartTime)) {
        const fightOnly = now - Number(combatStartTime);
        if (fightOnly > 0 && fightOnly < capMs) {
            return fightOnly;
        }
    }
    return null;
}

/** Recorded duration for live win: never shorter than fight-only wall time. */
export function resolveRecordedWinCycleMs(
    now: number,
    lastCombatTime: number | undefined | null,
    combatStartTime: number | undefined | null
): number | null {
    const cycleMs = resolveCombatCycleDurationMs(now, lastCombatTime, combatStartTime);
    if (cycleMs == null) return null;
    if (combatStartTime != null && Number.isFinite(combatStartTime)) {
        const fightMs = now - Number(combatStartTime);
        if (fightMs > 0) return Math.max(cycleMs, fightMs);
    }
    return cycleMs;
}

/** Fight-only wall time for live win (combatStart → victory). */
export function resolveRecordedFightDurationMs(
    now: number,
    combatStartTime: number | undefined | null,
    capMs: number = OFFLINE_COMBAT_CYCLE_CAP_MS
): number | null {
    if (combatStartTime == null || !Number.isFinite(combatStartTime)) return null;
    const fightMs = now - Number(combatStartTime);
    if (fightMs > 0 && fightMs < capMs) return fightMs;
    return null;
}

export function recordLiveFightDuration(
    durations: number[],
    fightMs: number,
    maxLen: number = LIVE_WIN_HISTORY_MAX
): void {
    if (!Number.isFinite(fightMs) || fightMs <= 0) return;
    durations.push(fightMs);
    while (durations.length > maxLen) durations.shift();
}

export function computeMedianLiveFightMs(
    recentLiveFightDurations: number[],
    ohkoFightFloorMs: number = 0
): number {
    const minFight = ohkoFightFloorMs > 0 ? ohkoFightFloorMs : perLiveActionDelayMs();
    const filtered = recentLiveFightDurations.filter(
        (d) => d >= minFight * 0.5 && d <= OFFLINE_COMBAT_CYCLE_CAP_MS
    );
    return filtered.length > 0 ? medianOf(filtered) : 0;
}

export function computeFloorCycleMs(
    spawnDelayMs: number,
    combatStartDelayMs: number,
    minPlayerActions: number = BALANCE.OFFLINE_PACING_MIN_PLAYER_ACTIONS
): number {
    const minFight = minPlayerActions * perLiveActionDelayMs();
    return spawnDelayMs + combatStartDelayMs + minFight;
}

/** Fastest plausible zone cycle (one player action after spawn). */
export function computeOhkoFloorCycleMs(
    spawnDelayMs: number,
    combatStartDelayMs: number
): number {
    return spawnDelayMs + combatStartDelayMs + perLiveActionDelayMs();
}

export function recordLiveWinDuration(
    durations: number[],
    cycleMs: number,
    maxLen: number = LIVE_WIN_HISTORY_MAX
): void {
    if (!Number.isFinite(cycleMs) || cycleMs <= 0) return;
    durations.push(cycleMs);
    while (durations.length > maxLen) durations.shift();
}

export function pushRollingSimCombatCost(
    costs: number[],
    costMs: number,
    maxLen: number = SIM_COST_ROLLING_MAX
): void {
    if (!Number.isFinite(costMs) || costMs <= 0) return;
    costs.push(costMs);
    while (costs.length > maxLen) costs.shift();
}

export function computeBatchCombatCostMs(input: {
    spawnDelayMs: number;
    combatStartDelayMs: number;
    rawWallMs: number;
}): number {
    return computeOfflineCombatCostMs({
        spawnDelayMs: input.spawnDelayMs,
        combatStartDelayMs: input.combatStartDelayMs,
        simWallMs: input.rawWallMs,
    });
}

export function computeRollingMinNextCostMs(
    recentSimCombatCosts: number[],
    ohkoFloorMs: number,
    entryPaceMs: number
): number {
    if (!recentSimCombatCosts.length) return entryPaceMs;
    return Math.max(ohkoFloorMs, Math.floor(medianOf(recentSimCombatCosts)));
}

export function computeDynamicHardCapCombats(
    currentCombat: number,
    remainingMs: number,
    minNextCombatCost: number,
    absoluteCap: number
): number {
    if (minNextCombatCost <= 0) return Math.min(absoluteCap, currentCombat);
    const projected = currentCombat + Math.floor(remainingMs / minNextCombatCost);
    return Math.min(absoluteCap, Math.max(currentCombat, projected));
}

const OFFLINE_CAP_MAX_LEVEL = 15;

/** Offline combat cap: base + (token levels + pokédollar levels) × per-level bonus. */
export function computeOfflineCatchupMaxCombats(
    tokenLevels: number,
    pokedollarLevels: number,
    baseCap = BALANCE.OFFLINE_CATCHUP_MAX_COMBATS,
    perLevel = BALANCE.OFFLINE_CATCHUP_COMBATS_PER_LEVEL,
): number {
    const t = Math.max(0, Math.min(OFFLINE_CAP_MAX_LEVEL, Math.floor(tokenLevels)));
    const p = Math.max(0, Math.min(OFFLINE_CAP_MAX_LEVEL, Math.floor(pokedollarLevels)));
    return baseCap + (t + p) * perLevel;
}

export function computeDisplayPaceMs(
    simulated: number,
    recentSimCombatCosts: number[],
    entryPaceMs: number,
    totalCostMs: number
): number {
    if (simulated > 0 && recentSimCombatCosts.length > 0) {
        return Math.floor(medianOf(recentSimCombatCosts));
    }
    if (simulated > 0 && totalCostMs > 0) {
        return Math.floor(totalCostMs / simulated);
    }
    return entryPaceMs;
}

export function computeEntryPaceMs(input: OfflineEntryPaceInput): OfflineEntryPaceResult {
    const {
        recentLiveWinDurations,
        spawnDelayMs,
        combatStartDelayMs,
        minPlayerActions = BALANCE.OFFLINE_PACING_MIN_PLAYER_ACTIONS,
        defaultCycleMs = BALANCE.OFFLINE_PACING_DEFAULT_CYCLE_MS,
    } = input;

    const floorCycleMs = computeFloorCycleMs(spawnDelayMs, combatStartDelayMs, minPlayerActions);
    const ohkoFloorMs = computeOhkoFloorCycleMs(spawnDelayMs, combatStartDelayMs);
    const filtered = recentLiveWinDurations.filter(
        (d) => d >= ohkoFloorMs && d <= OFFLINE_COMBAT_CYCLE_CAP_MS
    );
    const medianWinMs = filtered.length > 0 ? medianOf(filtered) : 0;
    const entryPaceMs = medianWinMs > 0
        ? Math.max(ohkoFloorMs, Math.floor(medianWinMs))
        : Math.max(floorCycleMs, defaultCycleMs);
    return { entryPaceMs, floorCycleMs, ohkoFloorMs, medianWinMs };
}

/** Ratio to align sim fight wall time with live fight median (fight vs fight). */
export function computeSimCalibrationRatio(
    medianLiveFightMs: number,
    recentSimWallMs: number[]
): number {
    if (medianLiveFightMs <= 0 || recentSimWallMs.length < CALIBRATION_MIN_SAMPLES) return 1;
    const simMed = medianOf(recentSimWallMs.filter((w) => w > 0));
    if (simMed <= 0) return 1;
    const raw = medianLiveFightMs / simMed;
    if (!Number.isFinite(raw) || raw <= 0) return 1;
    const minBound = raw < 1 ? CALIBRATION_SLOW_SIM_MIN : CALIBRATION_MIN;
    return Math.min(CALIBRATION_MAX, Math.max(minBound, raw));
}

export interface OfflineCombatDebitInput {
    simCostMs: number;
    recentLiveWinDurations: number[];
    spawnDelayMs: number;
    combatStartDelayMs: number;
    tolerance?: number;
    minSamples?: number;
}

/**
 * Caps offline time-budget debit to observed live win pace when history is reliable.
 * Sim cost is preserved separately for diagnostics; this value drives remainingMs.
 */
export function resolveOfflineCombatDebitMs(input: OfflineCombatDebitInput): number {
    const {
        simCostMs,
        recentLiveWinDurations,
        spawnDelayMs,
        combatStartDelayMs,
        tolerance = BALANCE.OFFLINE_PACING_LIVE_DEBIT_TOLERANCE,
        minSamples = LIVE_DEBIT_MIN_SAMPLES,
    } = input;

    if (!Number.isFinite(simCostMs) || simCostMs <= 0) return simCostMs;

    const entry = computeEntryPaceMs({
        recentLiveWinDurations,
        spawnDelayMs,
        combatStartDelayMs,
    });
    const ohkoFloor = entry.ohkoFloorMs;
    const filtered = recentLiveWinDurations.filter(
        (d) => d >= ohkoFloor && d <= OFFLINE_COMBAT_CYCLE_CAP_MS
    );
    if (filtered.length < minSamples || entry.medianWinMs <= 0) {
        return simCostMs;
    }

    const tol = Number.isFinite(tolerance) && tolerance > 0 ? tolerance : 1;
    const cap = Math.floor(entry.medianWinMs * tol);
    return Math.min(simCostMs, Math.max(ohkoFloor, cap));
}

export function applyCalibrationToWallMs(
    wallMs: number,
    medianLiveFightMs: number,
    recentSimWallMs: number[]
): number {
    const ratio = computeSimCalibrationRatio(medianLiveFightMs, recentSimWallMs);
    if (ratio === 1) return wallMs;
    return Math.floor(wallMs * ratio);
}

export function pushRecentSimWallMs(
    walls: number[],
    wallMs: number,
    maxLen: number = SIM_WALL_HISTORY_MAX
): void {
    if (!Number.isFinite(wallMs) || wallMs <= 0) return;
    walls.push(wallMs);
    while (walls.length > maxLen) walls.shift();
}

export function computeOfflineCombatCostMs(input: OfflineCombatCostInput): number {
    const spawn = Math.max(0, input.spawnDelayMs);
    const start = Math.max(0, input.combatStartDelayMs);
    let wall = Math.max(0, input.simWallMs);
    const ratio = input.calibrationRatio ?? 1;
    if (ratio !== 1 && Number.isFinite(ratio)) {
        wall = Math.floor(wall * ratio);
    }
    return spawn + start + wall;
}

export function estimateMaxCombatsFromTime(missedTimeMs: number, entryPaceMs: number): number {
    if (!Number.isFinite(missedTimeMs) || missedTimeMs <= 0) return 0;
    if (!Number.isFinite(entryPaceMs) || entryPaceMs <= 0) return 0;
    return Math.floor(missedTimeMs / entryPaceMs);
}

/** @deprecated Use computeEntryPaceMs + budget loop. Kept for tests migrating from old API. */
export function computeAverageCombatCycleMs(input: {
    recentLiveWinDurations?: number[];
    recentCombatDurations?: number[];
    spawnDelayMs: number;
    combatStartDelayMs: number;
    defaultCycleMs?: number;
}): number {
    return computeEntryPaceMs({
        recentLiveWinDurations: input.recentLiveWinDurations ?? input.recentCombatDurations ?? [],
        spawnDelayMs: input.spawnDelayMs,
        combatStartDelayMs: input.combatStartDelayMs,
        defaultCycleMs: input.defaultCycleMs,
    }).entryPaceMs;
}

export interface OfflineCyclePacingInput {
    recentLiveWinDurations?: number[];
    /** @deprecated Use recentLiveWinDurations */
    recentCombatDurations?: number[];
    missedTimeMs: number;
    spawnDelayMs: number;
    combatStartDelayMs: number;
    defaultCycleMs?: number;
}

export interface OfflineCyclePacingResult {
    avgCycleMs: number;
    maxCombats: number;
}

export function computeOfflineCyclePacing(input: OfflineCyclePacingInput): OfflineCyclePacingResult {
    const entry = computeEntryPaceMs({
        recentLiveWinDurations: input.recentLiveWinDurations ?? input.recentCombatDurations ?? [],
        spawnDelayMs: input.spawnDelayMs,
        combatStartDelayMs: input.combatStartDelayMs,
        defaultCycleMs: input.defaultCycleMs,
    });
    return {
        avgCycleMs: entry.entryPaceMs,
        maxCombats: estimateMaxCombatsFromTime(input.missedTimeMs, entry.entryPaceMs),
    };
}
