/**
 * @file src/lib/creatureUiRefresh.ts
 * Targeted facade UI refresh after roster mutations (capture, fusion, evolution).
 */

import type { GameRuntime } from '../types/game.js';

/** Team + storage + pokedex (+ combat/eggs for evolution flows). */
export function refreshCreatureDependentUi(game: GameRuntime): void {
  if (typeof game.updateTeamDisplay === 'function') game.updateTeamDisplay();
  if (typeof game.updateStorageDisplay === 'function') game.updateStorageDisplay();
  if (typeof game.updatePokedexDisplay === 'function') game.updatePokedexDisplay();
  if (typeof game.updateCombatDisplay === 'function') game.updateCombatDisplay();
  if (typeof game.updateEggsDisplay === 'function') game.updateEggsDisplay();
}

/** Storage first, then team (shards/IV on cards, new storage entries). */
export function refreshTeamAndStorageUi(game: GameRuntime): void {
  if (typeof game.updateStorageDisplay === 'function') game.updateStorageDisplay();
  if (typeof game.updateTeamDisplay === 'function') game.updateTeamDisplay();
}

export function refreshTeamUi(game: GameRuntime): void {
  if (typeof game.updateTeamDisplay === 'function') game.updateTeamDisplay();
}
