export function zoneFormatText(text: string, vars: Record<string, unknown> = {}): string {
    return String(text || '').replace(/\{(\w+)\}/g, (_, k: string) => (vars[k] != null ? coerceStr(vars[k]) : ''));
}

export function zoneLang(game: GameRuntime): string {
    if (!game || typeof game.normalizeLanguage !== 'function') return 'fr';
    return game.normalizeLanguage(game.language);
}

export function zoneText(game: GameRuntime, key: string, fallbackFr: string, fallbackEn: string, vars: Record<string, unknown> = {}): string {
    if (game && typeof game.t === 'function' && key) {
        const translated = game.t(key, vars);
        if (translated && translated !== key) return translated;
    }
    const fallback = zoneLang(game) === 'en' ? fallbackEn : fallbackFr;
    return zoneFormatText(fallback, vars);
}

export function zoneDisplayName(game: GameRuntime, zoneId: number, fallbackName: string = ''): string {
    if (game && typeof game.getLocalizedZoneName === 'function') {
        return game.getLocalizedZoneName(zoneId, fallbackName);
    }
    const zone = (typeof ZONES !== 'undefined') ? ZONES[zoneId] : null;
    return String(fallbackName || (zone ? zone.name : '') || ('Zone ' + zoneId));
}

export function _getZoneRegionId(zoneId: number): string {
    const zId = Number(zoneId);
    const zone = (typeof ZONES !== 'undefined' && ZONES) ? ZONES[zId] : null;
    return (zone && zone.regionId) ? String(zone.regionId) : 'kanto';
}

export function _getRegionMeta(regionId: string): Record<string, unknown> {
    const fallback = { id: String(regionId || 'kanto'), name: String(regionId || 'kanto') };
    const regions = getRegions();
    if (!regions || !Object.keys(regions).length) return fallback;
    return (regions[regionId] as Record<string, unknown> | undefined) || fallback;
}

export function _getSortedZoneIdsForRegion(regionId: string): number[] {
    if (typeof ZONES === 'undefined' || !ZONES) return [];
    return Object.keys(ZONES)
        .map(function (id) { return Number(id); })
        .filter(function (id) { return Number.isFinite(id) && _getZoneRegionId(id) === regionId; })
        .sort(function (a, b) {
            const za = ZONES[a] || {};
            const zb = ZONES[b] || {};
            const oa = Number(za.regionOrder);
            const ob = Number(zb.regionOrder);
            if (Number.isFinite(oa) && Number.isFinite(ob) && oa !== ob) return oa - ob;
            return a - b;
        });
}

export function _getFirstZoneIdForRegion(regionId: string): number | null {
    const ids = _getSortedZoneIdsForRegion(regionId);
    return arrayAt(ids, 0) ?? null;
}

export function _getLastZoneIdForRegion(regionId: string): number | null {
    const ids = _getSortedZoneIdsForRegion(regionId);
    if (!ids.length) return null;
    return arrayAt(ids, ids.length - 1) ?? null;
}

export function _getPreviousZoneIdInRegion(zoneId: number): number | null {
    const zId = Number(zoneId);
    if (!Number.isFinite(zId)) return null;
    const regionId = _getZoneRegionId(zId);
    const ids = _getSortedZoneIdsForRegion(regionId);
    const idx = ids.indexOf(zId);
    if (idx <= 0) return null;
    return arrayAt(ids, idx - 1) ?? null;
}

export function _findFirstUnlockedZoneInRegion(game: GameRuntime, regionId: string): number | null {
    const ids = _getSortedZoneIdsForRegion(regionId);
    for (let i = 0; i < ids.length; i++) {
        const zoneId = ids[i];
        if (zoneId !== undefined && isZoneUnlockedLogic(game, zoneId, false)) return zoneId;
    }
    return arrayAt(ids, 0) ?? null;
}

/** Furthest zone along regional order reachable via mastery chain (optional story hubs may be skipped). */
export function getFurthestAccessibleZoneInRegionLogic(game: GameRuntime, regionId: string): number | null {
    const snapshot = getRegionAccessSnapshot(game, regionId);
    const sorted = snapshot.sorted;
    const first = _getFirstZoneIdForRegion(regionId);
    if (!sorted.length || first == null) return first ?? null;
    if (!_isRegionUnlocked(game, regionId)) return null;
    if (!snapshot.unlocked.get(first)) return null;

    let best = first;
    for (let i = 0; i < sorted.length; i++) {
        const zId = sorted[i];
        if (zId === undefined) continue;
        if (snapshot.unlocked.get(zId)) {
            best = zId;
        } else if (!_meetsZoneUnlockRequirement(game, zId)) {
            continue;
        } else {
            break;
        }
    }
    return best;
}

function getSafeActiveZoneForRegion(game: GameRuntime, regionId: string): number | null {
    const accessible = getFurthestAccessibleZoneInRegionLogic(game, regionId);
    if (accessible != null && Number.isFinite(accessible) && accessible > 0) return accessible;
    if (!_isRegionUnlocked(game, regionId)) return null;
    return _getFirstZoneIdForRegion(regionId);
}

/** Clamp maxReached per region to mastery chain; keep zoneProgress intact. */
export function repairSequentialZoneAccessLogic(game: GameRuntime): void {
    if (!game || typeof game !== 'object') return;
    if (!maxReachedZoneByRegion || typeof maxReachedZoneByRegion !== 'object') return;

    beginZoneAccessBatch(game);
    try {
    const regionIds = new Set<string>();
    Object.keys(maxReachedZoneByRegion).forEach((r) => regionIds.add(r));
    Object.keys(ZONES).forEach((idStr) => {
        const id = Number(idStr);
        if (Number.isFinite(id)) regionIds.add(_getZoneRegionId(id));
    });

    regionIds.forEach((regionId) => {
        const accessible = getFurthestAccessibleZoneInRegionLogic(game, regionId);
        const stored = Number(maxReachedZoneByRegion[regionId]);
        if (accessible != null && Number.isFinite(accessible) && accessible > 0) {
            maxReachedZoneByRegion[regionId] = accessible;
            return;
        }
        if (Number.isFinite(stored) && stored > 0 && _getZoneRegionId(stored) === regionId) {
            if (!isZoneUnlockedLogic(game, stored, true)) {
                const safe = getSafeActiveZoneForRegion(game, regionId);
                maxReachedZoneByRegion[regionId] = safe ?? 0;
            }
            return;
        }
        maxReachedZoneByRegion[regionId] = 0;
    });

    const activeZone = Number(currentZone);
    if (Number.isFinite(activeZone) && !isZoneUnlockedLogic(game, activeZone, true)) {
        const fallback = getSafeActiveZoneForRegion(game, _getZoneRegionId(activeZone));
        if (fallback != null && Number.isFinite(fallback) && fallback > 0) {
            setActiveZone(fallback);
        }
    }
    setMaxReachedZone(Number(maxReachedZoneByRegion[String(currentRegion)] || currentZone));
    } finally {
        endZoneAccessBatch();
        invalidateZoneAccessCache();
    }
}

export function getNextZoneInRegionLogic(zoneId: number): number | null {
    const zId = Number(zoneId);
    if (!Number.isFinite(zId)) return null;
    const regionId = _getZoneRegionId(zId);
    const ids = _getSortedZoneIdsForRegion(regionId);
    const idx = ids.indexOf(zId);
    if (idx < 0 || idx >= ids.length - 1) return null;
    return arrayAt(ids, idx + 1) ?? null;
}

/** Prochaine zone annoncée au joueur : saute les hubs verrouillés (ex. Jadielle / arena:8). */
export function getNextProgressionZoneInRegionLogic(game: GameRuntime, zoneId: number): number | null {
    const zId = Number(zoneId);
    if (!Number.isFinite(zId)) return null;
    const ids = _getSortedZoneIdsForRegion(_getZoneRegionId(zId));
    const idx = ids.indexOf(zId);
    if (idx < 0) return null;
    for (let i = idx + 1; i < ids.length; i++) {
        const candidate = ids[i];
        if (candidate !== undefined && _meetsZoneUnlockRequirement(game, candidate)) {
            return candidate;
        }
    }
    return null;
}

type RegionMapArea = { id: number; top: number; left: number; size?: number; width?: number; height?: number };

function _resolveMobileMapAreas(regionId: string): RegionMapArea[] {
    if (regionId === 'kanto' && Array.isArray(KANTO_MAP_AREAS_MOBILE) && KANTO_MAP_AREAS_MOBILE.length) {
        return KANTO_MAP_AREAS_MOBILE;
    }
    if (regionId === 'johto' && Array.isArray(regionMapAssets.JOHTO_MAP_AREAS_MOBILE) && regionMapAssets.JOHTO_MAP_AREAS_MOBILE.length) {
        return regionMapAssets.JOHTO_MAP_AREAS_MOBILE;
    }
    if (regionId === 'hoenn' && Array.isArray(regionMapAssets.HOENN_MAP_AREAS_MOBILE) && regionMapAssets.HOENN_MAP_AREAS_MOBILE.length) {
        return regionMapAssets.HOENN_MAP_AREAS_MOBILE;
    }
    if (regionId === 'sinnoh' && Array.isArray(regionMapAssets.SINNOH_MAP_AREAS_MOBILE) && regionMapAssets.SINNOH_MAP_AREAS_MOBILE.length) {
        return regionMapAssets.SINNOH_MAP_AREAS_MOBILE;
    }
    if (regionId === 'unova' && Array.isArray(regionMapAssets.UNOVA_MAP_AREAS_MOBILE) && regionMapAssets.UNOVA_MAP_AREAS_MOBILE.length) {
        return regionMapAssets.UNOVA_MAP_AREAS_MOBILE;
    }
    if (regionId === 'kalos' && Array.isArray(regionMapAssets.KALOS_MAP_AREAS_MOBILE) && regionMapAssets.KALOS_MAP_AREAS_MOBILE.length) {
        return regionMapAssets.KALOS_MAP_AREAS_MOBILE;
    }
    return [];
}

