function _applyZoneMapAspectRatio(wrap: HTMLElement, regionId: string, img?: HTMLImageElement | null): void {
    if (img && img.naturalWidth > 0 && img.naturalHeight > 0) {
        wrap.style.removeProperty('--zone-map-aspect-ratio');
        return;
    }
    wrap.style.setProperty('--zone-map-aspect-ratio', _getRegionMapAspectRatio(regionId));
}

export function _getRegionMapAreas(regionId: string): RegionMapArea[] {
    if (isMobileViewport()) {
        const mobileAreas = _resolveMobileMapAreas(regionId);
        if (mobileAreas.length) return mobileAreas;
    }
    const meta = _getRegionMeta(regionId);
    if (meta && Array.isArray(meta.hotspots) && meta.hotspots.length) {
        return meta.hotspots as RegionMapArea[];
    }
    if (regionId === 'johto' && Array.isArray(regionMapAssets.JOHTO_MAP_AREAS)) {
        return regionMapAssets.JOHTO_MAP_AREAS;
    }
    if (regionId === 'hoenn' && Array.isArray(regionMapAssets.HOENN_MAP_AREAS)) {
        return regionMapAssets.HOENN_MAP_AREAS;
    }
    if (regionId === 'sinnoh' && Array.isArray(regionMapAssets.SINNOH_MAP_AREAS)) {
        return regionMapAssets.SINNOH_MAP_AREAS;
    }
    if (regionId === 'unova' && Array.isArray(regionMapAssets.UNOVA_MAP_AREAS)) {
        return regionMapAssets.UNOVA_MAP_AREAS;
    }
    if (regionId === 'kalos' && Array.isArray(regionMapAssets.KALOS_MAP_AREAS)) {
        return regionMapAssets.KALOS_MAP_AREAS;
    }
    if (regionId === 'alola' && Array.isArray(regionMapAssets.ALOLA_MAP_AREAS)) {
        return regionMapAssets.ALOLA_MAP_AREAS;
    }
    return (typeof KANTO_MAP_AREAS !== 'undefined' && Array.isArray(KANTO_MAP_AREAS)) ? KANTO_MAP_AREAS : [];
}

