export function _getRegionMapTitle(game: GameRuntime, regionId: string): string {
    const meta = _getRegionMeta(regionId);
    if (zoneLang(game) === 'en') {
        return coalesceStr(meta.mapTitleEn, '') || (coalesceStr(meta.name, regionId) + ' Region Map');
    }
    return coalesceStr(meta.mapTitleFr, '') || ('Carte de ' + coalesceStr(meta.name, regionId));
}

export function _getAvailableRegionIds(): string[] {
    const set: Record<string, boolean> = {};

    const regions = getRegions();
    if (regions) {
        Object.keys(regions).forEach(function (id) {
            if (id) set[String(id)] = true;
        });
    }

    if (typeof ZONES !== 'undefined' && ZONES) {
        Object.keys(ZONES).forEach(function (idStr) {
            const id = Number(idStr);
            if (!Number.isFinite(id)) return;
            const regionId = _getZoneRegionId(id);
            if (regionId) set[String(regionId)] = true;
        });
    }

    // Johto extension may be partially loaded (map/areas present) before full region metadata.
    if (regionMapAssets.JOHTO_MAP_IMAGE_URL || regionMapAssets.JOHTO_MAP_AREAS) {
        set.johto = true;
    }
    if (regionMapAssets.HOENN_MAP_IMAGE_URL || regionMapAssets.HOENN_MAP_AREAS) {
        set.hoenn = true;
    }
    if (regionMapAssets.SINNOH_MAP_IMAGE_URL || regionMapAssets.SINNOH_MAP_AREAS) {
        set.sinnoh = true;
    }

    const ids = Object.keys(set);
    if (!ids.length) return ['kanto'];

    ids.sort(function (a, b) {
        if (a === b) return 0;
        if (a === 'kanto') return -1;
        if (b === 'kanto') return 1;
        return a.localeCompare(b);
    });
    return ids.filter(function (id) {
        return isRegionReleased(id);
    });
}

export function _hasBadgeFlag(game: GameRuntime, badgeKey: string): boolean {
    if (!game || !badgeKey) return false;
    if (typeof game.hasBadge === 'function') return game.hasBadge(badgeKey);
    return !!(game.badges && game.badges[badgeKey]);
}

export function _meetsZoneUnlockRequirement(game: GameRuntime, zoneId: number): boolean {
    const zone = (typeof ZONES !== 'undefined') ? ZONES[zoneId] : null;
    if (!zone || !zone.unlockRequirement) return true;
    const req = String(zone.unlockRequirement);
    if (req.indexOf('badge:') === 0) {
        const badge = req.slice('badge:'.length);
        const hasBadge = _hasBadgeFlag(game, badge);
        if (!hasBadge && badge === 'maitre_kanto') {
            // Safety net: only restore maitre_kanto when there is STRONG evidence the Elite Four
            // was actually defeated in a prior session. Merely reaching the Plateau or clearing
            // the 8th gym is NOT proof ? otherwise Johto would unlock and story_elite_four would
            // auto-validate without ever fighting the league.
            const leagueQuestDone = Array.isArray(game && game.completedStoryQuests)
                && game.completedStoryQuests.indexOf('story_elite_four') !== -1;
            const badgesEarned = Number(game && game.stats && game.stats.badgesEarned);
            const arenasWon = Number(game && game.stats && game.stats.arenasWon);
            const eliteLikelyDone = (Number.isFinite(badgesEarned) && badgesEarned >= 9)
                || (Number.isFinite(arenasWon) && arenasWon >= 9);
            if (leagueQuestDone || eliteLikelyDone) {
                if (game && game.badges) game.badges.maitre_kanto = true;
                if (game && game.stats) {
                    const totalBadges = Object.values(game.badges || {}).filter(function (v) { return v === true; }).length;
                    if (Number.isFinite(totalBadges) && totalBadges > 0) game.stats.badgesEarned = totalBadges;
                }
                return true;
            }
        }
        return hasBadge;
    }
    if (req.indexOf('arena:') === 0) {
        const arenaId = parseInt(req.slice('arena:'.length), 10);
        if (!Number.isFinite(arenaId) || arenaId <= 0) return false;
        return typeof game.isArenaUnlocked === 'function' && game.isArenaUnlocked(String(arenaId));
    }
    if (req.indexOf('zone:') === 0) {
        const reqZoneId = parseInt(req.slice('zone:'.length), 10);
        if (!Number.isFinite(reqZoneId) || reqZoneId <= 0) return false;
        return isZoneMasteredInternal(game, reqZoneId);
    }
    return true;
}

function _isOptionalHubZone(zoneId: number): boolean {
    const zone = ZONES[zoneId];
    return !!(zone && zone.optionalHub === true);
}

/** Kalos/Alola post-league hubs: unlock from League badge only, not chained via prior hub mastery. */
function _usesMainlinePrevForOptionalHubUnlock(zoneId: number): boolean {
    const zone = ZONES[zoneId];
    if (!zone || zone.optionalHub !== true) return false;
    const regionId = String(zone.regionId);
    const req = String(zone.unlockRequirement || '');
    if (regionId === 'kalos' && req === 'badge:maitre_kalos') return true;
    if (regionId === 'alola' && req === 'badge:maitre_alola') return true;
    return false;
}

function _getPreviousZoneIdForUnlockCheck(zoneId: number): number | null {
    if (_isOptionalHubZone(zoneId)) {
        if (_usesMainlinePrevForOptionalHubUnlock(zoneId)) {
            return _getPreviousMainlineZoneIdInRegion(zoneId);
        }
        return _getPreviousZoneIdInRegion(zoneId);
    }
    return _getPreviousMainlineZoneIdInRegion(zoneId);
}

/** Previous zone for the UI "Previous area" button (same rules as unlock predecessor). */
export function _getPreviousAreaZoneIdInRegion(zoneId: number): number | null {
    return _getPreviousZoneIdForUnlockCheck(zoneId);
}

/** Previous zone in regional order, skipping optional side hubs. */
export function _getPreviousMainlineZoneIdInRegion(zoneId: number): number | null {
    const zId = Number(zoneId);
    if (!Number.isFinite(zId)) return null;
    const regionId = _getZoneRegionId(zId);
    const ids = _getSortedZoneIdsForRegion(regionId);
    const idx = ids.indexOf(zId);
    if (idx <= 0) return null;
    for (let i = idx - 1; i >= 0; i--) {
        const prevId = ids[i];
        if (prevId !== undefined && !_isOptionalHubZone(prevId)) return prevId;
    }
    return null;
}

export function _isRegionUnlocked(game: GameRuntime, regionId: string): boolean {
    return isRegionUnlockedForGame(game, regionId);
}

/** Ramène zone/région actives si la save pointe vers une région non publiée (ex. dev en Sinnoh). */
export function clampActiveZoneToReleasedRegions(_game: GameRuntime): void {
    const activeZone = Number.isFinite(Number(currentZone)) ? Number(currentZone) : 1;
    const zoneRegion = _getZoneRegionId(activeZone);
    if (isRegionReleased(zoneRegion)) return;

    let targetZone: number | null = null;
    let targetRegion: string | null = null;
    const releasedIds = [...RELEASED_REGION_IDS].reverse();
    for (const regionId of releasedIds) {
        const regionMax = Number(maxReachedZoneByRegion?.[regionId]) || 0;
        if (regionMax > 0 && typeof ZONES !== 'undefined' && ZONES[regionMax] && _getZoneRegionId(regionMax) === regionId) {
            targetZone = regionMax;
            targetRegion = regionId;
            break;
        }
    }
    if (targetZone == null) {
        for (const regionId of releasedIds) {
            const lastInRegion = _getLastZoneIdForRegion(regionId);
            if (lastInRegion != null && Number.isFinite(lastInRegion)) {
                targetZone = lastInRegion;
                targetRegion = regionId;
                break;
            }
        }
    }

    if (targetZone == null || !Number.isFinite(targetZone)) {
        targetZone = _getFirstZoneIdForRegion('kanto') || 1;
        setCurrentRegion('kanto');
    } else {
        setCurrentRegion(String(targetRegion || 'kanto'));
    }

    setActiveZone(targetZone);
    setMaxReachedZone(targetZone);
    if (maxReachedZoneByRegion) {
        const regionForZone = _getZoneRegionId(targetZone);
        const prev = Number(maxReachedZoneByRegion[regionForZone]);
        if (!Number.isFinite(prev) || prev < targetZone) {
            maxReachedZoneByRegion[regionForZone] = targetZone;
        }
    }
}

let ensureRegionProgressDepth = 0;

type RegionAccessSnapshot = {
    sorted: number[];
    gapBlockIdx: number;
    unlocked: Map<number, boolean>;
};

let zoneAccessBatchGame: GameRuntime | null = null;
let zoneAccessBatchByRegion: Map<string, RegionAccessSnapshot> | null = null;
let zoneSelectorRefreshRaf: number | null = null;

export function invalidateZoneAccessCache(): void {
    zoneAccessBatchGame = null;
    zoneAccessBatchByRegion = null;
}

function beginZoneAccessBatch(game: GameRuntime): void {
    zoneAccessBatchGame = game;
    zoneAccessBatchByRegion = new Map();
}

function endZoneAccessBatch(): void {
    zoneAccessBatchGame = null;
    zoneAccessBatchByRegion = null;
}

/** Coalesce multiple updateZoneSelector calls into one refresh per frame. */
export function scheduleZoneSelectorRefresh(game: GameRuntime): void {
    if (typeof requestAnimationFrame !== 'function') {
        updateZoneSelectorLogic(game);
        return;
    }
    if (zoneSelectorRefreshRaf != null) return;
    zoneSelectorRefreshRaf = requestAnimationFrame(function () {
        zoneSelectorRefreshRaf = null;
        updateZoneSelectorLogic(game);
    });
}

function isZoneMasteredInternal(game: GameRuntime, zoneId: number): boolean {
    const zone = ZONES[zoneId];
    if (!zone) return false;
    const zoneRegionId = _getZoneRegionId(zoneId);
    const firstZoneInRegion = _getFirstZoneIdForRegion(zoneRegionId);
    if (Number(firstZoneInRegion) === Number(zoneId)
        && getProgressionMasteryPokemonInZoneLogic(game, zoneId).length === 0) {
        return true;
    }

    if (zone.isFinal) {
        const leagueId = String(zone.leagueId || 'elite_four_gen1');
        const fallbackElite = getEliteFourLeagueEntry(leagueId);
        const e4 = getEliteFours() as Record<string, EliteFourLeagueDef>;
        const leagueDef: EliteFourLeagueDef | undefined = e4[leagueId]
            ? e4[leagueId]
            : (Array.isArray(fallbackElite) ? undefined : (fallbackElite as EliteFourLeagueDef | null) ?? undefined);
        const rewardBadge = coalesceStr(
            leagueDef?.rewardBadge,
            'maitre_' + coalesceStr(zone.regionId, 'kanto'),
        );
        return (typeof game.hasBadge === 'function')
            ? game.hasBadge(rewardBadge)
            : !!(game.badges && game.badges[rewardBadge] === true);
    }

    if (zone.isGym) {
        return isGymZoneMasteredLogic(game, zoneId);
    }

    const progress = game.zoneProgress && game.zoneProgress[zoneId];
    if (!progress) return false;

    if (Number(zone.requiredBosses) > 0 && (progress.bossesDefeated || 0) < Number(zone.requiredBosses)) return false;
    if (Number(zone.requiredEpics) > 0 && (progress.epicsDefeated || 0) < Number(zone.requiredEpics)) return false;

    const pokemonInZone = getProgressionMasteryPokemonInZoneLogic(game, zoneId);
    if (!pokemonInZone.length) return false;
    const tiers = progress.pokemonTiers || {};
    const maxTier = zone.maxTier || 50;
    let masterySpecies = pokemonInZone.filter(function (name) {
        return !isNaturalLegendarySpeciesForZoneLogic(game, name);
    });
    if (!masterySpecies.length) masterySpecies = pokemonInZone;
    return masterySpecies.every(function (name) {
        return getZonePokemonTier(tiers, name) >= maxTier;
    });
}

/** First sorted index that blocks downstream travel when zoneProgress exists beyond a gap. */
function computeRegionGapBlockIdx(game: GameRuntime, sorted: number[]): number {
    const progress = game.zoneProgress && typeof game.zoneProgress === 'object' ? game.zoneProgress : {};
    let suffixHasProgress = false;
    let blockIdx = sorted.length;

    for (let i = sorted.length - 1; i >= 0; i--) {
        const zId = sorted[i];
        if (zId === undefined) continue;
        const shouldEvaluateBlock = suffixHasProgress || !!progress[zId];
        if (shouldEvaluateBlock) {
            const zone = ZONES[zId];
            if (!zone || !_meetsZoneUnlockRequirement(game, zId)) {
                if (progress[zId]) suffixHasProgress = true;
                continue;
            }
            if (zone.optionalHub === true) {
                if (progress[zId]) suffixHasProgress = true;
                continue;
            }
            if (zone.isGym || zone.isFinal) {
                if (!isZoneMasteredInternal(game, zId)) {
                    blockIdx = Math.min(blockIdx, i);
                }
            } else {
                const pool = getProgressionMasteryPokemonInZoneLogic(game, zId);
                if (pool.length && !isZoneMasteredInternal(game, zId)) {
                    blockIdx = Math.min(blockIdx, i);
                }
            }
        }
        if (progress[zId]) suffixHasProgress = true;
    }
    return blockIdx;
}

function isMasteryChainIntactAtIdx(targetIdx: number, gapBlockIdx: number, sortedLength: number): boolean {
    if (gapBlockIdx >= sortedLength) return true;
    return targetIdx <= gapBlockIdx;
}

function computeZoneUnlockedInSnapshot(
    game: GameRuntime,
    zId: number,
    sorted: number[],
    gapBlockIdx: number,
    unlocked: Map<number, boolean>,
    checkPrevious: boolean,
): boolean {
    if (zId === 1) return true;
    if (!ZONES[zId]) return false;

    const regionId = _getZoneRegionId(zId);
    if (!_isRegionUnlocked(game, regionId)) return false;
    if (!_meetsZoneUnlockRequirement(game, zId)) return false;

    const targetIdx = sorted.indexOf(zId);
    if (targetIdx >= 0 && !isMasteryChainIntactAtIdx(targetIdx, gapBlockIdx, sorted.length)) {
        return false;
    }

    if (!checkPrevious) return true;

    const prevZoneId = _getPreviousZoneIdForUnlockCheck(zId);
    if (!prevZoneId) return true;

    const prevUnlocked = unlocked.get(prevZoneId);
    if (prevUnlocked === false) return false;
    if (prevUnlocked !== true && !computeZoneUnlockedInSnapshot(game, prevZoneId, sorted, gapBlockIdx, unlocked, false)) {
        return false;
    }

    const prevZone = ZONES[prevZoneId];
    if (prevZone && !prevZone.isGym && !prevZone.isFinal) {
        const prevZonePokemon = getProgressionMasteryPokemonInZoneLogic(game, prevZoneId);
        if (!prevZonePokemon.length) {
            const hubPrevId = _getPreviousMainlineZoneIdInRegion(prevZoneId);
            if (hubPrevId != null && !isZoneMasteredInternal(game, hubPrevId)) return false;
            return true;
        }
    }
    if (!isZoneMasteredInternal(game, prevZoneId)) return false;
    return true;
}

function buildRegionAccessSnapshot(game: GameRuntime, regionId: string): RegionAccessSnapshot {
    const sorted = _getSortedZoneIdsForRegion(regionId);
    const gapBlockIdx = computeRegionGapBlockIdx(game, sorted);
    const unlocked = new Map<number, boolean>();
    for (let i = 0; i < sorted.length; i++) {
        const zId = sorted[i];
        if (zId === undefined) continue;
        unlocked.set(zId, computeZoneUnlockedInSnapshot(game, zId, sorted, gapBlockIdx, unlocked, true));
    }
    return { sorted, gapBlockIdx, unlocked };
}

function getRegionAccessSnapshot(game: GameRuntime, regionId: string): RegionAccessSnapshot {
    if (zoneAccessBatchByRegion && zoneAccessBatchGame === game) {
        const cached = zoneAccessBatchByRegion.get(regionId);
        if (cached) return cached;
        const built = buildRegionAccessSnapshot(game, regionId);
        zoneAccessBatchByRegion.set(regionId, built);
        return built;
    }
    return buildRegionAccessSnapshot(game, regionId);
}

export function ensureRegionProgressStateLogic(game: GameRuntime): void {
    if (ensureRegionProgressDepth > 0) return;
    ensureRegionProgressDepth++;
    try {
    if (!maxReachedZoneByRegion || typeof maxReachedZoneByRegion !== 'object') {
        replaceMaxReachedZoneByRegion({});
    }
    if (!currentRegion) {
        setCurrentRegion(_getZoneRegionId(Number.isFinite(Number(currentZone)) ? currentZone : 1));
    }

    if (!Number.isFinite(Number(currentZone))) setActiveZone(1);
    const currentZoneRegion = _getZoneRegionId(currentZone);
    // Do NOT force currentRegion to currentZoneRegion on every call.
    // Otherwise selecting another region is instantly cancelled on the next refresh cycle.
    if (!currentRegion) {
        setCurrentRegion(currentZoneRegion);
    } else {
        const knownRegions = _getAvailableRegionIds();
        if (knownRegions.indexOf(String(currentRegion)) === -1) {
            setCurrentRegion(currentZoneRegion);
        }
    }

    const knownRegionsForProgress = _getAvailableRegionIds();
    for (let i = 0; i < knownRegionsForProgress.length; i++) {
        const regionId = knownRegionsForProgress[i];
        if (regionId === undefined) continue;
        const firstZoneId = _getFirstZoneIdForRegion(regionId);
        const currentVal = Number(maxReachedZoneByRegion[regionId]);
        if (regionId === 'kanto') {
            const kantoFirst = firstZoneId || 1;
            if (!Number.isFinite(currentVal) || currentVal <= 0) {
                maxReachedZoneByRegion[regionId] = Math.max(Number(maxReachedZone) || kantoFirst, kantoFirst);
            }
        }
    }

    sanitizeCrossRegionMaxReachedPollution(maxReachedZoneByRegion);
    sanitizeRegionalProgressWithoutStarterCommitment(game, maxReachedZoneByRegion);

    const currentZoneNum = Number(currentZone);
    const activeRegionForCap = _getZoneRegionId(currentZoneNum);
    if (shouldClampActiveZoneToCap(game, currentZoneNum)) {
        const fallback = getSafeActiveZoneForRegion(game, activeRegionForCap);
        if (fallback != null && Number.isFinite(fallback) && fallback > 0) {
            setActiveZone(fallback);
        }
    }

    const regionMax = Number(maxReachedZoneByRegion[currentZoneRegion]);
    if (
        (!Number.isFinite(regionMax) || regionMax <= 0)
        && hasRegionalStarterCommitment(game, currentZoneRegion)
    ) {
        const firstInRegion = _getFirstZoneIdForRegion(currentZoneRegion) || currentZoneNum;
        maxReachedZoneByRegion[currentZoneRegion] = firstInRegion;
    }

    setMaxReachedZone(Number(maxReachedZoneByRegion[currentRegion] || 0));
    if (
        (!Number.isFinite(maxReachedZone) || maxReachedZone <= 0)
        && hasRegionalStarterCommitment(game, currentRegion)
    ) {
        setMaxReachedZone(Number(_getFirstZoneIdForRegion(currentRegion) || 1));
        maxReachedZoneByRegion[currentRegion] = maxReachedZone;
    }

    clampActiveZoneToReleasedRegions(game);

    const postTravelRegion = _getZoneRegionId(currentZone);
    const postTravelZone = Number(currentZone);
    if (shouldClampActiveZoneToCap(game, postTravelZone)) {
        const fallback = getSafeActiveZoneForRegion(game, postTravelRegion);
        if (fallback != null && Number.isFinite(fallback) && fallback > 0) {
            setActiveZone(fallback);
            const frontier = getFurthestAccessibleZoneInRegionLogic(game, postTravelRegion);
            if (
                maxReachedZoneByRegion
                && frontier != null
                && frontier > 0
                && hasRegionalStarterCommitment(game, postTravelRegion)
            ) {
                maxReachedZoneByRegion[postTravelRegion] = frontier;
            }
        }
    }

    syncZoneGlobalsToWindow();
    } finally {
        ensureRegionProgressDepth--;
    }
}

