export function _hasSurfboard(game: GameRuntime): boolean {
    if (!game || !game.items) return false;
    return Number(game.items['surfboard'] || 0) > 0;
}

export function _hasAnyFishingRod(game: GameRuntime): boolean {
    if (!game || !game.items) return false;
    return Number(game.items['old_rod'] || 0) > 0
        || Number(game.items['super_rod'] || 0) > 0
        || Number(game.items['mega_rod'] || 0) > 0;
}

type SpawnChannel = 'land' | 'water' | 'fishing';

function _zoneEntryChannel(entry: unknown): SpawnChannel | null {
    if (typeof entry !== 'object' || !entry || entry === null) return null;
    const ch = (entry as { channel?: string }).channel;
    if (ch === 'land' || ch === 'water' || ch === 'fishing') return ch;
    return null;
}

function _flatPoolUsesChannelTags(zoneData: unknown): boolean {
    if (!Array.isArray(zoneData)) return false;
    return (zoneData as unknown[]).some(function (entry: unknown) {
        return _zoneEntryChannel(entry) != null;
    });
}

function _isTaggedEntryReachable(game: GameRuntime, entry: unknown): boolean {
    const channel = _zoneEntryChannel(entry);
    if (!channel) return true;
    if (channel === 'land') return true;
    if (channel === 'water') return _hasSurfboard(game);
    if (channel === 'fishing') return _hasAnyFishingRod(game);
    return true;
}

/**
 * R?cup?re TOUS les Pokémon d'une zone (liste de noms uniques).
 * Sert pour le calcul technique (Tiers, Chargement, etc.)
 * G?re les tableaux de strings ou de { name, weight } (spawn rate).
 */
export function getAllPokemonInZoneLogic(game: GameRuntime, zoneId: number): string[] {
    if (typeof ZONE_POKEMON === 'undefined') return [];
    const zoneData = ZONE_POKEMON[zoneId] as unknown;
    if (!zoneData) return [];

    if (Array.isArray(zoneData)) {
        if (_flatPoolUsesChannelTags(zoneData)) {
            return [...new Set((zoneData as unknown[])
                .map(function (entry: unknown) { return _zoneEntryToName(entry as string | { name?: string; [key: string]: unknown }); })
                .filter(Boolean))];
        }
        const allArray = (zoneData as unknown[])
            .map(function(entry: unknown) { return _zoneEntryToName(entry as string | { name?: string; [key: string]: unknown }); })
            .concat(_getZoneWaterEntries(zoneData, zoneId).map(function(entry: unknown) { return _zoneEntryToName(entry as string | { name?: string; [key: string]: unknown }); }))
            .concat(_getZoneFishingEntries(zoneData, zoneId).map(function(entry: unknown) { return _zoneEntryToName(entry as string | { name?: string; [key: string]: unknown }); }));
        return [...new Set(allArray)];
    }
    if (typeof zoneData === 'object') {
        let all: string[] = [];
        const zd = zoneData as ZonePokemonPool;
        if (zd.land) all = all.concat(Array.isArray(zd.land) ? zd.land.map(function(e: ZonePokemonEntry) { return _zoneEntryToName(e); }) : [_zoneEntryToName(zd.land)]);
        const waterEntries = _getZoneWaterEntries(zoneData, zoneId);
        if (waterEntries.length) all = all.concat(waterEntries.map(function(e: unknown) { return _zoneEntryToName(e as string | { name?: string; [key: string]: unknown }); }));
        const fishingEntries = _getZoneFishingEntries(zoneData, zoneId);
        if (fishingEntries.length) all = all.concat(fishingEntries.map(function(e: unknown) { return _zoneEntryToName(e as string | { name?: string; [key: string]: unknown }); }));
        return [...new Set(all)];
    }
    return [];
}

/**
 * R?cup?re uniquement les Pokémon que le joueur PEUT rencontrer actuellement
 * (Exclut les poissons s'il n'a pas de canne, etc.)
 * G?re les tableaux de strings ou de { name, weight }.
 */
export function getReachablePokemonInZoneLogic(game: GameRuntime, zoneId: number): string[] {
    if (typeof ZONE_POKEMON === 'undefined') return [];
    const zoneData = ZONE_POKEMON[zoneId] as unknown;
    if (!zoneData) return [];

    if (Array.isArray(zoneData)) {
        if (_flatPoolUsesChannelTags(zoneData)) {
            return [...new Set((zoneData as ZonePokemonEntry[])
                .filter(function (entry: ZonePokemonEntry) { return _isTaggedEntryReachable(game, entry); })
                .map(function (entry: ZonePokemonEntry) { return _zoneEntryToName(entry); })
                .filter(Boolean))];
        }
        let reachableArray: string[] = (zoneData as unknown[]).map(function(entry: unknown) { return _zoneEntryToName(entry as string | { name?: string; [key: string]: unknown }); });
        if (_hasSurfboard(game)) {
            reachableArray = reachableArray.concat(_getZoneWaterEntries(zoneData, zoneId).map(function(entry: unknown) { return _zoneEntryToName(entry as string | { name?: string; [key: string]: unknown }); }));
        }
        if (_hasAnyFishingRod(game)) {
            reachableArray = reachableArray.concat(_getZoneFishingEntries(zoneData, zoneId).map(function(entry: unknown) { return _zoneEntryToName(entry as string | { name?: string; [key: string]: unknown }); }));
        }
        return [...new Set(reachableArray)];
    }
    let reachable: string[] = [];
    const zd = zoneData as ZonePokemonPool;
    if (zd.land) reachable = reachable.concat(Array.isArray(zd.land) ? zd.land.map(function(e: ZonePokemonEntry) { return _zoneEntryToName(e); }) : [_zoneEntryToName(zd.land)]);
    if (_hasSurfboard(game)) {
        reachable = reachable.concat(_getZoneWaterEntries(zoneData, zoneId).map(function(entry: unknown) { return _zoneEntryToName(entry as string | { name?: string; [key: string]: unknown }); }));
    }
    if (_hasAnyFishingRod(game)) {
        reachable = reachable.concat(_getZoneFishingEntries(zoneData, zoneId).map(function(entry: unknown) { return _zoneEntryToName(entry as string | { name?: string; [key: string]: unknown }); }));
    }
    return [...new Set(reachable)];
}

function _zoneEntryWeight(entry: unknown, defaultWeight: number): number {
    if (typeof entry === 'object' && entry && entry !== null && 'weight' in entry) {
        const w = Number((entry as { weight?: number }).weight);
        return Number.isFinite(w) && w > 0 ? w : defaultWeight;
    }
    return defaultWeight;
}

/** Weighted encounter entries the player can reach in a zone (land / surf / fishing per inventory). */
export function getWeightedReachableEntriesInZoneLogic(
    game: GameRuntime,
    zoneId: number,
): Array<{ name: string; weight: number }> {
    if (typeof ZONE_POKEMON === 'undefined') return [];
    const zoneData = ZONE_POKEMON[zoneId] as unknown;
    if (!zoneData) return [];

    const weightedPool: Array<{ name: string; weight: number }> = [];

    if (Array.isArray(zoneData)) {
        if (_flatPoolUsesChannelTags(zoneData)) {
            (zoneData as ZonePokemonEntry[]).forEach(function (entry: ZonePokemonEntry) {
                if (!_isTaggedEntryReachable(game, entry)) return;
                if (typeof entry === 'object' && entry && entry.name != null) {
                    weightedPool.push({ name: entry.name, weight: _zoneEntryWeight(entry, 1) });
                } else if (typeof entry === 'string') {
                    weightedPool.push({ name: entry, weight: 1 });
                }
            });
        } else {
            (zoneData as ZonePokemonEntry[]).forEach(function (entry: ZonePokemonEntry) {
                if (typeof entry === 'object' && entry && entry.name != null) {
                    weightedPool.push({ name: entry.name, weight: _zoneEntryWeight(entry, 1) });
                } else if (typeof entry === 'string') {
                    weightedPool.push({ name: entry, weight: 1 });
                }
            });
            if (_hasSurfboard(game)) {
                _getZoneWaterEntries(zoneData, zoneId).forEach(function (e: ZonePokemonEntry) {
                    const speciesName = _zoneEntryToName(e);
                    if (!speciesName) return;
                    weightedPool.push({ name: speciesName, weight: _zoneEntryWeight(e, 8) });
                });
            }
            if (_hasAnyFishingRod(game)) {
                _getZoneFishingEntries(zoneData, zoneId).forEach(function (e: ZonePokemonEntry) {
                    const speciesName = _zoneEntryToName(e);
                    if (!speciesName) return;
                    weightedPool.push({ name: speciesName, weight: _zoneEntryWeight(e, 8) });
                });
            }
        }
    } else if (typeof zoneData === 'object') {
        const structuredPool = zoneData as ZonePokemonPool;
        if (structuredPool.land) {
            const landRaw = structuredPool.land;
            const landEntries: ZonePokemonEntry[] = Array.isArray(landRaw) ? landRaw : [landRaw];
            landEntries.forEach(function (e: ZonePokemonEntry) {
                const name = _zoneEntryToName(e);
                if (!name) return;
                weightedPool.push({ name, weight: _zoneEntryWeight(e, 1) });
            });
        }
        if (_hasSurfboard(game)) {
            _getZoneWaterEntries(zoneData, zoneId).forEach(function (e: ZonePokemonEntry) {
                const speciesName = _zoneEntryToName(e);
                if (!speciesName) return;
                weightedPool.push({ name: speciesName, weight: _zoneEntryWeight(e, 1) });
            });
        }
        if (_hasAnyFishingRod(game)) {
            _getZoneFishingEntries(zoneData, zoneId).forEach(function (e: ZonePokemonEntry) {
                const speciesName = _zoneEntryToName(e);
                if (!speciesName) return;
                weightedPool.push({ name: speciesName, weight: _zoneEntryWeight(e, 1) });
            });
        }
    }
    return weightedPool;
}

/** True si la zone peut encore g?n?rer un sauvage (land / surf / p?che selon l'inventaire). */
export function hasWildSpawnPoolInZoneLogic(game: GameRuntime, zoneId: number): boolean {
    return getReachablePokemonInZoneLogic(game, zoneId).length > 0;
}

/** True si handleCombatLogic peut lancer startCombat() automatiquement (sauvages ou dresseurs gym classiques). */
export function canAutoStartCombatInZoneLogic(game: GameRuntime, zoneId: number): boolean {
    if (hasWildSpawnPoolInZoneLogic(game, zoneId)) return true;
    const zone = ZONES[zoneId];
    return !!(zone && zone.isGym && !zone.isFinal);
}

/** Zone de route d'arène (dresseurs récurrents, hors Ligue isFinal). */
export function isGymRouteZone(zoneId: number): boolean {
    const zone = ZONES[zoneId];
    return !!(zone && zone.isGym && !zone.isFinal);
}

/** Town / gym city / league hubs intentionally have no wild encounter pool. */
export function isHubZoneWithoutWildEncounters(zone: {
    name?: string;
    isGym?: boolean;
    isFinal?: boolean;
}): boolean {
    if (zone.isGym || zone.isFinal) return true;
    return /\b(Town|City|League)\b/i.test(zone.name || '');
}

/** Zone sans objectif de maîtrise espèces (ville de transit). Les gyms/ligue ont leur propre critère. */
export function isTransitHubZoneLogic(game: GameRuntime, zoneId: number): boolean {
    const zone = ZONES[zoneId];
    if (!zone || zone.isGym || zone.isFinal) return false;
    return getProgressionMasteryPokemonInZoneLogic(game, zoneId).length === 0;
}

/** Cooldown apr?s un spawn sauvage d'une esp?ce ? raret? naturelle l?gendaire (boss / ?pique exclus). */
export const LEGENDARY_WILD_SPAWN_COOLDOWN_MS = 6 * 60 * 1000;

export function _naturalRarityForZoneSystem(game: GameRuntime, speciesName: string): string {
    if (game && typeof game.getNaturalRarity === 'function') return game.getNaturalRarity(speciesName);
    return RARITY.COMMON;
}

/** Esp?ce dont la raret? dans POKEMON_POOL est l?gendaire (utilis? ma?trise + pools ?pique + cooldown sauvage). */
export function isNaturalLegendarySpeciesForZoneLogic(game: GameRuntime, speciesName: string): boolean {
    return _naturalRarityForZoneSystem(game, speciesName) === RARITY.LEGENDARY;
}

export function _ensureLegendaryWildCooldownMap(game: GameRuntime): void {
    if (!game.legendaryWildCooldownUntil || typeof game.legendaryWildCooldownUntil !== 'object') {
        game.legendaryWildCooldownUntil = {};
    }
}

/** Live wall clock, or virtual AFK timeline during offline zone sim. */
export function getLegendaryWildCooldownNowMs(game: GameRuntime): number {
    if (game.isOfflineSimulating) {
        const simNow = Number(game._offlineSimClockMs);
        if (Number.isFinite(simNow)) return simNow;
    }
    return Date.now();
}

export function isLegendaryWildCooldownActiveLogic(game: GameRuntime, speciesName: string): boolean {
    _ensureLegendaryWildCooldownMap(game);
    const until = Number(game.legendaryWildCooldownUntil[speciesName]);
    return Number.isFinite(until) && getLegendaryWildCooldownNowMs(game) < until;
}

function _writeLegendaryWildCooldownForSpeciesLogic(game: GameRuntime, speciesName: string): void {
    if (!isNaturalLegendarySpeciesForZoneLogic(game, speciesName)) return;
    _ensureLegendaryWildCooldownMap(game);
    const now = getLegendaryWildCooldownNowMs(game);
    game.legendaryWildCooldownUntil[speciesName] = now + LEGENDARY_WILD_SPAWN_COOLDOWN_MS;
}

function _shouldApplyLegendaryWildEncounterCooldown(
    game: GameRuntime,
    enemy: { name: string; isBoss?: boolean; isEpic?: boolean; isGymTrainer?: boolean; isRoaming?: boolean },
): boolean {
    if (!enemy?.name) return false;
    if (enemy.isBoss || enemy.isEpic || enemy.isGymTrainer) return false;
    return !!(enemy.isRoaming || isNaturalLegendarySpeciesForZoneLogic(game, enemy.name));
}

/** Spawn / alerte live uniquement (bloqu? en offline pour ?viter CD fant?me au tirage). */
export function setLegendaryWildCooldownForSpeciesLogic(game: GameRuntime, speciesName: string): void {
    if (game.isOfflineSimulating) return;
    _writeLegendaryWildCooldownForSpeciesLogic(game, speciesName);
}

/** Apr?s un combat de zone live : cooldown sur l'esp?ce affront?e (pool l?gendaire ou roamer). */
export function applyLegendaryWildCooldownAfterEncounterLogic(
    game: GameRuntime,
    enemy: { name: string; isBoss?: boolean; isEpic?: boolean; isGymTrainer?: boolean; isRoaming?: boolean },
): void {
    if (game.isOfflineSimulating) return;
    if (!_shouldApplyLegendaryWildEncounterCooldown(game, enemy)) return;
    _writeLegendaryWildCooldownForSpeciesLogic(game, enemy.name);
}

/** Apr?s une victoire simul?e offline : m?me anti-farm que le live (sans toucher pendingRoamer au spawn). */
export function applyLegendaryWildCooldownAfterOfflineEncounterLogic(
    game: GameRuntime,
    enemy: { name: string; isBoss?: boolean; isEpic?: boolean; isGymTrainer?: boolean; isRoaming?: boolean },
): void {
    if (!_shouldApplyLegendaryWildEncounterCooldown(game, enemy)) return;
    _writeLegendaryWildCooldownForSpeciesLogic(game, enemy.name);
}

/**
 * Tirage pond?r? en excluant les l?gendaires encore en cooldown (poids mis ? 0).
 * Repli : esp?ces non l?gendaires seulement ; dernier recours : premi?re entr?e du pool.
 */
export function _pickWeightedWildRespectingLegendaryCooldown(game: GameRuntime, weightedPool: Array<{ name: string; weight: number }>): string {
    let filtered = weightedPool.map(function (e) {
        let w = e.weight;
        if (isNaturalLegendarySpeciesForZoneLogic(game, e.name) && isLegendaryWildCooldownActiveLogic(game, e.name)) {
            w = 0;
        }
        return { name: e.name, weight: w };
    });
    let total = filtered.reduce(function (s, x) { return s + x.weight; }, 0);
    if (total <= 0) {
        filtered = weightedPool.map(function (e) {
            const w = isNaturalLegendarySpeciesForZoneLogic(game, e.name) ? 0 : e.weight;
            return { name: e.name, weight: w };
        });
        total = filtered.reduce(function (s, x) { return s + x.weight; }, 0);
    }
    const poolFallback = arrayAt(weightedPool, 0);
    if (total <= 0) {
        const nonLegendary = weightedPool.find(function (e) {
            return !isNaturalLegendarySpeciesForZoneLogic(game, e.name);
        });
        if (nonLegendary) return nonLegendary.name;
        const legendaryOffCd = weightedPool.find(function (e) {
            return isNaturalLegendarySpeciesForZoneLogic(game, e.name)
                && !isLegendaryWildCooldownActiveLogic(game, e.name);
        });
        if (legendaryOffCd) return legendaryOffCd.name;
        return '';
    }
    let r = Math.random() * total;
    for (let i = 0; i < filtered.length; i++) {
        const entry = filtered[i];
        if (!entry || entry.weight <= 0) continue;
        r -= entry.weight;
        if (r <= 0) return entry.name;
    }
    const lastFiltered = arrayAt(filtered, filtered.length - 1);
    return lastFiltered?.name ?? poolFallback?.name ?? '';
}

export function _nonLegendaryReachablePoolForEpic(game: GameRuntime, zoneId: number): string[] {
    const pool = getReachablePokemonInZoneLogic(game, zoneId);
    return pool.filter(function (n) { return !isNaturalLegendarySpeciesForZoneLogic(game, n); });
}

/**
 * V?rifie si une zone est termin?e ? 100%
 */
export function isZoneMasteredLogic(game: GameRuntime, zoneId: number): boolean {
    if (ensureRegionProgressDepth === 0 && zoneAccessBatchByRegion === null) {
        ensureRegionProgressStateLogic(game);
    }
    return isZoneMasteredInternal(game, zoneId);
}

/**
 * Verification deblocage Zone (avec progression regionale)
 */
export function isZoneUnlockedLogic(game: GameRuntime, zoneId: number, checkPrevious: boolean): boolean {
    if (ensureRegionProgressDepth === 0 && zoneAccessBatchByRegion === null) {
        ensureRegionProgressStateLogic(game);
    }
    if (checkPrevious === undefined) checkPrevious = true;
    const zId = Number(zoneId);

    if (zoneAccessBatchByRegion && zoneAccessBatchGame === game && checkPrevious) {
        const regionId = _getZoneRegionId(zId);
        const snapshot = getRegionAccessSnapshot(game, regionId);
        const cached = snapshot.unlocked.get(zId);
        if (cached !== undefined) return cached;
    }

    const sorted = _getSortedZoneIdsForRegion(_getZoneRegionId(zId));
    const gapBlockIdx = computeRegionGapBlockIdx(game, sorted);
    const unlockedScratch = new Map<number, boolean>();
    return computeZoneUnlockedInSnapshot(game, zId, sorted, gapBlockIdx, unlockedScratch, checkPrevious);
}

export function updateZoneSelectorLogic(game: GameRuntime): void {
    beginZoneAccessBatch(game);
    try {
    ensureRegionProgressStateLogic(game);

    const selector = getSelect('zoneSelect');
    const mapEl = getById('zoneMap');
    if (!selector) return;

    const regionSnapshot = getRegionAccessSnapshot(game, currentRegion);

    const regionSelect = getSelect('regionSelect');
    const availableRegionIds = _getAvailableRegionIds();

    if (regionSelect) {
        const regionSelectManagedBySvelte = !!regionSelect.closest('[data-svelte-ui]');
        if (!regionSelectManagedBySvelte) {
            if (!regionSelect.dataset.regionBound) {
                regionSelect.addEventListener('change', function () {
                    if (typeof game.changeRegion === 'function') {
                        game.changeRegion((this).value);
                    }
                });
                regionSelect.dataset.regionBound = '1';
            }

            regionSelect.innerHTML = '';
            availableRegionIds.forEach(function (regionId) {
                const option = document.createElement('option');
                option.value = regionId;
                const meta = _getRegionMeta(regionId);
                option.textContent = coalesceStr(meta.name, regionId).toUpperCase();
                option.disabled = !_isRegionUnlocked(game, regionId);
                regionSelect.appendChild(option);
            });
            if (!_isRegionUnlocked(game, currentRegion)) setCurrentRegion('kanto');
            regionSelect.value = currentRegion;
            regionSelect.disabled = availableRegionIds.length <= 1;
        }
    }

    if (!_isRegionUnlocked(game, currentRegion)) setCurrentRegion('kanto');
    const zoneIds = _getSortedZoneIdsForRegion(currentRegion);

    selector.innerHTML = '';
    zoneIds.forEach(function (zId) {
        const option = document.createElement('option');
        option.value = String(zId);
        option.text = zoneDisplayName(game, zId, ZONES[zId] ? ZONES[zId].name : ('Zone ' + zId));
        option.disabled = !(regionSnapshot.unlocked.get(zId) ?? false);
        selector.appendChild(option);
    });

    if (_getZoneRegionId(currentZone) !== currentRegion) {
        const fallbackZone = _findFirstUnlockedZoneInRegion(game, currentRegion);
        if (fallbackZone != null) setActiveZone(Number(fallbackZone));
    }
    selector.value = String(currentZone);

    const mapTitleEl = getById('zoneMapTitleLabel');
    const mapTitle = _getRegionMapTitle(game, currentRegion);
    if (mapTitleEl) mapTitleEl.textContent = mapTitle;

    if (!mapEl) return;

    const mapAreas = _getRegionMapAreas(currentRegion);
    const viewportKey = isMobileViewport() ? 'mobile' : 'desktop';
    const layoutKey = _getZoneMapLayoutKey();
    if (
        mapEl.dataset.regionId !== currentRegion
        || mapEl.dataset.viewportKey !== viewportKey
        || mapEl.dataset.layoutKey !== layoutKey
    ) {
        mapEl.innerHTML = '';
        const imgUrl = _getRegionMapImageUrl(currentRegion);
        const wrap = document.createElement('div');
        wrap.className = 'zone-map-kanto';
        _applyZoneMapAspectRatio(wrap, currentRegion);
        wrap.innerHTML = '<img class="zone-map-kanto-img" src="' + imgUrl + '" alt="' + mapTitle + '" decoding="async">';

        const overlay = document.createElement('div');
        overlay.className = 'zone-map-kanto-overlay';

        const mapAreaSurfaces = mapAreas.map(function (a) {
            return (Number(a.width) || 0) * (Number(a.height) || 0);
        });
        const minMapSurface = mapAreaSurfaces.length ? Math.min.apply(null, mapAreaSurfaces) : 0;
        const maxMapSurface = mapAreaSurfaces.length ? Math.max.apply(null, mapAreaSurfaces) : 0;
        const mapSurfaceRange = maxMapSurface - minMapSurface;

        mapAreas.forEach(function (area) {
            const zone = ZONES[area.id];
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'zone-map-area';
            btn.dataset.zoneId = String(area.id);
            btn.style.left = area.left + '%';
            btn.style.top = area.top + '%';
            btn.style.width = (area.width || 0) + '%';
            btn.style.height = (area.height || 0) + '%';
            // Petites zones = z-index plus haut (toujours cliquables au-dessus des grandes)
            const surf = (Number(area.width) || 0) * (Number(area.height) || 0);
            const t = mapSurfaceRange > 0 ? (surf - minMapSurface) / mapSurfaceRange : 0;
            let zBase = Math.round(15 + (1 - t) * 85);
            zBase += (parseInt(String(area.id), 10) || 0) % 5;
            zBase = Math.min(110, Math.max(10, zBase));
            btn.style.setProperty('--zone-area-z', String(zBase));
            btn.addEventListener('mouseenter', function (e) {
                if (typeof game.scheduleTooltip === 'function') {
                    const tooltipZoneName = zoneDisplayName(game, area.id, zone ? zone.name : ('Zone ' + area.id));
                    game.scheduleTooltip(e, tooltipZoneName, '', 50);
                }
            });
            btn.addEventListener('mouseleave', function () {
                if (typeof game.hideTooltip === 'function') {
                    game.hideTooltip();
                }
            });
            btn.addEventListener('click', function () {
                if (!(this).classList.contains('locked')) {
                    (this as HTMLButtonElement).blur();
                    game.changeZone(Number((this).dataset.zoneId));
                    const modal = getById('zoneMapModal');
                    const btnMap = getById('zoneMapBtn');
                    if (modal) modal.classList.remove('show');
                    if (btnMap) btnMap.setAttribute('aria-expanded', 'false');
                }
            });
            overlay.appendChild(btn);
        });

        const playerMarker = document.createElement('img');
        playerMarker.className = 'zone-map-player-marker';
        playerMarker.src = (typeof KANTO_MAP_PLAYER_SPRITE_URL !== 'undefined' && KANTO_MAP_PLAYER_SPRITE_URL)
            ? KANTO_MAP_PLAYER_SPRITE_URL
            : 'img/Player-sprite.png';
        playerMarker.alt = zoneText(game, '', 'Position actuelle', 'Current position');
        playerMarker.setAttribute('aria-hidden', 'true');
        overlay.appendChild(playerMarker);

        wrap.appendChild(overlay);
        mapEl.appendChild(wrap);
        mapEl.dataset.regionId = currentRegion;
        mapEl.dataset.viewportKey = viewportKey;
        mapEl.dataset.layoutKey = layoutKey;

        const mapImgOnBuild = wrap.querySelector<HTMLImageElement>('.zone-map-kanto-img');
        if (mapImgOnBuild) {
            const syncAspect = function () {
                _applyZoneMapAspectRatio(wrap, currentRegion, mapImgOnBuild);
            };
            if (mapImgOnBuild.complete && mapImgOnBuild.naturalWidth > 0) {
                syncAspect();
            } else {
                mapImgOnBuild.addEventListener('load', syncAspect, { once: true });
            }
        }
    }

    const mapImg = mapEl.querySelector<HTMLImageElement>('.zone-map-kanto-img');
    if (mapImg) mapImg.alt = mapTitle;

    const areas = mapEl.querySelectorAll('.zone-map-area');
    areas.forEach(function (btn) {
        const btnEl = btn as HTMLElement;
        const zId = parseInt(btnEl.dataset.zoneId ?? '', 10);
        const isUnlocked = regionSnapshot.unlocked.get(zId) ?? false;
        const isMastered = isZoneMasteredInternal(game, zId);
        const zone = ZONES[zId];
        btn.setAttribute('aria-label', zoneDisplayName(game, zId, zone ? zone.name : ('Zone ' + zId)));
        const isTransitHub = isTransitHubZoneLogic(game, zId);
        btn.classList.toggle('locked', !isUnlocked);
        btn.classList.toggle('current', zId === currentZone);
        btn.classList.toggle('hub', isUnlocked && isTransitHub && !isMastered);
        btn.classList.toggle('completed', isUnlocked && isMastered);
        btn.setAttribute('aria-selected', zId === currentZone ? 'true' : 'false');
        if (btnEl instanceof HTMLButtonElement) {
            btnEl.disabled = !isUnlocked;
        }
    });

    const playerMarker = mapEl.querySelector<HTMLElement>('.zone-map-player-marker');
    if (playerMarker) {
        if (playerMarker instanceof HTMLImageElement) {
            playerMarker.alt = zoneText(game, '', 'Position actuelle', 'Current position');
        }
        let currentArea = null as { id: number; top: number; left: number; size?: number; width?: number; height?: number } | null;
        for (let i = 0; i < mapAreas.length; i++) {
            const area = mapAreas[i];
            if (area && area.id === currentZone) {
                currentArea = area;
                break;
            }
        }
        if (currentArea) {
            playerMarker.style.left = (currentArea.left + (currentArea.width || 0) / 2) + '%';
            playerMarker.style.top = (currentArea.top + (currentArea.height || 0) / 2) + '%';
            playerMarker.style.display = '';
        } else {
            playerMarker.style.display = 'none';
        }
    }
    } finally {
        endZoneAccessBatch();
    }
}

export function changeRegionLogic(game: GameRuntime, regionId: string): boolean {
    if (game.towerState?.isActive) {
        logMessage(zoneText(
            game,
            '',
            "Terminez d'abord l'ascension de la Tour avant de changer de region.",
            'Finish the Tower ascent before changing region.',
        ));
        return false;
    }
    if (game.subwayState?.isActive) {
        logMessage(zoneText(
            game,
            '',
            'Terminez d\'abord le Battle Subway avant de changer de region.',
            'Finish the Battle Subway before changing region.',
        ));
        return false;
    }
    ensureRegionProgressStateLogic(game);
    const targetRegion = String(regionId || 'kanto');
    if (!_isRegionUnlocked(game, targetRegion)) {
        let lockBodyFr = 'Terminez la region precedente pour la debloquer.';
        let lockBodyEn = 'Finish the previous region to unlock it.';
        let lockBodyArgs: Record<string, unknown> | null = null;
        const firstZoneId = _getFirstZoneIdForRegion(targetRegion);
        const firstZone = (typeof ZONES !== 'undefined' && ZONES && firstZoneId != null) ? ZONES[firstZoneId] : null;
        if (firstZone && firstZone.unlockRequirement) {
            const req = String(firstZone.unlockRequirement);
            if (req.indexOf('badge:') === 0) {
                const requiredBadge = req.slice('badge:'.length);
                const hasRequiredBadge = (typeof game.hasBadge === 'function')
                    ? game.hasBadge(requiredBadge)
                    : !!(game.badges && game.badges[requiredBadge]);
                if (!hasRequiredBadge) {
                    if (requiredBadge === 'maitre_kanto') {
                        lockBodyFr = 'Il faut battre la Ligue Kanto pour obtenir le titre Maitre de Kanto.';
                        lockBodyEn = 'You need to beat the Kanto League to earn the Master of Kanto title.';
                    } else {
                        let badgeName: string = requiredBadge;
                        if (typeof ACCOUNT_TALENTS !== 'undefined' && ACCOUNT_TALENTS && ACCOUNT_TALENTS[requiredBadge]) {
                            const talentDef = ACCOUNT_TALENTS[requiredBadge];
                            badgeName = (game && typeof game.getLocalizedAccountTalentName === 'function')
                                ? game.getLocalizedAccountTalentName(requiredBadge, talentDef.name || requiredBadge)
                                : (talentDef.name || requiredBadge);
                        }
                        lockBodyFr = 'Condition manquante : {badge}.';
                        lockBodyEn = 'Missing requirement: {badge}.';
                        lockBodyArgs = { badge: badgeName };
                    }
                }
            }
        }
        if (toast.error) {
            toast.error(
                zoneText(game, '', 'Region verrouillee', 'Region locked'),
                zoneText(game, '', lockBodyFr, lockBodyEn, lockBodyArgs || undefined)
            );
        } else {
            logMessage(zoneText(game, '', lockBodyFr, lockBodyEn, lockBodyArgs || undefined));
        }
        updateZoneSelectorLogic(game);
        return false;
    }

    if (!hasRegionalStarterCommitment(game, targetRegion)) {
        if (typeof game.maybePromptRegionalResonance === 'function') {
            game.maybePromptRegionalResonance(targetRegion);
        }
        return true;
    }

    setCurrentRegion(targetRegion);
    game.currentRegion = targetRegion;
    tryUnlockSynergyRegionOnVisit(game, targetRegion);
    const zoneInRegion = _findFirstUnlockedZoneInRegion(game, currentRegion);
    if (zoneInRegion != null && _getZoneRegionId(currentZone) !== currentRegion) {
        setActiveZone(Number(zoneInRegion));
    }

    const firstZoneInTarget = _getFirstZoneIdForRegion(targetRegion);
    const targetRegionMax = Number(maxReachedZoneByRegion?.[targetRegion] || 0);
    if (
        firstZoneInTarget != null &&
        (!Number.isFinite(targetRegionMax) || targetRegionMax <= 0 || _getZoneRegionId(targetRegionMax) !== targetRegion)
    ) {
        maxReachedZoneByRegion[targetRegion] = Number(zoneInRegion ?? firstZoneInTarget);
    }

    setMaxReachedZone(Number((maxReachedZoneByRegion && maxReachedZoneByRegion[currentRegion]) || currentZone || 1));
    abortTransientCombatStateForTravel(game);
    markPlayerRegionVisited(game, targetRegion);

    updateZoneSelectorLogic(game);
    updateZoneInfo(game);
    if (typeof game.refreshBattleFeatureButtons === 'function') {
        game.refreshBattleFeatureButtons();
    }
    if (typeof game.updateDisplay === 'function') {
        game.updateDisplay(['zone', 'pokedex', 'team', 'visibility', 'combat']);
    }
    publishZoneChanged();
    invalidateResonanceCache(game);
    if (typeof game.maybePromptRegionalResonance === 'function') {
        game.maybePromptRegionalResonance(targetRegion);
    }
    if (game.checkSpecialQuests) game.checkSpecialQuests('region_visited', { regionId: targetRegion });
    if (targetRegion === 'paldea') {
        onPaldeaRegionVisitedAcademy(game);
    }
    return true;
}

/**
 * Arr?te combat sauvage / dresseur de zone / run d'ar?ne avant voyage (changement de zone ou de r?gion).
 * ?vite un ?tat bloqu? (arenaState actif sans combat, ou combat dresseur apr?s changement de r?gion).
 */
export function abortTransientCombatStateForTravel(game: GameRuntime): void {
    if (!game) return;
    if (game.arenaState && game.arenaState.active && typeof game.resetArenaState === 'function') {
        game.resetArenaState();
    } else {
        game.currentEnemy = null;
        game.combatState = 'waiting';
        game.lastCombatTime = Date.now();
    }
    if (game.gymTrainerState && game.gymTrainerState.active) {
        if (game.gymTrainerState.isFarmThreat) {
            abortFarmThreatCombat(game);
            return;
        }
        game.gymTrainerState = null;
        game.faintedThisCombat = game.faintedThisCombat || new Set();
        game.faintedThisCombat.clear();
        game.faintedUidsThisCombat = game.faintedUidsThisCombat || new Set();
        game.faintedUidsThisCombat.clear();
        if (game.currentPlayerCreature && typeof game.getPlayerMaxHp === 'function') {
            const poolHp = Math.min(game.getPlayerMaxHp(), Math.max(0, game.currentPlayerCreature.currentHp || 0));
            game.playerTeam.forEach(function (c) {
                c.mainAccountCurrentHp = poolHp;
                if (c.mainAccountCurrentHp > 0) {
                    c.currentHp = Math.min(c.maxHp || c.mainAccountCurrentHp, c.mainAccountCurrentHp);
                }
            });
        }
    }
}

export function changeZoneLogic(game: GameRuntime, zoneId: number): void {
    ensureRegionProgressStateLogic(game);

    const selector = getSelect('zoneSelect');
    if (selector) { selector.value = String(zoneId); selector.blur(); }

    const zId = Number(zoneId);
    const zone = ZONES[zId];
    if (!zone) return;

    const targetRegion = _getZoneRegionId(zId);
    if (targetRegion !== currentRegion && !_isRegionUnlocked(game, targetRegion)) {
        if (toast.error) {
            toast.error(zoneText(game, '', 'Region verrouillee', 'Region locked'), zoneText(game, '', 'Terminez la region precedente pour la debloquer.', 'Finish the previous region to unlock it.'));
        }
        updateZoneSelectorLogic(game);
        return;
    }

    if (!isZoneUnlockedLogic(game, zId, true)) {
        const prevZone = _getPreviousZoneIdInRegion(zId);
        const prevZoneName = zoneDisplayName(game, prevZone!, (prevZone && ZONES[prevZone]) ? ZONES[prevZone].name : 'precedente');
        if (toast.error) {
            toast.error(
                zoneText(game, '', 'Zone verrouillee', 'Zone locked'),
                zoneText(game, '', "Terminez d'abord : {zone}", 'Finish first: {zone}', { zone: prevZoneName })
            );
        }
        updateZoneSelectorLogic(game);
        return;
    }

    if (targetRegion !== String(currentRegion || '') && !hasRegionalStarterCommitment(game, targetRegion)) {
        if (typeof game.maybePromptRegionalResonance === 'function') {
            game.maybePromptRegionalResonance(targetRegion);
        }
        updateZoneSelectorLogic(game);
        return;
    }

    const prevRegion = String(currentRegion || '');
    setCurrentRegion(targetRegion);
    game.currentRegion = targetRegion;
    tryUnlockSynergyRegionOnVisit(game, targetRegion);
    if (Number(currentZone) !== zId) {
        game.recentLiveWinDurations = [];
        game.recentLiveFightDurations = [];
        game.recentCombatDurations = [];
    }
    setActiveZone(zId);
    const regionKey = String(currentRegion);
    const prevMax = Number(maxReachedZoneByRegion[regionKey] || 0);
    if (
        isZoneStoryAheadOf(zId, prevMax)
        && shouldAdvanceMaxReachedOnZoneSelect(game, regionKey, zId)
    ) {
        maxReachedZoneByRegion[regionKey] = zId;
    }
    setMaxReachedZone(Number(maxReachedZoneByRegion[regionKey] || zId));

    abortTransientCombatStateForTravel(game);
    markPlayerRegionVisited(game, targetRegion);

    // Persistance par zone : on ne RESET plus la liste ? chaque changement
    // de zone ? on bascule vers la liste m?moris?e pour la nouvelle zone
    // (cr??e vide si pas encore de cibles pour cette zone).
    game.captureTarget = null;
    if (typeof game._syncCaptureTargetsToCurrentZone === 'function') {
        game._syncCaptureTargetsToCurrentZone();
    }
    if (typeof game.updateCaptureButtonDisplay === 'function') {
        game.updateCaptureButtonDisplay();
    }

    logMessage(zoneText(
        game,
        '',
        'Voyage vers : {zone}',
        'Traveling to: {zone}',
        { zone: zoneDisplayName(game, currentZone, ZONES[currentZone]?.name ?? '') }
    ));

    updateZoneSelectorLogic(game);
    if (game.updateCaptureButtonDisplay) game.updateCaptureButtonDisplay();
    if (game.updateCaptureBadge) game.updateCaptureBadge();
    if (game.updateCaptureTargetList) game.updateCaptureTargetList();
    updateZoneInfo(game);
    if (typeof game.updateCombatDisplay === 'function') {
        game.updateCombatDisplay();
    }

    if (!game.sessionStats.zonesVisited) game.sessionStats.zonesVisited = new Set();
    game.sessionStats.zonesVisited.add(zId);
    if (game.checkSpecialQuests) game.checkSpecialQuests('zone_visited');
    if (zId === 2 && game.checkSpecialQuests) {
        game.checkSpecialQuests('zone_2_visited');
        game.checkSpecialQuests('map_route_1_selected');
    }

    if (!game.items) game.items = {};
    if (!game.completedStoryQuests) game.completedStoryQuests = [];
    if (!game.completedTeamRocketQuests) game.completedTeamRocketQuests = [];

    let storyTriggered = false;
    if (game.quests) {
        if (zId === 237) tryStartHoennSafariZoneQuest(game, 237);
        if (zId === 332) tryStartSinnohGreatMarshQuest(game, 332);
        if (zId === 363) tryStartSinnohBattleZoneCensusQuest(game, 363);
        if (zId === 409) tryStartUnovaDarumakaRoute4Quest(game, 409);
        if (zId === 415) tryStartUnovaCubchooRoute7Quest(game, 415);
        if (zId === 421) tryStartUnovaPawniardRoute9Quest(game, 421);
        if (zId === 430) tryStartUnovaDesertResortCensusQuest(game, 430);
        if (zId === 711 || zId === 740) tryStartGalarWildAreaCensusQuest(game, zId);
        if (zId === 715) tryStartGalarGlimwoodCensusQuest(game, 715);
        ensureStoryQuestProgress(game);
        storyTriggered = true;
    }

    if (!storyTriggered && typeof game.generateNewQuest === 'function') game.generateNewQuest();
    publishZoneChanged();
    if (targetRegion !== prevRegion) {
        invalidateResonanceCache(game);
        if (typeof game.maybePromptRegionalResonance === 'function') {
            game.maybePromptRegionalResonance(targetRegion);
        }
    }
}

export function rollWildShiny(game: GameRuntime): boolean {
    let shinyChance = 1 / 8192;
    if (game && typeof game.getCollectionBonuses === 'function') {
        const coll = game.getCollectionBonuses() || {};
        const shinyBoost = coll.shiny || 0;
        const activeShinyBoost = game.getActiveBoostMultiplier
            ? game.getActiveBoostMultiplier('shiny')
            : 0;
        let upgradeBonus = 0;
        if (game.upgrades?.shinyHunt) {
            upgradeBonus = game.upgrades.shinyHunt.level * 0.05;
        }
        const masteryShinyBonus = game.getMasteryBonus ? (game.getMasteryBonus('shiny_chance') || 0) : 0;
        shinyChance *= (1 + shinyBoost + activeShinyBoost + upgradeBonus + masteryShinyBonus);
        if (typeof game.getShinyPityMultiplier === 'function') {
            shinyChance *= game.getShinyPityMultiplier();
        }
    }
    const rolledShiny = Math.random() < shinyChance;
    if (typeof game.recordShinyPityBattle === 'function') {
        game.recordShinyPityBattle(rolledShiny);
    }
    return rolledShiny;
}

/**
 * Cr?e un Boss de zone (l?gendaire, IV max, zone x16 ? volontairement moins burst que l?ancien x30).
 */
export function createBossLogic(game: GameRuntime): (CreatureData & Record<string, unknown>) | null {
    const zone = ZONES[currentZone];
    if (!zone) return null;
    const localPool = getReachablePokemonInZoneLogic(game, currentZone);
    let name = 'Mewtwo';
    const forcePokemonTowerMarowak = Number(currentZone) === 25
        && Array.isArray(game.quests)
        && game.quests.some(function (q: QuestData) {
            return q
                && q.id === 'story_pokemon_tower_marowak'
                && q.accepted
                && !q.completed;
        });
    const forceDragonspiralDruddigon = Number(currentZone) === 432
        && Array.isArray(game.quests)
        && game.quests.some(function (q: QuestData) {
            return q
                && q.id === 'story_unova_dragonspiral'
                && q.accepted
                && !q.completed;
        });
    if (forcePokemonTowerMarowak) {
        name = 'Marowak';
    } else if (forceDragonspiralDruddigon) {
        name = 'Druddigon';
    } else if (localPool && localPool.length > 0) {
        const picked = arrayAt(localPool, Math.floor(Math.random() * localPool.length));
        if (picked) name = picked;
    }
    const levelRange = zone.levelRange ?? [1, 10];
    const levelMax = levelRange[1] ?? 10;
    const level = levelMax + 5;
    const creatureName = resolveCanonicalSpeciesName(name);
    const type = game.findTypeForPokemon ? game.findTypeForPokemon(creatureName) : 'normal';
    const secondaryType = POKEMON_SECONDARY_TYPES[creatureName] || POKEMON_SECONDARY_TYPES[name] || null;
    const enemy = new (getCreatureClass())(creatureName, type, level, RARITY.LEGENDARY, true, rollWildShiny(game), secondaryType, true, false);
    const elitePowerCfg = (BALANCE && typeof BALANCE.ZONE_ELITE_POWER === 'object' && BALANCE.ZONE_ELITE_POWER)
        ? BALANCE.ZONE_ELITE_POWER
        : null;
    enemy.zoneMultiplier = resolveZoneBossMultiplier(zone.multiplier || 1, _getZoneRegionId(currentZone), elitePowerCfg);
    enemy.recalculateStats?.();
    enemy.heal?.();
    logMessage(zoneText(
        game,
        '',
        '[BOSS] Boss de zone apparu : {name} !',
        '[BOSS] Zone boss appeared: {name}!',
        { name: enemy.name }
    ));
    return enemy;
}

