/** URL base pour les sprites dresseurs Pokemon Showdown */
export const GYM_TRAINER_SPRITE_BASE = 'https://play.pokemonshowdown.com/sprites/trainers/';

function readArenaPowerConfig(): {
    varianceMin: number;
    varianceMax: number;
} {
    let arenaPowerCfg: ArenaPowerBalance | null = null;
    if (BALANCE && typeof BALANCE.ARENA_POWER === 'object' && BALANCE.ARENA_POWER) {
        arenaPowerCfg = BALANCE.ARENA_POWER;
    }
    let varianceMin = Number(arenaPowerCfg && arenaPowerCfg.GYM_TRAINER_VARIANCE_MIN);
    let varianceMax = Number(arenaPowerCfg && arenaPowerCfg.GYM_TRAINER_VARIANCE_MAX);
    if (!Number.isFinite(varianceMin)) varianceMin = 0.92;
    if (!Number.isFinite(varianceMax)) varianceMax = 1.08;
    if (varianceMax < varianceMin) {
        const swap = varianceMin;
        varianceMin = varianceMax;
        varianceMax = swap;
    }
    return { varianceMin, varianceMax };
}

/** Niveau et multiplicateur de stats des dresseurs d'ar?ne (m?me formule que createGymTrainerLogic). */
export function getGymTrainerPowerForArena(arenaId: number): GymTrainerPower | null {
    const arena = (typeof ARENAS !== 'undefined')
        ? (ARENAS as Record<string, ArenaEntry>)[String(arenaId)]
        : null;
    if (!arena) return null;
    const baseLevel: number = arena.teamLevel || 50;
    const numericArenaId = parseInt(String(arenaId || ''), 10) || 1;
    const cfg = readArenaPowerConfig();
    const arenaPowerCfg = (BALANCE && typeof BALANCE.ARENA_POWER === 'object' && BALANCE.ARENA_POWER)
        ? BALANCE.ARENA_POWER as ArenaPowerBalance
        : null;
    const baseTrainerMult = resolveGymTrainerBaseMult(
        numericArenaId,
        { regionId: arena.regionId },
        arenaPowerCfg
    );
    return {
        baseLevel,
        baseTrainerMult,
        varianceMin: cfg.varianceMin,
        varianceMax: cfg.varianceMax,
    };
}

function rollGymTrainerLevel(baseLevel: number): number {
    return Math.max(1, baseLevel - 3 + Math.floor(Math.random() * 2));
}

function rollGymTrainerStatMult(power: GymTrainerPower): number {
    const trainerVarianceRange = power.varianceMax - power.varianceMin;
    return power.baseTrainerMult * (power.varianceMin + Math.random() * trainerVarianceRange);
}

function applyTrainerStatMult(creature: CreatureInstance, trainerMult: number): void {
    creature.recalculateStats?.();
    creature.maxHp = Math.floor(creature.maxHp * trainerMult);
    creature.attack = Math.floor(creature.attack * trainerMult);
    creature.spattack = Math.floor(creature.spattack * trainerMult);
    creature.defense = Math.floor(creature.defense * trainerMult);
    creature.spdefense = Math.floor(creature.spdefense * trainerMult);
    creature.speed = Math.floor(creature.speed * trainerMult);
    creature.currentHp = creature.maxHp;
}

/**
 * Cr?e un dresseur de zone gym avec 2-3 Pokémon du type de l'ar?ne.
 * Stats calqu?es sur la puissance du champion de l'ar?ne, mais un peu plus faibles (facteur 0.8).
 * Niveau = arena.teamLevel ; multiplicateurs PV/ATQ/DEF/SPD = (2 + difficulty) * 0.8.
 * Les Pokémon sont marqu?s isGymTrainer pour appliquer +25% XP/Pokedollars et bloquer le loot.
 */
export function createGymTrainerLogic(game: GameRuntime): Array<CreatureData & Record<string, unknown>> | null {
    const zone = ZONES[currentZone];
    if (!zone || !zone.isGym) return null;
    const arenaId = (typeof ZONE_ID_TO_ARENA_ID !== 'undefined') ? ZONE_ID_TO_ARENA_ID[currentZone] : null;
    const arena = (arenaId != null && typeof ARENAS !== 'undefined') ? (ARENAS as Record<string, ArenaEntry>)[String(arenaId)] : null;
    if (!arena || !arena.fixedTeam || !arena.fixedTeam.length) return null;

    const trainerPool: GymTrainerArchetype[] = (typeof GYM_ZONE_TRAINERS !== 'undefined' && (GYM_ZONE_TRAINERS as Record<number, GymTrainerArchetype[]>)[currentZone])
        ? ((GYM_ZONE_TRAINERS as Record<number, GymTrainerArchetype[]>)[currentZone] ?? [])
        : [];
    const trainer = arrayAt(trainerPool, Math.floor(Math.random() * trainerPool.length))
        ?? { name: 'Dresseur', sprite: 'youngster.png' };
    const spriteUrl = (typeof GYM_TRAINER_SPRITE_BASE !== 'undefined' ? GYM_TRAINER_SPRITE_BASE : 'https://play.pokemonshowdown.com/sprites/trainers/') + (trainer.sprite || 'youngster.png');

    const championPool = arena.fixedTeam.slice();
    const extraPool = (typeof ARENA_TRAINER_POKEMON_EXTRA !== 'undefined' && arenaId != null && ARENA_TRAINER_POKEMON_EXTRA[String(arenaId)])
        ? (ARENA_TRAINER_POKEMON_EXTRA[String(arenaId)] as GymPoolEntry[]).slice()
        : [];
    const fullPool = championPool.concat(extraPool);
    let teamSize = 2 + Math.floor(Math.random() * 2);
    if (teamSize > fullPool.length) teamSize = fullPool.length;
    const team: CreatureInstance[] = [];
    const type = arena.type || 'normal';
    const gymPower = getGymTrainerPowerForArena(Number(arenaId));
    if (!gymPower) return null;
    const baseLevel = gymPower.baseLevel;

    for (let t = 0; t < teamSize; t++) {
        const pickFromChampion = fullPool.length > championPool.length && Math.random() < 0.5;
        const poolToUse = (pickFromChampion && championPool.length > 0) ? championPool : fullPool;
        const usedNames: Record<string, boolean> = {};
        for (let i = 0; i < team.length; i++) {
            const member = team[i];
            if (member) usedNames[member.name] = true;
        }
        let pick: GymPoolEntry | undefined;
        let name: string;
        let attempts = 0;
        do {
            pick = poolToUse[Math.floor(Math.random() * poolToUse.length)];
            name = typeof pick === 'string' ? pick : String(pick?.name ?? '');
            attempts++;
        } while (usedNames[name] && attempts < 20);
        usedNames[name] = true;
        const secondaryType = (typeof POKEMON_SECONDARY_TYPES !== 'undefined' && POKEMON_SECONDARY_TYPES[name]) ? POKEMON_SECONDARY_TYPES[name] : null;
        const level = rollGymTrainerLevel(baseLevel);
        const trainerMult = rollGymTrainerStatMult(gymPower);
        const creature = new (getCreatureClass())(name, type, level, RARITY.COMMON, true, false, secondaryType);
        const arenaMoveSets = (arena.fixedMovesets && typeof arena.fixedMovesets === 'object')
            ? arena.fixedMovesets as Record<string, string[]>
            : null;
        const explicitMoves = arenaMoveSets ? (arenaMoveSets[name] ?? null) : null;
        creature.currentMoves = pickTrainerMoves(name, type, explicitMoves, { ensureTypeDiversity: true });
        creature.isGymTrainer = true;
        creature.zoneMultiplier = 1;
        applyTrainerStatMult(creature, trainerMult);
        creature.zoneMultiplier = (zone.multiplier || 1) * 5;
        creature.heal?.();
        team.push(creature);
    }

    game.gymTrainerState = {
        active: true,
        trainerName: trainer.name,
        trainerSpriteUrl: spriteUrl,
        team: team,
        currentIndex: 0
    };
    logMessage(zoneText(
        game,
        '',
        '{name} vous defie !',
        '{name} challenges you!',
        { name: trainer.name ?? 'Dresseur' }
    ));
    const firstMember = arrayAt(team, 0);
    return firstMember ? [firstMember] : null;
}

/**
 * Cr?e le rival (style Gary) comme un dresseur sp?cial utilisant le même flux que les dresseurs de gym.
 */
export function createRivalTrainerLogic(game: GameRuntime): Array<CreatureData & Record<string, unknown>> | null {
    if (!game) return null;

    const teamNames = ['Pidgeot', 'Alakazam', 'Rhydon', 'Gyarados', 'Arcanine', 'Blastoise'];
    const baseLevel = 80;
    const difficulty = 9;
    const championMult = 2 + (difficulty*0.5);
    const baseTrainerMult = championMult;

    const team: CreatureInstance[] = [];
    for (let i = 0; i < teamNames.length; i++) {
        const name = teamNames[i];
        if (name === undefined) continue;
        const type = game.findTypeForPokemon ? game.findTypeForPokemon(name) : 'normal';
        const secondaryType = recordGet(POKEMON_SECONDARY_TYPES as Record<string, string>, name) ?? null;
        const level = baseLevel;
        const creature: CreatureInstance = new (getCreatureClass())(name, type, level, RARITY.EPIC, true, false, secondaryType);
        creature.isGymTrainer = true;
        creature.zoneMultiplier = 1;
        creature.recalculateStats?.();
        creature.maxHp = Math.floor(creature.maxHp * baseTrainerMult);
        creature.attack = Math.floor(creature.attack * baseTrainerMult);
        creature.spattack = Math.floor(creature.spattack * baseTrainerMult);
        creature.defense = Math.floor(creature.defense * baseTrainerMult);
        creature.spdefense = Math.floor(creature.spdefense * baseTrainerMult);
        creature.speed = Math.floor(creature.speed * baseTrainerMult);
        creature.currentHp = creature.maxHp;
        creature.heal?.();
        team.push(creature);
    }

    const spriteUrl = (typeof GYM_TRAINER_SPRITE_BASE !== 'undefined' ? GYM_TRAINER_SPRITE_BASE : 'https://play.pokemonshowdown.com/sprites/trainers/') + 'blue.png';

    game.gymTrainerState = {
        active: true,
        isRival: true,
        trainerName: 'Rival',
        trainerSpriteUrl: spriteUrl,
        team: team,
        currentIndex: 0
    };

    logMessage(zoneText(
        game,
        '',
        '{name} vous defie !',
        '{name} challenges you!',
        { name: 'Rival' }
    ));

    const rivalFirst = arrayAt(team, 0);
    return rivalFirst ? [rivalFirst] : null;
}

/**
 * Renvoie la d?finition d'apparition Rival pour une zone, OU null si pas configur?e.
 * Cette fonction n'examine PAS la ma?trise ni l'?tat de d?faite ;
 * elle renvoie juste les m?ta-donn?es de RIVAL_ENCOUNTERS.
 */
function isStoryQuestActiveForEncounter(game: GameRuntime, storyQuestId: string): boolean {
    if (!storyQuestId || !Array.isArray(game.quests)) return false;
    return game.quests.some(function (q: QuestData) {
        return String(q.id) === String(storyQuestId) && !!q.accepted && !q.completed && !q.claimed;
    });
}

export function getRivalEncounterMetaForZone(zoneId: number): RivalZoneMeta | null {
    const johtoFaction = JOHTO_FACTION_ENCOUNTERS[zoneId];
    if (johtoFaction) return johtoFaction as RivalZoneMeta;
    const faction = HOENN_FACTION_ENCOUNTERS[zoneId];
    if (faction) return faction as RivalZoneMeta;
    const sinnohFaction = SINNOH_FACTION_ENCOUNTERS[zoneId];
    if (sinnohFaction) return sinnohFaction as RivalZoneMeta;
    const unovaFaction = UNOVA_FACTION_ENCOUNTERS[zoneId];
    if (unovaFaction) return unovaFaction as RivalZoneMeta;
    const kalosFaction = KALOS_FACTION_ENCOUNTERS[zoneId];
    if (kalosFaction) return kalosFaction as RivalZoneMeta;
    const alolaFaction = ALOLA_FACTION_ENCOUNTERS[zoneId];
    if (alolaFaction) return alolaFaction as RivalZoneMeta;
    const galarFaction = GALAR_FACTION_ENCOUNTERS[zoneId];
    if (galarFaction) return galarFaction as RivalZoneMeta;
    const paldeaFaction = PALDEA_FACTION_ENCOUNTERS[zoneId];
    if (paldeaFaction) return paldeaFaction as RivalZoneMeta;
    const encounters = RIVAL_ENCOUNTERS as Record<string | number, RivalZoneMeta>;
    const meta = encounters[zoneId] ?? encounters[String(zoneId)];
    return meta || null;
}

/**
 * Renvoie l'info Rival "actuellement disponible" sur la zone donn?e :
 *  - meta : objet de RIVAL_ENCOUNTERS
 *  - alreadyDefeated : d?j? battu sur cette zone (pour grisage / masquage)
 *  - mastered : zone ma?tris?e
 *  - available = mastered && !alreadyDefeated
 * Retourne null si la zone n'a pas d'apparition Rival configur?e.
 */
export function getRivalZoneAvailabilityLogic(game: GameRuntime, zoneId: number): Record<string, unknown> | null {
    const meta = getRivalEncounterMetaForZone(zoneId);
    if (!meta) return null;
    const mastered = (typeof isZoneMasteredLogic === 'function') ? !!isZoneMasteredLogic(game, zoneId) : false;
    const defeatedMap: Record<string, boolean> = (game && game.rivalState && game.rivalState.zonesDefeated) || {};
    const defeatKey = meta.rivalKey ? String(meta.rivalKey) : String(meta.zoneId ?? zoneId);
    const alreadyDefeated = !!(defeatedMap[defeatKey]) || !!(defeatedMap[String(meta.zoneId ?? zoneId)]);
    const storyQuestId = meta.unlockWhenStoryQuest ? String(meta.unlockWhenStoryQuest) : '';
    let available = false;
    if (storyQuestId) {
        const questActive = isStoryQuestActiveForEncounter(game, storyQuestId);
        available = questActive && !alreadyDefeated;
    } else {
        available = mastered && !alreadyDefeated;
    }
    return {
        meta: meta,
        mastered: mastered,
        alreadyDefeated: alreadyDefeated,
        available: available
    };
}

/**
 * Construit la team Rival adapt?e ? la zone ? partir de la meta de RIVAL_ENCOUNTERS.
 * Factions (arenaId) : m?me niveau/stats que les dresseurs d'ar?ne (createGymTrainerLogic).
 * Rivaux Kanto : niveau = haut de plage zone + levelOffset ; stats via championMult.
 * Pokemon marqu?s isGymTrainer pour r?utiliser le bonus XP/$ existant et bloquer le loot.
 */
export function createRivalZoneTrainerLogic(game: GameRuntime, zoneId: number): Array<CreatureData & Record<string, unknown>> | null {
    if (!game) return null;
    const avail = getRivalZoneAvailabilityLogic(game, zoneId);
    if (!avail || !avail.meta) return null;
    const meta = avail.meta as RivalZoneMeta;

    const zone = ZONES[zoneId];
    if (!zone) return null;

    const factionArenaId = meta.arenaId != null ? Number(meta.arenaId) : NaN;
    const useZoneScale = meta.scaleWithZone === true;
    const gymPower = !useZoneScale && Number.isFinite(factionArenaId)
        ? getGymTrainerPowerForArena(factionArenaId)
        : null;

    let legacyBaseLevel = 0;
    let legacyTrainerMult = 1;
    if (!gymPower) {
        const rivalLevelRange = zone.levelRange ?? [1, 25];
        legacyBaseLevel = rivalLevelRange.length >= 2 ? (rivalLevelRange[1] ?? 25) : 25;
        legacyBaseLevel = Math.max(2, Math.floor(legacyBaseLevel + (meta.levelOffset || 0)));
        const difficulty = Math.min(10, Math.max(1, Math.floor(legacyBaseLevel / 8)));
        const championMult = 1.5 + (difficulty * 0.8);
        legacyTrainerMult = championMult * (meta.statMultiplier || 1);
    }

    const team: CreatureInstance[] = [];
    const archetypes = Array.isArray(meta.teamArchetypes) ? meta.teamArchetypes : [];
    const usedNames: Record<string, boolean> = {};
    archetypes.forEach(function (arch: { picks?: string[]; [key: string]: unknown }) {
        const archPicks = arch?.picks;
        const picks: string[] = Array.isArray(archPicks) ? archPicks : [];
        if (!picks.length) return;
        let name: string | null = null;
        let attempts = 0;
        do {
            name = arrayAt(picks, Math.floor(Math.random() * picks.length)) ?? null;
            attempts++;
        } while (name && usedNames[name] && attempts < 20 && picks.length > 1);
        if (!name) return;
        usedNames[name] = true;

        const type = game.findTypeForPokemon ? game.findTypeForPokemon(name) : 'normal';
        const secondaryType = (typeof POKEMON_SECONDARY_TYPES !== 'undefined' && POKEMON_SECONDARY_TYPES[name]) ? POKEMON_SECONDARY_TYPES[name] : null;
        const level = gymPower
            ? rollGymTrainerLevel(gymPower.baseLevel) + Math.floor(meta.levelOffset || 0)
            : legacyBaseLevel;
        const trainerMult = gymPower
            ? rollGymTrainerStatMult(gymPower) * (meta.statMultiplier || 1)
            : legacyTrainerMult;
        const creature = new (getCreatureClass())(name, type, level, RARITY.RARE, true, false, secondaryType);
        creature.currentMoves = pickTrainerMoves(name, type, null, { ensureTypeDiversity: true });
        creature.isGymTrainer = true;
        creature.zoneMultiplier = 1;
        applyTrainerStatMult(creature, trainerMult);
        creature.zoneMultiplier = (zone.multiplier || 1) * 5;
        creature.heal?.();
        team.push(creature);
    });

    if (!team.length) return null;

    const spriteUrl = (typeof GYM_TRAINER_SPRITE_BASE !== 'undefined' ? GYM_TRAINER_SPRITE_BASE : 'https://play.pokemonshowdown.com/sprites/trainers/')
        + (meta.spriteKey || 'blue') + '.png';

    game.gymTrainerState = {
        active: true,
        isRival: true,
        isZoneRival: true,
        rivalZoneId: Number(meta.zoneId),
        rivalEncounterKey: meta.rivalKey || ('zone_' + meta.zoneId),
        rivalRewards: meta.rewards || null,
        trainerName: meta.displayName || 'Rival',
        trainerSpriteUrl: spriteUrl,
        team: team,
        currentIndex: 0
    };

    logMessage(zoneText(
        game,
        '',
        '{name} vous defie !',
        '{name} challenges you!',
        { name: meta.displayName || 'Rival' }
    ));

    const zoneRivalFirst = arrayAt(team, 0);
    return zoneRivalFirst ? [zoneRivalFirst] : null;
}

/**
 * Retourne le prochain ennemi ? affronter (Roamer, Boss, ?pique, dresseur gym ou standard).
 * Game appelle cette fonction au moment du spawn ; zoneSystem d?cide lequel et avec quelles stats.
 * Les probabilit?s (Boss 1%, ?pique 2.5%) s'appliquent quel que soit le contexte :
 * onglet actif, onglet cach? ou simulation de rattrapage (catch-up).
 */
export function getOrCreateEnemyLogic(game: GameRuntime): (CreatureData & Record<string, unknown>) | null {
    if (!game.completedStoryQuests || game.completedStoryQuests.length === 0) return null;
    if ((game as GameRuntime & { _offlineGymTrainerMode?: boolean })._offlineGymTrainerMode
        && game.gymTrainerState && game.gymTrainerState.active) {
        const gts = game.gymTrainerState;
        const idx = gts.currentIndex ?? 0;
        const member = arrayAt(gts.team, idx);
        return member ? (member as CreatureData & Record<string, unknown>) : null;
    }
    if (game.pendingRoamer && !game.isOfflineSimulating) {
        const name = game.pendingRoamer;
        game.pendingRoamer = null;
        const type = game.findTypeForPokemon ? game.findTypeForPokemon(name) : 'normal';
        const roamSecondary = POKEMON_SECONDARY_TYPES[name] || null;
        const roamerZone = ZONES[currentZone];
        const roamLevel = roamerZone && roamerZone.levelRange && roamerZone.levelRange[1] != null
            ? roamerZone.levelRange[1] + 5
            : 50;
        const roamer: CreatureInstance = new (getCreatureClass())(name, type, roamLevel, RARITY.LEGENDARY, true, rollWildShiny(game), roamSecondary, true, false);
        // Pok?rus : roamer infect? (palier 1) ? sera transmissible au joueur via combat
        if (Math.random() < (1 / 6)) {
            if (typeof roamer.tryInfectPokerus === 'function') {
                roamer.tryInfectPokerus(Date.now(), { source: 'active' });
            } else {
                const durationMs = POKERUS_DURATION_MS;
                roamer.pokerusUntil = Date.now() + durationMs;
                roamer.pokerusLevel = 1;
            }
        }
        roamer.isRoaming = true;
        roamer.zoneMultiplier = roamerZone ? (roamerZone.multiplier || 1) * 16 : 10;
        roamer.recalculateStats?.();
        roamer.heal?.();
        logMessage(zoneText(
            game,
            '',
            '[ROAMER] Un Pokemon vagabond apparait : {name} !',
            '[ROAMER] A roaming Pokemon appears: {name}!',
            { name }
        ));
        setLegendaryWildCooldownForSpeciesLogic(game, name);
        return roamer;
    }
    const zone = ZONES[currentZone];
    if (!zone) return null;
    if (zone.isGym && !zone.isFinal) {
        const gymTeam = createGymTrainerLogic(game);
        return arrayAt(gymTeam ?? [], 0) ?? null;
    }
    if (!hasWildSpawnPoolInZoneLogic(game, currentZone)) return null;
    const masteryRareMult = (game && game.getMasteryBonus) ? (1 + (game.getMasteryBonus('rare_spawn_mult') || 0)) : 1;
    const legendarySpawnMult = (game && game.getMasteryBonus)
        ? (1 + (game.getMasteryBonus('legendary_spawn_mult') || 0))
        : 1;
    const rareRollMult = masteryRareMult * legendarySpawnMult;
    const isBossTime = Math.random() < (0.01 * rareRollMult);
    const isEpicTime = !isBossTime && Math.random() < (0.025 * rareRollMult);
    if (isBossTime) return createBossLogic(game);
    if (isEpicTime) return createEpicLogic(game);

    let weightedPool = getWeightedReachableEntriesInZoneLogic(game, currentZone);
    if (!weightedPool || weightedPool.length === 0) {
        debugWarn("Zone " + currentZone + " sans pool de rencontres sauvages.");
        return null;
    }
    // Radar du Pok?dex : poids x3 (base) ou x6 (radar am?lior?) pour les esp?ces cibl?es
    if (game.getPokedexRadarTargets) {
        const radarTargets = game.getPokedexRadarTargets();
        const radarMult = (game.getPokedexRadarWeightMultiplier ? (game.getPokedexRadarWeightMultiplier() || 1) : 3);
        if (radarTargets.length > 0) {
            weightedPool = weightedPool.map(function (entry) {
                return radarTargets.indexOf(entry.name) !== -1
                    ? { name: entry.name, weight: entry.weight * radarMult }
                    : entry;
            });
        }
    }
    if (game.getMasteryBonus && (game.getMasteryBonus('regional_focus') || 0) > 0) {
        const _rf = (typeof game.getRegionalFocusRegionId === 'function') ? game.getRegionalFocusRegionId() : null;
        const _zreg = (typeof _getZoneRegionId === 'function' && typeof currentZone !== 'undefined' && currentZone != null)
            ? _getZoneRegionId(currentZone)
            : 'kanto';
        const _rfb = game.getMasteryBonus('regional_focus') || 0;
        if (_rf && _zreg === _rf && _rfb > 0) {
            weightedPool = weightedPool.map(function (entry) {
                const nat = getEggNativeRegionIdForSpecies(entry.name);
                if (nat && nat === _rf) {
                    return { name: entry.name, weight: (entry.weight || 1) * (1 + _rfb) };
                }
                return entry;
            });
        }
    }
    const randomName = _pickWeightedWildRespectingLegendaryCooldown(game, weightedPool);
    if (!randomName) return null;
    const creatureName = resolveCanonicalSpeciesName(randomName);
    const randomType = game.findTypeForPokemon ? game.findTypeForPokemon(creatureName) : 'normal';
    const secondaryType = POKEMON_SECONDARY_TYPES[creatureName] || POKEMON_SECONDARY_TYPES[randomName] || null;
    const wildLevelRange = zone.levelRange ?? [1, 10];
    const wildMin = wildLevelRange[0] ?? 1;
    const wildMax = wildLevelRange[1] ?? 10;
    const level = Math.floor(Math.random() * (wildMax - wildMin + 1)) + wildMin;
    const trueRarity = game.getNaturalRarity ? game.getNaturalRarity(creatureName) : RARITY.COMMON;
    const enemy: CreatureInstance = new (getCreatureClass())(creatureName, randomType, level, trueRarity, true, rollWildShiny(game), secondaryType);
    // Pok?rus : 1 / 65536 chance qu'un sauvage spawn infect? (palier 1, transmissible au joueur)
    if (Math.random() < (1 / 65536)) {
        if (typeof enemy.tryInfectPokerus === 'function') {
            enemy.tryInfectPokerus(Date.now(), { source: 'active' });
        } else {
            const durationMs2 = POKERUS_DURATION_MS;
            enemy.pokerusUntil = Date.now() + durationMs2;
            enemy.pokerusLevel = 1;
        }
    }
    const zoneProgressEntry = game.zoneProgress?.[currentZone];
    const savedTier = getZonePokemonTier(zoneProgressEntry?.pokemonTiers, randomName);
    enemy.tier = savedTier;
    enemy.zoneMultiplier = (zone.multiplier || 1) * 5;
    enemy.recalculateStats?.();
    enemy.heal?.();
    return enemy;
}

