/** Prefer global formatter when legacy-bridge registered it; else use module import. */
function resolveFormatNumber(n: number | string | null | undefined): string {
    const fn = (globalThis as Record<string, unknown>).formatNumber;
    if (typeof fn === 'function') return (fn as (value: number) => string)(Number(n));
    return formatNumberImpl(n);
}

/** Quêtes avec objectifs numériques très grands (dégâts typés, etc.). */
export function questUsesFormattedTarget(quest: Quest | null | undefined): boolean {
    if (!quest) return false;
    return quest.trackingKey === 'typedDamageDealtDuringQuest';
}

export function formatQuestProgressNumber(quest: Quest | null | undefined, value: number): string {
    const n = Math.max(0, Math.floor(Number(value) || 0));
    if (questUsesFormattedTarget(quest)) return resolveFormatNumber(n);
    return String(n);
}

function escapeHtml(s: string): string {
    return escapeHtmlImpl(s);
}

