export class Quest {
    id: string | number = '';
    title: string = '';
    description: string = '';
    target: number = 0;
    progress: number = 0;
    current: number = 0;
    completed: boolean = false;
    claimed: boolean = false;
    accepted: boolean = false;
    trackingKey: string = '';
    difficulty: string = 'EASY';
    special: string | null = null;
    specialParams: QuestSpecialParams = {};
    startTime: number = 0;
    startValue: number = 0;
    questType: string | null = null;
    badgeCountForRewards: number = 1;
    repeatCount: number = 0;
    repeatKey: string | null = null;
    /** Index within template.target[] when the objective was rolled from a tier list (0 = lowest). */
    targetTierIndex: number = 0;
    rewards: QuestRewards = { pokedollars: 0, tokens: 0, eggs: {} };
    requiredSpecies?: string;
    requiredType?: string;
    typesObtained?: Set<string>;
    tags?: string[];
    dialogue?: string;
    i18nKey?: string;

    constructor(template: QuestTemplate, multiplier: number = 1, difficulty: string = 'EASY', options: QuestOptions = {}) {
        this.id = Date.now() + Math.random();
        this.title = template.title;
        this.description = template.desc || template.description || '';
        if (Array.isArray(template.target)) {
            const tierIdx = Math.floor(Math.random() * template.target.length);
            this.targetTierIndex = tierIdx;
            this.target = template.target[tierIdx] ?? 0;
        } else {
            this.targetTierIndex = 0;
            this.target = template.target ?? 0;
        }
        this.progress = 0;
        this.current = 0;
        this.completed = false;
        this.claimed = false;
        this.accepted = false;
        this.trackingKey = template.trackingKey;
        this.difficulty = difficulty;
        this.special = template.special || null;
        this.startTime = Date.now();
        this.startValue = 0;
        this.questType = null;
        this.badgeCountForRewards = Math.max(1, Math.floor(Number(options.badgeCount) || 0));
        // Nombre de fois que ce modele de quete a deja ete termine par le joueur.
        // +1% de gains par repetition (applique aux pokedollars et aux jetons).
        this.repeatCount = Math.max(0, Math.floor(Number(options.repeatCount) || 0));
        this.repeatKey = options.repeatKey || null;

        this.specialParams = {};

        if (template.specialParams && typeof template.specialParams === 'object') {
            Object.assign(this.specialParams, template.specialParams);
        }

        if (template.special === 'monotype') {
            const types = Object.values(TYPES);
            const pickedType = arrayAt(types, Math.floor(Math.random() * types.length)) ?? 'normal';
            this.specialParams.requiredType = pickedType;
            this.description = this.description.replace('{type}', pickedType);
        }

        if (template.time) {
            this.specialParams.timeLimit = Array.isArray(template.time)
                ? template.time[Math.floor(Math.random() * template.time.length)]
                : template.time;
            this.description = this.description.replace('{time}', String(this.specialParams.timeLimit || ''));
        }

        if (template.special === 'zone_unlock') {
            this.specialParams.targetZone = Math.floor(Math.random() * 5) + 2;
            this.description = this.description.replace('{zone}', String(this.specialParams.targetZone));
        }

        const targetStr = questUsesFormattedTarget({ trackingKey: this.trackingKey } as Quest)
            ? resolveFormatNumber(this.target)
            : String(this.target);
        this.description = this.description.replace('{target}', targetStr);

        const QD = questDifficulties();
        const diffDef = QD[difficulty] || {};
        const diffMultiplier = Number((diffDef).multiplier ?? (diffDef).rewardMultiplier ?? 1);
        this.rewards = this.calculateRewards(diffMultiplier * multiplier, this.targetTierIndex);
    }

    calculateRewards(multiplier: number, targetTierIndex: number = 0): QuestRewards {
        const rewardBase = QUEST_REWARD_BASE ?? { pokedollars: 100, tokens: 1 };
        const basePokedollars = Number(rewardBase.pokedollars) || 100;
        const badgeScaledPokedollarsBase = basePokedollars * this.badgeCountForRewards;
        const repeatMultiplier = 1 + (Math.max(0, Math.floor(Number(this.repeatCount) || 0)) * 0.01);
        const scaledMultiplier = multiplier * repeatMultiplier;
        const tierIdx = Math.max(0, Math.floor(Number(targetTierIndex) || 0));
        const tierMult = 1 + tierIdx * 0.4;
        const base: QuestRewards = {
            pokedollars: Math.floor(badgeScaledPokedollarsBase * scaledMultiplier * tierMult),
            tokens: Math.round((Number(rewardBase.tokens) || 1) * scaledMultiplier * tierMult),
            eggs: {}
        };
        const R = rarityKeys();
        const rareEgg = R.RARE;
        const epicEgg = R.EPIC;
        const legendaryEgg = R.LEGENDARY;
        if (this.difficulty === 'MEDIUM' && rareEgg) {
            base.eggs[rareEgg] = 1;
        } else if (this.difficulty === 'HARD' && epicEgg) {
            base.eggs[epicEgg] = 1;
        } else if (this.difficulty === 'EXTREME' && legendaryEgg) {
            base.eggs[legendaryEgg] = 1;
        }
        if (tierIdx >= 2) {
            if (rareEgg && base.eggs[rareEgg]) {
                base.eggs[rareEgg] += 1;
            } else if (epicEgg && base.eggs[epicEgg]) {
                base.eggs[epicEgg] += 1;
            } else if (legendaryEgg && base.eggs[legendaryEgg]) {
                base.eggs[legendaryEgg] += 1;
            }
        }
        if (this.difficulty === 'HARD') {
            base.tokens += 3;
        } else if (this.difficulty === 'EXTREME') {
            base.tokens += 6;
            base.pokedollars *= 2;
        }
        return base;
    }

    updateProgress(value: number): boolean {
        this.current = Math.min(value, this.target);
        this.progress = this.current;
        if (this.current >= this.target && !this.completed) {
            this.completed = true;
            return true;
        }
        return false;
    }

    getProgressPercent(): number {
        return Math.min(100, (this.current / this.target) * 100);
    }
}

