export function questLang(game: GameRuntime | null | undefined): string {
    if (!game || typeof game.normalizeLanguage !== 'function') return 'fr';
    return game.normalizeLanguage(game.language);
}

export function questFormat(text: string | null | undefined, vars: Record<string, unknown> = {}): string {
    return coerceStr(text, '').replace(/\{(\w+)\}/g, (_: string, k: string) => coerceStr(vars[k], ''));
}

function localizeQuestZoneName(game: GameRuntime | null | undefined, zoneId: number): string {
    const id = Number(zoneId);
    if (!Number.isFinite(id) || id <= 0) return '';
    const zoneDef = (ZONES as Record<number, ZoneDataEntry | undefined>)[id];
    if (game && typeof game.getLocalizedZoneName === 'function') {
        const fallback = zoneDef?.name ? String(zoneDef.name) : '';
        return game.getLocalizedZoneName(id, fallback);
    }
    return zoneDef?.name ? String(zoneDef.name) : `Zone ${id}`;
}

export function findStoryQuestDefById(
    questId: string | number | null | undefined,
): Record<string, unknown> | null {
    if (questId == null || questId === '') return null;
    const id = String(questId);
    let def = (STORY_QUESTS as Record<string, Record<string, unknown>>)[id];
    if (!def) {
        for (const candidate of Object.values(STORY_QUESTS)) {
            if (candidate && typeof candidate === 'object' && (candidate as { id?: string }).id === id) {
                def = candidate as Record<string, unknown>;
                break;
            }
        }
    }
    return def || null;
}

/** Legacy story_unova_dragonspiral used target 5 (any boss in zone 432); now 1 Druddigon boss. */
export function migrateStoryUnovaDragonspiralQuestOnRestore(quest: {
    id?: string | number;
    claimed?: boolean;
    target?: unknown;
    current?: number;
    completed?: boolean;
    requiredSpecies?: string;
    description?: string;
    dialogue?: string;
    specialParams?: Record<string, unknown>;
}): void {
    if (quest.id !== 'story_unova_dragonspiral' || quest.claimed) return;
    const dragonspiralDef = STORY_QUESTS.unova_dragonspiral;
    if (!dragonspiralDef) return;
    const hadLegacyTarget = Number(quest.target) === 5 || !quest.requiredSpecies;
    quest.target = dragonspiralDef.target;
    quest.requiredSpecies = dragonspiralDef.requiredSpecies;
    quest.description = dragonspiralDef.description;
    if (dragonspiralDef.dialogue) quest.dialogue = dragonspiralDef.dialogue;
    if (!quest.specialParams || typeof quest.specialParams !== 'object') {
        quest.specialParams = {};
    }
    quest.specialParams.requiredZone = 432;
    if (hadLegacyTarget) {
        quest.current = Math.min(Math.max(0, Number(quest.current) || 0), 1);
        quest.completed = (quest.current || 0) >= 1;
    }
}

/** Legacy story_kalos_azure_bay required Absol (not in Azure Bay pool); now Lapras. */
export function migrateStoryKalosAzureBayQuestOnRestore(quest: {
    id?: string | number;
    claimed?: boolean;
    requiredSpecies?: string;
    description?: string;
    dialogue?: string;
    current?: number;
    completed?: boolean;
}): void {
    if (quest.id !== 'story_kalos_azure_bay' || quest.claimed) return;
    const azureBayDef = STORY_QUESTS.kalos_azure_bay;
    if (!azureBayDef) return;
    if (quest.requiredSpecies === azureBayDef.requiredSpecies) return;
    const hadLegacyAbsol = quest.requiredSpecies === 'Absol' || !quest.requiredSpecies;
    if (!hadLegacyAbsol) return;
    quest.requiredSpecies = azureBayDef.requiredSpecies;
    quest.description = azureBayDef.description;
    if (azureBayDef.dialogue) quest.dialogue = azureBayDef.dialogue;
    if (quest.completed) {
        quest.current = 0;
        quest.completed = false;
    }
}

/** Resync Boss OR Epic story quest text from current story definitions on restore. */
export function migrateBossOrEpicStoryQuestTextOnRestore(quest: {
    id?: string | number;
    claimed?: boolean;
    trackingKey?: string;
    requiredSpecies?: string;
    description?: string;
    dialogue?: string;
}): void {
    if (quest.claimed || !isBossOrEpicSpeciesQuest(quest)) return;
    const storyDef = findStoryQuestDefById(quest.id);
    if (!storyDef) return;
    if (storyDef.description) quest.description = String(storyDef.description);
    if (storyDef.dialogue) quest.dialogue = String(storyDef.dialogue);
}

