const KALOS_ALOLA_ARENA_STORY_QUEST_ID_RE = /^story_(kalos|alola)_arena_\d+$/;

function getKalosAlolaArenaRequiredBadge(storyDef: Record<string, unknown> | null): string {
    const defSp = storyDef?.specialParams as Record<string, unknown> | undefined;
    return defSp && defSp.requiredBadge != null ? String(defSp.requiredBadge) : '';
}

/** Resync Kalos/Alola gym story quests to gym_badge tracking and undo false completions from badgesEarned. */
export function migrateKalosAlolaArenaStoryQuestOnRestore(
    game: GameRuntime,
    quest: {
        id?: string | number;
        claimed?: boolean;
        title?: string;
        description?: string;
        target?: number;
        current?: number;
        completed?: boolean;
        trackingKey?: string;
        specialParams?: Record<string, unknown>;
    },
): void {
    const id = String(quest.id || '');
    if (!KALOS_ALOLA_ARENA_STORY_QUEST_ID_RE.test(id)) return;

    const storyDef = findStoryQuestDefById(id);
    if (!storyDef) return;

    if (storyDef.title) quest.title = String(storyDef.title);
    if (storyDef.description) quest.description = String(storyDef.description);
    quest.trackingKey = String(storyDef.trackingKey || 'gym_badge');
    quest.target = 1;

    if (!quest.specialParams || typeof quest.specialParams !== 'object') {
        quest.specialParams = {};
    }
    const defSp = storyDef.specialParams as Record<string, unknown> | undefined;
    if (defSp && typeof defSp === 'object' && defSp.requiredBadge != null) {
        quest.specialParams.requiredBadge = defSp.requiredBadge;
    }

    const reqBadge = getKalosAlolaArenaRequiredBadge(storyDef);
    const hasBadge = !!reqBadge
        && typeof game.hasBadge === 'function'
        && game.hasBadge(reqBadge);

    quest.current = hasBadge ? 1 : 0;
    quest.completed = hasBadge;
    if (!hasBadge && quest.claimed) {
        quest.claimed = false;
    }
}

/** Drop Kalos/Alola arena story completions that were granted without the matching gym badge. */
export function repairKalosAlolaArenaStoryQuestCompletionsOnRestore(game: GameRuntime): void {
    if (!Array.isArray(game.completedStoryQuests)) return;

    game.completedStoryQuests = game.completedStoryQuests.filter((questId) => {
        const id = String(questId);
        if (!KALOS_ALOLA_ARENA_STORY_QUEST_ID_RE.test(id)) return true;

        const storyDef = findStoryQuestDefById(id);
        const reqBadge = getKalosAlolaArenaRequiredBadge(storyDef);
        if (!reqBadge) return true;

        return typeof game.hasBadge === 'function' && game.hasBadge(reqBadge);
    });
}

const REGION_START_STORY_QUEST_ID_RE = /^story_(sinnoh|unova|kalos|alola)_start$/;

function getRegionStartRequiredRegion(storyDef: Record<string, unknown> | null | undefined): string {
    const defSp = storyDef?.specialParams as Record<string, unknown> | undefined;
    if (defSp && defSp.requiredRegion != null) return String(defSp.requiredRegion);
    const id = String(storyDef?.id || '');
    const match = id.match(REGION_START_STORY_QUEST_ID_RE);
    return match?.[1] ?? '';
}

export function readRegionVisitedQuestProgress(
    game: GameRuntime,
    quest: { specialParams?: Quest['specialParams'] },
): number {
    const reqRegion = quest.specialParams && typeof quest.specialParams === 'object'
        ? String((quest.specialParams as Record<string, unknown>).requiredRegion || '')
        : '';
    if (!reqRegion) return 0;
    return hasPlayerSelectedRegionForWelcomeQuest(game, reqRegion) ? 1 : 0;
}

/** Gate story progress on completion (before claim) to avoid re-offering welcome quests. */
export function markRegionStartStoryQuestGateComplete(
    game: GameRuntime,
    quest: { id?: string | number; specialParams?: Quest['specialParams'] },
): void {
    const id = String(quest.id || '');
    if (!REGION_START_STORY_QUEST_ID_RE.test(id)) return;
    const reqRegion = quest.specialParams && typeof quest.specialParams === 'object'
        ? String((quest.specialParams as Record<string, unknown>).requiredRegion || '')
        : getRegionStartRequiredRegion(findStoryQuestDefById(id));
    if (!Array.isArray(game.completedStoryQuests)) game.completedStoryQuests = [];
    if (!game.completedStoryQuests.some((entry) => String(entry) === id)) {
        game.completedStoryQuests.push(id);
    }
}

/** Resync Welcome-to-region story quests to region_visited and undo false completions from badgesEarned. */
export function migrateRegionStartStoryQuestOnRestore(
    game: GameRuntime,
    quest: {
        id?: string | number;
        claimed?: boolean;
        title?: string;
        description?: string;
        target?: number;
        current?: number;
        completed?: boolean;
        trackingKey?: string;
        specialParams?: Record<string, unknown>;
    },
): void {
    const id = String(quest.id || '');
    if (!REGION_START_STORY_QUEST_ID_RE.test(id)) return;

    const storyDef = findStoryQuestDefById(id);
    if (!storyDef) return;

    if (storyDef.title) quest.title = String(storyDef.title);
    if (storyDef.description) quest.description = String(storyDef.description);
    quest.trackingKey = String(storyDef.trackingKey || 'region_visited');
    quest.target = 1;

    if (!quest.specialParams || typeof quest.specialParams !== 'object') {
        quest.specialParams = {};
    }
    const defSp = storyDef.specialParams as Record<string, unknown> | undefined;
    const reqRegion = getRegionStartRequiredRegion(storyDef);
    if (reqRegion) {
        quest.specialParams.requiredRegion = reqRegion;
    } else if (defSp && typeof defSp === 'object' && defSp.requiredRegion != null) {
        quest.specialParams.requiredRegion = defSp.requiredRegion;
    }

    const alreadyGateComplete = Array.isArray(game.completedStoryQuests)
        && game.completedStoryQuests.some((entry) => String(entry) === id);
    if (alreadyGateComplete || quest.claimed) {
        quest.current = 1;
        quest.completed = true;
        return;
    }

    const visited = readRegionVisitedQuestProgress(game, quest);
    quest.current = visited;
    quest.completed = visited >= 1;
    if (visited >= 1) {
        markRegionStartStoryQuestGateComplete(game, quest);
    }
    if (visited < 1 && quest.claimed) {
        quest.claimed = false;
    }
}

/** Drop Welcome-to-region story completions granted without visiting the target region. */
export function repairRegionStartStoryQuestCompletionsOnRestore(game: GameRuntime): void {
    if (!Array.isArray(game.completedStoryQuests)) return;

    game.completedStoryQuests = game.completedStoryQuests.filter((questId) => {
        const id = String(questId);
        if (!REGION_START_STORY_QUEST_ID_RE.test(id)) return true;

        const storyDef = findStoryQuestDefById(id);
        const reqRegion = getRegionStartRequiredRegion(storyDef);
        if (!reqRegion) return true;

        return hasPlayerSelectedRegionForWelcomeQuest(game, reqRegion);
    });
}

/** Story quests that require defeating a specific species as Boss or Epic in a zone. */
export function isBossOrEpicSpeciesQuest(quest: {
    id?: string | number;
    trackingKey?: string;
    requiredSpecies?: string;
} | null | undefined): boolean {
    if (!quest) return false;
    if (quest.trackingKey !== 'bossDefeated' || !quest.requiredSpecies) return false;
    const id = coerceStr(quest.id, '');
    return id.startsWith('story_unova_')
        || id.startsWith('story_kalos_')
        || id.startsWith('story_alola_')
        || id.startsWith('story_galar_');
}

/** @deprecated Use {@link isBossOrEpicSpeciesQuest}. */
export function isUnovaBossSpeciesQuest(quest: Parameters<typeof isBossOrEpicSpeciesQuest>[0]): boolean {
    return isBossOrEpicSpeciesQuest(quest);
}

export function matchesBossSpeciesQuestKill(
    quest: {
        requiredSpecies?: string;
        id?: string | number;
        questType?: string;
        specialParams?: Quest['specialParams'];
    },
    params?: Record<string, unknown> | null,
): boolean {
    if (quest.requiredSpecies) {
        const killSpecies = resolveRosterSpeciesKey(coerceStr(params?.species, ''));
        const requiredSpecies = resolveRosterSpeciesKey(quest.requiredSpecies);
        if (killSpecies !== requiredSpecies) return false;
    }
    const requiredZone = resolveQuestRequiredZone(quest);
    if (requiredZone != null && Number(params?.zoneId) !== requiredZone) return false;
    return true;
}

/** Story def wins over stale saved specialParams.requiredZone when present. */
export function resolveQuestRequiredZone(quest: {
    id?: string | number;
    questType?: string;
    specialParams?: Quest['specialParams'];
} | null | undefined): number | null {
    if (!quest) return null;
    if (quest.questType === 'STORY' && quest.id) {
        const storyDef = findStoryQuestDefById(quest.id);
        const defZone = Number((storyDef?.specialParams as QuestSpecialParams | undefined)?.requiredZone);
        if (Number.isFinite(defZone) && defZone > 0) return defZone;
    }
    const instanceZone = Number(quest.specialParams?.requiredZone);
    if (Number.isFinite(instanceZone) && instanceZone > 0) return instanceZone;
    return null;
}

export const CAPTURE_MIN_IV_BY_DIFFICULTY: Record<string, number> = {
    EASY: 60,
    MEDIUM: 70,
    HARD: 80,
    EXTREME: 90,
};

export function getCaptureMinIvPercent(difficulty: string | null | undefined): number {
    const key = coerceStr(difficulty, 'EASY').toUpperCase();
    const val = CAPTURE_MIN_IV_BY_DIFFICULTY[key];
    if (typeof val === 'number' && Number.isFinite(val)) return val;
    return CAPTURE_MIN_IV_BY_DIFFICULTY.EASY ?? 60;
}

function hasNonEmptyCaptureRequirements(specialParams: QuestSpecialParams | null | undefined): boolean {
    const caps = specialParams?.captureRequirements;
    return Array.isArray(caps) && caps.length > 0;
}

export function isSimpleStoryCaptureDef(def: Record<string, unknown> | null | undefined): boolean {
    if (!def || def.trackingKey !== 'creature_captured') return false;
    if (STORY_CAPTURE_NO_IV_QUEST_IDS.has(coerceStr(def.id, ''))) return false;
    const sp = def.specialParams;
    if (sp && typeof sp === 'object' && hasNonEmptyCaptureRequirements(sp as QuestSpecialParams)) return false;
    if (sp && typeof sp === 'object' && Number((sp as QuestSpecialParams).minIvPercent) > 0) return false;
    return true;
}

export function applyStorySimpleCaptureIvGate(quest: Quest, storyDef: Record<string, unknown>): void {
    if (!isSimpleStoryCaptureDef(storyDef)) return;
    if (!quest.specialParams || typeof quest.specialParams !== 'object') quest.specialParams = {};
    if (Number(quest.specialParams.minIvPercent) > 0) return;
    quest.specialParams.minIvPercent = getCaptureMinIvPercent(coerceStr(storyDef.difficulty, quest.difficulty));
}

export function applyWildSpeciesIvCaptureToClassicQuest(game: GameRuntime, quest: Quest): boolean {
    const pick = pickReachableWildCaptureForClassicQuest(game, {
        excludeSpecies: getClassicQualityCatchExcludedSpecies(game),
    });
    if (!pick) return false;
    if (!quest.specialParams || typeof quest.specialParams !== 'object') quest.specialParams = {};
    quest.requiredSpecies = pick.species;
    quest.specialParams.requiredZone = pick.zoneId;
    quest.specialParams.minIvPercent = getCaptureMinIvPercent(quest.difficulty);
    ensureIvCaptureEggRewards(game, quest);
    return true;
}

export function storyQuestHasIvGate(quest: Quest | null | undefined): boolean {
    if (!quest || quest.questType !== 'STORY' || quest.trackingKey !== 'creature_captured') return false;
    if (hasNonEmptyCaptureRequirements(quest.specialParams)) return false;
    const minIv = Number(quest.specialParams?.minIvPercent);
    return Number.isFinite(minIv) && minIv > 0;
}

export function questHasIvCaptureGate(quest: Quest | null | undefined): boolean {
    if (!quest || quest.trackingKey !== 'creature_captured') return false;
    if (hasNonEmptyCaptureRequirements(quest.specialParams)) return false;
    const minIv = Number(quest.specialParams?.minIvPercent);
    if (!(Number.isFinite(minIv) && minIv > 0)) return false;
    if (quest.questType === 'STORY') return true;
    if (quest.questType === 'TEAM_ROCKET') return true;
    return isClassicQualityCatchQuest(quest);
}

export const IV_CAPTURE_FIELDS = [
    'ivHP',
    'ivAttack',
    'ivDefense',
    'ivSpAttack',
    'ivSpDefense',
    'ivSpeed',
] as const;

const LEGACY_MIN_IV_PERCENT_VALUES = new Set([50, 60, 70, 80, 72, 74]);
const LEGACY_MIN_IV_STAT_VALUES = new Set([24, 25, 27]);

export function resyncIvQuestThresholds(quest: Quest): void {
    if (!quest.specialParams || typeof quest.specialParams !== 'object') return;

    const minIvPercent = Math.floor(Number(quest.specialParams.minIvPercent));
    if (Number.isFinite(minIvPercent) && LEGACY_MIN_IV_PERCENT_VALUES.has(minIvPercent)) {
        quest.specialParams.minIvPercent = minIvPercent + 10;
    }

    const captureRequirements = quest.specialParams.captureRequirements;
    if (!Array.isArray(captureRequirements) || captureRequirements.length === 0) return;

    for (let i = 0; i < captureRequirements.length; i++) {
        const req = captureRequirements[i];
        if (!req || typeof req !== 'object') continue;
        const reqMinIvPercent = Math.floor(Number(req.minIvPercent));
        if (Number.isFinite(reqMinIvPercent) && LEGACY_MIN_IV_PERCENT_VALUES.has(reqMinIvPercent)) {
            req.minIvPercent = reqMinIvPercent + 10;
        }
        for (let k = 0; k < IV_CAPTURE_FIELDS.length; k++) {
            const field = IV_CAPTURE_FIELDS[k];
            if (field === undefined) continue;
            const minKey = `min${field.charAt(0).toUpperCase()}${field.slice(1)}`;
            const minStat = Math.floor(Number(req[minKey]));
            if (Number.isFinite(minStat) && LEGACY_MIN_IV_STAT_VALUES.has(minStat)) {
                req[minKey] = minStat + 3;
            }
        }
    }
}

export type CaptureIvSnapshot = {
    ivPercent: number;
    ivHP: number;
    ivAttack: number;
    ivDefense: number;
    ivSpAttack: number;
    ivSpDefense: number;
    ivSpeed: number;
};

export function hasCaptureIvStatFields(params: Record<string, unknown>): boolean {
    for (let i = 0; i < IV_CAPTURE_FIELDS.length; i++) {
        const field = IV_CAPTURE_FIELDS[i];
        if (field === undefined) continue;
        if (Number.isFinite(Number(params[field]))) return true;
    }
    return false;
}

export function sanitizeCaptureIvsFromParams(
    params: Record<string, unknown>,
): { captureIvs: Record<string, number>; captureIvPercent: number } {
    const captureIvs: Record<string, number> = {};
    let ivTotal = 0;
    let ivCount = 0;
    for (let i = 0; i < IV_CAPTURE_FIELDS.length; i++) {
        const field = IV_CAPTURE_FIELDS[i];
        if (field === undefined) continue;
        const value = Number(params[field]);
        if (!Number.isFinite(value)) continue;
        const sanitized = Math.max(0, value);
        captureIvs[field] = sanitized;
        ivTotal += sanitized;
        ivCount++;
    }
    let captureIvPercent = Number(params.ivPercent);
    if (!Number.isFinite(captureIvPercent) && ivCount > 0) {
        captureIvPercent = (ivTotal / (31 * ivCount)) * 100;
    }
    return { captureIvs, captureIvPercent };
}

export function computeIvPercentFromCaptureIvs(captureIvs: Record<string, number>): number {
    let ivTotal = 0;
    let ivCount = 0;
    for (let i = 0; i < IV_CAPTURE_FIELDS.length; i++) {
        const field = IV_CAPTURE_FIELDS[i];
        if (field === undefined) continue;
        const value = Number(captureIvs[field]);
        if (!Number.isFinite(value)) continue;
        ivTotal += Math.max(0, value);
        ivCount++;
    }
    if (ivCount === 0) return 0;
    return Math.max(0, Math.min(100, (ivTotal / (31 * ivCount)) * 100));
}

export function mergeCaptureIvBest(
    existing: CaptureIvSnapshot | null | undefined,
    captureIvs: Record<string, number>,
): CaptureIvSnapshot {
    const merged: Record<string, number> = {};
    for (let i = 0; i < IV_CAPTURE_FIELDS.length; i++) {
        const field = IV_CAPTURE_FIELDS[i];
        if (field === undefined) continue;
        const prevVal = existing
            ? Math.max(0, Math.floor(Number(existing[field]) || 0))
            : 0;
        const capVal = Math.max(0, Math.floor(Number(captureIvs[field]) || 0));
        merged[field] = Math.max(prevVal, capVal);
    }
    const ivPercent = computeIvPercentFromCaptureIvs(merged);
    return {
        ivPercent: Math.round(ivPercent * 10) / 10,
        ivHP: merged.ivHP ?? 0,
        ivAttack: merged.ivAttack ?? 0,
        ivDefense: merged.ivDefense ?? 0,
        ivSpAttack: merged.ivSpAttack ?? 0,
        ivSpDefense: merged.ivSpDefense ?? 0,
        ivSpeed: merged.ivSpeed ?? 0,
    };
}

export function captureMeetsIvRequirements(
    mergedIvs: CaptureIvSnapshot | Record<string, number>,
    req: Record<string, unknown>,
): boolean {
    const percent = computeIvPercentFromCaptureIvs(mergedIvs as Record<string, number>);
    const reqMinIvPercent = Number(req.minIvPercent);
    if (Number.isFinite(reqMinIvPercent) && reqMinIvPercent > 0 && percent < reqMinIvPercent) {
        return false;
    }
    for (let i = 0; i < IV_CAPTURE_FIELDS.length; i++) {
        const field = IV_CAPTURE_FIELDS[i];
        if (field === undefined) continue;
        const minKey = `min${field.charAt(0).toUpperCase()}${field.slice(1)}`;
        const minStat = Number(req[minKey]);
        if (Number.isFinite(minStat) && minStat > 0) {
            const val = Number((mergedIvs as Record<string, number>)[field]);
            if (!Number.isFinite(val) || val < minStat) return false;
        }
    }
    return true;
}

function creatureIvsFromRecord(creature: Record<string, unknown>): Record<string, number> {
    return {
        ivHP: Math.max(0, Number(creature.ivHP) || 0),
        ivAttack: Math.max(0, Number(creature.ivAttack) || 0),
        ivDefense: Math.max(0, Number(creature.ivDefense) || 0),
        ivSpAttack: Math.max(0, Number(creature.ivSpAttack) || 0),
        ivSpDefense: Math.max(0, Number(creature.ivSpDefense) || 0),
        ivSpeed: Math.max(0, Number(creature.ivSpeed) || 0),
    };
}

export function buildEvolutionQuestEventParams(
    baseName: string,
    evolvedName: string,
    creature: Record<string, unknown>,
): Record<string, unknown> {
    const captureIvs = creatureIvsFromRecord(creature);
    return {
        baseName,
        evolvedName,
        uid: creature.uid,
        ...captureIvs,
        ivPercent: computeIvPercentFromCaptureIvs(captureIvs),
    };
}

export function rosterHasQualifiedObtainSpecies(
    game: GameRuntime,
    obtainSpecies: string,
    minIvPercent: number,
): boolean {
    const roster = [
        ...(game.playerTeam || []),
        ...(game.storage || []),
        ...(game.pension || []),
    ];
    return roster.some((creature) => {
        if (!creature || creature.name !== obtainSpecies) return false;
        const ivPercent = computeIvPercentFromCaptureIvs(creatureIvsFromRecord(creature as Record<string, unknown>));
        return ivPercent >= minIvPercent;
    });
}

export function tryCompleteObtainSpeciesQuest(
    quest: Quest,
    params: Record<string, unknown>,
): boolean {
    const obtainSpecies = coerceStr(quest.specialParams?.obtainSpecies, '');
    if (!obtainSpecies || quest.trackingKey !== 'creature_captured') return false;

    const evolvedName = coerceStr(params.evolvedName, '');
    if (evolvedName !== obtainSpecies) return false;
    if (!quest.specialParams?.lineCapturedInZone) return false;

    const { captureIvs } = sanitizeCaptureIvsFromParams(params);
    const minIvPercent = Number(quest.specialParams?.minIvPercent);
    if (Number.isFinite(minIvPercent) && minIvPercent > 0) {
        const ivPercent = computeIvPercentFromCaptureIvs(captureIvs);
        if (!Number.isFinite(ivPercent) || ivPercent < minIvPercent) return false;
    }

    quest.current = Math.max(1, Number(quest.target) || 1);
    quest.updateProgress(quest.current);
    return true;
}

function captureMatchesRequirementContext(
    quest: Quest,
    req: Record<string, unknown>,
    params: Record<string, unknown>,
): boolean {
    const reqSpecies = coalesceStr(req.requiredSpecies, quest.requiredSpecies ?? '');
    if (reqSpecies && coerceStr(params.species, '') !== reqSpecies) return false;
    const requiredZone = Number(
        (req.requiredZone !== undefined)
            ? req.requiredZone
            : (resolveQuestRequiredZone(quest) ?? NaN),
    );
    if (Number.isFinite(requiredZone) && requiredZone > 0 && Number(params.zoneId) !== requiredZone) {
        return false;
    }
    return true;
}

export function buildCaptureQuestEventParams(
    creature: {
        name?: string;
        uid?: string | number;
        type?: string;
        secondaryType?: string | null;
        ivHP?: number;
        ivAttack?: number;
        ivDefense?: number;
        ivSpAttack?: number;
        ivSpDefense?: number;
        ivSpeed?: number;
    },
    zoneId: number,
    extras: Record<string, unknown> = {},
): Record<string, unknown> {
    const ivHP = Math.max(0, Number(creature.ivHP) || 0);
    const ivAttack = Math.max(0, Number(creature.ivAttack) || 0);
    const ivDefense = Math.max(0, Number(creature.ivDefense) || 0);
    const ivSpAttack = Math.max(0, Number(creature.ivSpAttack) || 0);
    const ivSpDefense = Math.max(0, Number(creature.ivSpDefense) || 0);
    const ivSpeed = Math.max(0, Number(creature.ivSpeed) || 0);
    const ivPercent = computeIvPercentFromCaptureIvs({
        ivHP,
        ivAttack,
        ivDefense,
        ivSpAttack,
        ivSpDefense,
        ivSpeed,
    });
    return {
        species: creature.name,
        uid: creature.uid,
        creatureType: creature.type,
        secondaryType: creature.secondaryType ?? undefined,
        zoneId: Number(zoneId),
        ivPercent,
        ivHP,
        ivAttack,
        ivDefense,
        ivSpAttack,
        ivSpDefense,
        ivSpeed,
        ...extras,
    };
}

export function recordStoryQuestBestCaptureAttempt(
    quest: Quest,
    captureIvs: Record<string, number>,
    _captureIvPercent?: number,
): void {
    if (!quest.specialParams || typeof quest.specialParams !== 'object') quest.specialParams = {};
    quest.specialParams.bestCaptureAttempt = mergeCaptureIvBest(
        quest.specialParams.bestCaptureAttempt,
        captureIvs,
    );
}

/** True when the merged best-IV snapshot changed (UI must refresh even if quest.current is unchanged). */
export function recordStoryQuestBestCaptureAttemptIfChanged(
    quest: Quest,
    captureIvs: Record<string, number>,
): boolean {
    const before = JSON.stringify(quest.specialParams?.bestCaptureAttempt ?? null);
    recordStoryQuestBestCaptureAttempt(quest, captureIvs);
    const after = JSON.stringify(quest.specialParams?.bestCaptureAttempt ?? null);
    return before !== after;
}

export function buildStoryQuestIvProgressHTML(game: GameRuntime, quest: Quest): string {
    if (!questHasIvCaptureGate(quest) || !quest.accepted || quest.completed) return '';
    const minIvPercent = Math.floor(Number(quest.specialParams?.minIvPercent) || 0);
    if (!(minIvPercent > 0)) return '';

    const best = quest.specialParams?.bestCaptureAttempt;
    if (!best || !Number.isFinite(Number(best.ivPercent))) {
        const empty = escapeQuestHtml(questUiText(
            game,
            'ivBestCaptureEmpty',
            'Pas encore de capture éligible',
        ));
        return `<div class="quest-iv-panel quest-iv-panel--empty"><div class="quest-iv-empty">${empty}</div></div>`;
    }

    const bestPercent = Math.round(Number(best.ivPercent) * 10) / 10;
    const qualified = bestPercent >= minIvPercent;
    const stateClass = qualified ? 'is-qualified' : 'is-below';
    const barPercent = Math.min(100, Math.max(0, (bestPercent / minIvPercent) * 100));
    const header = escapeQuestHtml(questUiText(
        game,
        'ivBestCaptureLabel',
        'Meilleurs IV combinés : {percent}% / {required}% requis',
        { percent: String(bestPercent), required: String(minIvPercent) },
    ));
    const stats = [
        `HP ${best.ivHP}`,
        `Atk ${best.ivAttack}`,
        `Def ${best.ivDefense}`,
        `SpA ${best.ivSpAttack}`,
        `SpD ${best.ivSpDefense}`,
        `Spe ${best.ivSpeed}`,
    ].map((s) => `<span class="quest-iv-stat">${escapeQuestHtml(s)}</span>`).join('');

    return `<div class="quest-iv-panel ${stateClass}"><div class="quest-iv-header">${header}</div><div class="quest-iv-stats">${stats}</div><div class="quest-progress-bar quest-iv-bar"><div class="quest-progress-fill" style="width:${barPercent}%"></div></div></div>`;
}

export function normalizeCaptureQuestDescription(
    text: string,
    quest: { trackingKey?: string; specialParams?: QuestSpecialParams } | null | undefined,
    _lang?: string,
): string {
    if (!text || !quest || quest.trackingKey !== 'creature_captured') return text;
    if (hasNonEmptyCaptureRequirements(quest.specialParams)) return text;

    let out = text;
    out = out.replace(/\s*\(zone\s*\d+[^)]*\)/gi, '');
    out = out.replace(/\s*\(must all be caught while this quest is active\)/gi, '');
    out = out.replace(/\s*\(must be caught(?: OR evolved)? while this quest is active\)/gi, '');
    out = out.replace(/\s+while this quest is active/gi, '');
    out = out.replace(/\s+in battle(?=[\s,.]|$)/gi, '');
    out = out.replace(/\s*\(doivent tous être attrapés pendant que cette quête est active\)/gi, '');
    out = out.replace(/\s*\(doivent être attrapés pendant que cette quête est active\)/gi, '');
    out = out.replace(/\s*\(doit être attrapé(?: OU évolué)? pendant que cette quête est active\)/gi, '');
    out = out.replace(/\s+pendant que cette quête est active/gi, '');
    out = out.replace(/\s+en combat(?=[\s,.]|$)/gi, '');
    out = out.replace(/\s{2,}/g, ' ');
    out = out.replace(/\s+\./g, '.');
    out = out.replace(/\(\s*\)/g, '');
    return out.trim();
}

export function formatMinIvQualityClause(game: GameRuntime | null | undefined, minIvPercent: number): string {
    const minIv = Math.floor(Number(minIvPercent));
    if (!Number.isFinite(minIv) || minIv <= 0) return '';
    const fr = game ? questLang(game) === 'fr' : false;
    return fr
        ? `(${minIv}% de qualité IV totaux minimum)`
        : `(${minIv}% total IVs quality minimum)`;
}

function appendMinIvClauseToDescription(
    game: GameRuntime,
    quest: Quest,
    baseDescription: string,
): string {
    const minIv = Number(quest.specialParams?.minIvPercent);
    if (!Number.isFinite(minIv) || minIv <= 0) return baseDescription;
    if (quest.trackingKey !== 'creature_captured') return baseDescription;
    if (hasNonEmptyCaptureRequirements(quest.specialParams)) return baseDescription;
    if (
        baseDescription.includes('{minIvPercent}')
        || baseDescription.includes('total IVs quality minimum')
        || baseDescription.includes('qualité IV totaux minimum')
    ) {
        return baseDescription;
    }
    const clause = formatMinIvQualityClause(game, minIv);
    if (!clause) return baseDescription;
    const trimmed = baseDescription.replace(/\s+$/, '');
    if (!trimmed) return `${clause}.`;
    if (trimmed.endsWith('.')) return `${trimmed.slice(0, -1)} ${clause}.`;
    return `${trimmed} ${clause}.`;
}

/** Resolve {zoneName}, {zoneName1}, … from specialParams.requiredZone / captureRequirements. */
export function buildQuestZoneNameVars(
    game: GameRuntime | null | undefined,
    quest: {
        id?: string | number;
        questType?: string;
        specialParams?: Quest['specialParams'];
    } | null | undefined,
): Record<string, string> {
    const vars: Record<string, string> = {};
    if (!quest) return vars;

    const sp = quest.specialParams;
    const resolvedZone = resolveQuestRequiredZone(quest);
    let requiredZone = resolvedZone != null ? resolvedZone : NaN;
    let caps = sp?.captureRequirements;

    if (quest.questType === 'STORY' && quest.id) {
        const storyDef = findStoryQuestDefById(quest.id);
        const defSp = storyDef?.specialParams as QuestSpecialParams | undefined;
        if (defSp && typeof defSp === 'object') {
            if (!Array.isArray(caps) || caps.length === 0) {
                if (Array.isArray(defSp.captureRequirements) && defSp.captureRequirements.length > 0) {
                    caps = defSp.captureRequirements;
                }
            }
        }
    }

    if (Number.isFinite(requiredZone) && requiredZone > 0) {
        vars.zoneName = localizeQuestZoneName(game, requiredZone);
    }
    if (Array.isArray(caps)) {
        caps.forEach((req, idx) => {
            const z = Number((req as { requiredZone?: number }).requiredZone);
            if (Number.isFinite(z) && z > 0) {
                vars[`zoneName${idx + 1}`] = localizeQuestZoneName(game, z);
            }
        });
    }
    return vars;
}

export interface QuestNavigationLinkTarget {
    zoneId: number | null;
    label: string;
}

/** @deprecated Use QuestNavigationLinkTarget */
export type QuestZoneLinkTarget = QuestNavigationLinkTarget & { zoneId: number };

function resolveQuestCaptureRequirements(
    quest: {
        id?: string | number;
        questType?: string | null;
        specialParams?: Quest['specialParams'];
    } | null | undefined,
): QuestSpecialParams['captureRequirements'] {
    if (!quest) return undefined;
    let caps = quest.specialParams?.captureRequirements;
    if (quest.questType === 'STORY' && quest.id) {
        const storyDef = findStoryQuestDefById(quest.id);
        const defSp = storyDef?.specialParams as QuestSpecialParams | undefined;
        if (defSp && typeof defSp === 'object') {
            if (!Array.isArray(caps) || caps.length === 0) {
                if (Array.isArray(defSp.captureRequirements) && defSp.captureRequirements.length > 0) {
                    caps = defSp.captureRequirements;
                }
            }
        }
    }
    return caps;
}

/** Zone IDs + localized labels for quest-required zones (main + captureRequirements). */
export function collectQuestZoneLinkTargets(
    game: GameRuntime | null | undefined,
    quest: Quest | {
        id?: string | number;
        questType?: string | null;
        specialParams?: Quest['specialParams'];
    } | null | undefined,
): QuestZoneLinkTarget[] {
    if (!quest) return [];

    const entries: QuestZoneLinkTarget[] = [];
    const seen = new Set<number>();

    const addZone = (zoneId: number) => {
        if (!Number.isFinite(zoneId) || zoneId <= 0 || seen.has(zoneId)) return;
        seen.add(zoneId);
        entries.push({ zoneId, label: localizeQuestZoneName(game, zoneId) });
    };

    const resolvedZone = resolveQuestRequiredZone(quest);
    if (resolvedZone != null) addZone(resolvedZone);

    const caps = resolveQuestCaptureRequirements(quest);
    if (Array.isArray(caps)) {
        for (const req of caps) {
            const z = Number((req as { requiredZone?: number }).requiredZone);
            if (Number.isFinite(z) && z > 0) addZone(z);
        }
    }

    return entries;
}

/** Resolve teleport zone for a quest species (quest zone first, else highest unlocked spawn). */
export function resolveQuestSpeciesTargetZone(
    game: GameRuntime | null | undefined,
    quest: Quest | {
        id?: string | number;
        questType?: string | null;
        requiredSpecies?: string;
        specialParams?: Quest['specialParams'];
    } | null | undefined,
    species: string,
): number | null {
    const speciesKey = String(species || '').trim();
    if (!speciesKey || !game) return null;

    const caps = resolveQuestCaptureRequirements(quest);
    if (Array.isArray(caps)) {
        for (const req of caps) {
            if (String((req as { requiredSpecies?: string }).requiredSpecies || '') !== speciesKey) continue;
            const z = Number((req as { requiredZone?: number }).requiredZone);
            if (Number.isFinite(z) && z > 0) return z;
        }
    }

    const resolvedZone = resolveQuestRequiredZone(quest);
    if (resolvedZone != null && String(quest?.requiredSpecies || '') === speciesKey) {
        return resolvedZone;
    }

    return findHighestUnlockedZoneForSpecies(game, speciesKey);
}

/** Localized species labels + target zones for quest navigation links. */
export function collectQuestSpeciesLinkTargets(
    game: GameRuntime | null | undefined,
    quest: Quest | {
        id?: string | number;
        questType?: string | null;
        requiredSpecies?: string;
        specialParams?: Quest['specialParams'];
    } | null | undefined,
): QuestNavigationLinkTarget[] {
    if (!quest) return [];

    const speciesSet = new Set<string>();
    if (quest.requiredSpecies) speciesSet.add(String(quest.requiredSpecies));

    const caps = resolveQuestCaptureRequirements(quest);
    if (Array.isArray(caps)) {
        for (const req of caps) {
            const s = (req as { requiredSpecies?: string }).requiredSpecies;
            if (s) speciesSet.add(String(s));
        }
    }

    const entries: QuestNavigationLinkTarget[] = [];
    for (const species of speciesSet) {
        const label = uiPokemonName(game, species) || species;
        if (!label) continue;
        entries.push({
            label,
            zoneId: resolveQuestSpeciesTargetZone(game, quest, species),
        });
    }
    return entries;
}

export function collectQuestNavigationLinkTargets(
    game: GameRuntime | null | undefined,
    quest: Quest | {
        id?: string | number;
        questType?: string | null;
        requiredSpecies?: string;
        specialParams?: Quest['specialParams'];
    } | null | undefined,
): QuestNavigationLinkTarget[] {
    const byLabel = new Map<string, QuestNavigationLinkTarget>();

    for (const target of collectQuestZoneLinkTargets(game, quest)) {
        byLabel.set(target.label, { zoneId: target.zoneId, label: target.label });
    }
    for (const target of collectQuestSpeciesLinkTargets(game, quest)) {
        const existing = byLabel.get(target.label);
        if (!existing) {
            byLabel.set(target.label, target);
            continue;
        }
        if (target.zoneId != null && existing.zoneId == null) {
            byLabel.set(target.label, target);
        }
    }

    return [...byLabel.values()];
}

function buildQuestDisplayVars(game: GameRuntime, quest: Quest): Record<string, unknown> {
    const rt = quest && quest.specialParams ? (quest.specialParams.requiredType || '') : '';
    const typePretty = rt
        ? (String(rt).charAt(0).toUpperCase() + String(rt).slice(1).toLowerCase())
        : '';
    const speciesRaw = quest?.requiredSpecies ? String(quest.requiredSpecies) : '';
    const minIvPercent = quest?.specialParams ? Number(quest.specialParams.minIvPercent) : NaN;
    return {
        target: quest && quest.target != null
            ? (typeof quest.target === 'number'
                ? (questUsesFormattedTarget(quest) ? resolveFormatNumber(quest.target) : String(quest.target))
                : quest.target)
            : '',
        type: typePretty,
        typeLabel: typePretty,
        species: speciesRaw ? uiPokemonName(game, speciesRaw) : '',
        minIvPercent: Number.isFinite(minIvPercent) && minIvPercent > 0 ? String(minIvPercent) : '',
        time: quest && quest.specialParams ? (quest.specialParams.timeLimit || '') : '',
        zone: quest && quest.specialParams ? (quest.specialParams.targetZone || '') : '',
        ...buildQuestZoneNameVars(game, quest),
    };
}

