export function getQuestMaxNationalDex(
    quest: { specialParams?: { maxNationalDex?: number }; target?: number } | null | undefined,
): number {
    const maxDex = Number(quest?.specialParams?.maxNationalDex) || Number(quest?.target) || 0;
    return Math.max(0, Math.floor(maxDex));
}

export function countOwnedUniqueSpeciesUpTo(
    game: GameRuntime,
    maxNationalDex: number | null | undefined,
): number {
    const cap = Math.max(0, Math.floor(Number(maxNationalDex) || 0));
    if (cap < 1) return getOwnedUniqueSpeciesNameSet(game).size;
    const allowed = new Set(getNationalDexSpeciesNamesUpTo(cap));
    if (allowed.size === 0) return 0;
    const owned = getOwnedUniqueSpeciesNameSet(game);
    let count = 0;
    for (const name of owned) {
        if (allowed.has(name)) count++;
    }
    return count;
}

export function getUniqueSpeciesOwnedCountForQuest(
    game: GameRuntime,
    quest: Quest | null | undefined,
): number {
    const maxDex = getQuestMaxNationalDex(quest);
    const target = Math.max(1, Math.floor(Number(quest?.target) || maxDex || 999));
    return Math.min(countOwnedUniqueSpeciesUpTo(game, maxDex), target);
}

/** Legacy/evolution entries: mark discovered when the player clearly obtained the variant. */
export function backfillPokedexDiscoveredFlags(game: GameRuntime): void {
    if (!game.pokedex || typeof game.pokedex !== 'object') return;
    for (const entry of Object.values(game.pokedex)) {
        if (!entry || typeof entry !== 'object') continue;
        const row = entry as Record<string, unknown>;
        if (row.discovered) continue;
        const hasCount = Number(row.count) > 0;
        if (row.seen || row.caught || row.firstDiscoveredAt || hasCount) {
            row.discovered = true;
        }
    }
}

/** Recompute active pokedexUniqueDiscovered quests from current dex state. */
export function resyncPokedexUniqueDiscoveredQuests(game: GameRuntime): void {
    const quests = game.quests as Quest[] | undefined;
    if (!Array.isArray(quests)) return;
    for (const quest of quests) {
        if (!quest || quest.trackingKey !== 'pokedexUniqueDiscovered') continue;
        if (!quest.accepted || quest.claimed) continue;
        const dexCount = getPokedexUniqueDiscoveredCountForQuest(game, quest);
        const next = Math.min(dexCount, quest.target || 999);
        quest.current = next;
        quest.updateProgress(next);
    }
}

/** Esp?ces manquantes ? l'instant T dans la plage Dex 1..maxNationalDex (pour l'aper?u qu?te). */
export function buildPokedexMissingSpeciesSnapshot(game: GameRuntime, maxNationalDex: number | null | undefined): string[] {
    const owned = getOwnedUniqueSpeciesNameSet(game);
    return getNationalDexSpeciesNamesUpTo(maxNationalDex).filter(function (name) {
        return !owned.has(name);
    });
}

/**
 * Sauvegardes anciennes : compl?te previewMissingSpeciesList une fois si absent.
 */
export function ensurePokedexMissingPreviewSnapshot(game: GameRuntime, quest: Quest | null | undefined): void {
    if (!quest || quest.trackingKey !== 'uniqueSpeciesOwned' || !quest.accepted) return;
    if (quest.specialParams && Object.prototype.hasOwnProperty.call(quest.specialParams, 'previewMissingSpeciesList')) return;
    const defKey = Object.keys(STORY_QUESTS).find(function (k) {
        const d = STORY_QUESTS_MAP[k];
        return d && d.id === quest.id && d.specialParams && d.specialParams.pokedexMissingPreview;
    });
    if (!defKey) return;
    const def = recordGet(STORY_QUESTS_MAP, defKey);
    if (!def) return;
    const maxDex = Number(def.specialParams?.maxNationalDex) || 0;
    if (maxDex < 1) return;
    if (!quest.specialParams || typeof quest.specialParams !== 'object') quest.specialParams = {};
    quest.specialParams.pokedexMissingPreview = true;
    quest.specialParams.maxNationalDex = maxDex;
    quest.specialParams.previewMissingSpeciesList = buildPokedexMissingSpeciesSnapshot(game, maxDex);
}

export function questUiText(game: GameRuntime, key: string, fallback: string, vars?: Record<string, unknown>): string {
    const lang = questLang(game);
    let text = fallback;
    const enText = recordGet(QUEST_UI_I18N_EN as Record<string, string>, key);
    if (lang === 'en' && enText) text = enText;
    return questFormat(text, vars);
}

export function getQuestBadgeRewardMultiplier(game: GameRuntime): number {
    if (!game) return 1;
    const statsBadges = Math.floor(Number(game.stats && game.stats.badgesEarned) || 0);
    const badgesMap = (game.badges && typeof game.badges === 'object') ? game.badges : {};
    const ownedBadges = Object.values(badgesMap).filter(Boolean).length;
    return Math.max(1, statsBadges, ownedBadges);
}

export function getScaledQuestTokenReward(game: GameRuntime, rewards: QuestRewards | null | undefined): number {
    if (!rewards || typeof rewards !== 'object') return 0;
    const rawTokens = (rewards.tokens != null) ? rewards.tokens : rewards.questTokens;
    const baseTokens = Math.max(0, Math.floor(Number(rawTokens) || 0));
    if (baseTokens <= 0) return 0;
    const badgeScaled = baseTokens * getQuestBadgeRewardMultiplier(game);
    if (typeof game.scaleMasteryQuestTokenAmount === 'function') {
        return game.scaleMasteryQuestTokenAmount(badgeScaled);
    }
    return badgeScaled;
}

export function getQuestContentByLang(lang: string): Record<string, Record<string, unknown>> {
    return (lang === 'en') ? QUEST_CONTENT_I18N_EN : QUEST_CONTENT_I18N_FR;
}

export function getQuestLocalizedItemName(game: GameRuntime, itemKey: string, itemDef: Record<string, unknown> | null | undefined): string {
    const fallbackName: string = (itemDef && itemDef.name) ? coerceStr(itemDef.name, itemKey) : coerceStr(itemKey, '');
    if (game && typeof game.getLocalizedItemName === 'function') {
        return game.getLocalizedItemName(itemKey, fallbackName, itemDef ?? null);
    }
    if (typeof window !== 'undefined' && typeof (window as unknown as Record<string, unknown>).getLocalizedItemNameUI === 'function') {
        const localized = (window as unknown as Record<string, unknown>).getLocalizedItemNameUI as (game: GameRuntime, itemKey: string, itemDef: Record<string, unknown>, fallbackName: string) => string;
        const result = localized(game, itemKey, itemDef || {}, fallbackName);
        if (typeof result === 'string' && result.trim()) return result;
    }
    return fallbackName;
}

export function getQuestLocalizationEntry(game: GameRuntime, quest: Quest | null | undefined): Record<string, unknown> | null {
    if (!quest) return null;
    const lang = questLang(game);
    const content = getQuestContentByLang(lang);
    if (!content) return null;
    let marker = (typeof quest.i18nKey === 'string') ? quest.i18nKey : '';
    if (!marker) {
        if (quest.questType === 'STORY' && quest.id) marker = `story:${quest.id}`;
        else if (quest.questType === 'TEAM_ROCKET' && quest.id) marker = `rocket:${quest.id}`;
        else if (quest.title) {
            const QTmpl = questTemplates();
            const templateTypes = Object.keys(QTmpl);
            for (let i = 0; i < templateTypes.length; i++) {
                const type = templateTypes[i];
                if (type === undefined) continue;
                const list = Array.isArray(QTmpl[type]) ? QTmpl[type] : [];
                const idx = list.findIndex((t: Record<string, unknown>) => t && t.title === quest.title);
                if (idx >= 0) {
                    marker = `template:${type}:${idx}`;
                    break;
                }
            }
        }
    }
    if (!marker) return null;

    if (marker.startsWith('template:')) {
        const parts = marker.split(':');
        const type = parts[1] || '';
        const idx = Number(parts[2] || -1);
        const templatesByType = content.templates;
        const list = templatesByType && type ? templatesByType[type] : undefined;
        const entry = arrayAt(Array.isArray(list) ? list : [], idx);
        return entry ? (entry as Record<string, unknown>) : null;
    }
    if (marker.startsWith('story:')) {
        const id = marker.slice('story:'.length);
        return (content.story as Record<string, Record<string, unknown>>)[id] || null;
    }
    if (marker.startsWith('rocket:')) {
        const id = marker.slice('rocket:'.length);
        return (content.rocket as Record<string, Record<string, unknown>>)[id] || null;
    }

    return null;
}

export function getQuestDisplayTitle(game: GameRuntime, quest: Quest): string {
    const localized = getQuestLocalizationEntry(game, quest);
    const baseTitle: string = (localized && localized.title) ? coerceStr(localized.title, '') : (quest && quest.title ? quest.title : '');
    const rt = quest && quest.specialParams ? (quest.specialParams.requiredType || '') : '';
    const typePretty = rt
        ? (String(rt).charAt(0).toUpperCase() + String(rt).slice(1).toLowerCase())
        : '';
    const vars: Record<string, string> = {
        type: typePretty,
        typeLabel: typePretty
    };
    return questFormat(baseTitle, vars);
}

export function getQuestDisplayDescription(game: GameRuntime, quest: Quest): string {
    const localized = getQuestLocalizationEntry(game, quest);
    const base: string = (localized && localized.description)
        ? coerceStr(localized.description, '')
        : (localized && localized.dialogue)
            ? coerceStr(localized.dialogue, '')
            : (quest && quest.description ? quest.description : '');
    const formatted = questFormat(base, buildQuestDisplayVars(game, quest));
    const normalized = normalizeCaptureQuestDescription(formatted, quest, questLang(game));
    return appendMinIvClauseToDescription(game, quest, normalized);
}

export function getQuestDisplayDialogue(game: GameRuntime, quest: Quest): string {
    const localized = getQuestLocalizationEntry(game, quest);
    const vars = buildQuestDisplayVars(game, quest);
    if (localized && localized.dialogue) {
        return questFormat(coerceStr(localized.dialogue, ''), vars);
    }
    const isStoryOrRocket = quest && (quest.questType === 'STORY' || quest.questType === 'TEAM_ROCKET');
    if (localized && isStoryOrRocket) {
        if (questLang(game) === 'en' && quest && quest.dialogue) {
            return questFormat(quest.dialogue, vars);
        }
        return '';
    }
    const base: string = (quest && quest.dialogue) ? quest.dialogue : '';
    return questFormat(base, vars);
}

export const QUEST_ACTION_SAFE_ID_RE = /^[A-Za-z0-9_.:-]{1,120}$/;

export function escapeQuestHtml(value: unknown): string {
    return escapeHtmlImpl(coerceStr(value, ''));
    return coerceStr(value, '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

function isQuestZoneUnlocked(game: GameRuntime | null | undefined, zoneId: number): boolean {
    if (!game || typeof game.isZoneUnlocked !== 'function') return false;
    return !!game.isZoneUnlocked(zoneId, true);
}

function isQuestZoneLinkClickable(game: GameRuntime | null | undefined, zoneId: number): boolean {
    if (!isQuestZoneUnlocked(game, zoneId)) return false;
    if (game?.towerState?.isActive) return false;
    return true;
}

/** Inject bold clickable zone/species links into escaped quest text. Returns plain text when no targets apply. */
export function formatQuestTextWithNavigationLinks(
    game: GameRuntime | null | undefined,
    plainText: string,
    quest: Quest | {
        id?: string | number;
        questType?: string | null;
        requiredSpecies?: string;
        specialParams?: Quest['specialParams'];
    } | null | undefined,
): string {
    const text = coerceStr(plainText, '');
    if (!text) return text;

    const targets = collectQuestNavigationLinkTargets(game, quest);
    if (targets.length === 0) return text;

    let html = escapeQuestHtml(text);
    const sorted = targets
        .filter((t) => t.label)
        .sort((a, b) => b.label.length - a.label.length);

    for (const { zoneId, label } of sorted) {
        const escapedLabel = escapeQuestHtml(label);
        if (!escapedLabel || !html.includes(escapedLabel)) continue;
        const clickable = zoneId != null && isQuestZoneLinkClickable(game, zoneId);
        const replacement = clickable
            ? `<span class="quest-zone-link" role="button" tabindex="0" data-action="goToQuestZone" data-arg="${zoneId}"><strong>${escapedLabel}</strong></span>`
            : `<strong class="quest-zone-name">${escapedLabel}</strong>`;
        html = html.split(escapedLabel).join(replacement);
    }

    return html;
}

/** @deprecated Use formatQuestTextWithNavigationLinks */
export function formatQuestTextWithZoneLinks(
    game: GameRuntime | null | undefined,
    plainText: string,
    quest: Quest | {
        id?: string | number;
        questType?: string | null;
        requiredSpecies?: string;
        specialParams?: Quest['specialParams'];
    } | null | undefined,
): string {
    return formatQuestTextWithNavigationLinks(game, plainText, quest);
}

/** Navigation link HTML is only built when the quest panel is visible (expensive zone scans). */
