export function getQuestCounts(game: GameRuntime): { story: number; rocket: number; classic: number } {
    const counts = { story: 0, rocket: 0, classic: 0 };
    if (!game || !Array.isArray(game.quests)) return counts;
    for (const q of game.quests) {
        if (q.questType === 'STORY') counts.story++;
        else if (q.questType === 'TEAM_ROCKET') counts.rocket++;
        else counts.classic++;
    }
    return counts;
}

// Quêtes STORY_QUEST_PARALLEL_GATE_IDS : porte ouverte tant qu'elles sont actives (voir storyQuests.ts).
// move_drag ne compte pas comme satisfaite tant qu'elle n'est pas terminee : sinon la quete d'apres (classic) partirait trop tot.
const STORY_QUEST_PARALLEL_GATE_ID_SET = new Set<string>(STORY_QUEST_PARALLEL_GATE_IDS);

export function isStoryQuestGateSatisfied(game: GameRuntime, storyDef: Record<string, unknown> | null | undefined): boolean {
    if (!storyDef || !storyDef.id) return true;
    const questId = String(storyDef.id);
    if (Array.isArray(game.completedStoryQuests) && game.completedStoryQuests.some((id) => String(id) === questId)) {
        return true;
    }
    if (STORY_QUEST_PARALLEL_GATE_ID_SET.has(questId)) {
        return Array.isArray(game.quests) && game.quests.some(q => String(q.id) === questId);
    }
    return false;
}

export function isStoryQuestDeferred(game: GameRuntime, storyDef: Record<string, unknown> | null | undefined): boolean {
    if (!storyDef || storyDef.id !== 'story_move_drag') return false;
    const done = Array.isArray(game.completedStoryQuests) && game.completedStoryQuests.includes('story_learn_move');
    const active = Array.isArray(game.quests) && game.quests.some(q => String(q.id) === 'story_learn_move');
    return !done && !active;
}

/**
 * Ajoute la prochaine qu?te sc?nario en ordre (tutoriel lin?aire).
 * Appel? au chargement, au changement de zone, et quand une qu?te sc?nario est termin?e.
 */
function syncMasteryIntroCombo(game: GameRuntime, quest: Quest): boolean {
    const flags: string[] = [];
    const m = typeof game.ensureMasterySpecializationState === 'function'
        ? game.ensureMasterySpecializationState()
        : null;
    const branchOrder = m && Array.isArray((m as { branchOrder?: unknown }).branchOrder)
        ? (m as { branchOrder: string[] }).branchOrder
        : [];
    if (branchOrder.length >= 1) flags.push('mastery_specialization_chosen');
    const spent = typeof game.getMasteryPoints === 'function'
        ? (game.getMasteryPoints().spent ?? 0)
        : 0;
    if (spent > 0) flags.push('mastery_point_spent');

    if (!quest.specialParams || typeof quest.specialParams !== 'object') {
        quest.specialParams = {};
    }
    quest.specialParams.requires = ['mastery_specialization_chosen', 'mastery_point_spent'];
    quest.specialParams.doneFlags = flags;
    quest.target = 2;
    quest.current = flags.length;
    return quest.updateProgress(flags.length);
}

function isStoryQuestPrevGateSatisfied(
    game: GameRuntime,
    key: string,
    orderIndex: number,
    order: readonly string[],
): boolean {
    if (isUnovaPostLeagueStoryOrderKey(key) && !hasUnovaEliteFourCompleted(game)) {
        return false;
    }
    if (isKalosPostLeagueStoryOrderKey(key) && !hasKalosEliteFourCompleted(game)) {
        return false;
    }
    if (isAlolaPostLeagueStoryOrderKey(key) && !hasAlolaEliteFourCompleted(game)) {
        return false;
    }
    if (isGalarPostLeagueStoryOrderKey(key) && !hasGalarEliteFourCompleted(game)) {
        return false;
    }
    if (isPaldeaPostLeagueStoryOrderKey(key) && !hasPaldeaEliteFourCompleted(game)) {
        return false;
    }
    if (isArenaStoryOrderKey(key) && key !== 'arena_first') {
        const prevArenaKey = getPreviousArenaStoryOrderKey(key);
        const prevArenaDef = prevArenaKey ? recordGet(STORY_QUESTS_MAP, prevArenaKey) : null;
        if (prevArenaDef && isStoryQuestDeferred(game, prevArenaDef)) return true;
        if (prevArenaDef && !isStoryQuestGateSatisfied(game, prevArenaDef)) return false;
        const isLeagueStoryKey = key === 'elite_four' || key.endsWith('_elite_four');
        if (prevArenaKey && isLeagueStoryKey) {
            for (const betweenKey of getLinearStoryOrderKeysBetween(prevArenaKey, key)) {
                const betweenDef = recordGet(STORY_QUESTS_MAP, betweenKey);
                if (!betweenDef || isStoryQuestDeferred(game, betweenDef)) continue;
                if (!isStoryQuestGateSatisfied(game, betweenDef)) return false;
            }
        }
        return true;
    }
    const def = recordGet(STORY_QUESTS_MAP, key);
    if (def && !isStoryQuestOptionalLegendary(def)) {
        for (let i = orderIndex - 1; i >= 0; i--) {
            const prevKey = order[i];
            if (prevKey === undefined) break;
            const prevDef = recordGet(STORY_QUESTS_MAP, prevKey);
            if (!prevDef) continue;
            if (isStoryQuestOptionalLegendary(prevDef)) continue;
            return isStoryQuestDeferred(game, prevDef)
                || isStoryQuestGateSatisfied(game, prevDef);
        }
        return orderIndex === 0;
    }
    const prevKey = orderIndex > 0 ? order[orderIndex - 1] : undefined;
    const prevDef = prevKey !== undefined ? recordGet(STORY_QUESTS_MAP, prevKey) : null;
    return orderIndex === 0
        || !prevDef
        || isStoryQuestDeferred(game, prevDef)
        || isStoryQuestGateSatisfied(game, prevDef);
}

