/** Start the next quest in the Kalos post-League berry + fétiche tutorial arc. */
export function tryStartKalosBerryFeticheArcQuest(game: GameRuntime): boolean {
    if (!game) return false;
    if (!hasKalosEliteFourCompleted(game)) return false;
    if (typeof game.hasBadge === 'function' && !game.hasBadge('maitre_kalos')) return false;

    const completed = Array.isArray(game.completedStoryQuests) ? game.completedStoryQuests : [];
    const active = Array.isArray(game.quests) ? game.quests as Quest[] : [];
    if (active.some((q) => KALOS_BERRY_FETICHE_STORY_QUEST_ID_SET.has(String(q.id)))) return false;

    for (let i = 0; i < STORY_QUEST_KALOS_BERRY_FETICHE_ORDER_KEYS.length; i++) {
        const key = STORY_QUEST_KALOS_BERRY_FETICHE_ORDER_KEYS[i];
        const def = recordGet(STORY_QUESTS_MAP, key);
        if (!def?.id) continue;
        if (completed.includes(String(def.id))) continue;

        if (i > 0) {
            const prevKey = STORY_QUEST_KALOS_BERRY_FETICHE_ORDER_KEYS[i - 1];
            const prevDef = recordGet(STORY_QUESTS_MAP, prevKey);
            if (prevDef?.id && !completed.includes(String(prevDef.id))) return false;
        }

        addStoryQuestLogic(game, def);
        return true;
    }
    return false;
}

