function clearRivalDefeatFlagsForStoryDef(
    game: GameRuntime,
    storyDef: Record<string, unknown>,
): void {
    if (storyDef.trackingKey !== 'rival_zone_defeated') return;
    const questId = String(storyDef.id || '');
    if (questId && Array.isArray(game.completedStoryQuests)
        && game.completedStoryQuests.some((id) => String(id) === questId)) {
        return;
    }
    const sp = storyDef.specialParams as Record<string, unknown> | undefined;
    const rivalKey = sp && sp.rivalKey != null ? String(sp.rivalKey) : '';
    const requiredZone = sp && sp.requiredZone != null ? Number(sp.requiredZone) : NaN;
    const defeated = game.rivalState?.zonesDefeated;
    if (!defeated) return;
    let changed = false;
    if (rivalKey && defeated[rivalKey]) {
        delete defeated[rivalKey];
        changed = true;
    }
    if (Number.isFinite(requiredZone) && requiredZone > 0 && defeated[String(requiredZone)]) {
        delete defeated[String(requiredZone)];
        changed = true;
    }
    if (changed && typeof game.persistRivalZonesDefeated === 'function') {
        game.persistRivalZonesDefeated();
    }
}

function clearRivalDefeatFlagsForActiveQuest(
    game: GameRuntime,
    quest: Quest,
): boolean {
    if (quest.questType !== 'STORY' || quest.trackingKey !== 'rival_zone_defeated') return false;
    const questId = String(quest.id || '');
    if (questId && Array.isArray(game.completedStoryQuests)
        && game.completedStoryQuests.some((id) => String(id) === questId)) {
        return false;
    }
    const rivalKey = quest.specialParams ? coerceStr(quest.specialParams.rivalKey, '') : '';
    const requiredZone = resolveQuestRequiredZone(quest);
    const defeated = game.rivalState?.zonesDefeated;
    if (!defeated) return false;
    let changed = false;
    if (rivalKey && defeated[rivalKey]) {
        delete defeated[rivalKey];
        changed = true;
    }
    if (requiredZone != null && defeated[String(requiredZone)]) {
        delete defeated[String(requiredZone)];
        changed = true;
    }
    return changed;
}

/** Clear stale rival defeat flags for active faction story quests (journal already open, 0/1). */
export function reconcileActiveRivalZoneStoryQuests(game: GameRuntime): void {
    if (!game || !Array.isArray(game.quests)) return;
    let changed = false;
    for (const quest of game.quests as unknown[] as Quest[]) {
        if (quest.questType === 'STORY'
            && quest.trackingKey === 'rival_zone_defeated'
            && !quest.claimed
            && !quest.accepted) {
            acceptQuestLogic(game, quest.id);
        }
        if (!quest.accepted || quest.completed || quest.claimed) continue;
        if (clearRivalDefeatFlagsForActiveQuest(game, quest)) changed = true;
    }
    if (changed && typeof game.persistRivalZonesDefeated === 'function') {
        game.persistRivalZonesDefeated();
    }
}

function tryAddNextStoryQuest(game: GameRuntime, mode: 'arena' | 'linear'): boolean {
    const order = STORY_QUEST_ORDER;
    for (let i = 0; i < order.length; i++) {
        const key = order[i];
        if (key === undefined) continue;
        if (mode === 'arena' && !isArenaStoryOrderKey(key)) continue;
        if (mode === 'linear' && isArenaStoryOrderKey(key)) continue;
        const def = recordGet(STORY_QUESTS_MAP, key);
        if (!def) continue;
        if (isStoryQuestDeferred(game, def)) continue;
        const questId = String(def.id || '');
        const alreadyInList = game.quests.some((q) => String(q.id) === questId);
        if (alreadyInList) continue;
        const completed = Array.isArray(game.completedStoryQuests)
            && game.completedStoryQuests.some((id) => String(id) === questId);
        if (completed) continue;
        const prevCompleted = isStoryQuestPrevGateSatisfied(game, key, i, order);
        if (i > 0 && !prevCompleted) {
            if (mode === 'linear') continue;
            break;
        }
        if (isUnovaPostLeagueStoryOrderKey(key) && !hasUnovaEliteFourCompleted(game)) {
            if (mode === 'linear') continue;
            break;
        }
        if (isKalosPostLeagueStoryOrderKey(key) && !hasKalosEliteFourCompleted(game)) {
            if (mode === 'linear') continue;
            break;
        }
        if (isAlolaPostLeagueStoryOrderKey(key) && !hasAlolaEliteFourCompleted(game)) {
            if (mode === 'linear') continue;
            break;
        }
        if (isGalarPostLeagueStoryOrderKey(key) && !hasGalarEliteFourCompleted(game)) {
            if (mode === 'linear') continue;
            break;
        }
        if (isPaldeaPostLeagueStoryOrderKey(key) && !hasPaldeaEliteFourCompleted(game)) {
            if (mode === 'linear') continue;
            break;
        }
        addStoryQuestLogic(game, def);
        return true;
    }
    return false;
}

let batchStoryQuestDisplay = false;
let storyQuestDisplayPending = false;

export function ensureStoryQuestProgress(game: GameRuntime): void {
    batchStoryQuestDisplay = true;
    storyQuestDisplayPending = false;
    try {
        if (tryStartPokemonTowerMarowakQuest(game)) {
            refreshRivalZoneMiniHud(game);
            return;
        }
        tryStartMasteryIntroQuest(game);
        tryStartHoennSafariZoneQuest(game);
        tryStartSinnohGreatMarshQuest(game);
        tryStartPaldeaAsadoDesertCensusQuest(game);
        tryStartSinnohBattleZoneCensusQuest(game);
        tryStartUnovaDarumakaRoute4Quest(game);
        tryStartUnovaCubchooRoute7Quest(game);
        tryStartUnovaPawniardRoute9Quest(game);
        tryStartUnovaDesertResortCensusQuest(game);
        tryStartKalosRioluRoute22Quest(game);
        tryStartKalosGoomyRoute14Quest(game);
        tryStartKalosPawniardRoute15Quest(game);
        tryStartKalosParfumTrailCensusQuest(game);
        tryStartGalarWildAreaCensusQuest(game);
        tryStartGalarGlimwoodCensusQuest(game);
        tryStartKalosFlareMaisonRematchQuest(game);
        tryStartKalosBerryFeticheArcQuest(game);
        tryStartAlolaRockruffCaptureQuest(game);

        pruneUnovaPostLeagueQuests(game);
        pruneKalosPostLeagueQuests(game);
        pruneKalosBerryFeticheQuests(game);
        pruneAlolaPostLeagueQuests(game);
        pruneGalarPostLeagueQuests(game);
        prunePaldeaPostLeagueQuests(game);
        reconcileActiveRivalZoneStoryQuests(game);
        refreshRivalZoneMiniHud(game);

        const maxPasses = 12;
        for (let pass = 0; pass < maxPasses; pass++) {
            let added = false;
            if (tryAddNextStoryQuest(game, 'arena')) added = true;
            else if (tryAddNextStoryQuest(game, 'linear')) added = true;
            if (!added) {
                refreshRivalZoneMiniHud(game);
                return;
            }
        }
        refreshRivalZoneMiniHud(game);
    } finally {
        batchStoryQuestDisplay = false;
        if (storyQuestDisplayPending) {
            storyQuestDisplayPending = false;
            updateQuestsDisplayLogic(game);
        }
    }
}

