/**
 * Qu?tes Rocket r?gionales : d?bloqu?es par badge ma?tre ou ?quivalent.
 * Si absent, la mission est toujours ?ligible (missions Rocket de base).
 */
export function isTeamRocketQuestUnlocked(game: GameRuntime, rocketDef: Record<string, unknown> | null | undefined): boolean {
    if (!game || !rocketDef) return false;
    if (rocketDef.requiredBadge) {
        return typeof game.hasBadge === 'function' && game.hasBadge(rocketDef.requiredBadge as string);
    }
    if (Array.isArray(rocketDef.requiredBadges) && rocketDef.requiredBadges.length) {
        return rocketDef.requiredBadges.every((b: unknown) =>
            typeof b === 'string' && typeof game.hasBadge === 'function' && game.hasBadge(b)
        );
    }
    return true;
}

export function ensureTeamRocketQuestProgress(game: GameRuntime): void {
    if (!game.unlockedFeatures || !game.unlockedFeatures.teamRocketTab) return;
    if (typeof TEAM_ROCKET_QUESTS === 'undefined') return;

    // Maximum 1 qu?te Team Rocket active ? la fois
    const hasActiveRocket = game.quests.some(q =>
        q.questType === 'TEAM_ROCKET' &&
        !q.completed &&
        !q.claimed
    );
    if (hasActiveRocket) return;

    // Phase 1 : qu?tes Rocket en mode "story line" dans un ordre fixe.
    if (typeof TEAM_ROCKET_QUEST_ORDER !== 'undefined' && Array.isArray(TEAM_ROCKET_QUEST_ORDER)) {
        for (let i = 0; i < TEAM_ROCKET_QUEST_ORDER.length; i++) {
            const key = TEAM_ROCKET_QUEST_ORDER[i];
            if (key === undefined) continue;
            const def = recordGet(TEAM_ROCKET_QUESTS_MAP, key);
            if (!def) continue;
            const alreadyInList = game.quests.some(q => q.id === def.id);
            if (alreadyInList) continue;
            const completed = game.completedTeamRocketQuests && game.completedTeamRocketQuests.includes(def.id);
            if (completed) continue;
            if (!isTeamRocketQuestUnlocked(game, def)) continue;

            // Storyline Rocket : on ajoute la premi?re qu?te non termin?e et d?j? d?bloqu?e.
            addTeamRocketQuestLogic(game, def);
            return;
        }
    }

    const allKeys = Object.keys(TEAM_ROCKET_QUESTS);
    const available = allKeys.filter(key => {
        const def = TEAM_ROCKET_QUESTS_MAP[key];
        if (!def) return false;
        if (!isTeamRocketQuestUnlocked(game, def)) return false;
        if (game.quests.some(q => q.id === def.id)) return false;
        if (game.completedTeamRocketQuests && game.completedTeamRocketQuests.includes(def.id)) return false;
        return true;
    });
    if (available.length === 0) return;

    const key = arrayAt(available, Math.floor(Math.random() * available.length));
    const rocketDef = key !== undefined ? recordGet(TEAM_ROCKET_QUESTS_MAP, key) : undefined;
    if (rocketDef) addTeamRocketQuestLogic(game, rocketDef);
}

export function templateAllowedForClassicQuest(game: GameRuntime, t: QuestTemplate): boolean {
    if (t.trackingKey === 'recyclerUsed') {
        return game.unlockedFeatures && game.unlockedFeatures.recyclerSubTab;
    }
    if (t.trackingKey === 'towerFloor') {
        return game.unlockedFeatures && game.unlockedFeatures.towerTab;
    }
    if (t.trackingKey === 'prestigeCount') {
        const prestigeCount = (game.stats && typeof game.stats.prestigeCount === 'number') ? game.stats.prestigeCount : 0;
        return prestigeCount >= 1;
    }
    if (t.special === 'wild_species_iv_capture') {
        return isClassicWildSpeciesIvCaptureEligible(game);
    }
    return true;
}

/**
 * Liste tous les templates eligibles dont le rang est <= maxTemplateRank (pool unifie entre les types).
 */
export function isClassicTypeHuntTemplate(template: QuestTemplate): boolean {
    return !!(
        template
        && template.trackingKey === 'typedSpeciesCaptured'
        && template.specialParams
        && typeof template.specialParams === 'object'
        && template.specialParams.requiredType
    );
}

export function collectClassicQuestCandidates(game: GameRuntime, allowedQuestTypes: string[], maxTemplateRank: number): Array<{ typeKey: string; template: QuestTemplate; templateIndex: number; groupedTemplateChoices?: Array<{ typeKey: string; template: QuestTemplate; templateIndex: number }> }> {
    const templates = questTemplates();
    const difficultyRank: Record<string, number> = { EASY: 1, MEDIUM: 2, HARD: 3, EXTREME: 4 };
    const rankOf = (d: unknown) => difficultyRank[coerceStr(d, 'EASY')] || 1;
    const out: Array<{ typeKey: string; template: QuestTemplate; templateIndex: number; groupedTemplateChoices?: Array<{ typeKey: string; template: QuestTemplate; templateIndex: number }> }> = [];
    for (let a = 0; a < allowedQuestTypes.length; a++) {
        const typeKey = allowedQuestTypes[a];
        if (typeKey === undefined) continue;
        const list = templates[typeKey];
        if (!list || !list.length) continue;
        const typeHuntChoices = [];
        for (let ti = 0; ti < list.length; ti++) {
            const tpl = list[ti] as unknown as QuestTemplate;
            if (!templateAllowedForClassicQuest(game, tpl)) continue;
            if (rankOf(tpl.difficulty) <= maxTemplateRank) {
                if (isClassicTypeHuntTemplate(tpl)) {
                    const requiredType = tpl.specialParams?.requiredType;
                    if (requiredType && isClassicTypeHuntTypeEligible(String(requiredType))) {
                        typeHuntChoices.push({ typeKey, template: tpl, templateIndex: ti });
                    }
                } else {
                    out.push({ typeKey, template: tpl, templateIndex: ti });
                }
            }
        }
        const firstHunt = typeHuntChoices[0];
        if (firstHunt) {
            out.push({
                typeKey: firstHunt.typeKey,
                template: firstHunt.template,
                templateIndex: firstHunt.templateIndex,
                groupedTemplateChoices: typeHuntChoices
            });
        }
    }
    return out;
}

export function generateQuestLogic(game: GameRuntime): void {
    const countsBefore = getQuestCounts(game);
    if (countsBefore.classic >= 10) return;
    if (!game.unlockedFeatures || !game.unlockedFeatures.classicQuests) return;

    let difficulty = 'EASY';
    const totalCreatures = game.playerTeam.length + game.storage.length + game.pension.length;
    const prestigeCount = game.stats.prestigeCount || 0;
    const badgesCount = Object.values(game.badges).filter(b => b).length;

    if (prestigeCount >= 3 || badgesCount >= 5) {
        const roll = Math.random();
        if (roll < 0.3) difficulty = 'EXTREME';
        else if (roll < 0.6) difficulty = 'HARD';
        else difficulty = 'MEDIUM';
    } else if (totalCreatures > 50 || badgesCount >= 3) {
        const roll = Math.random();
        if (roll < 0.4) difficulty = 'HARD';
        else difficulty = 'MEDIUM';
    } else if (totalCreatures > 20) {
        const roll = Math.random();
        if (roll < 0.6) difficulty = 'MEDIUM';
        else difficulty = 'EASY';
    }

    const difficultyRank: Record<string, number> = { EASY: 1, MEDIUM: 2, HARD: 3, EXTREME: 4 };
    /** Boutique Jetons : 0?3 achete debloquent Medium / Hard / Extreme (rang max = 1 + valeur). */
    const shopTier = Math.max(0, Math.min(3, Math.floor(Number(game.permanentBoosts && game.permanentBoosts.dailyQuestDifficulty) || 0)));
    const shopMaxRank = 1 + shopTier;
    const rolledRank = difficultyRank[difficulty] || 1;
    const desiredRank = Math.min(rolledRank, shopMaxRank);

    const QT = questTypes();
    const QTmpl = questTemplates();
    const allQuestTypes = Object.values(QT);
    if (allQuestTypes.length === 0 || Object.keys(QTmpl).length === 0) return;
    const allowedQuestTypes = allQuestTypes.filter(typeKey => {
        // Les qu?tes d'exploration actuelles sont centr?es sur les exp?ditions.
        // On les bloque tant que l'onglet Exp?ditions n'est pas d?bloqu?
        // pour éviter de g?n?rer des objectifs impossibles.
        if (typeKey === QT.EXPLORATION) {
            return game.unlockedFeatures && game.unlockedFeatures.expeditionsTab;
        }
        // Qu?tes de prestige uniquement quand le joueur a d?j? commenc? ? prestiger.
        if (typeKey === QT.PRESTIGE) {
            const pc = (game.stats && typeof game.stats.prestigeCount === 'number') ? game.stats.prestigeCount : 0;
            return pc >= 1;
        }
        return true;
    });

    if (allowedQuestTypes.length === 0) return;

    let candidates = collectClassicQuestCandidates(game, allowedQuestTypes, desiredRank);
    for (let fallbackRank = desiredRank - 1; fallbackRank >= 1 && candidates.length === 0; fallbackRank--) {
        candidates = collectClassicQuestCandidates(game, allowedQuestTypes, fallbackRank);
    }
    if (candidates.length === 0) return;

    let chosen: (typeof candidates)[number] | undefined;
    let randomType = '';
    let randomTemplate: QuestTemplate | undefined;
    let templateIndex = 0;
    let quest: Quest | null = null;
    const remaining = candidates.slice();
    let generationAttempts = 0;

    while (!quest && remaining.length > 0 && generationAttempts < 3) {
        generationAttempts++;

        const pickIdx = Math.floor(Math.random() * remaining.length);
        chosen = arrayAt(remaining, pickIdx);
        if (!chosen) break;
        if (Array.isArray(chosen.groupedTemplateChoices) && chosen.groupedTemplateChoices.length > 0) {
            chosen = arrayAt(chosen.groupedTemplateChoices, Math.floor(Math.random() * chosen.groupedTemplateChoices.length)) ?? chosen;
        }

        randomType = chosen.typeKey;
        randomTemplate = chosen.template;
        templateIndex = chosen.templateIndex;
        const templateDifficulty = randomTemplate.difficulty || 'EASY';
        const repeatKey = `template:${randomType}:${templateIndex}`;
        if (!game.questRepeatCounts || typeof game.questRepeatCounts !== 'object') game.questRepeatCounts = {};
        const repeatCount = Math.max(0, Math.floor(Number(game.questRepeatCounts[repeatKey]) || 0));
        const candidateQuest = new Quest(randomTemplate, 1, templateDifficulty, {
            badgeCount: badgesCount,
            repeatCount,
            repeatKey
        });
        candidateQuest.questType = randomType;
        candidateQuest.i18nKey = repeatKey;

        if (randomTemplate.special === 'wild_species_iv_capture') {
            if (!applyWildSpeciesIvCaptureToClassicQuest(game, candidateQuest)) {
                if (pickIdx >= 0) remaining.splice(pickIdx, 1);
                continue;
            }
        }
        quest = candidateQuest;
    }

    if (!quest || !randomTemplate) return;

    const repeatKey = `template:${randomType}:${templateIndex}`;
    (game.quests as unknown[] as Quest[]).push(quest);
    if (typeof game.trackBalanceEvent === 'function') game.trackBalanceEvent('quest_generated', { questType: randomType, questId: quest.id });
    patchClassicQuestCountDom(game);
    scheduleQuestsDisplayRefresh(game);

    const diffInfo = questDifficulties()[quest.difficulty] || { name: quest.difficulty };
    const diffPrefix = coerceStr((diffInfo).icon, `[${quest.difficulty}]`);
    const displayTitle = getQuestDisplayTitle(game, quest);
    const difficultyLabel = (quest.difficulty === 'MEDIUM')
        ? questUiText(game, 'badgeMedium', coalesceStr((diffInfo).name, 'Moyen'))
        : (quest.difficulty === 'HARD')
            ? questUiText(game, 'badgeHard', coalesceStr((diffInfo).name, 'Difficile'))
            : (quest.difficulty === 'EXTREME')
                ? questUiText(game, 'badgeExtreme', coalesceStr((diffInfo).name, 'Extreme'))
                : questUiText(game, 'badgeEasy', coalesceStr((diffInfo).name, 'Facile'));
    const baseLog = questUiText(game, 'difficultyPrefix', 'Nouvelle quete {difficulty} : {title}', { difficulty: difficultyLabel, title: displayTitle });
    const repeatSuffix = (quest.repeatCount > 0)
        ? ` ${questUiText(game, 'repeatBonusLog', '(Repetition x{count} : +{percent}% butin)', { count: quest.repeatCount + 1, percent: quest.repeatCount })}`
        : '';
    logMessage(`${diffPrefix} ${baseLog}${repeatSuffix}`);
}

/** True while story_surf is accepted and not yet completed (CT Surf token shop gate). */
export function isStorySurfQuestActiveForShop(game: GameRuntime): boolean {
    if (!game?.quests) return false;
    return (game.quests as unknown[] as Quest[]).some(
        (q) => q.id === 'story_surf' && q.accepted && !q.completed,
    );
}

function isHoennVictoryRoadZoneCleared(game: GameRuntime): boolean {
    const zoneId = 262;
    if (typeof game.isZoneMastered === 'function' && game.isZoneMastered(zoneId)) return true;
    const zp = game.zoneProgress && game.zoneProgress[zoneId];
    if (!zp) return false;
    return Math.floor(Number(zp.bossesDefeated) || 0) >= 3;
}

function isSinnohVictoryRoadZoneCleared(game: GameRuntime): boolean {
    const zoneId = 344;
    if (typeof game.isZoneMastered === 'function' && game.isZoneMastered(zoneId)) return true;
    const zp = game.zoneProgress && game.zoneProgress[zoneId];
    if (!zp) return false;
    return Math.floor(Number(zp.bossesDefeated) || 0) >= 3;
}

/** Auto-complete Hoenn endgame story quests when the objective was already met before the offer. */
export function syncLateStoryQuestProgress(game: GameRuntime, questId: string): void {
    const quest = (game.quests as unknown[] as Quest[]).find((q) => String(q.id) === questId);
    if (!quest || !quest.accepted || quest.completed) return;

    switch (questId) {
        case 'story_hoenn_victory_road':
            quest.current = isHoennVictoryRoadZoneCleared(game) ? 1 : 0;
            break;
        case 'story_tower_gen3_386':
            quest.current = Math.min(
                typeof game.towerRecord === 'number' ? game.towerRecord : 0,
                quest.target || 386,
            );
            break;
        case 'story_pokedex_386': {
            quest.current = getUniqueSpeciesOwnedCountForQuest(game, quest);
            break;
        }
        case 'story_hoenn_tri_region_champion':
            quest.current = game.stats && game.stats.badgesEarned !== undefined
                ? game.stats.badgesEarned
                : Object.values(game.badges || {}).filter(Boolean).length;
            break;
        case 'story_sinnoh_victory_road':
            quest.current = isSinnohVictoryRoadZoneCleared(game) ? 1 : 0;
            break;
        case 'story_tower_gen4_493':
            quest.current = Math.min(
                typeof game.towerRecord === 'number' ? game.towerRecord : 0,
                quest.target || 493,
            );
            break;
        case 'story_pokedex_493': {
            quest.current = getUniqueSpeciesOwnedCountForQuest(game, quest);
            break;
        }
        case 'story_sinnoh_quad_region_champion':
            quest.current = game.stats && game.stats.badgesEarned !== undefined
                ? game.stats.badgesEarned
                : Object.values(game.badges || {}).filter(Boolean).length;
            break;
        case 'story_tower_gen6_721':
            quest.current = Math.min(
                typeof game.towerRecord === 'number' ? game.towerRecord : 0,
                quest.target || 721,
            );
            break;
        case 'story_pokedex_721': {
            quest.current = getUniqueSpeciesOwnedCountForQuest(game, quest);
            break;
        }
        case 'story_kalos_hexa_region_champion':
            quest.current = game.stats && game.stats.badgesEarned !== undefined
                ? game.stats.badgesEarned
                : Object.values(game.badges || {}).filter(Boolean).length;
            break;
        case 'story_tower_gen8_898':
            quest.current = Math.min(
                typeof game.towerRecord === 'number' ? game.towerRecord : 0,
                quest.target || 898,
            );
            break;
        case 'story_pokedex_898': {
            quest.current = getUniqueSpeciesOwnedCountForQuest(game, quest);
            break;
        }
        case 'story_galar_octa_region_champion':
            quest.current = game.stats && game.stats.badgesEarned !== undefined
                ? game.stats.badgesEarned
                : Object.values(game.badges || {}).filter(Boolean).length;
            break;
        case 'story_sinnoh_garchomp': {
            const minIv = Number(quest.specialParams?.minIvPercent) || getCaptureMinIvPercent('EXTREME');
            if (rosterHasQualifiedObtainSpecies(game, 'Garchomp', minIv)) {
                quest.current = Math.max(1, Number(quest.target) || 1);
            }
            break;
        }
        default:
            return;
    }

    if (quest.current >= quest.target) {
        quest.completed = true;
    }
}

export function addStoryQuestLogic(
    game: GameRuntime,
    storyDef: Record<string, unknown>,
    opts?: { skipDisplay?: boolean },
): boolean {
    const questId = String(storyDef.id || '');
    if (questId) {
        if (Array.isArray(game.completedStoryQuests)
            && game.completedStoryQuests.some((id) => String(id) === questId)) {
            return false;
        }
        if (Array.isArray(game.quests)
            && (game.quests as unknown[] as Quest[]).some((q) => String(q.id) === questId)) {
            return false;
        }
    }

    clearRivalDefeatFlagsForStoryDef(game, storyDef);

    const quest = new Quest({
        title: storyDef.title as string,
        desc: storyDef.description as string | undefined,
        target: storyDef.target as number,
        trackingKey: storyDef.trackingKey as string
    }, 1, storyDef.difficulty as string | undefined);

    quest.id = storyDef.id as string | number;
    quest.i18nKey = `story:${coerceStr(storyDef.id, '')}`;
    quest.rewards = (storyDef.rewards as QuestRewards) || {} as QuestRewards;
    quest.questType = 'STORY';
    if (storyDef.dialogue) quest.dialogue = storyDef.dialogue as string;
    if (storyDef.requiredSpecies) quest.requiredSpecies = storyDef.requiredSpecies as string;
    if (storyDef.specialParams && typeof storyDef.specialParams === 'object') {
        quest.specialParams = { ...storyDef.specialParams as Record<string, unknown> };
    }
    applyStorySimpleCaptureIvGate(quest, storyDef);
    ensureIvCaptureEggRewards(game, quest);

    if (storyDef.id === 'story_vitamin' && game.items) {
        game.items['pv_plus'] = (game.items['pv_plus'] || 0) + 1;
        logMessage(`${questUiText(game, 'giftVitaminLog', 'Le Professeur vous donne 1 PV Plus pour tester les vitamines !')}`);
        toast?.info?.(
            questUiText(game, 'giftVitaminTitle', 'Vitamine offerte'),
            questUiText(game, 'giftVitaminBody', "1 PV Plus ajoute au sac. Les vitamines tombent aussi en combat et a la Tour.")
        );
    }
    if (storyDef.id === 'story_kalos_miltank_farm') {
        unlockMiltankFarmLogic(game);
    }
    if (storyDef.id === 'story_kalos_berry_recipe' && game.items) {
        const recipe = getBerryTreeRecipe(KALOS_TUTORIAL_BERRY_KEY);
        if (recipe) {
            for (const itemKey of recipe.ingredients) {
                const owned = Number(game.items[itemKey]) || 0;
                if (owned < 1) game.items[itemKey] = 1;
            }
        }
        logMessage(questUiText(
            game,
            'giftBerryRecipeLog',
            'Le Professeur vous donne les objets pour tester la première recette de baie !',
        ));
        toast?.info?.(
            questUiText(game, 'giftBerryRecipeTitle', 'Ingrédients offerts'),
            questUiText(
                game,
                'giftBerryRecipeBody',
                'Ouvre la ferme Route 12, touche l\'arbre à baies et combine les objets dans Découverte.',
            ),
        );
    }
    if (storyDef.id === 'story_kalos_berry_harvest') {
        if (!game.miltankFarmState) {
            game.miltankFarmState = createDefaultMiltankFarmState(Date.now());
        }
        normalizeMiltankFarmState(game.miltankFarmState);
        if (!game.miltankFarmState.berryTree) {
            game.miltankFarmState.berryTree = createDefaultBerryTreeState();
        }
        const berryTree = normalizeBerryTreeState(game.miltankFarmState.berryTree);
        game.miltankFarmState.berryTree = berryTree;
        if (!berryTree.unlockedBerryKeys.includes(KALOS_TUTORIAL_BERRY_KEY)) {
            berryTree.unlockedBerryKeys.push(KALOS_TUTORIAL_BERRY_KEY);
        }
        const harvestRecipe = getBerryTreeRecipe(KALOS_TUTORIAL_BERRY_KEY);
        if (harvestRecipe) {
            berryTree.revealedSlotsByBerry[KALOS_TUTORIAL_BERRY_KEY] = [...harvestRecipe.ingredients];
        }
        publishMiltankFarmChanged();
        logMessage(questUiText(
            game,
            'giftBerryHarvestLog',
            'Plante une baie sur l\'onglet Arbre de l\'arbre à baies, puis récolte ta première récolte !',
            'Plant a berry on the Berry tree\'s Tree tab, then claim your first harvest!',
        ));
    }
    if (storyDef.id === 'story_kalos_fetiche_feed' && game.feticheState) {
        game.feticheState.satiety = 10;
    }
    if (storyDef.id === 'story_alola_poke_pelago') {
        unlockPokePelagoLogic(game);
    }
    if (storyDef.id === 'story_stat_boost' && game.items) {
        game.items['defense_plus'] = (game.items['defense_plus'] || 0) + 1;
        logMessage(`${questUiText(game, 'giftBoostLog', 'Le Professeur vous donne 1 Defense + pour tester les boosts temporaires !')}`);
        toast?.info?.(
            questUiText(game, 'giftBoostTitle', 'Boost offert'),
            questUiText(game, 'giftBoostBody', "1 Defense + ajoute au sac. Les boosts (Defense +, Attaque +, etc.) tombent en combat.")
        );
    }
    if (storyDef.id === 'story_equip_item' && game.items) {
        game.items['leftovers'] = (game.items['leftovers'] || 0) + 1;
        logMessage(`${questUiText(game, 'giftHeldLog', 'Le Professeur vous donne des Restes pour equiper un Pokemon !')}`);
        toast?.info?.(
            questUiText(game, 'giftHeldTitle', 'Objet tenu offert'),
            questUiText(game, 'giftHeldBody', '1 Restes ajoute au sac. Equipez-le sur un Pokemon (fiche -> Objet tenu).')
        );
    }
    if (storyDef.id === 'story_tower_climb') {
        game.combatTickets = (game.combatTickets || 0) + 1;
        logMessage(`${questUiText(game, 'giftTowerTicketLog', 'Le Professeur vous donne 1 Ticket de Combat pour tenter la Tour ! Les autres tickets se recuperent en drop sur les Boss.')}`);
        toast?.info?.(
            questUiText(game, 'giftTowerTicketTitle', 'Ticket de Combat offert'),
            questUiText(game, 'giftTowerTicketBody', '1 ticket ajoute. Les tickets supplementaires droppent sur les Boss. La Tour rapporte des Marques du Triomphe (boutique Tour).')
        );
    }
    if (storyDef.id === 'story_unova_battle_subway') {
        logMessage(`${questUiText(game, 'giftSubwayUnlockLog', 'Battle Subway débloqué ! Ouvre l\'onglet Tour, passe sur Battle Subway, et lance un wagon gratuit pour cette quête.')}`);
        toast?.info?.(
            questUiText(game, 'giftSubwayUnlockTitle', 'Battle Subway débloqué'),
            questUiText(game, 'giftSubwayUnlockBody', 'Onglet Tour -> Battle Subway -> Lancer un wagon (gratuit pendant cette quête). Remporte 7 combats dresseur (wagon complet) pour la terminer.'),
        );
    }
    if (game.unlockedFeatures) {
        // Certains d?blocages doivent se faire uniquement au claim (voir plus bas).
        // Ici, on ?vite sp?cifiquement d'activer le Mode Auto d?s l'acceptation de la qu?te.
        const unlockList = recordGet(STORY_QUEST_UNLOCKS_MAP, storyDef.id as string);
        if (unlockList) {
            const unlockKeys = unlockList.filter(function (key: string) {
                if (storyDef.id === 'story_auto_mode' && key === 'autoMode') return false;
                return true;
            });
            if (unlockKeys.length) {
                unlockKeys.forEach(function (key: string) {
                    (game.unlockedFeatures as unknown as Record<string, boolean>)[key] = true;
                });
                if (unlockKeys.includes('fetiche')) {
                    publishFeticheChanged({ force: true });
                }
                if (typeof game.updateUnlockedTabsUI === 'function') game.updateUnlockedTabsUI();
            }
        }
    }

    (game.quests as unknown[] as Quest[]).push(quest);
    if (typeof game.trackBalanceEvent === 'function') game.trackBalanceEvent('quest_generated', { questType: 'STORY', questId: quest.id });
    const skipDisplay = opts?.skipDisplay || batchStoryQuestDisplay;
    if (skipDisplay) {
        storyQuestDisplayPending = true;
    } else {
        updateQuestsDisplayLogic(game);
    }
    if (typeof game.updateIncubatorsDisplay === 'function') game.updateIncubatorsDisplay();

    if (narrativeManager && narrativeManager.showStoryQuestIntro) {
        const introDone = !narrativeManager.state || narrativeManager.state.introComplete;
        const suppressFirst = narrativeManager.state && narrativeManager.state.suppressNextStoryQuestIntro;
        if (introDone && !suppressFirst) {
            const localizedStoryDef: StoryQuestDef = {
                ...storyDef as unknown as StoryQuestDef,
                title: getQuestDisplayTitle(game, quest),
                description: getQuestDisplayDescription(game, quest),
                dialogue: getQuestDisplayDialogue(game, quest)
            };
            narrativeManager.showStoryQuestIntro(game, localizedStoryDef);
        }
    } else {
        toast?.legendary?.(questUiText(game, 'specialQuestTitle', 'Quete Speciale !'), getQuestDisplayTitle(game, quest));
    }
    logMessage(`?? ${questUiText(game, 'scenarioQuestLog', 'QUETE SCENARIO : {title}', { title: getQuestDisplayTitle(game, quest) })}`);

    acceptQuestLogic(game, storyDef.id as string | number);
    syncLateStoryQuestProgress(game, String(storyDef.id));
    reconcileActiveRivalZoneStoryQuests(game);
    if (storyDef.trackingKey === 'rival_zone_defeated') {
        refreshRivalZoneMiniHud(game);
    }
    if (typeof game.trackBalanceEvent === 'function') game.trackBalanceEvent('quest_accepted', { questType: 'STORY', questId: storyDef.id });
    if (storyDef.id === 'story_surf') publishShopChangedLazy();
    return true;
}

export function addTeamRocketQuestLogic(game: GameRuntime, rocketDef: Record<string, unknown>): void {
    const quest = new Quest({
        title: rocketDef.title as string,
        desc: rocketDef.description as string | undefined,
        target: rocketDef.target as number,
        trackingKey: rocketDef.trackingKey as string
    }, 1, rocketDef.difficulty as string | undefined);

    quest.id = rocketDef.id as string | number;
    quest.i18nKey = `rocket:${coerceStr(rocketDef.id, '')}`;
    quest.rewards = (rocketDef.rewards as QuestRewards) || {} as QuestRewards;
    quest.questType = 'TEAM_ROCKET';
    quest.tags = Array.isArray(rocketDef.tags) ? [...(rocketDef.tags as string[])] : ['team_rocket'];
    if (rocketDef.dialogue) quest.dialogue = rocketDef.dialogue as string;
    if (rocketDef.requiredSpecies) quest.requiredSpecies = rocketDef.requiredSpecies as string;
    if (rocketDef.specialParams && typeof rocketDef.specialParams === 'object') {
        quest.specialParams = { ...rocketDef.specialParams as Record<string, unknown> };
    }
    if (
        rocketDef.trackingKey === 'creature_captured'
        && !hasNonEmptyCaptureRequirements(quest.specialParams)
        && !(Number(quest.specialParams?.minIvPercent) > 0)
    ) {
        if (!quest.specialParams || typeof quest.specialParams !== 'object') quest.specialParams = {};
        quest.specialParams.minIvPercent = getCaptureMinIvPercent(
            coerceStr(rocketDef.difficulty, quest.difficulty),
        );
    }
    ensureIvCaptureEggRewards(game, quest);

    (game.quests as unknown[] as Quest[]).push(quest);
    if (typeof game.trackBalanceEvent === 'function') game.trackBalanceEvent('quest_generated', { questType: 'TEAM_ROCKET', questId: quest.id });
    updateQuestsDisplayLogic(game);

    const rocketToast = toast;
    if (rocketToast?.warning) {
        rocketToast.warning(questUiText(game, 'rocketQuestTitle', 'Mission Team Rocket'), getQuestDisplayTitle(game, quest));
    }
    logMessage(`?? ${questUiText(game, 'rocketQuestLog', 'QUETE TEAM ROCKET : {title}', { title: getQuestDisplayTitle(game, quest) })}`);

    acceptQuestLogic(game, rocketDef.id as string | number);
    if (rocketDef.trackingKey === 'rocket_spins') {
        const acceptedQuest = (game.quests as unknown[] as Quest[]).find(q => q.id == rocketDef.id);
        if (acceptedQuest) ensureRocketSpinQuestStartValue(game, acceptedQuest);
    }
    if (typeof game.trackBalanceEvent === 'function') game.trackBalanceEvent('quest_accepted', { questType: 'TEAM_ROCKET', questId: rocketDef.id });
}

