                    if (reqCourse && courseId !== reqCourse) break;
                    const minRank = quest.specialParams && typeof quest.specialParams === 'object'
                        ? Math.max(1, Math.floor(Number((quest.specialParams as Record<string, unknown>).minRank) || 2))
                        : 2;
                    const rank = Math.floor(Number(params.rank) || 0);
                    quest.current = rank >= minRank ? 1 : 0;
