function patchClassicQuestCountDom(game: GameRuntime): void {
    const questCount = document.getElementById('questCount');
    if (!questCount) return;
    const counts = getQuestCounts(game);
    questCount.textContent = String(counts.classic);
}

export function updateQuestTimerLogic(game: GameRuntime, deltaTime: number | null | undefined): void {
    const counts = getQuestCounts(game);
    if (counts.classic >= 10) {
        updateQuestTimerDisplayLogic(game);
        return;
    }
    if (!game.unlockedFeatures || !game.unlockedFeatures.classicQuests) {
        updateQuestTimerDisplayLogic(game);
        return;
    }

    if (isNaN(game.nextQuestTimer) || game.nextQuestTimer === undefined) {
        debugWarn("?? Timer Qu?te corrompu (NaN). R?initialisation forc?e.");
        game.nextQuestTimer = 60000;
    }

    if (typeof deltaTime === 'number') {
        game.nextQuestTimer -= deltaTime;
    } else {
        const now = Date.now();
        const elapsed = now - game.lastQuestUpdate;
        game.lastQuestUpdate = now;
        game.nextQuestTimer -= elapsed;
    }

    if (game.nextQuestTimer <= 0) {
        generateQuestLogic(game);
        game.nextQuestTimer = 120000 + (Math.random() * 360000);
        logMessage(`${questUiText(game, 'newQuestAvailable', 'Une nouvelle quete est disponible !')}`);
    }

    updateQuestTimerDisplayLogic(game);
}

export function updateQuestTimerDisplayLogic(game: GameRuntime): void {
    const timerElement = document.getElementById('nextQuestTime');
    if (!timerElement) return;

    const counts = getQuestCounts(game);
    if (counts.classic >= 10) {
        timerElement.textContent = questUiText(game, 'timerMax', 'MAX classiques (10/10)');
        timerElement.style.color = "#ef4444";
        timerElement.style.fontWeight = "bold";
        timerElement.title = questUiText(game, 'timerMaxTitle', 'Terminez ou refusez des quetes classiques pour en recevoir de nouvelles.');
        return;
    }

    let seconds = Math.ceil(game.nextQuestTimer / 1000);
    if (seconds < 0) seconds = 0;
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = seconds % 60;
    timerElement.textContent = `${minutes}m ${remainingSeconds.toString().padStart(2, '0')}s`;
    timerElement.style.color = "#333";
    timerElement.style.fontWeight = "normal";
}

