export function acceptQuestLogic(game: GameRuntime, questId: string | number): void {
    const quest = (game.quests as unknown[] as Quest[]).find(q => q.id == questId);
    if (!quest || quest.accepted) return;

    quest.accepted = true;

    switch (quest.trackingKey) {
        case 'totalPokedollarsEarned':
            quest.startValue = game.stats.totalPokedollarsEarned || 0;
            break;
        case 'currentMoney':
            quest.startValue = game.pokedollars;
            quest.current = 0;
            break;
        case 'evolutionCount':
            quest.current = game.stats && game.stats.evolutionsCount !== undefined ? game.stats.evolutionsCount : 0;
            break;
        case 'pensionCount':
            quest.current = game.stats && game.stats.pensionCount !== undefined ? game.stats.pensionCount : (game.pension ? game.pension.length : 0);
            break;
        case 'pensionUpgradeBought':
            quest.current = (game.upgrades && game.upgrades.pension && game.upgrades.pension.level > 0) ? 1 : 0;
            break;
        case 'badgesEarned':
            quest.current = game.stats && game.stats.badgesEarned !== undefined ? game.stats.badgesEarned : (Object.values(game.badges || {}).filter(Boolean).length);
            break;
        case 'region_visited':
            quest.current = readRegionVisitedQuestProgress(game, quest);
            break;
        case 'gym_badge': {
            const reqBadge = quest.specialParams && typeof quest.specialParams === 'object'
                ? String((quest.specialParams as Record<string, unknown>).requiredBadge || '')
                : '';
            quest.current = (reqBadge && typeof game.hasBadge === 'function' && game.hasBadge(reqBadge)) ? 1 : 0;
            break;
        }
        case 'collectionBonusActive':
            quest.current = (game.getCollectionBonusDetails && game.getCollectionBonusDetails().some((d: any) => d.isActive)) ? 1 : 0;
            break;
        case 'synergyActive': {
            if (!quest.specialParams || typeof quest.specialParams !== 'object') quest.specialParams = {};
            quest.specialParams.synergyActiveAtAccept = hasActiveTeamSynergyOnGame(game);
            quest.current = 0;
            break;
        }
        case 'zonesUnlocked':
            if (typeof ZONES !== 'undefined' && typeof game.isZoneUnlocked === 'function') {
                quest.current = Object.keys(ZONES).filter(z => (game.isZoneUnlocked as (z: number) => boolean)(Number(z))).length;
            }
            break;
        case 'zone_2_visited':
            quest.current = (currentZone === 2) || ((game.sessionStats as Record<string, unknown>) && (game.sessionStats as Record<string, unknown>).zonesVisited && ((game.sessionStats as Record<string, unknown>).zonesVisited as Set<number>).has(2)) ? 1 : 0;
            break;
        case 'zone_2_mastered':
            quest.current = (typeof game.isZoneMastered === 'function' && game.isZoneMastered(2)) ? 1 : 0;
            break;
        case 'map_route_1_selected':
            quest.current = (currentZone === 2) || ((game.sessionStats as Record<string, unknown>) && (game.sessionStats as Record<string, unknown>).zonesVisited && ((game.sessionStats as Record<string, unknown>).zonesVisited as Set<number>).has(2)) ? 1 : 0;
            break;
        case 'classicQuestsCompleted':
            quest.current = Math.min((game.stats && game.stats.classicQuestsCompleted) || 0, quest.target || 1);
            break;
        case 'active_pokemon_drag':
        case 'move_drag':
        case 'move_unlocked_by_farm':
        case 'use_tm':
        case 'talent_reset':
            quest.current = 0;
            break;
        case 'elite_four_beaten':
            quest.current = (typeof game.hasBadge === 'function' && game.hasBadge('maitre_kanto')) ? 1 : 0;
            break;
        case 'elite_four_gen2_beaten':
            quest.current = (typeof game.hasBadge === 'function' && game.hasBadge('maitre_johto')) ? 1 : 0;
            break;
        case 'elite_four_gen3_beaten':
            quest.current = (typeof game.hasBadge === 'function' && game.hasBadge('maitre_hoenn')) ? 1 : 0;
            break;
        case 'elite_four_gen4_beaten':
            quest.current = (typeof game.hasBadge === 'function' && game.hasBadge('maitre_sinnoh')) ? 1 : 0;
            break;
        case 'elite_four_gen5_beaten':
            quest.current = (typeof game.hasBadge === 'function' && game.hasBadge('maitre_unova')) ? 1 : 0;
            break;
        case 'elite_four_gen6_beaten':
            quest.current = (typeof game.hasBadge === 'function' && game.hasBadge('maitre_kalos')) ? 1 : 0;
            break;
        case 'elite_four_gen7_beaten':
            quest.current = (typeof game.hasBadge === 'function' && game.hasBadge('maitre_alola')) ? 1 : 0;
            break;
        case 'elite_four_gen8_beaten':
            quest.current = (typeof game.hasBadge === 'function' && game.hasBadge('maitre_galar')) ? 1 : 0;
            break;
        case 'elite_four_gen9_beaten':
            quest.current = (typeof game.hasBadge === 'function' && game.hasBadge('maitre_paldea')) ? 1 : 0;
            break;
        case 'multi_species_captured':
            quest.specialParams = quest.specialParams || {};
            quest.specialParams.capturedSpecies = [];
            quest.current = 0;
            break;
        case 'uniqueSpeciesOwned': {
            quest.current = getUniqueSpeciesOwnedCountForQuest(game, quest);
            if (quest.specialParams && quest.specialParams.pokedexMissingPreview) {
                const maxDex = getQuestMaxNationalDex(quest);
                if (maxDex > 0 && !Object.prototype.hasOwnProperty.call(quest.specialParams, 'previewMissingSpeciesList')) {
                    quest.specialParams.previewMissingSpeciesList = buildPokedexMissingSpeciesSnapshot(game, maxDex);
                }
            }
            break;
        }
        case 'pokedexUniqueDiscovered':
            quest.current = Math.min(getPokedexUniqueDiscoveredCountForQuest(game, quest), quest.target || 999);
            break;
        case 'totalOwned': {
            const total = (game.playerTeam ? game.playerTeam.length : 0)
                + (game.storage ? game.storage.length : 0)
                + (game.pension ? game.pension.length : 0);
            quest.current = Math.min(total, quest.target || 999);
            break;
        }
        case 'towerRecord':
            quest.current = Math.min((typeof game.towerRecord === 'number' ? game.towerRecord : 0), quest.target || 999);
            break;
        case 'maxPrestige': {
            const minP = (quest.specialParams && Number(quest.specialParams.minPrestige)) || 3;
            const allP = (game.playerTeam || []).concat(game.storage || [], game.pension || []);
            const maxP = Math.max(0, ...allP.map(function (c) { return c.prestige || 0; }));
            quest.current = maxP >= minP ? 1 : 0;
            break;
        }
        case 'mastery_intro_combo':
            syncMasteryIntroCombo(game, quest);
            break;
        case 'vitaminUsed':
        case 'statBoostUsed':
        case 'heldItemEquipped':
        case 'recyclerUsed':
        case 'expeditionLaunched':
        case 'incubator_hatched':
        case 'incubator_hatched_rare_plus':
        case 'incubator_hatched_epic':
        case 'incubator_hatched_legendary':
            quest.current = 0;
            break;
        case 'waterSpeciesCaptured':
        case 'typedSpeciesCaptured':
            quest.specialParams = quest.specialParams || {};
            quest.specialParams.capturedSpecies = [];
            quest.current = 0;
            break;
        case 'towerFloor':
            quest.startValue = (game.stats && typeof game.stats.towerFloorsClimbed === 'number')
                ? game.stats.towerFloorsClimbed
                : 0;
            quest.current = 0;
            break;
        case 'ultimateUsed':
        case 'ultimateUsedManual':
        case 'combatsWon':
        case 'statusInflicted':
        case 'eggsOpened':
        case 'shiniesObtained':
        case 'creaturesObtained':
            setQuestStatCounterBaselineOnAccept(game, quest);
            break;
        case 'typedDamageDealtDuringQuest': {
            const req = quest.specialParams && quest.specialParams.requiredType
                ? String(quest.specialParams.requiredType).toLowerCase().trim()
                : '';
            const typed = (game.stats && game.stats.typedDamageDealt && typeof game.stats.typedDamageDealt === 'object')
                ? game.stats.typedDamageDealt
                : null;
            quest.startValue = req ? (Number((typed && typed[req]) || 0) || 0) : 0;
            quest.current = 0;
            break;
        }
        case 'rocket_spins':
            setRocketCounterBaselineOnAccept(quest, readRocketSpinTotal(game));
            break;
        case 'rocket_clean_exit':
            quest.current = 0;
            break;
        case 'rocket_double_or_nothing':
            setRocketCounterBaselineOnAccept(
                quest,
                Math.max(0, Number((game.stats && game.stats.rocketDoubleOrNothing) || 0)),
            );
            break;
        case 'rocket_precision_gambler':
            setRocketCounterBaselineOnAccept(
                quest,
                Math.max(0, Number((game.stats && game.stats.rocketCasinoWinningSpins) || 0)),
            );
            break;
        case 'rocket_loan_cycle':
            quest.current = 0;
            break;
        case 'totalRocketBankInterestGained':
            setRocketCounterBaselineOnAccept(
                quest,
                Math.max(0, Number((game.stats && game.stats.totalRocketBankInterestGained) || 0)),
            );
            break;
        case 'rocketTrustLevelMax':
            quest.startValue = readRocketTrustLevel(game);
            quest.current = 0;
            quest.progress = 0;
            break;
        case 'rocket_net_rj_window': {
            const tr = game.teamRocketState || {};
            const currentRj = Math.max(0, Number(tr.rj) || 0);
            quest.current = 0;
            quest.specialParams = quest.specialParams || {};
            quest.specialParams.windowStartAt = Date.now();
            quest.specialParams.windowStartRj = currentRj;
            break;
        }
        case 'starter_level_up': {
            const starter = game.playerTeam && game.playerTeam.find(c => c.isStarter);
            quest.startValue = starter ? starter.level : 1;
            quest.current = 0;
            break;
        }
        case 'rocket_persian_ascent':
            ensureRocketPersianAscentSpecialParams(quest);
            updateRocketPersianAscentProgressFromState(game, quest);
            break;
        default:
            quest.current = 0;
            break;
    }

    if (quest.current >= quest.target && !quest.completed) {
        quest.completed = true;
        if (quest.trackingKey === 'region_visited') {
            markRegionStartStoryQuestGateComplete(game, quest);
        }
        showQuestCompletionModalLogic(game, quest);
        if (quest.questType === 'TEAM_ROCKET' && typeof ensureTeamRocketQuestProgress === 'function') {
            ensureTeamRocketQuestProgress(game);
        }
    }

    if (quest.special === 'rainbow' || quest.trackingKey === 'newTypesDuringQuest') {
        quest.typesObtained = new Set();
    }

    // Qu?te L?o (fusion) : 5 Pok? Balls ? l'acceptation pour capturer des doublons
    if (quest.id === 'story_duplicates') {
        game.items['pokeball'] = (game.items['pokeball'] || 0) + 5;
        logMessage(`${questUiText(game, 'leoGiftLog', "Leo vous donne 5 Poke Balls pour l'experience.")}`);
    toast?.info?.(
            questUiText(game, 'leoGiftTitle', 'Leo vous donne 5 Poke Balls'),
            questUiText(game, 'leoGiftBody', 'Pour capturer des doublons !')
        );
    }

    logMessage(`? ${questUiText(game, 'acceptedLog', 'Quete acceptee : {title}', { title: getQuestDisplayTitle(game, quest) })}`);
    updateQuestsDisplayLogic(game);
}

export function refuseQuestLogic(game: GameRuntime, questId: string | number): void {
    const index = game.quests.findIndex(q => q.id == questId);
    if (index !== -1) {
        const quest = (game.quests as unknown[] as Quest[])[index];
        if (!quest) return;
        logMessage(`? ${questUiText(game, 'refusedLog', 'Quete refusee : {title}', { title: getQuestDisplayTitle(game, quest) })}`);
        game.quests.splice(index, 1);
        game.saveGame(); // Direct call
    }

    updateQuestsDisplayLogic(game);
}

export function abandonQuestLogic(game: GameRuntime, questId: string | number): void {
    const index = game.quests.findIndex(q => q.id == questId);
    if (index === -1) return;

    const quest = (game.quests as unknown[] as Quest[])[index];
    if (!quest) return;

    if (quest.questType === 'STORY' || quest.questType === 'TEAM_ROCKET') {
        logMessage(`? ${questUiText(game, 'storyCannotAbandonLog', 'Les quetes scenario/faction ne peuvent pas etre abandonnees.')}`);
        return;
    }

    if (!quest.accepted || quest.completed) {
        logMessage(`? ${questUiText(game, 'cannotAbandonLog', "Impossible d'abandonner cette quete !")}`);
        return;
    }

    if (!confirm(questUiText(game, 'abandonConfirm', 'Etes-vous sur de vouloir abandonner la quete "{title}"?\nVotre progression sera perdue.', { title: getQuestDisplayTitle(game, quest) }))) {
        return;
    }

    game.quests.splice(index, 1);

    logMessage(`? ${questUiText(game, 'abandonedLog', 'Quete abandonnee : {title}', { title: getQuestDisplayTitle(game, quest) })}`);
    updateQuestsDisplayLogic(game);
}

