export function buildQuestRewardsSummaryHtml(game: GameRuntime, quest: Quest | null | undefined): string {
    if (!quest || !quest.rewards) return '';

    const r = quest.rewards;
    const eggSpriteByRarity = {
        common: 'img/common-egg.png',
        rare: 'img/rare-egg.png',
        epic: 'img/epic-egg.png',
        legendary: 'img/legendary-egg.png'
    };

    const rows = [];
    const tokenLabel = questUiText(game, 'rewardQuestTokensLabel', 'Jetons de Quetes');
    const rerollLabel = questUiText(game, 'rewardRerollCrystalLabel', 'Cristal(x) de Reinitialisation');
    const masteryLabel = questUiText(game, 'rewardMasteryOrbLabel', 'Orbe(s) de Maitrise');
    const eggLabel = questUiText(game, 'rewardEggLabel', 'Oeuf');
    const autoIncubatorLabel = questUiText(game, 'rewardAutoIncubatorUnlock', 'Debloque +{count} incubateur(s) auto', { count: r.unlocks && r.unlocks.autoIncubatorSlots ? r.unlocks.autoIncubatorSlots : 0 });

    const repeatCountValue = Math.max(0, Math.floor(Number(quest.repeatCount) || 0));
    if (repeatCountValue > 0) {
        const repeatText = questUiText(game, 'repeatSummary', 'Bonus de repetition x{count} : +{percent}% butin', {
            count: repeatCountValue + 1,
            percent: repeatCountValue
        });
        rows.push(`<div class="quest-completion-reward" style="color:#b45309;font-weight:600;">${repeatText}</div>`);
    }

    if (r.pokedollars > 0) {
        rows.push(`<div class="quest-completion-reward"><img src="img/pokedollars.png" class="quest-reward-inline-img" alt="Pokedollars"> ${resolveFormatNumber(r.pokedollars)} Pokedollars</div>`);
    }

    const tokenReward = getScaledQuestTokenReward(game, r);
    if (tokenReward > 0) {
        rows.push(`<div class="quest-completion-reward"><img src="https://raw.githubusercontent.com/msikma/pokesprite/master/items/key-item/magma-emblem.png" class="quest-token-inline" alt="Jetons"> ${tokenReward} ${tokenLabel}</div>`);
    }

    if ((r.talentRerolls ?? 0) > 0) {
        rows.push(`<div class="quest-completion-reward"><img src="img/talent-reroll.png" class="quest-reward-inline-img" alt="Talent reroll"> ${r.talentRerolls} ${rerollLabel}</div>`);
    }

    if ((r.talentChoices ?? 0) > 0) {
        rows.push(`<div class="quest-completion-reward"><img src="img/ability-patch.png" class="quest-reward-inline-img" alt="Talent choice"> ${r.talentChoices} ${masteryLabel}</div>`);
    }

    if (r.eggs) {
        Object.entries(r.eggs).forEach(([rarity, count]) => {
            if (count <= 0) return;
            const rarityKey = String(rarity || '').toLowerCase();
            const eggSprite = (eggSpriteByRarity as Record<string, string>)[rarityKey] || eggSpriteByRarity.common;
            rows.push(`<div class="quest-completion-reward"><img src="${eggSprite}" class="quest-reward-inline-img quest-reward-egg" alt="${eggLabel} ${rarity}"> ${count}x ${eggLabel} ${rarity}</div>`);
        });
    }

    if (r.boosts) {
        const boostNames: Record<string, string> = {
            xp: 'XP',
            money: 'Pokedollars',
            eggDrop: questUiText(game, 'rewardEggDropLabel', 'Drop Oeufs')
        };
        r.boosts.forEach(b => {
            const min = Math.floor((b.duration || 0) / 60000);
            rows.push(`<div class="quest-completion-reward">+${(b.value || 0) * 100}% ${boostNames[b.type] || b.type} (${min}min)</div>`);
        });
    }

    if (r.items) {
        Object.entries(r.items).forEach(([key, count]) => {
            if (count <= 0) return;
            const itemDef = ((ALL_ITEMS as ItemRecord)[key] || (KEY_ITEMS as ItemRecord)[key] || { name: key, icon: '[item]' }) as Record<string, unknown>;
            const iconHTML = getItemIconHTML(itemDef) || coerceStr(itemDef.icon, '[item]');
            const itemName = getQuestLocalizedItemName(game, key, itemDef);
            rows.push(`<div class="quest-completion-reward">${iconHTML} ${count}x ${itemName || key}</div>`);
        });
    }

    if (r.unlocks && r.unlocks.autoIncubatorSlots) {
        rows.push(`<div class="quest-completion-reward">${autoIncubatorLabel}</div>`);
    }

    return rows.join('');
}
export function showQuestCompletionModalLogic(game: GameRuntime, quest: Quest): void {
    const title = getQuestDisplayTitle(game, quest);
    logMessage(`?? ${questUiText(game, 'completeLog', 'Quete terminee : {title} ! Recuperez la recompense dans l onglet Quetes.', { title })}`);
    if (game.notifyQuest) {
        toast?.info?.(
            questUiText(game, 'completeToastTitle', 'Quete terminee'),
            questUiText(game, 'completeToastBody', '{title} - Recuperez la recompense dans l onglet Quetes.', { title })
        );
    }
}

export function claimQuestRewardLogic(game: GameRuntime, quest?: Quest | null): void {
    const toClaim = quest != null ? quest : game.pendingQuestReward;
    if (!toClaim) return;

    const questToUse = toClaim as unknown as Quest;

    if (questToUse.questType !== 'STORY' && questToUse.questType !== 'TEAM_ROCKET') {
        if (game.stats) game.stats.classicQuestsCompleted = (game.stats.classicQuestsCompleted || 0) + 1;
        if (typeof game.checkAchievements === 'function') game.checkAchievements('classicQuestsCompleted');
        if (typeof checkSpecialQuestsLogic === 'function') checkSpecialQuestsLogic(game, 'classic_quest_claimed');
        // Scaling longue duree : +1% de gains par repetition du meme modele de quete quotidienne.
        const repeatKey = questToUse.repeatKey || questToUse.i18nKey || null;
        if (repeatKey && typeof repeatKey === 'string' && repeatKey.indexOf('template:') === 0) {
            if (!game.questRepeatCounts || typeof game.questRepeatCounts !== 'object') game.questRepeatCounts = {};
            game.questRepeatCounts[repeatKey] = Math.max(0, Math.floor(Number(game.questRepeatCounts[repeatKey]) || 0)) + 1;
        }
        if (isClassicQualityCatchQuest(questToUse) && questToUse.requiredSpecies) {
            recordClassicQualityCatchSpeciesToHistory(game, questToUse.requiredSpecies);
        }
    }

    if (questToUse.rewards) {
        if (questToUse.rewards.pokedollars && questToUse.rewards.pokedollars > 0) {
            const pdResult = typeof game.addCombatPokedollars === 'function'
                ? game.addCombatPokedollars(questToUse.rewards.pokedollars, 'silent')
                : { creditedToWallet: questToUse.rewards.pokedollars, net: questToUse.rewards.pokedollars };
            const credited = Math.max(0, Number(pdResult.creditedToWallet ?? pdResult.net) || 0);
            if (game.showUiFloatingText && credited > 0) {
                game.showUiFloatingText('headerStatMoney', `+${resolveFormatNumber(credited)}$`, 'ft-money');
            }
        }

        const tokenReward = getScaledQuestTokenReward(game, questToUse.rewards);
        if (tokenReward > 0) {
            game.questTokens = (game.questTokens || 0) + tokenReward;
            if (game.stats) game.stats.totalQuestTokensEarned = (game.stats.totalQuestTokensEarned || 0) + tokenReward;
            if (game.showUiFloatingText) (game.showUiFloatingText)('headerStatTokens', `+${tokenReward}??`, 'ft-token');
        }

        if (questToUse.rewards.eggs) {
            Object.entries(questToUse.rewards.eggs).forEach(([rarity, count]) => {
                if (count > 0) game.eggs[rarity] = (game.eggs[rarity] || 0) + count;
            });
        }

        if (questToUse.rewards.boosts && Array.isArray(questToUse.rewards.boosts)) {
            questToUse.rewards.boosts.forEach((boost: { type: string; value: number; duration: number }) => (game.addBoost as (b: Record<string, unknown>) => void)(boost));
        }

        if (questToUse.rewards.items) {
            Object.entries(questToUse.rewards.items).forEach(([itemKey, count]) => {
                const qty = Math.max(0, Math.floor(Number(count) || 0));
                if (qty <= 0) return;
                if (itemKey === 'talent_reroll') {
                    game.talentRerolls = (game.talentRerolls || 0) + qty;
                    logMessage(`${questUiText(game, 'rewardTalentPill', '+{qty} Pilule Talent', { qty })}`);
                    return;
                }
                if (itemKey === 'talent_choice') {
                    game.talentChoices = (game.talentChoices || 0) + qty;
                    logMessage(`${questUiText(game, 'rewardTalentPatch', '+{qty} Patch Talent', { qty })}`);
                    return;
                }
                game.addItem(itemKey, qty);
            });
        }
        if (questToUse.rewards.unlocks && questToUse.rewards.unlocks.autoIncubatorSlots) {
            const delta = Math.max(0, Number(questToUse.rewards.unlocks.autoIncubatorSlots) || 0);
            if (!game.autoIncubation && typeof game.createDefaultAutoIncubationState === 'function') {
                game.autoIncubation = game.createDefaultAutoIncubationState();
            }
            if (game.autoIncubation) {
                game.autoIncubation.unlockedAutoSlots = Math.min(4, (game.autoIncubation.unlockedAutoSlots || 0) + delta);
                const incToast = toast;
                if (incToast?.success) {
                    incToast.success(
                        questUiText(game, 'autoIncubationTitle', 'Auto-incubation'),
                        questUiText(game, 'autoIncubationBody', 'Incubateurs auto debloques: {count}/4', { count: game.autoIncubation.unlockedAutoSlots })
                    );
                }
            }
        }
    }

    // Toast résumant les gains de la quête (auto-dismiss après 5s).
    const rewardToast = toast;
    if (rewardToast?.show && questToUse.rewards && game.notifyQuest) {
        const rewardsHtml = buildQuestRewardsSummaryHtml(game, questToUse);
        if (rewardsHtml && String(rewardsHtml).trim() !== '') {
            rewardToast.show({
                title: questUiText(game, 'completeToastTitle', 'Quete terminee'),
                message: rewardsHtml,
                type: 'success',
                duration: 5000,
                html: true
            });
        }
    }

    // Dialogue sp?cial : canne ? p?che d?bloqu?e apr?s la premi?re ar?ne
    if (questToUse.id === 'story_arena_first' && typeof narrativeManager.showInfoModal === 'function') {
        narrativeManager.showInfoModal(
            game,
            questUiText(game, 'duplicatesInfoTitle', 'Nouveaux Pokemon aquatiques'),
            questUiText(game, 'duplicatesInfoBody', 'Grace a cette canne a peche, des Pokemon de type Eau apparaissent maintenant sur certaines routes. Repere les zones ou la peche est possible pour les rencontrer.')
        );
    }
    if (questToUse.id === 'story_surf' && typeof narrativeManager.showInfoModal === 'function') {
        narrativeManager.showInfoModal(
            game,
            questUiText(game, 'surfInfoTitle', 'Surf debloque'),
            questUiText(game, 'surfInfoBody', 'Grace a la Planche Surf, des Pokemon de type Eau apparaissent maintenant sur les routes aquatiques. Explore les routes avec rivieres et zones marines.')
        );
    }
    if (questToUse.id === 'story_surf') publishShopChangedLazy();

    game.questsCompleted = (game.questsCompleted || 0) + 1;

    if (questToUse.questType === 'STORY') {
        if (!game.completedStoryQuests) game.completedStoryQuests = [];
        if (!game.completedStoryQuests.some((id) => String(id) === String(questToUse.id))) {
            game.completedStoryQuests.push(String(questToUse.id));
        }
        if (typeof game.unlockHeaderSkinsByStoryQuest === 'function') {
            game.unlockHeaderSkinsByStoryQuest(questToUse.id as string, { silent: false });
        }
        // D?blocages UI (unfolding) : appliquer STORY_QUEST_UNLOCKS
        const claimUnlocks = recordGet(STORY_QUEST_UNLOCKS_MAP, questToUse.id as string);
        if (game.unlockedFeatures && claimUnlocks) {
            claimUnlocks.forEach(function (key: string) {
                (game.unlockedFeatures as unknown as Record<string, boolean>)[key] = true;
            });
            if (claimUnlocks.includes('fetiche')) {
                publishFeticheChanged({ force: true });
            }
            if (typeof game.updateUnlockedTabsUI === 'function') game.updateUnlockedTabsUI();
        }
        if (questToUse.id === 'story_kalos_miltank_pasture') {
            upgradeMiltankPastureLogic(game);
        }
    } else if (questToUse.questType === 'TEAM_ROCKET') {
        if (!game.completedTeamRocketQuests) game.completedTeamRocketQuests = [];
        if (!game.completedTeamRocketQuests.includes(questToUse.id as string)) {
            game.completedTeamRocketQuests.push(questToUse.id as string);
        }
    }

    const questTags = Array.isArray(questToUse.tags) ? questToUse.tags.map(t => String(t).toLowerCase()) : [];
    const isTeamRocketTagged = questToUse.questType === 'TEAM_ROCKET' || questTags.includes('team_rocket') || questTags.includes('team-rocket');
    if (isTeamRocketTagged && typeof game.addRocketTrustProgress === 'function') {
        game.addRocketTrustProgress('quest', 1, { questId: questToUse.id });
    }

    questToUse.claimed = true;
    if (typeof game.trackBalanceEvent === 'function') game.trackBalanceEvent('quest_claimed', { questType: questToUse.questType || 'UNKNOWN', questId: questToUse.id });
    const index = game.quests.findIndex(q => q.id === questToUse.id);
    if (index !== -1) game.quests.splice(index, 1);

    game.pendingQuestReward = null;

    // Story quest : d'abord modal r?cap (r?compenses + infos), puis apr?s ? Continuer ? + d?lai, le Prof Chen propose la suivante
    if (questToUse.questType === 'STORY') {
        if (typeof narrativeManager.showStoryQuestCompletionSummary === 'function') {
            const completionData = {
                id: String(questToUse.id),
                title: getQuestDisplayTitle(game, questToUse),
                description: getQuestDisplayDescription(game, questToUse) || '',
                dialogue: getQuestDisplayDialogue(game, questToUse) || '',
                rewardsHtml: buildQuestRewardsSummaryHtml(game, questToUse),
            };
            narrativeManager.showStoryQuestCompletionSummary(game, completionData, () => {
                const delayMs = 5000;
                setTimeout(() => {
                    if (typeof ensureStoryQuestProgress === 'function') ensureStoryQuestProgress(game);
                    if (typeof updateQuestsDisplayLogic === 'function') updateQuestsDisplayLogic(game);
                }, delayMs);
            });
        } else {
            setTimeout(() => {
                if (typeof ensureStoryQuestProgress === 'function') ensureStoryQuestProgress(game);
                if (typeof updateQuestsDisplayLogic === 'function') updateQuestsDisplayLogic(game);
            }, 5000);
        }
    } else if (questToUse.questType === 'TEAM_ROCKET') {
        const delayMs = 1200;
        setTimeout(() => {
            if (typeof ensureTeamRocketQuestProgress === 'function') ensureTeamRocketQuestProgress(game);
        }, delayMs);
    }

    if (typeof updateQuestsDisplayLogic === 'function') updateQuestsDisplayLogic(game);
    if (typeof game.updateIncubatorsDisplay === 'function') game.updateIncubatorsDisplay();
    if (game.updateEggsDisplay) game.updateEggsDisplay();
    if (game.updatePlayerStatsDisplay) game.updatePlayerStatsDisplay();
    if (game.updateShopDisplay) game.updateShopDisplay();
    if (game.updateItemsDisplay) game.updateItemsDisplay();
    updateZoneInfo(game);

    if (game.saveGame) game.saveGame({ immediate: true, reason: 'quest_claim' });
}

