export function getQuestRepeatBadgeDisplay(
    game: GameRuntime,
    quest: Quest,
): { text: string; title: string } | null {
    const repeatCountValue = Math.max(0, Math.floor(Number(quest.repeatCount) || 0));
    if (repeatCountValue <= 0) return null;
    return {
        text: questUiText(game, 'repeatBadge', 'Repetition x{count} (+{percent}% butin)', {
            count: repeatCountValue + 1,
            percent: repeatCountValue,
        }),
        title: questUiText(game, 'repeatBadgeTitle', '+1% par repetition de cette quete'),
    };
}

function questSpeciesCellHtml(
    stateClass: 'is-caught' | 'is-missing',
    displayName: string,
    spriteUrl: string,
    tickHTML: string,
): string {
    const safeName = escapeQuestHtml(displayName);
    return `<div class="quest-species-cell ${stateClass}" data-tooltip-title="${safeName}" aria-label="${safeName}">`
        + `<img src="${spriteUrl}" alt="${safeName}" loading="lazy">${tickHTML}</div>`;
}

export function bindQuestSpeciesGridTooltipEvents(container: HTMLElement, game: GameRuntime): void {
    if (container.dataset.questSpeciesTooltipBound === '1') return;
    if (!game || typeof game.scheduleTooltip !== 'function') return;
    container.dataset.questSpeciesTooltipBound = '1';

    container.addEventListener('mouseover', (ev) => {
        const node = (ev.target as HTMLElement).closest('.quest-species-cell[data-tooltip-title]');
        if (!node) return;
        const el = node as HTMLElement;
        game.scheduleTooltip(ev, el.dataset.tooltipTitle || '', '', 50);
    });
    container.addEventListener('mouseout', (ev) => {
        const node = (ev.target as HTMLElement).closest('.quest-species-cell[data-tooltip-title]');
        if (node && typeof game.hideTooltip === 'function') {
            game.hideTooltip();
        }
    });
}

export function buildQuestCardHTML(game: GameRuntime, quest: Quest): string {
    const toSafeInt = (value: unknown) => Math.max(0, Math.floor(Number(value) || 0));

    ensurePokedexMissingPreviewSnapshot(game, quest);

    let badgeClass = 'badge-easy';
    let badgeText = questUiText(game, 'badgeEasy', 'Facile');
    if (quest.questType === 'STORY') {
        badgeClass = 'badge-extreme';
        badgeText = questUiText(game, 'badgeStory', 'Scenario');
    } else if (quest.questType === 'TEAM_ROCKET') {
        badgeClass = 'badge-hard';
        badgeText = 'Team Rocket';
    } else {
        if (quest.difficulty === 'MEDIUM') { badgeClass = 'badge-medium'; badgeText = questUiText(game, 'badgeMedium', 'Moyen'); }
        if (quest.difficulty === 'HARD') { badgeClass = 'badge-hard'; badgeText = questUiText(game, 'badgeHard', 'Difficile'); }
        if (quest.difficulty === 'EXTREME') { badgeClass = 'badge-extreme'; badgeText = questUiText(game, 'badgeExtreme', 'Extreme'); }
    }

    const current = toSafeInt(quest.current);
    const target = Math.max(1, toSafeInt(quest.target) || 1);
    const percent = Math.min(100, (current / target) * 100);
    const displayTitle = escapeQuestHtml(getQuestDisplayTitle(game, quest));
    const displayDescription = escapeQuestHtml(getQuestDisplayDescription(game, quest));
    const displayDialogue = escapeQuestHtml(getQuestDisplayDialogue(game, quest));
    const safeBadgeText = escapeQuestHtml(badgeText);
    const safeQuestId = getSafeQuestActionId(quest.id);

    let rewardsHTML = '';
    if (quest.rewards) {
        const eggSpriteByRarity = {
            common: 'img/common-egg.png',
            rare: 'img/rare-egg.png',
            epic: 'img/epic-egg.png',
            legendary: 'img/legendary-egg.png'
        };

        const rewardParts = [];

        const rewardPokedollars = Number(quest.rewards.pokedollars || 0);
        if (rewardPokedollars > 0) {
            rewardParts.push(`<span class="quest-reward-item"><img src="img/pokedollars.png" class="quest-reward-inline-img" alt="Pokedollars"> ${resolveFormatNumber(rewardPokedollars)}</span>`);
        }

        const tokenReward = getScaledQuestTokenReward(game, quest.rewards);
        if (tokenReward > 0) {
            rewardParts.push(`<span class="quest-reward-item"><img src="https://raw.githubusercontent.com/msikma/pokesprite/master/items/key-item/magma-emblem.png" class="quest-token-inline" alt="Jetons"> ${tokenReward}</span>`);
        }

        const talentRerollsReward = toSafeInt(quest.rewards.talentRerolls || 0);
        if (talentRerollsReward > 0) {
            rewardParts.push(`<span class="quest-reward-item"><img src="img/talent-reroll.png" class="quest-reward-inline-img" alt="Talent reroll"> ${talentRerollsReward}</span>`);
        }

        const talentChoicesReward = toSafeInt(quest.rewards.talentChoices || 0);
        if (talentChoicesReward > 0) {
            rewardParts.push(`<span class="quest-reward-item"><img src="img/ability-patch.png" class="quest-reward-inline-img" alt="Talent choice"> ${talentChoicesReward}</span>`);
        }

        if (quest.rewards.items) {
            Object.entries(quest.rewards.items).forEach(([key, count]) => {
                const safeCount = toSafeInt(count);
                if (safeCount <= 0) return;
                const itemDef = (ALL_ITEMS as ItemRecord)[key]
                    ?? (KEY_ITEMS as ItemRecord)[key]
                    ?? { name: key, icon: '[item]' };
                const iconHTML = getItemIconHTML(itemDef) || coerceStr(itemDef.icon, '[item]');
                const itemName = getQuestLocalizedItemName(game, key, itemDef);
                rewardParts.push(`<span class="quest-reward-item">${iconHTML} ${safeCount}x ${escapeQuestHtml(itemName || key)}</span>`);
            });
        }

        const autoSlotsReward = toSafeInt(quest.rewards.unlocks && quest.rewards.unlocks.autoIncubatorSlots);
        if (autoSlotsReward > 0) {
            rewardParts.push(`<span class="quest-reward-item">+${autoSlotsReward} ${escapeQuestHtml(questUiText(game, 'rewardAutoIncubatorLabel', 'incubateur auto'))}</span>`);
        }

        if (quest.rewards.eggs) {
            Object.entries(quest.rewards.eggs).forEach(([rarity, count]) => {
                const safeCount = toSafeInt(count);
                if (safeCount <= 0) return;
                const rarityKey = String(rarity || '').toLowerCase();
                const eggSprite = (eggSpriteByRarity as Record<string, string>)[rarityKey] || eggSpriteByRarity.common;
                const safeRarity = escapeQuestHtml(rarity);
                const eggLabel = escapeQuestHtml(questUiText(game, 'rewardEggLabel', 'Oeuf'));
                rewardParts.push(`<span class="quest-reward-item"><img src="${eggSprite}" class="quest-reward-inline-img quest-reward-egg" alt="${eggLabel} ${safeRarity}"> ${safeCount}x ${eggLabel} ${safeRarity}</span>`);
            });
        }

        rewardsHTML = rewardParts.join('');
    }

    let actionsHTML = '';
    if (!safeQuestId) {
        actionsHTML = `<div class="quest-actions" style="color:#94a3b8;font-size:12px;">${escapeQuestHtml(questUiText(game, 'invalidQuestData', 'Quest data invalid - action disabled.'))}</div>`;
    } else if (!quest.accepted) {
        actionsHTML = `<div class="quest-actions"><button class="quest-btn btn-accept" data-action="acceptQuest" data-arg="${safeQuestId}">${escapeQuestHtml(questUiText(game, 'accept', 'Accepter'))}</button><button class="quest-btn btn-refuse" data-action="refuseQuest" data-arg="${safeQuestId}">${escapeQuestHtml(questUiText(game, 'refuse', 'Refuser'))}</button></div>`;
    } else if (quest.completed) {
        actionsHTML = `<button class="quest-btn btn-claim" data-action="showQuestCompletionModal" data-arg="${safeQuestId}">${escapeQuestHtml(questUiText(game, 'claim', 'Recuperer'))}</button>`;
    } else if (quest.questType !== 'STORY' && quest.questType !== 'TEAM_ROCKET') {
        actionsHTML = `<button class="quest-btn btn-refuse" style="width:100%;" data-action="abandonQuest" data-arg="${safeQuestId}">${escapeQuestHtml(questUiText(game, 'abandon', 'Abandonner'))}</button>`;
    } else {
        actionsHTML = `<div class="quest-actions" style="color:#94a3b8;font-size:12px;">${escapeQuestHtml(questUiText(game, 'storyNotAbandonable', 'Quete scenario - non abandonnable'))}</div>`;
    }

    const dialogueBlock = (displayDialogue && displayDialogue !== displayDescription)
        ? `<div class="quest-dialogue" style="color:#555;font-style:italic;margin:6px 0;font-size:12px;">"${displayDialogue}"</div>`
        : '';
    // Species roster grid (multi_species_captured quests : Safari Zones, Lake Trio, Dialga/Palkia, etc.)
    let speciesGridHTML = '';
    if (quest.trackingKey === 'multi_species_captured'
        && quest.specialParams
        && Array.isArray(quest.specialParams.requiredSpeciesList)
        && quest.specialParams.requiredSpeciesList.length > 0) {
        const list = quest.specialParams.requiredSpeciesList;
        const captured = Array.isArray(quest.specialParams.capturedSpecies) ? quest.specialParams.capturedSpecies : [];
        const capturedSet = new Set(captured.map(String));
        const cells = list.map(species => {
            const isCaught = capturedSet.has(String(species));
            const spriteUrl = getPokemonSpriteUrl(species, false, false);
            const displayName = uiPokemonName(game, species) || escapeQuestHtml(species);
            const stateClass = isCaught ? 'is-caught' : 'is-missing';
            const tickHTML = isCaught ? '<span class="quest-species-tick">✓</span>' : '';
            return questSpeciesCellHtml(stateClass, displayName, spriteUrl, tickHTML);
        }).join('');
        speciesGridHTML = `<div class="quest-species-grid">${cells}</div>`;
    } else if (quest.trackingKey === 'uniqueSpeciesOwned'
        && quest.specialParams
        && quest.specialParams.pokedexMissingPreview) {
        const maxDex = getQuestMaxNationalDex(quest);
        if (maxDex > 0) {
            const list = buildPokedexMissingSpeciesSnapshot(game, maxDex);
            if (list.length > 0) {
                const cells = list.map(function (species) {
                    const spriteUrl = getPokemonSpriteUrl(species, false, false);
                    const displayName = uiPokemonName(game, species) || String(species);
                    return questSpeciesCellHtml('is-missing', displayName, spriteUrl, '');
                }).join('');
                const caption = escapeQuestHtml(questUiText(
                    game,
                    'pokedexMissingPreviewCaption',
                    'Espèces qu\'il vous reste à posséder (équipe, stockage, pension, expéditions, ferme Miltank)',
                ));
                speciesGridHTML = `<div class="quest-pokedex-missing-caption">${caption}</div><div class="quest-species-grid quest-pokedex-missing-preview">${cells}</div>`;
            }
        }
    }

    const repeatBadge = getQuestRepeatBadgeDisplay(game, quest);
    const repeatBadgeHTML = repeatBadge
        ? `<span class="quest-repeat-badge" title="${escapeQuestHtml(repeatBadge.title)}">${escapeQuestHtml(repeatBadge.text)}</span>`
        : '';

    const ivProgressHTML = !speciesGridHTML ? buildStoryQuestIvProgressHTML(game, quest) : '';
    const extraContent = speciesGridHTML || ivProgressHTML;
    const questExtraHTML = extraContent
        ? `<!-- quest-extra -->${extraContent}<!-- /quest-extra -->`
        : '';

    return `
        <div class="quest-header"><div class="quest-badge ${badgeClass}">${safeBadgeText}</div><h4 class="quest-title"><span class="quest-title-text">${displayTitle}</span>${repeatBadgeHTML}</h4></div>
        <div class="quest-description">${displayDescription}</div>${dialogueBlock}
        <div class="quest-progress-container"><div class="quest-progress-bar"><div class="quest-progress-fill" style="width: ${percent}%"></div></div><div class="quest-progress-text">${resolveFormatNumber(current)} / ${resolveFormatNumber(target)}</div></div>
        ${questExtraHTML}
        <div class="quest-rewards">${rewardsHTML}</div>${actionsHTML}
    `;
}
/** Lazy via busPublishLazy — avoids questSystem ↔ publishHooks ↔ questSnapshot circular init. */
function publishQuestsPanelChanged(_game: GameRuntime): void {
    publishQuestsChangedLazy();
}

export function findScrollableAncestor(el: HTMLElement | null | undefined): HTMLElement | Element | null {
    let node = el && el.parentElement ? el.parentElement : null;
    while (node) {
        const style = (typeof window !== 'undefined' && window.getComputedStyle) ? window.getComputedStyle(node) : null;
        const overflowY = style ? style.overflowY : '';
        if ((overflowY === 'auto' || overflowY === 'scroll') && node.scrollHeight > node.clientHeight) {
            return node;
        }
        node = node.parentElement;
    }
    return document.scrollingElement || document.documentElement;
}

export function updateQuestsDisplayLogic(game: GameRuntime): void {
    cancelPendingQuestsDisplayRefresh();
    const questContainer = document.getElementById('questContainer');
    const questCount = document.getElementById('questCount');
    const questTokens = document.getElementById('questTokens');
    const questCompleted = document.getElementById('questCompleted');
    const classicHeaderBlock = questCount ? questCount.closest('[data-unlock-key="classicQuests"]') : null;
    const classicUnlocked = !!(game.unlockedFeatures && game.unlockedFeatures.classicQuests);

    // Always publish for Svelte QuestPanel (lazy mount may not have #questContainer yet).
    publishQuestsPanelChanged(game);

    if (!questContainer) return;

    if (questTokens) questTokens.textContent = String(game.questTokens);
    if (questCompleted) questCompleted.textContent = String(game.questsCompleted);

    if (classicHeaderBlock) {
        (classicHeaderBlock as HTMLElement).style.display = classicUnlocked ? '' : 'none';
    }

    if (typeof game.updateTabBadges === 'function') game.updateTabBadges();
    if (typeof updateQuestObjectiveHighlights === 'function') updateQuestObjectiveHighlights(game);
}

/** One-shot mobile Extras navigation per story quest id (not re-run after each combat win). */
let mobileExtrasNavigatedForQuestId: string | null = null;

export function resetMobileExtrasNavigatedForQuest(): void {
    mobileExtrasNavigatedForQuestId = null;
}

/** Whether mobile should switch to Extras for this story quest (one shot; skips if already on Extras). */
export function shouldSwitchMobileExtrasForQuest(
    activeQuestId: string | number,
    lastNavigatedForQuestId: string | null,
    isExtrasPanelActive: boolean,
): boolean {
    return lastNavigatedForQuestId !== String(activeQuestId) && !isExtrasPanelActive;
}

/**
 * Met en valeur les ?l?ments UI li?s ? l'objectif de la premi?re qu?te sc?nario active (accepted, non compl?t?e).
 * Utilise QUEST_OBJECTIVE_HINTS pour appliquer la classe .quest-objective-highlight aux bons ?l?ments.
 */
export function updateQuestObjectiveHighlights(game: GameRuntime): void {
    withUiScrollPreserve(() => {
        document.querySelectorAll('.quest-objective-highlight').forEach(function (el) {
            el.classList.remove('quest-objective-highlight');
        });

        if (!game || !game.quests) {
            resetMobileExtrasNavigatedForQuest();
            return;
        }

        const activeStory = game.quests.find(function (q) {
            return q.questType === 'STORY' && q.accepted && !q.completed && !q.claimed;
        });
        if (!activeStory || !QUEST_OBJECTIVE_HINTS_MAP[activeStory.id]) {
            resetMobileExtrasNavigatedForQuest();
            return;
        }

        const selectors = QUEST_OBJECTIVE_HINTS_MAP[activeStory.id];
        if (!selectors) return;

        const secondaryContent = document.getElementById('secondaryContent');
        if (isMobileViewport() && secondaryContent) {
            const needsExtrasPanel = selectors.some((selector) => {
                try {
                    return Array.from(document.querySelectorAll(selector)).some(
                        (node) => secondaryContent.contains(node),
                    );
                } catch {
                    return false;
                }
            });
            if (needsExtrasPanel) {
                const questKey = String(activeStory.id);
                const isExtrasActive = secondaryContent.classList.contains('mobile-active');
                if (shouldSwitchMobileExtrasForQuest(activeStory.id, mobileExtrasNavigatedForQuestId, isExtrasActive)) {
                    switchMobilePanel('extras');
                    requestAnimationFrame(() => refreshTabsContainerScrollStates());
                }
                if (mobileExtrasNavigatedForQuestId !== questKey) {
                    mobileExtrasNavigatedForQuestId = questKey;
                }
            }
        }

        for (let i = 0; i < selectors.length; i++) {
            const selector = selectors[i];
            if (selector === undefined) continue;
            try {
                const nodes = document.querySelectorAll(selector);
                nodes.forEach(function (node) {
                    if (!node?.classList) return;
                    node.classList.add('quest-objective-highlight');
                    // Ne pas scrollIntoView ici : après chaque combat checkSpecialQuests
                    // remontait les panneaux (team-area / extras) en haut.
                    if (node instanceof HTMLElement && !isElementVisibleForScroll(node)) return;
                });
            } catch (e) {
                debugWarn('Quest objective hint selector invalid:', selector, e);
            }
        }
    });
}

registerQuestsDisplayRefresh(updateQuestsDisplayLogic);
