/**
 * Hooks combat pour la méga-évolution : persistance au switch et timer actif uniquement en `fighting`.
 */
import type { GameRuntime } from '../types/game.ts';
import type { CreatureData, ICreature } from '../types/creature.ts';
import { transferDynamaxHpScale } from './dynamaxCombat.ts';

type MegaCreature = ICreature & {
    _megaStatsSourceName?: string | null;
    pauseMegaEvolutionTimer?(now?: number): void;
    resumeMegaEvolutionTimer?(now?: number): void;
    recalculateStats?(): void;
};

/** Pause le timer du Pokémon sortant, reprend celui du rentrant si méga actif. */
export function onCombatActiveCreatureChanged(
    game: GameRuntime,
    prev: MegaCreature | null | undefined,
    next: MegaCreature | null | undefined,
): void {
    const now = Date.now();
    if (prev && prev !== next && typeof prev.pauseMegaEvolutionTimer === 'function') {
        prev.pauseMegaEvolutionTimer(now);
    }
    if (next?._megaStatsSourceName && typeof next.resumeMegaEvolutionTimer === 'function') {
        if (game.combatState === 'fighting') {
            next.resumeMegaEvolutionTimer(now);
        }
    }
    if (typeof game.invalidateStatsCache === 'function') game.invalidateStatsCache();
    if (next && typeof next.recalculateStats === 'function') next.recalculateStats();
    // After recalculateStats so Dynamax HP scale is not wiped by base maxHp rewrite.
    transferDynamaxHpScale(
        game,
        prev,
        next,
    );
}

/** Aligne pause/reprise du timer méga sur combatState (fighting = actif). */
export function syncMegaTimerWithCombatState(game: GameRuntime): void {
    const c = game.currentPlayerCreature as MegaCreature | null | undefined;
    if (!c?._megaStatsSourceName) return;
    const now = Date.now();
    if (game.combatState === 'fighting') {
        if (typeof c.resumeMegaEvolutionTimer === 'function') c.resumeMegaEvolutionTimer(now);
    } else if (typeof c.pauseMegaEvolutionTimer === 'function') {
        c.pauseMegaEvolutionTimer(now);
    }
}
