/**
 * Typed DOM lookups shared by mixins and Svelte bridges.
 */

export function getById<T extends HTMLElement = HTMLElement>(id: string): T | null {
  const el = document.getElementById(id);
  return el instanceof HTMLElement ? (el as T) : null;
}

export function requireById<T extends HTMLElement = HTMLElement>(id: string): T {
  const el = getById<T>(id);
  if (!el) throw new Error(`[dom] Missing element #${id}`);
  return el;
}

export function getInput(id: string): HTMLInputElement | null {
  const el = document.getElementById(id);
  return el instanceof HTMLInputElement ? el : null;
}

export function getSelect(id: string): HTMLSelectElement | null {
  const el = document.getElementById(id);
  return el instanceof HTMLSelectElement ? el : null;
}
