/**
 * @file src/lib/recyclerSnapshot.ts
 * Structured snapshots for the Recycler shop sub-tabs.
 */

import { RARITY, POKEMON_POOL } from '../../constants/core.ts';
import { DUST_SHOP_ITEMS, DUST_CONVERSION_RATES } from '../../constants/balance/pokemartDust.ts';
import { ACCOUNT_TALENTS } from '../../constants/balance/arenasTrainers.ts';
import type { GameRuntime } from '../types/game.js';
import type { UpgradeState } from '../types/game/state.js';
import type {
  DustShopOfferSnapshot,
  RecyclerShardSnapshot,
  RecyclerSnapshot,
} from '../bus/snapshots.js';
import { getPokemonSpriteUrl } from './cardSprites.ts';
import { uiDataText, uiPokemonName, uiText } from '../ui/i18n.ts';
import { formatNumber } from '../../formatters.ts';
import { getAllItem } from '../ui/uiItems.ts';
import { getItemIconHTML } from '../ui/utils.ts';
import { getDustShopItemCost, getNextEscalatingDustShopCost, isEscalatingDustShopKey } from './dustShopCost.ts';

interface DustShopEntry {
  id: string;
  name: string;
  description: string;
  cost: number;
  icon?: string;
  img?: string;
  type?: string;
  item?: string;
  requiredBadge?: string;
  requiresRadar?: boolean;
  escalatingCost?: boolean;
}

interface DustLinkedUpgrade extends UpgradeState {
  dustCosts?: number[];
  cooldownSecs?: number[];
  reductionSecs?: number[];
  msValues?: number[];
}

const dustShopEntries = DUST_SHOP_ITEMS as Record<string, DustShopEntry>;

function uiT(
  game: GameRuntime,
  key: string,
  fallback: string,
  vars: Record<string, unknown> = {},
): string {
  return uiText(key, fallback, vars, game);
}

function poolHasFamily(
  pool: Record<string, string[] | undefined> | undefined,
  familyName: string,
): boolean {
  if (!pool) return false;
  for (const typeKey in pool) {
    const entries = pool[typeKey];
    if (entries?.includes(familyName)) return true;
  }
  return false;
}

function getFamilyRarity(familyName: string): string {
  try {
    if (poolHasFamily(POKEMON_POOL[RARITY.COMMON], familyName)) return RARITY.COMMON;
    if (poolHasFamily(POKEMON_POOL[RARITY.RARE], familyName)) return RARITY.RARE;
    if (poolHasFamily(POKEMON_POOL[RARITY.EPIC], familyName)) return RARITY.EPIC;
    if (poolHasFamily(POKEMON_POOL[RARITY.LEGENDARY], familyName)) return RARITY.LEGENDARY;
  } catch {
    return 'common';
  }
  return 'common';
}

function buildRecyclerShards(
  game: GameRuntime,
  query: string,
  sortMode: string,
  sortDir: 'asc' | 'desc',
): { shards: RecyclerShardSnapshot[]; empty: string | null } {
  const rarityOrder: Record<string, number> = {
    [RARITY.COMMON]: 0,
    [RARITY.RARE]: 1,
    [RARITY.EPIC]: 2,
    [RARITY.LEGENDARY]: 3,
  };

  const rows: RecyclerShardSnapshot[] = [];

  Object.entries(game.shards || {}).forEach(([shardKey, rawCount]) => {
    const count = Math.max(0, Number(rawCount) || 0);
    if (count <= 0) return;
    const familyName = shardKey;
    if (query && !familyName.toLowerCase().includes(query)) return;

    const rarity = getFamilyRarity(familyName);
    const baseRate = DUST_CONVERSION_RATES[rarity as keyof typeof DUST_CONVERSION_RATES] ?? 1;
    const masteryDust = typeof game.getMasteryBonus === 'function'
      ? ((game.getMasteryBonus('dust_mult') || 0)
        + (game.getMasteryBonus('recycle_efficiency') || 0)
        + (game.getMasteryBonus('duplicate_value') || 0))
      : 0;
    const dustPerUnit = baseRate * (1 + masteryDust);
    const dustValue = Math.floor(count * dustPerUnit);

    rows.push({
      shardKey,
      familyName,
      displayName: uiPokemonName(game, familyName),
      spriteUrl: getPokemonSpriteUrl(familyName, false),
      rarity,
      count,
      countFormatted: formatNumber(count),
      dustValue,
      dustValueFormatted: formatNumber(dustValue),
      dustPerUnit,
      isProtected: Array.isArray(game.protectedShards) && game.protectedShards.includes(shardKey),
    });
  });

  if (sortMode === 'count') {
    rows.sort((a, b) => {
      if (b.count !== a.count) {
        const base = b.count - a.count;
        return sortDir === 'asc' ? -base : base;
      }
      const ra = rarityOrder[a.rarity] ?? 0;
      const rb = rarityOrder[b.rarity] ?? 0;
      if (rb !== ra) {
        const baseR = rb - ra;
        return sortDir === 'asc' ? -baseR : baseR;
      }
      return a.familyName.localeCompare(b.familyName);
    });
  } else {
    rows.sort((a, b) => {
      const ra = rarityOrder[a.rarity] ?? 0;
      const rb = rarityOrder[b.rarity] ?? 0;
      if (rb !== ra) {
        const baseR = rb - ra;
        return sortDir === 'asc' ? -baseR : baseR;
      }
      return a.familyName.localeCompare(b.familyName);
    });
  }

  const empty = rows.length === 0
    ? uiT(game, 'shop.recyclerNoShards', 'No shards to recycle.')
    : null;

  return { shards: rows, empty };
}

function resolveBadgeLock(
  game: GameRuntime,
  item: DustShopEntry,
): { lockedByBadge: boolean; lockedBadgeLabel: string | null } {
  if (!item.requiredBadge) {
    return { lockedByBadge: false, lockedBadgeLabel: null };
  }
  const hasBadge = typeof game.hasBadge === 'function' && game.hasBadge(item.requiredBadge);
  if (hasBadge) {
    return { lockedByBadge: false, lockedBadgeLabel: null };
  }
  const fallbackName = (ACCOUNT_TALENTS as Record<string, { name?: string }>)[item.requiredBadge]?.name
    ?? item.requiredBadge;
  const label = typeof game.getLocalizedAccountTalentName === 'function'
    ? game.getLocalizedAccountTalentName(item.requiredBadge, fallbackName)
    : fallbackName;
  return { lockedByBadge: true, lockedBadgeLabel: label };
}

function resolveRadarLock(
  game: GameRuntime,
  item: DustShopEntry,
): { lockedByRadar: boolean; lockedRadarLabel: string | null } {
  if (!item.requiresRadar) {
    return { lockedByRadar: false, lockedRadarLabel: null };
  }
  const hasRadar = typeof game.getMasteryBonus === 'function'
    && (game.getMasteryBonus('pokedex_radar') || 0) > 0;
  if (hasRadar) {
    return { lockedByRadar: false, lockedRadarLabel: null };
  }
  return {
    lockedByRadar: true,
    lockedRadarLabel: uiT(game, 'shop.dustRadarRequired', 'Requires Pokédex Radar mastery'),
  };
}

function buildDustShopOffers(game: GameRuntime): DustShopOfferSnapshot[] {
  if (!DUST_SHOP_ITEMS) return [];

  const offers: DustShopOfferSnapshot[] = [];
  const buyLabel = uiT(game, 'shop.buy', 'Buy');
  const maxLabel = uiT(game, 'shop.maxed', 'MAX');

  Object.entries(dustShopEntries).forEach(([dustKey, item]) => {
    if (item.id === 'shiny_egg') return;

    const i18nKey = String(item.id || dustKey || '');
    const displayName = uiDataText(game, 'dustShop', i18nKey, 'name', item.name);
    let displayDescription = uiDataText(game, 'dustShop', i18nKey, 'description', item.description);
    const badgeLock = resolveBadgeLock(game, item);
    const radarLock = resolveRadarLock(game, item);
    const baseCost = Math.floor(Number(item.cost) || 0);
    const dynamicCost = getDustShopItemCost(baseCost, dustKey, game.dustShopPurchaseCounts);
    let costHintLine: string | null = null;
    if (isEscalatingDustShopKey(dustKey)) {
      const nextCost = getNextEscalatingDustShopCost(baseCost, dustKey, game.dustShopPurchaseCounts);
      costHintLine = uiT(game, 'shop.dustEscalatingCostHint', 'Price increases by 10% per purchase. Next purchase: {nextCost} Dust.', {
        nextCost: formatNumber(nextCost),
      });
    }

    if (item.type === 'upgrade') {
      const upg = game.upgrades?.[item.id] as DustLinkedUpgrade | undefined;
      if (!upg) return;

      const level = upg.level || 0;
      const isMaxed = level >= upg.maxLevel;
      const nextCost = isMaxed ? 0 : (upg.dustCosts && upg.dustCosts[level + 1]) || 0;
      const canAfford = !isMaxed && game.essenceDust >= nextCost && !badgeLock.lockedByBadge && !radarLock.lockedByRadar;

      const hasAutoClick = upg.cooldownSecs != null && upg.reductionSecs != null;
      const currentCD = upg.cooldownSecs?.[level] ?? 0;
      const nextCD = hasAutoClick && !isMaxed ? (upg.cooldownSecs?.[level + 1] ?? 0) : 0;
      const currentReduc = upg.reductionSecs?.[level] ?? 0;
      const nextReduc = hasAutoClick && !isMaxed ? (upg.reductionSecs?.[level + 1] ?? 0) : 0;
      const currentMs = hasAutoClick ? 0 : ((upg.msValues && upg.msValues[level]) || 1);
      const nextMs = (isMaxed || hasAutoClick) ? 0 : ((upg.msValues && upg.msValues[level + 1]) || 0);

      const levelLine = hasAutoClick
        ? uiT(game, 'shop.dustUpgradeLevelAuto', 'Lvl {level}/{max} — CD: {cd}s | Reduction: -{reduc}s', {
          level,
          max: upg.maxLevel,
          cd: currentCD,
          reduc: currentReduc,
        })
        : uiT(game, 'shop.dustUpgradeLevelMs', 'Lvl {level}/{max} — Current: -{ms}ms', {
          level,
          max: upg.maxLevel,
          ms: currentMs,
        });
      const nextLevelLine = !isMaxed
        ? (hasAutoClick
          ? uiT(game, 'shop.dustUpgradeNextAuto', 'Next: Lvl {level} → CD: {cd}s | Reduction: -{reduc}s', {
            level: level + 1,
            cd: nextCD,
            reduc: nextReduc,
          })
          : uiT(game, 'shop.dustUpgradeNextMs', 'Next: Lvl {level} → -{ms}ms', {
            level: level + 1,
            ms: nextMs,
          }))
        : null;

      offers.push({
        id: item.id,
        displayName,
        description: displayDescription,
        iconHtml: '',
        ownedCountFormatted: null,
        costFormatted: isMaxed ? maxLabel : formatNumber(nextCost),
        canBuy: canAfford,
        isMaxed,
        isUpgrade: true,
        buttonLabel: isMaxed ? maxLabel : buyLabel,
        levelLine,
        nextLevelLine,
        lockedByBadge: badgeLock.lockedByBadge,
        lockedBadgeLabel: badgeLock.lockedBadgeLabel,
        costHintLine: null,
      });
      return;
    }

    const alreadyOwned = (item.id === 'auto_catcher' && !!game.hasAutoCatcher)
      || (item.id === 'radar_slot_plus' && (game.dustShopRadarSlotBonus || 0) > 0);
    const isMaxed = alreadyOwned;
    const isLocked = badgeLock.lockedByBadge || radarLock.lockedByRadar;
    const canAfford = !isMaxed && game.essenceDust >= dynamicCost && !isLocked;

    const linkedItemDef = (item.type === 'item' && item.item)
      ? (getAllItem(item.item) ?? null)
      : null;
    const displayItem = linkedItemDef
      ? { ...item, img: linkedItemDef.img || item.img, icon: linkedItemDef.icon || item.icon }
      : item;
    const iconSourceItem = linkedItemDef || displayItem;
    const iconHTML = getItemIconHTML(iconSourceItem) || (item.icon || 'OBJ');

    let ownedCount = 0;
    if (item.id === 'talent_reroll') {
      ownedCount = Math.max(0, Number(game.talentRerolls) || 0);
    } else if (item.id === 'talent_choice') {
      ownedCount = Math.max(0, Number(game.talentChoices) || 0);
    } else if (item.type === 'item' && item.item) {
      ownedCount = Math.max(0, Number((game.items && game.items[item.item]) || 0));
    }

    let buttonLabel = buyLabel;
    if (isMaxed) buttonLabel = maxLabel;
    else if (radarLock.lockedByRadar && radarLock.lockedRadarLabel) {
      buttonLabel = radarLock.lockedRadarLabel;
    } else if (badgeLock.lockedByBadge && badgeLock.lockedBadgeLabel) {
      buttonLabel = badgeLock.lockedBadgeLabel;
    }

    offers.push({
      id: item.id,
      displayName,
      description: displayDescription,
      iconHtml: iconHTML,
      ownedCountFormatted: uiT(game, 'shop.ownedCount', 'Owned: {count}', {
        count: formatNumber(ownedCount),
      }),
      costFormatted: formatNumber(dynamicCost),
      canBuy: canAfford,
      isMaxed,
      isUpgrade: false,
      buttonLabel,
      levelLine: null,
      nextLevelLine: null,
      lockedByBadge: badgeLock.lockedByBadge || radarLock.lockedByRadar,
      lockedBadgeLabel: radarLock.lockedByRadar
        ? radarLock.lockedRadarLabel
        : badgeLock.lockedBadgeLabel,
      costHintLine,
    });
  });

  return offers;
}

export function buildRecyclerSnapshot(game: GameRuntime): RecyclerSnapshot {
  const searchInput = typeof document !== 'undefined'
    ? document.getElementById('recyclerSearchInput')
    : null;
  const query = (searchInput instanceof HTMLInputElement && searchInput.value)
    ? searchInput.value.toLowerCase().trim()
    : '';
  const sortMode = game.recyclerSortMode || 'rarity';
  const sortDir = game.recyclerSortDir === 'asc' ? 'asc' : 'desc';

  const { shards, empty } = buildRecyclerShards(game, query, sortMode, sortDir);

  return {
    recyclerShards: shards,
    recyclerDustOffers: buildDustShopOffers(game),
    recyclerShardsEmpty: empty,
    essenceDust: formatNumber(game.essenceDust),
    recyclerSortRarityActive: sortMode === 'rarity',
    recyclerSortCountActive: sortMode === 'count',
  };
}
