/**
 * Classic "Quality Catch" quests: pick a wild species the player can actually encounter.
 */
import { ZONES, ZONE_POKEMON } from '../../constants/balance/zonesAndPacing.js';
import type { GameRuntime } from '../types/game.js';
import { isRegionReleased } from '../../constants/balance/regionRelease.ts';
import {
    getReachablePokemonInZoneLogic,
    isNaturalLegendarySpeciesForZoneLogic,
    isZoneUnlockedLogic,
} from '../../zoneSystem.ts';
import { getSortedZoneIdsForRegion } from './regionProgressCap.ts';
import { isRegionUnlockedForGame } from './regionUnlock.ts';
import { arrayAt } from './safeAccess.ts';

const REGION_ORDER_FOR_NAVIGATION = ['kanto', 'johto', 'hoenn', 'sinnoh', 'unova', 'kalos', 'alola', 'galar', 'paldea']
    .filter((id) => isRegionReleased(id));

function getRegionOrderIndex(regionId: string): number {
    const idx = REGION_ORDER_FOR_NAVIGATION.indexOf(String(regionId || ''));
    return idx >= 0 ? idx : 999;
}

function collectAllKnownZoneIds(): number[] {
    const ids = new Set<number>();
    for (const key of Object.keys(ZONES)) {
        const n = Number(key);
        if (Number.isFinite(n) && n > 0) ids.add(n);
    }
    if (ZONE_POKEMON) {
        for (const key of Object.keys(ZONE_POKEMON)) {
            const n = Number(key);
            if (Number.isFinite(n) && n > 0) ids.add(n);
        }
    }
    return [...ids];
}

function getZoneProgressionSortKey(zoneId: number): [number, number, number] {
    const z = ZONES[zoneId as keyof typeof ZONES] as { regionId?: string; regionOrder?: number } | undefined;
    const regionId = z?.regionId ? String(z.regionId) : getZoneRegionId(zoneId);
    const regionOrder = z && Number.isFinite(Number(z.regionOrder)) ? Number(z.regionOrder) : zoneId;
    return [getRegionOrderIndex(regionId), regionOrder, zoneId];
}

function isZoneUnlockedForGame(game: GameRuntime, zoneId: number): boolean {
    if (typeof game.isZoneUnlocked === 'function') {
        return game.isZoneUnlocked(zoneId, true);
    }
    return isZoneUnlockedLogic(game, zoneId, true);
}

function getZoneRegionId(zoneId: number): string {
    const zone = ZONES[zoneId as keyof typeof ZONES] as { regionId?: string } | undefined;
    return zone?.regionId ? String(zone.regionId) : 'kanto';
}

function collectRegionIdsFromZones(): string[] {
    const regions = new Set<string>();
    for (const key of Object.keys(ZONES)) {
        const zoneId = Number(key);
        if (!Number.isFinite(zoneId) || zoneId <= 0) continue;
        regions.add(getZoneRegionId(zoneId));
    }
    return [...regions];
}

function getMaxReachedZoneForRegion(game: GameRuntime, regionId: string): number {
    const store = game.maxReachedZoneByRegion;
    if (store && typeof store === 'object') {
        const fromStore = Math.floor(Number(store[regionId]));
        if (Number.isFinite(fromStore) && fromStore > 0) return fromStore;
    }
    if (regionId === 'kanto') {
        const legacy = Math.floor(Number(game.maxReachedZone));
        if (Number.isFinite(legacy) && legacy > 0) return legacy;
        const current = Math.floor(Number(game.currentZone));
        if (Number.isFinite(current) && current > 0) return current;
    }
    return 0;
}

/** Zones the player has organically reached (per region story order), still subject to unlock checks. */
export function getProgressionCappedZoneIdsForGame(game: GameRuntime): number[] {
    const out: number[] = [];
    const seen = new Set<number>();

    for (const regionId of collectRegionIdsFromZones()) {
        if (!isRegionUnlockedForGame(game, regionId)) continue;

        const sorted = getSortedZoneIdsForRegion(regionId);
        if (!sorted.length) continue;

        const maxReached = getMaxReachedZoneForRegion(game, regionId);
        let capped: number[];
        if (maxReached > 0) {
            const maxIdx = sorted.indexOf(maxReached);
            capped = maxIdx >= 0
                ? sorted.slice(0, maxIdx + 1)
                : sorted.filter((zoneId) => zoneId <= maxReached);
        } else {
            const first = arrayAt(sorted, 0);
            capped = first != null ? [first] : [];
        }

        for (const zoneId of capped) {
            if (seen.has(zoneId)) continue;
            if (!isZoneUnlockedForGame(game, zoneId)) continue;
            seen.add(zoneId);
            out.push(zoneId);
        }
    }

    return out;
}

/** All unlocked zones in accessible released regions, sorted by regional progression. */
export function getUnlockedZoneIdsForClassicQuestPool(game: GameRuntime): number[] {
    const matches: number[] = [];
    for (const zoneId of collectAllKnownZoneIds()) {
        if (!isZoneUnlockedForGame(game, zoneId)) continue;
        const regionId = getZoneRegionId(zoneId);
        if (!isRegionReleased(regionId)) continue;
        if (!isRegionUnlockedForGame(game, regionId)) continue;
        matches.push(zoneId);
    }

    matches.sort((a, b) => {
        const ka = getZoneProgressionSortKey(a);
        const kb = getZoneProgressionSortKey(b);
        for (let i = 0; i < 3; i++) {
            if (ka[i] !== kb[i]) return ka[i]! - kb[i]!;
        }
        return 0;
    });

    return matches;
}

function addSpeciesFromZone(
    game: GameRuntime,
    zoneId: number,
    names: Set<string>,
): void {
    const pool = getReachablePokemonInZoneLogic(game, zoneId);
    for (const species of pool) {
        if (!species) continue;
        if (isNaturalLegendarySpeciesForZoneLogic(game, species)) continue;
        names.add(species);
    }
}

/** Union of wild species encounterable in unlocked zones (surf/fishing gated by inventory). */
const reachableWildSpeciesCache = new WeakMap<GameRuntime, ReadonlySet<string>>();

export function getPlayerReachableWildSpecies(game: GameRuntime): ReadonlySet<string> {
    const cached = reachableWildSpeciesCache.get(game);
    if (cached) return cached;

    const names = new Set<string>();
    for (const zoneId of getUnlockedZoneIdsForClassicQuestPool(game)) {
        addSpeciesFromZone(game, zoneId, names);
    }
    reachableWildSpeciesCache.set(game, names);
    return names;
}

export function isSpeciesReachableForPlayer(game: GameRuntime, speciesName: string): boolean {
    const species = String(speciesName || '').trim();
    if (!species) return false;
    return getPlayerReachableWildSpecies(game).has(species);
}

/** Lowest unlocked zone where the species can be encountered with current inventory. */
export function findLowestProgressionZoneForSpecies(game: GameRuntime, speciesName: string): number | null {
    const species = String(speciesName || '').trim();
    if (!species) return null;

    for (const zoneId of getUnlockedZoneIdsForClassicQuestPool(game)) {
        const pool = getReachablePokemonInZoneLogic(game, zoneId);
        if (pool.includes(species) && !isNaturalLegendarySpeciesForZoneLogic(game, species)) {
            return zoneId;
        }
    }
    return null;
}

/** Highest unlocked zone where the species can be encountered with current inventory. */
const highestZoneBySpeciesCache = new WeakMap<GameRuntime, Map<string, number | null>>();

export function invalidateHighestUnlockedZoneSpeciesCache(game: GameRuntime): void {
    highestZoneBySpeciesCache.delete(game);
    reachableWildSpeciesCache.delete(game);
}

export function findHighestUnlockedZoneForSpecies(game: GameRuntime, speciesName: string): number | null {
    const species = String(speciesName || '').trim();
    if (!species) return null;

    let perGame = highestZoneBySpeciesCache.get(game);
    if (!perGame) {
        perGame = new Map();
        highestZoneBySpeciesCache.set(game, perGame);
    }
    if (perGame.has(species)) return perGame.get(species) ?? null;

    const matches: number[] = [];
    for (const zoneId of collectAllKnownZoneIds()) {
        if (!isZoneUnlockedForGame(game, zoneId)) continue;
        const regionId = getZoneRegionId(zoneId);
        if (!isRegionReleased(regionId)) continue;
        const pool = getReachablePokemonInZoneLogic(game, zoneId);
        if (!pool.includes(species) || isNaturalLegendarySpeciesForZoneLogic(game, species)) continue;
        matches.push(zoneId);
    }

    if (matches.length === 0) {
        perGame.set(species, null);
        return null;
    }

    matches.sort((a, b) => {
        const ka = getZoneProgressionSortKey(a);
        const kb = getZoneProgressionSortKey(b);
        for (let i = 0; i < 3; i++) {
            if (ka[i] !== kb[i]) return ka[i]! - kb[i]!;
        }
        return 0;
    });

    const result = matches[matches.length - 1] ?? null;
    perGame.set(species, result);
    return result;
}

export function isClassicWildSpeciesIvCaptureEligible(game: GameRuntime): boolean {
    return getPlayerReachableWildSpecies(game).size > 0;
}

export type ClassicCapturePick = {
    species: string;
    zoneId: number;
};

export const RECENT_CLASSIC_QUALITY_CATCH_SPECIES_CAP = 8;

export type ClassicCapturePickOptions = {
    excludeSpecies?: Set<string>;
};

/** Classic daily quests use numeric ids; saves normalize them to numeric strings. */
export function isClassicDailyNumericQuestId(id: unknown): boolean {
    if (typeof id === 'number' && Number.isFinite(id)) return true;
    if (typeof id !== 'string') return false;
    const trimmed = id.trim();
    if (!trimmed || /^[a-zA-Z_]/.test(trimmed)) return false;
    return Number.isFinite(Number(trimmed));
}

export function isClassicQualityCatchQuest(quest: {
    questType?: string | null;
    trackingKey?: string;
    id?: string | number;
    specialParams?: { minIvPercent?: unknown } | null;
    claimed?: boolean;
} | null | undefined): boolean {
    if (!quest || quest.claimed) return false;
    if (quest.questType !== 'COLLECTION') return false;
    if (quest.trackingKey !== 'creature_captured') return false;
    const minIv = Number(quest.specialParams?.minIvPercent);
    if (!(Number.isFinite(minIv) && minIv > 0)) return false;
    return isClassicDailyNumericQuestId(quest.id);
}

export function getRecentClassicQualityCatchSpecies(game: GameRuntime): string[] {
    const raw = game.recentClassicQualityCatchSpecies;
    if (!Array.isArray(raw)) return [];
    const out: string[] = [];
    for (const entry of raw) {
        const species = String(entry || '').trim();
        if (species) out.push(species);
    }
    return out.slice(0, RECENT_CLASSIC_QUALITY_CATCH_SPECIES_CAP);
}

export function getActiveClassicQualityCatchSpecies(game: GameRuntime): Set<string> {
    const out = new Set<string>();
    if (!Array.isArray(game.quests)) return out;
    for (const quest of game.quests) {
        if (!isClassicQualityCatchQuest(quest)) continue;
        const species = typeof quest.requiredSpecies === 'string' ? quest.requiredSpecies.trim() : '';
        if (species) out.add(species);
    }
    return out;
}

export function getClassicQualityCatchExcludedSpecies(
    game: GameRuntime,
    options?: { exceptQuestId?: string | number },
): Set<string> {
    const out = new Set<string>();
    const exceptId = options?.exceptQuestId;

    if (Array.isArray(game.quests)) {
        for (const quest of game.quests) {
            if (exceptId != null && quest?.id == exceptId) continue;
            if (!isClassicQualityCatchQuest(quest)) continue;
            const species = typeof quest.requiredSpecies === 'string' ? quest.requiredSpecies.trim() : '';
            if (species) out.add(species);
        }
    }

    for (const species of getRecentClassicQualityCatchSpecies(game)) {
        out.add(species);
    }

    return out;
}

export function recordClassicQualityCatchSpeciesToHistory(game: GameRuntime, speciesName: string): void {
    const species = String(speciesName || '').trim();
    if (!species) return;
    if (!Array.isArray(game.recentClassicQualityCatchSpecies)) {
        game.recentClassicQualityCatchSpecies = [];
    }
    const history = game.recentClassicQualityCatchSpecies;
    if (history[0] === species) return;
    const filtered = history.filter((entry) => String(entry || '').trim() !== species);
    filtered.unshift(species);
    game.recentClassicQualityCatchSpecies = filtered.slice(0, RECENT_CLASSIC_QUALITY_CATCH_SPECIES_CAP);
}

export function pickReachableWildCaptureForClassicQuest(
    game: GameRuntime,
    options: ClassicCapturePickOptions = {},
): ClassicCapturePick | null {
    const fullPool = [...getPlayerReachableWildSpecies(game)];
    if (!fullPool.length) return null;

    const exclude = options.excludeSpecies;
    let pool = fullPool;
    if (exclude && exclude.size > 0) {
        const filtered = fullPool.filter((name) => !exclude.has(name));
        if (filtered.length > 0) pool = filtered;
    }

    const species = arrayAt(pool, Math.floor(Math.random() * pool.length));
    if (!species) return null;

    const zoneId = findLowestProgressionZoneForSpecies(game, species);
    if (zoneId == null) return null;

    return { species, zoneId };
}

export function pickReachableWildSpeciesForClassicQuest(
    game: GameRuntime,
    options: ClassicCapturePickOptions = {},
): string | null {
    return pickReachableWildCaptureForClassicQuest(game, options)?.species ?? null;
}

/** Re-roll or drop active classic Quality Catch quests with unreachable species. */
export function repairClassicQualityCatchQuestsForGame(game: GameRuntime): void {
    if (!Array.isArray(game.quests)) return;

    const next: typeof game.quests = [];
    for (let i = 0; i < game.quests.length; i++) {
        const quest = game.quests[i];
        if (!quest || !isClassicQualityCatchQuest(quest)) {
            next.push(quest);
            continue;
        }

        const requiredSpecies = typeof quest.requiredSpecies === 'string' ? quest.requiredSpecies : '';
        if (requiredSpecies && isSpeciesReachableForPlayer(game, requiredSpecies)) {
            const zoneId = findLowestProgressionZoneForSpecies(game, requiredSpecies);
            if (zoneId != null) {
                if (!quest.specialParams || typeof quest.specialParams !== 'object') {
                    quest.specialParams = {};
                }
                quest.specialParams.requiredZone = zoneId;
            }
            next.push(quest);
            continue;
        }

        const pick = pickReachableWildCaptureForClassicQuest(game, {
            excludeSpecies: getClassicQualityCatchExcludedSpecies(game, { exceptQuestId: quest.id }),
        });
        if (!pick) {
            next.push(quest);
            continue;
        }

        if (!quest.specialParams || typeof quest.specialParams !== 'object') {
            quest.specialParams = {};
        }
        quest.requiredSpecies = pick.species;
        quest.specialParams.requiredZone = pick.zoneId;
        next.push(quest);
    }

    game.quests = next;
}

/** Clears zone/species memoization when progression changes. */
export function _resetClassicCaptureQuestEligibilityCacheForTests(): void {
    // WeakMap caches are keyed by game instance; tests use fresh game objects.
}
