/**
 * Pure helpers for game.unlockedMoves (family move unlock registry).
 */
import { resolveMoveName, hasMoveDefinition, isDamagingMove } from '../../constants/movesDb.ts';
import {
    familyForSpecies,
    getFamilyNaturalMovesPool,
    isEeveeLineMember,
    moveUnlockKey,
} from './pokemonLearnset.ts';

export function canonUnlockRegistryKey(key: string): string {
    if (isEeveeLineMember(key)) return moveUnlockKey(key);
    return familyForSpecies(key);
}

export function normalizeUnlockedMoveList(sourceMoves: string[]): string[] {
    const seen = new Set<string>();
    const cleanedMoves: string[] = [];
    (sourceMoves || []).forEach((moveName: string) => {
        const resolvedMove = resolveMoveName(moveName);
        if (!resolvedMove || resolvedMove === 'Charge') return;
        if (!hasMoveDefinition(resolvedMove)) return;
        if (!isDamagingMove(resolvedMove)) return;
        if (seen.has(resolvedMove)) return;
        seen.add(resolvedMove);
        cleanedMoves.push(resolvedMove);
    });
    return cleanedMoves;
}

export function isMoveValidForRegistryKey(moveName: string, registryKey: string): boolean {
    const resolvedMove = resolveMoveName(moveName);
    if (!resolvedMove || resolvedMove === 'Charge') return false;
    if (!hasMoveDefinition(resolvedMove)) return false;
    if (!isDamagingMove(resolvedMove)) return false;
    const lineagePool = new Set(getFamilyNaturalMovesPool(registryKey));
    return lineagePool.has(resolvedMove);
}

/**
 * Union of persisted unlocked moves and currently equipped moves per registry key.
 * Never removes valid persisted entries.
 */
export function mergeUnlockedMovesRegistry(
    existing: Record<string, string[]> | null | undefined,
    equippedByRegistryKey: Record<string, string[]>,
): Record<string, string[]> {
    const mergedByCanon: Record<string, string[]> = {};

    const addToCanon = (rawKey: string, moves: string[]) => {
        const canon = canonUnlockRegistryKey(rawKey);
        if (!mergedByCanon[canon]) mergedByCanon[canon] = [];
        moves.forEach((moveName: string) => {
            if (!isMoveValidForRegistryKey(moveName, canon)) return;
            const resolvedMove = resolveMoveName(moveName)!;
            if (!mergedByCanon[canon].includes(resolvedMove)) {
                mergedByCanon[canon].push(resolvedMove);
            }
        });
    };

    if (existing && typeof existing === 'object') {
        Object.keys(existing).forEach((key: string) => {
            const raw = existing[key];
            if (!Array.isArray(raw) || raw.length === 0) return;
            addToCanon(key, raw);
        });
    }

    Object.keys(equippedByRegistryKey).forEach((key: string) => {
        const raw = equippedByRegistryKey[key];
        if (!Array.isArray(raw) || raw.length === 0) return;
        addToCanon(key, raw);
    });

    const result: Record<string, string[]> = {};
    Object.keys(mergedByCanon).forEach((canon: string) => {
        const moves = mergedByCanon[canon];
        if (!moves) return;
        result[canon] = normalizeUnlockedMoveList(moves);
    });
    return result;
}

/** True when a registry list is likely legacy-inflated (full learnset dump). */
export function shouldCompactInflatedUnlockedList(listLength: number, poolLen: number): boolean {
    if (listLength <= 0) return false;
    if (listLength > 64) return true;
    return poolLen > 0 && listLength > poolLen + 5;
}

/**
 * Compacts an inflated list to pool-valid moves, always preserving equipped moves.
 */
export function compactInflatedUnlockedMoveList(
    list: string[],
    poolSet: Set<string>,
    poolLen: number,
    equippedNorm: string[],
): string[] {
    let next = poolLen > 0 ? list.filter((m: string) => poolSet.has(m)) : list.slice();
    next = normalizeUnlockedMoveList(next);
    const seen = new Set(next);
    equippedNorm.forEach((m: string) => {
        if (!seen.has(m)) {
            seen.add(m);
            next.push(m);
        }
    });
    next = normalizeUnlockedMoveList(next);
    if (poolLen > 0 && next.length > poolLen + 3) {
        next = normalizeUnlockedMoveList(next.filter((m: string) => poolSet.has(m)));
        equippedNorm.forEach((m: string) => {
            if (!next.includes(m)) next.unshift(m);
        });
        next = normalizeUnlockedMoveList(next).slice(0, poolLen + 3);
    }
    return next.length ? next : equippedNorm.slice();
}

/** Early capture path: sanitize only when a family entry is clearly legacy-bloated. */
export function isBulkyUnlockedRegistryEntry(listLength: number, poolLen: number): boolean {
    return shouldCompactInflatedUnlockedList(listLength, poolLen);
}
