/**
 * Species learnset display: natural pool vs CT-compatible moves.
 * Natural pools are shared across linear evolution families (e.g. Magikarp + Gyarados).
 * Eevee line uses lineage pools (Eevee + one evolution), not all eeveelutions combined.
 */
import { getDefaultMovesPool } from '../../constants/balance/pokemonDefaultsBase.ts';
import { EVOLUTION_FAMILIES } from '../../constants/evolutionFamilies.ts';
import { resolveMoveName, hasMoveDefinition, isDamagingMove } from '../../constants/movesDb.ts';

import { canLearnCT, getCtCompatibilityTable } from '../../constants/ctCompatibility.ts';
import { resolveCanonicalSpeciesName } from './rosterSpeciesAliases.ts';

export interface SpeciesLearnsetDisplay {
    natural: string[];
    ct: string[];
}

export const EEVEE_FAMILY_ROOT = 'Eevee';

export const EEVEELUTION_SPECIES = new Set([
    'Vaporeon',
    'Jolteon',
    'Flareon',
    'Espeon',
    'Umbreon',
    'Leafeon',
    'Glaceon',
    'Sylveon',
]);

const learnsetCache = new Map<string, SpeciesLearnsetDisplay>();
const familyNaturalPoolCache = new Map<string, string[]>();
const familyMembersCache = new Map<string, string[]>();

const evolutionFamilies = EVOLUTION_FAMILIES as Record<string, string>;

function normalizeSpeciesKey(name: string): string {
    return name ? resolveCanonicalSpeciesName(String(name).trim()) : '';
}

function filterDamagingMoves(names: string[]): string[] {
    const seen = new Set<string>();
    const out: string[] = [];
    for (const raw of names) {
        const resolved = resolveMoveName(raw);
        if (!resolved || resolved === 'Charge') continue;
        if (!hasMoveDefinition(resolved)) continue;
        if (!isDamagingMove(resolved)) continue;
        if (seen.has(resolved)) continue;
        seen.add(resolved);
        out.push(resolved);
    }
    return out;
}

function sortMoveNames(names: string[]): string[] {
    return [...names].sort((a, b) => a.localeCompare(b, 'fr', { sensitivity: 'base' }));
}

export function familyForSpecies(speciesName: string): string {
    const key = normalizeSpeciesKey(speciesName);
    if (!key) return '';
    if (Object.prototype.hasOwnProperty.call(evolutionFamilies, key)) {
        return evolutionFamilies[key] ?? key;
    }
    return key;
}

export function isEeveeLineMember(speciesName: string): boolean {
    const key = normalizeSpeciesKey(speciesName);
    if (!key) return false;
    if (key === EEVEE_FAMILY_ROOT) return true;
    return EEVEELUTION_SPECIES.has(key);
}

/** Eevee only, or Eevee + the given evolution — never sibling eeveelutions. */
export function getEeveeLineageSpecies(speciesName: string): string[] {
    const key = normalizeSpeciesKey(speciesName);
    if (!key || !isEeveeLineMember(key)) return [];
    if (key === EEVEE_FAMILY_ROOT) return [EEVEE_FAMILY_ROOT];
    return [EEVEE_FAMILY_ROOT, key];
}

/** Registry key for unlockedMoves: per-species on the Eevee line, family root elsewhere. */
export function moveUnlockKey(creatureName: string): string {
    const key = normalizeSpeciesKey(creatureName);
    if (!key) return '';
    if (isEeveeLineMember(key)) return key;
    return familyForSpecies(key);
}

function naturalPoolCacheKey(speciesName: string): string {
    const key = normalizeSpeciesKey(speciesName);
    if (!key) return '';
    if (isEeveeLineMember(key)) return `eevee-line:${key}`;
    return `fam:${familyForSpecies(key)}`;
}

export function getSpeciesInEvolutionFamily(familyRoot: string): string[] {
    const root = normalizeSpeciesKey(familyRoot);
    if (!root) return [];

    const cached = familyMembersCache.get(root);
    if (cached) return cached;

    const members: string[] = [root];
    for (const [speciesName, family] of Object.entries(evolutionFamilies)) {
        if (family === root && !members.includes(speciesName)) {
            members.push(speciesName);
        }
    }

    familyMembersCache.set(root, members);
    return members;
}

export function getFamilyNaturalMovesPool(speciesName: string): string[] {
    const key = normalizeSpeciesKey(speciesName);
    if (!key) return [];

    const cacheKey = naturalPoolCacheKey(key);
    const cached = familyNaturalPoolCache.get(cacheKey);
    if (cached) return cached;

    const unionRaw: string[] = [];
    if (isEeveeLineMember(key)) {
        for (const member of getEeveeLineageSpecies(key)) {
            unionRaw.push(...getDefaultMovesPool(member));
        }
    } else {
        const family = familyForSpecies(key);
        if (!family) return [];
        for (const member of getSpeciesInEvolutionFamily(family)) {
            unionRaw.push(...getDefaultMovesPool(member));
        }
    }

    const pool = sortMoveNames(filterDamagingMoves(unionRaw));
    familyNaturalPoolCache.set(cacheKey, pool);
    return pool;
}

export function pickRandomFamilyNaturalMove(speciesName: string): string {
    const pool = getFamilyNaturalMovesPool(speciesName);
    if (!pool.length) return 'Charge';
    return pool[Math.floor(Math.random() * pool.length)] || 'Charge';
}

export function getNaturalMovesForSpecies(pokemonName: string): string[] {
    return getFamilyNaturalMovesPool(pokemonName);
}

function collectCtMoveCandidates(pokemonName: string): string[] {
    const table = getCtCompatibilityTable();
    if (!table) return [];

    const seen = new Set<string>();
    const candidates: string[] = [];

    for (const moveName of Object.keys(table)) {
        const resolved = resolveMoveName(moveName);
        if (!resolved || seen.has(resolved)) continue;
        if (!canLearnCT(pokemonName, resolved)) continue;
        seen.add(resolved);
        candidates.push(resolved);
    }

    return candidates;
}

export function getCtMovesForSpecies(pokemonName: string): string[] {
    const key = normalizeSpeciesKey(pokemonName);
    if (!key) return [];

    const naturalSet = new Set(getNaturalMovesForSpecies(key));
    const ctOnly = collectCtMoveCandidates(key).filter((m) => !naturalSet.has(m));
    return sortMoveNames(filterDamagingMoves(ctOnly));
}

export function getSpeciesLearnsetDisplay(pokemonName: string): SpeciesLearnsetDisplay {
    const key = normalizeSpeciesKey(pokemonName);
    if (!key) return { natural: [], ct: [] };

    const cacheKey = isEeveeLineMember(key) ? `eevee-line:${key}` : `fam:${familyForSpecies(key)}`;
    const cached = learnsetCache.get(cacheKey);
    if (cached) return cached;

    const natural = getNaturalMovesForSpecies(key);
    const ct = getCtMovesForSpecies(key);
    const result = { natural, ct };
    learnsetCache.set(cacheKey, result);
    return result;
}

const ALL_EEVEE_MOVE_SPECIES = [EEVEE_FAMILY_ROOT, ...EEVEELUTION_SPECIES] as const;

/**
 * Splits legacy unlockedMoves.Eevee (full-family union) into per-species keys.
 * Idempotent when the legacy bucket is empty or already migrated.
 */
export function migrateEeveeUnlockedMovesRegistry(
    unlockedMoves: Record<string, string[]>,
): boolean {
    if (!unlockedMoves || typeof unlockedMoves !== 'object') return false;

    const legacy = unlockedMoves[EEVEE_FAMILY_ROOT];
    if (!Array.isArray(legacy) || legacy.length === 0) return false;

    const lineagePools: Record<string, Set<string>> = {};
    for (const species of ALL_EEVEE_MOVE_SPECIES) {
        lineagePools[species] = new Set(getFamilyNaturalMovesPool(species));
    }

    const addToKey = (registryKey: string, move: string) => {
        if (!unlockedMoves[registryKey]) unlockedMoves[registryKey] = [];
        if (!unlockedMoves[registryKey].includes(move)) {
            unlockedMoves[registryKey].push(move);
        }
    };

    for (const raw of legacy) {
        const resolved = resolveMoveName(raw);
        if (!resolved || resolved === 'Charge') continue;
        if (!hasMoveDefinition(resolved)) continue;
        if (!isDamagingMove(resolved)) continue;

        for (const species of ALL_EEVEE_MOVE_SPECIES) {
            if (lineagePools[species]?.has(resolved)) {
                addToKey(species, resolved);
            }
        }
    }

    unlockedMoves[EEVEE_FAMILY_ROOT] = legacy.filter((raw) => {
        const resolved = resolveMoveName(raw);
        return !!resolved && lineagePools[EEVEE_FAMILY_ROOT]?.has(resolved);
    });

    return true;
}
