/**
 * Team Plasma story battles (Unova).
 * Uses the zone-rival combat pipeline; unlocked while the linked story quest is active.
 */

export type UnovaFactionEncounterMeta = {
    zoneId: number;
    rivalKey: string;
    spriteKey: string;
    displayName: string;
    flavor: { fr: string; en: string };
    faction: 'plasma';
    arenaId: number;
    /** Late-game Plasma: scale level/stats from zone.levelRange, not arenaId. */
    scaleWithZone?: boolean;
    unlockWhenStoryQuest: string;
    teamArchetypes: Array<{ picks: string[]; pickOne?: boolean }>;
    levelOffset?: number;
    statMultiplier?: number;
    rewards?: {
        pokedollarsMult?: number;
        balls?: Record<string, number>;
        combatTickets?: number;
    };
};

