type EvolutionParentsMap = Record<string, string[]>;
type GameEvolutionCache = ThisGame & { _evolutionParentsMap?: EvolutionParentsMap };

function familyForCreature(creatureName: string): string {
    const canonicalName = resolveCanonicalSpeciesName(creatureName);
    if (Object.prototype.hasOwnProperty.call(EVOLUTION_FAMILIES, canonicalName)) {
        return EVOLUTION_FAMILIES[canonicalName as keyof typeof EVOLUTION_FAMILIES];
    }
    return canonicalName;
}

function buildEvolutionParentsMap(): EvolutionParentsMap {
    const parentsMap: EvolutionParentsMap = {};
    const pushParent = (childName: string, parentName: string) => {
        if (!childName || !parentName) return;
        if (!parentsMap[childName]) parentsMap[childName] = [];
        if (!parentsMap[childName].includes(parentName)) {
            parentsMap[childName].push(parentName);
        }
    };

    Object.entries(EVOLUTIONS).forEach(([parentName, evolutionData]) => {
        if (!parentName || !evolutionData) return;

        if (typeof evolutionData.evolves_to === 'string' && evolutionData.evolves_to) {
            pushParent(evolutionData.evolves_to, parentName);
        }

        if (Array.isArray(evolutionData.options)) {
            evolutionData.options.forEach((option: EvolutionOption) => {
                if (typeof option.evolves_to === 'string' && option.evolves_to) {
                    pushParent(option.evolves_to, parentName);
                }
            });
        }
    });

    return parentsMap;
}

function getCachedParentsMap(game: ThisGame): EvolutionParentsMap {
    const g = game as GameEvolutionCache;
    if (g._evolutionParentsMap) return g._evolutionParentsMap;
    const parentsMap = buildEvolutionParentsMap();
    g._evolutionParentsMap = parentsMap;
    return parentsMap;
}

function forEachOwnedCreature(game: ThisGame, fn: (creature: CreatureData) => void): void {
    for (const list of [game.playerTeam, game.storage, game.pension]) {
        if (!Array.isArray(list)) continue;
        for (const creature of list) {
            if (creature) fn(creature);
        }
    }
}

