function normalizeMoveNameList(sourceMoves: string[]): string[] {
    const seen = new Set<string>();
    const cleanedMoves: string[] = [];
    sourceMoves.forEach((moveName: string) => {
        const resolvedMove = resolveMoveName(moveName);
        if (!resolvedMove || resolvedMove === 'Charge') return;
        if (!hasMoveDefinition(resolvedMove)) return;
        if (!isDamagingMove(resolvedMove)) return;
        if (seen.has(resolvedMove)) return;
        seen.add(resolvedMove);
        cleanedMoves.push(resolvedMove);
    });
    return cleanedMoves;
}

function unlockedMovesForCreature(game: ThisGame, creatureName: string): string[] {
    const persistedMoves = readPersistedUnlockedForCreature(game, creatureName);
    const equippedFamilyMoves: string[] = [];
    ownedCreaturesForMoveUnlock(game, creatureName).forEach((ownedCreature) => {
        equippedMovesForCreature(ownedCreature).forEach((moveName) => equippedFamilyMoves.push(moveName));
    });

    const effectiveMoves = normalizeMoveNameList([...persistedMoves, ...equippedFamilyMoves]);

    if (!game.unlockedMoves || typeof game.unlockedMoves !== 'object') game.unlockedMoves = {};

    if (isEeveeLineMember(creatureName)) {
        const key = moveUnlockKey(creatureName);
        const lineagePool = new Set(getFamilyNaturalMovesPool(creatureName));
        const forKey = effectiveMoves.filter((m) => lineagePool.has(m));
        game.unlockedMoves[key] = forKey;
        if (key !== 'Eevee') {
            const eeveePool = new Set(getFamilyNaturalMovesPool('Eevee'));
            game.unlockedMoves.Eevee = effectiveMoves.filter((m) => eeveePool.has(m));
        }
    } else {
        const family = familyForCreature(creatureName);
        game.unlockedMoves[family] = effectiveMoves;
    }

    return effectiveMoves;
}

