export function applyEvolutionSystem(GameClass: GameCtor): void {

    // OPTIMISATION : Fusion avec Correction de Raret? (Fix Snorlax)
    GameClass.prototype.processFusion = function (this: ThisGame, source: CreatureData, target: CreatureData): FusionResult {
        let improved = false;
        let ivImproved = false; // Uniquement quand au moins un IV est meilleur
        let prestigeImproved = false;
        let shinyFound = false;
        let rarityFixed = false; // Nouveau flag
        const sourceWasPerfect = isCreaturePerfect(this, source);
        const targetWasPerfect = isCreaturePerfect(this, target);
        const targetWasPerfectShiny = targetWasPerfect && !!target.isShiny;

        // 1. Fusion des IVs (on garde le meilleur pour chaque stat)
        if (source.ivHP > target.ivHP) { target.ivHP = source.ivHP; improved = true; ivImproved = true; }
        if (source.ivAttack > target.ivAttack) { target.ivAttack = source.ivAttack; improved = true; ivImproved = true; }
        if (source.ivSpAttack > target.ivSpAttack) { target.ivSpAttack = source.ivSpAttack; improved = true; ivImproved = true; }
        if (source.ivDefense > target.ivDefense) { target.ivDefense = source.ivDefense; improved = true; ivImproved = true; }
        if (source.ivSpDefense > target.ivSpDefense) { target.ivSpDefense = source.ivSpDefense; improved = true; ivImproved = true; }
        if (source.ivSpeed > target.ivSpeed) { target.ivSpeed = source.ivSpeed; improved = true; ivImproved = true; }

        // ============================================================
        // 2. TRANSFERT D'EXP?RIENCE (Nouveau & Intelligent)
        // ============================================================
        // On doit calculer tout l'XP que le 'source' a accumul? dans sa vie

        let sourceTotalXP = source.exp; // On commence avec la barre actuelle

        // On ajoute l'XP de tous les niveaux pr?c?dents
        // On boucle de 1 jusqu'au niveau actuel du Pokémon source
        for (let i = 1; i < source.level; i++) {
            // On recr?e ta formule de baseExp pour le niveau 'i'
            const baseExp = Math.floor((200 * Math.pow(1.02, i)) + (i * i));

            // On applique le multiplicateur de raret? du SOURCE
            const rarityMult = (typeof XP_CURVE_MULTIPLIERS !== 'undefined' && XP_CURVE_MULTIPLIERS[source.rarity])
                ? XP_CURVE_MULTIPLIERS[source.rarity]
                : 1.0;

            sourceTotalXP += Math.floor(baseExp * (rarityMult ?? 1.0));
        }

        // On donne ce gros paquet d'XP ? la cible
        if (sourceTotalXP > 0) {
            // Ta fonction gainExp g?re d?j? les mont?es de niveau en cascade (while loop)
            target.gainExp!(Math.floor(sourceTotalXP / 2)); //50% de p?nalit? pour éviter le farm abusif
            improved = true;
        }

        // NOTE : Si ton jeu a une fonction pour v?rifier la mont?e de niveau
        // (du genre target.checkLevelUp()), tu peux l'ajouter ici.
        // Sinon, target.recalculateStats!() ? la fin devrait g?rer l'affichage.

        // ============================================================
        // 2. FUSION DU PRESTIGE (Universelle & S?curis?e)
        // ============================================================

        const sourceLevel = source.prestige || 0;
        const targetLevel = target.prestige || 0;

        // Si le sacrifi? (Source) est plus grad? que le receveur (Target)
        // Peu importe l'esp?ce, on prend le grade le plus ?lev?.
        if (sourceLevel > targetLevel) {

            // A. On copie le niveau sup?rieur
            target.prestige = sourceLevel;
            prestigeImproved = true;
            improved = true;

            // B. On calcule la diff?rence de niveaux
            const levelDiff = sourceLevel - targetLevel;

            // C. On convertit cette diff?rence en JETONS
            // Le joueur utilisera ces jetons pour racheter les bonus sur la nouvelle cr?ature.
            // Cela remplace l'addition des stats (qui causait les bugs).
            target.prestigeTokens = (target.prestigeTokens || 0) + levelDiff;
        }


        // 3. Fusion Shiny
        if (source.isShiny && !target.isShiny) {
            target.isShiny = true;
            shinyFound = true;
            improved = true;
        }

        // 4. â… CORRECTION RARET? (Le Fix pour ton Snorlax)
        // On d?finit une hi?rarchie de valeur
        const rarityValue: Record<string, number> = { 'common': 1, 'rare': 2, 'epic': 3, 'legendary': 4 };

        // Si le nouveau est "plus rare" (la bonne raret?) que l'ancien (le bugu?)
        if ((rarityValue[source.rarity] ?? 0) > (rarityValue[target.rarity] ?? 0)) {
            target.rarity = source.rarity;
            rarityFixed = true;
            improved = true;
            // On v?rifie si un talent doit ?tre assign? (ex: passage de Rare ? Epic)
            if (!target.passiveTalent && (target.rarity === 'epic' || target.rarity === 'legendary')) {
                target.assignRandomTalent!(); // On lui donne son talent manquant !
            }
        }

        // 5. Recalcul
        if (improved) {
            if (typeof target.recalculateStats === 'function') target.recalculateStats();
            if (typeof target.heal === 'function') target.heal();
            if (typeof this.tryGrantMegaStone === 'function') this.tryGrantMegaStone(target, { silent: true });
        }

        const targetIsPerfect = isCreaturePerfect(this, target);
        if (targetIsPerfect && !targetWasPerfect && !sourceWasPerfect && typeof this.recordPerfectCreatureObtained === 'function') {
            this.recordPerfectCreatureObtained(target);
        } else if (
            targetIsPerfect
            && target.isShiny
            && !targetWasPerfectShiny
            && !(sourceWasPerfect && source.isShiny)
        ) {
            if (!this.stats || typeof this.stats !== 'object') this.stats = {} as GameStats;
            this.stats.perfectShinyCount = (Number(this.stats.perfectShinyCount) || 0) + 1;
            if (typeof this.checkAchievements === 'function') this.checkAchievements('perfectShinyCount');
            if (typeof this.trackHolyGrailCreature === 'function') this.trackHolyGrailCreature(target);
        } else if (targetIsPerfect && typeof this.trackHolyGrailCreature === 'function') {
            this.trackHolyGrailCreature(target);
        }

        if (ivImproved) {
            if (!this.stats || typeof this.stats !== 'object') this.stats = {} as GameStats;
            this.stats.ivUpgrades = (this.stats.ivUpgrades || 0) + 1;
            this.checkAchievements('ivUpgrades');
        }

        // Si la cible est en exp?dition, on persiste la version fusionn?e.
        this.persistExpeditionCreatureData(target);

        // 6. Shards
        let shardsGained = (source.isShiny || source.isShadow) ? 3 : 1;
        if (Math.random() < this.getShardBonusChance()) shardsGained *= 2;

        const shardKey = getShardKey(target.name, target.rarity);
        this.shards[shardKey] = (this.shards[shardKey] || 0) + shardsGained;

        for (let i = 0; i < shardsGained; i++) this.checkSpecialQuests('totalShards');
        // Ne pas compter ici : fusion_completed est compt? uniquement pour les doublons captur?s (combat), pas &Sufs/?volution

        if (typeof this.checkAndShowCollectionBonusModal === 'function') this.checkAndShowCollectionBonusModal();
        return {
            improved: improved,
            ivImproved: ivImproved,
            shards: shardsGained,
            prestigeUp: prestigeImproved,
            becameShiny: shinyFound,
            rarityUp: rarityFixed // On renvoie l'info
        };
    };

    GameClass.prototype.getFamilyForCreature = function (this: ThisGame, creatureName: string): string {
        return familyForCreature(creatureName);
    };

    GameClass.prototype.getEvolutionParentsMap = function (this: ThisGame): EvolutionParentsMap {
        return getCachedParentsMap(this);
    };

    GameClass.prototype.getAncestorSpeciesForCreature = function (this: ThisGame, creatureName: string, includeSelf: boolean = false): string[] {
        const targetName = String(creatureName || '').trim();
        if (!targetName) return [];

        const family = familyForCreature(targetName);
        const parentsMap = getCachedParentsMap(this);
        const seen = new Set<string>();
        const ordered: string[] = [];
        const stack = [targetName];

        while (stack.length > 0) {
            const speciesName = stack.pop();
            if (!speciesName || seen.has(speciesName)) continue;
            seen.add(speciesName);

            if (familyForCreature(speciesName) !== family) continue;

            if (includeSelf || speciesName !== targetName) {
                ordered.push(speciesName);
            }
            const parents = parentsMap[speciesName] ?? [];
            parents.forEach((parentName: string) => {
                if (!seen.has(parentName)) stack.push(parentName);
            });
        }

        return ordered.reverse();
    };

    GameClass.prototype.rebuildUnlockedMovesFromOwnedCreatures = function (this: ThisGame) {
        const equippedByRegistryKey: Record<string, string[]> = {};

        forEachOwnedCreature(this, (creature) => {
            const registryKey = moveUnlockKey(creature.name);
            const equippedMoves = equippedMovesForCreature(creature);
            if (!equippedByRegistryKey[registryKey]) equippedByRegistryKey[registryKey] = [];
            equippedMoves.forEach((moveName: string) => {
                if (!equippedByRegistryKey[registryKey].includes(moveName)) {
                    equippedByRegistryKey[registryKey].push(moveName);
                }
            });
        });

        this.unlockedMoves = mergeUnlockedMovesRegistry(this.unlockedMoves, equippedByRegistryKey);
    };

    GameClass.prototype.repairUnlockedMovesRegistryOnce = function (this: ThisGame) {
        const migrationKey = 'poketime_unlocked_moves_merge_v2';
        try {
            if (typeof localStorage !== 'undefined' && localStorage.getItem(migrationKey) === '1') return;
        } catch (_) {}

        this.rebuildUnlockedMovesFromOwnedCreatures();

        try {
            if (typeof localStorage !== 'undefined') localStorage.setItem(migrationKey, '1');
        } catch (_) {}
    };

    GameClass.prototype.getOwnedCreaturesForFamily = function (this: ThisGame, creatureName: string): CreatureData[] {
        return ownedCreaturesForFamily(this, creatureName);
    };

    GameClass.prototype.getEquippedMovesForCreature = function (this: ThisGame, creature: CreatureData): string[] {
        return equippedMovesForCreature(creature);
    };

    GameClass.prototype.registerCreatureMovesForFamily = function (this: ThisGame, creature: CreatureData) {
        if (!creature) return 0;

        const equippedMoves = equippedMovesForCreature(creature);
        let unlockedCount = 0;

        equippedMoves.forEach((moveName: string) => {
            if (this.unlockMoveForFamily(creature.name, moveName)) unlockedCount++;
        });

        if (equippedMoves.length > 0) {
            creature.currentMoves = equippedMoves;
        }

        return unlockedCount;
    };

    GameClass.prototype.tryAssignUnlockedMoveToFamily = function (this: ThisGame, creatureName: string, moveName: string) {
        const resolvedMoveName = resolveMoveName(moveName);
        if (!resolvedMoveName || resolvedMoveName === 'Charge') return 0;
        if (!hasMoveDefinition(resolvedMoveName)) return 0;
        if (!isDamagingMove(resolvedMoveName)) return 0;

        let assignedCount = 0;
        const familyCreatures = ownedCreaturesForMoveUnlock(this, creatureName);

        familyCreatures.forEach((creature: CreatureData) => {
            const equippedMoves = equippedMovesForCreature(creature);

            if (equippedMoves.includes(resolvedMoveName) || equippedMoves.length >= 4) {
                if (equippedMoves.length > 0) creature.currentMoves = equippedMoves;
                return;
            }

            creature.currentMoves = [...equippedMoves, resolvedMoveName];
            creature.movePp = creature.movePp || {};
            const def = (typeof getMoveDefinition === 'function') ? getMoveDefinition(resolvedMoveName) : null;
            const basePp = (typeof getBasePPForMove === 'function') ? getBasePPForMove(def) : 15;
            creature.movePp[resolvedMoveName] = { current: basePp, max: basePp };
            assignedCount++;
        });

        return assignedCount;
    };

    GameClass.prototype.unlockMoveForFamily = function (this: ThisGame, creatureName: string, moveName: string) {
        const resolvedMoveName = resolveMoveName(moveName);
        if (!resolvedMoveName || resolvedMoveName === 'Charge') return false; // Ne pas spammer avec Charge
        if (!hasMoveDefinition(resolvedMoveName)) return false;
        if (!isDamagingMove(resolvedMoveName)) return false;

        const lineagePool = new Set(getFamilyNaturalMovesPool(creatureName));
        if (!lineagePool.has(resolvedMoveName)) return false;

        const registryKey = moveUnlockKey(creatureName);
        if (!this.unlockedMoves) this.unlockedMoves = {};
        if (!this.unlockedMoves[registryKey]) this.unlockedMoves[registryKey] = [];

        if (!this.unlockedMoves[registryKey].includes(resolvedMoveName)) {
            this.unlockedMoves[registryKey].push(resolvedMoveName);
            return true; // Nouvelle attaque d?bloqu?e !
        }
        return false;
    };

    /**
     * Réduit un registre d'attaques familial gonflé (anciennes saves : learnset entier dans unlockedMoves,
     * ou clef "Gengar" au lieu de la famille de base "Gastly").
     * Idempotent : fusion des clefs vers la famille canonique puis compaction si la liste est incohérente
     * avec l'équipement réel.
     */
    GameClass.prototype.sanitizeInflatedUnlockedMovesRegistry = function (this: ThisGame) {
        if (!this.unlockedMoves || typeof this.unlockedMoves !== 'object') return;

        // 1) Fusionner toutes les clefs vers la clef canonique (famille ou espèce Evoli)
        const mergedByCanon: Record<string, string[]> = {};
        Object.keys(this.unlockedMoves).forEach((key: string) => {
            const raw = this.unlockedMoves[key];
            if (!Array.isArray(raw) || raw.length === 0) return;
            const canon = canonUnlockRegistryKey(key);
            if (!mergedByCanon[canon]) mergedByCanon[canon] = [];
            mergedByCanon[canon].push(...raw);
        });
        Object.keys(this.unlockedMoves).forEach((k: string) => { delete this.unlockedMoves[k]; });
        Object.keys(mergedByCanon).forEach((canon: string) => {
            const moves = mergedByCanon[canon];
            if (!moves) return;
            this.unlockedMoves[canon] = normalizeUnlockedMoveList(moves);
        });

        // 2) Compacter uniquement les listes clairement legacy (learnset entier), sans toucher la progression légitime
        Object.keys(this.unlockedMoves).forEach((canon: string) => {
            const pool = getFamilyNaturalMovesPool(canon);
            const poolSet = new Set(
                (Array.isArray(pool) ? pool : []).map((m: string) => (
                    resolveMoveName(m)
                )).filter(Boolean) as string[],
            );
            const poolLen = poolSet.size;

            const equippedFlat: string[] = [];
            forEachOwnedCreature(this, (creature) => {
                const creatureRegistry = moveUnlockKey(creature.name);
                if (isEeveeLineMember(canon)) {
                    if (creatureRegistry !== canon) return;
                } else if (familyForCreature(creature.name) !== canon) {
                    return;
                }
                equippedMovesForCreature(creature).forEach((m: string) => equippedFlat.push(m));
            });
            const equippedNorm = normalizeUnlockedMoveList(equippedFlat);

            const list = normalizeUnlockedMoveList(this.unlockedMoves[canon] || []);
            if (list.length === 0) {
                this.unlockedMoves[canon] = equippedNorm;
                return;
            }

            if (!shouldCompactInflatedUnlockedList(list.length, poolLen)) return;

            this.unlockedMoves[canon] = compactInflatedUnlockedMoveList(
                list,
                poolSet,
                poolLen,
                equippedNorm,
            );
        });
    };

    /**
     * Tente de débloquer une attaque offensive pour la famille de l'espèce.
     * @returns {false|string} false si échec, sinon le nom résolu de l'attaque débloquée.
     */
    /**
     * @param {string} creatureName
     * @param {string} moveName
     * @param {boolean} [fromEgg] - si true : probabilité œuf (MOVE_UNLOCK_EGG_CHANCE), sinon capture (MOVE_UNLOCK_CAPTURE_HATCH_CHANCE)
     */
    GameClass.prototype.tryUnlockMoveFromCaptureOrEgg = function (this: ThisGame, creatureName: string, moveName: string, fromEgg?: boolean) {
        // Registre gonflé / mauvaise clef : nettoyage global si une entrée de cette famille est trop longue.
        if (this.unlockedMoves && typeof this.unlockedMoves === 'object' && typeof this.sanitizeInflatedUnlockedMovesRegistry === 'function') {
            const registryEarly = moveUnlockKey(creatureName);
            const poolEarly = getFamilyNaturalMovesPool(creatureName);
            const poolLenEarly = Array.isArray(poolEarly) ? poolEarly.length : 0;
            let bulkyFam = false;
            Object.keys(this.unlockedMoves).forEach((k: string) => {
                const a = this.unlockedMoves[k];
                if (!Array.isArray(a)) return;
                if (canonUnlockRegistryKey(k) !== registryEarly) return;
                if (isBulkyUnlockedRegistryEntry(a.length, poolLenEarly)) bulkyFam = true;
            });
            if (bulkyFam) this.sanitizeInflatedUnlockedMovesRegistry();
        }

        const normalizeCandidate = (raw: string) => {
            const resolved = resolveMoveName(raw);
            if (!resolved || resolved === 'Charge') return null;
            if (!hasMoveDefinition(resolved)) return null;
            if (!isDamagingMove(resolved)) return null;
            return resolved;
        };

        const rebuildCandidates = (unlockedSet: Set<string>, pool: string[]): string[] => {
            const out: string[] = [];
            if (!Array.isArray(pool)) return out;
            pool.forEach((entry: string) => {
                const c = normalizeCandidate(entry);
                if (c && !unlockedSet.has(c)) out.push(c);
            });
            return out;
        };

        const registryKey = moveUnlockKey(creatureName);
        const pool = getFamilyNaturalMovesPool(creatureName);

        const unlockedList = unlockedMovesForCreature(this, creatureName);
        const unlockedSet = new Set<string>(unlockedList);
        const candidates = rebuildCandidates(unlockedSet, pool);

        let chosen: string | null = null;
        if (candidates.length > 0) {
            chosen = candidates[Math.floor(Math.random() * candidates.length)] ?? null;
        } else {
            chosen = normalizeCandidate(moveName);
            if (!chosen || unlockedSet.has(chosen)) return false;
        }
        if (!chosen) return false;

        const baseChance = fromEgg
            ? MOVE_UNLOCK_EGG_CHANCE
            : MOVE_UNLOCK_CAPTURE_HATCH_CHANCE;
        const chance = Math.max(0, Math.min(1, baseChance));
        if (Math.random() >= chance) return false;

        const unlockFn: unknown = this['unlockMoveForFamily'];
        const didUnlock = typeof unlockFn === 'function'
            && (unlockFn as (this: ThisGame, n: string, m: string) => boolean).call(this, creatureName, chosen);
        const assignFn: unknown = this['tryAssignUnlockedMoveToFamily'];
        if (didUnlock && typeof assignFn === 'function') {
            (assignFn as (this: ThisGame, n: string, m: string) => number).call(this, creatureName, chosen);
        }
        return didUnlock ? chosen : false;
    };

    GameClass.prototype.getUnlockedMovesForCreature = function (this: ThisGame, creatureName: string): string[] {
        return unlockedMovesForCreature(this, creatureName);
    };

    GameClass.prototype.registerCreatureNaturesForFamily = function (this: ThisGame, creature: CreatureData) {
        if (!creature) return 0;
        const natureId = normalizeNatureId(typeof creature.nature === 'string' ? creature.nature : undefined);
        creature.nature = natureId;
        return this.unlockNatureForFamily(creature.name, natureId) ? 1 : 0;
    };

    GameClass.prototype.unlockNatureForFamily = function (this: ThisGame, creatureName: string, natureId: string): boolean {
        const normalized = normalizeNatureId(natureId);
        if (!isValidNatureId(normalized)) return false;

        const registryKey = natureUnlockKey(creatureName);
        if (!registryKey) return false;
        if (!this.unlockedNatures) this.unlockedNatures = {};
        if (!this.unlockedNatures[registryKey]) this.unlockedNatures[registryKey] = [];

        if (!this.unlockedNatures[registryKey].includes(normalized)) {
            this.unlockedNatures[registryKey].push(normalized);
            return true;
        }
        return false;
    };

    GameClass.prototype.tryUnlockNatureFromCaptureOrEgg = function (
        this: ThisGame,
        creatureName: string,
        fromEgg = false,
    ): string | false {
        const registryKey = natureUnlockKey(creatureName);
        if (!registryKey) return false;

        const unlockedList = unlockedNaturesForCreature(this, creatureName);
        const candidates = getRemainingUnlockableNatureIds(unlockedList);
        if (candidates.length === 0) return false;

        const unlockedCount = Math.max(1, unlockedList.length);
        const baseChance = fromEgg ? NATURE_UNLOCK_EGG_CHANCE : NATURE_UNLOCK_CAPTURE_HATCH_CHANCE;
        const chance = Math.max(0, Math.min(1, baseChance / unlockedCount));
        if (Math.random() >= chance) return false;

        const chosen = candidates[Math.floor(Math.random() * candidates.length)] ?? null;
        if (!chosen) return false;

        const didUnlock = this.unlockNatureForFamily(creatureName, chosen);
        return didUnlock ? chosen : false;
    };

    GameClass.prototype.getUnlockedNaturesForCreature = function (this: ThisGame, creatureName: string): string[] {
        return unlockedNaturesForCreature(this, creatureName);
    };

    GameClass.prototype.equipNatureForCreature = function (
        this: ThisGame,
        creatureIndex: number,
        location: string,
        natureId: string,
    ): boolean {
        const creature = getCreatureAt(this, location, creatureIndex);
        if (!creature || !natureId) return false;

        const normalized = normalizeNatureId(natureId);
        if (!isValidNatureId(normalized)) return false;

        const unlocked = unlockedNaturesForCreature(this, creature.name);
        if (!unlocked.includes(normalized)) {
            toast.error(this.t('modal.nature.actionImpossible'), this.t('modal.nature.notUnlocked'));
            return false;
        }

        if (creature.nature === normalized) {
            this.showCreatureModal(creatureIndex, location);
            return false;
        }

        creature.nature = normalized;
        if (typeof creature.recalculateStats === 'function') creature.recalculateStats();
        if (typeof creature.heal === 'function') creature.heal();

        toast.success(
            this.t('modal.nature.title'),
            this.t('modal.nature.equipSuccess', { nature: this.getLocalizedNatureName(normalized) }),
        );

        this.saveGame();
        refreshCreatureDependentUi(this);
        this.showCreatureModal(creatureIndex, location);
        return true;
    };

    GameClass.prototype.getLocalizedNatureName = function (this: ThisGame, natureId: string): string {
        const key = `natures.${normalizeNatureId(natureId)}`;
        const localized = this.t(key);
        return localized !== key ? localized : natureId;
    };

    GameClass.prototype.getNatureEffectShortLabel = function (this: ThisGame, natureId: string): string {
        const def = getNatureDef(natureId);
        if (!def.boostStat && !def.reduceStat) return this.t('modal.nature.neutral');
        const t = (key: string) => this.t(key);
        const parts: string[] = [];
        if (def.boostStat) parts.push(`+${natureStatShortLabel(t, def.boostStat)}`);
        if (def.reduceStat) parts.push(`-${natureStatShortLabel(t, def.reduceStat)}`);
        return parts.join(' / ');
    };

    GameClass.prototype.getNatureEffectPickerHtml = function (this: ThisGame, natureId: string): string {
        const def = getNatureDef(natureId);
        if (!def.boostStat && !def.reduceStat) {
            return `<span class="nature-picker-entry-effect nature-picker-neutral">${escapeHtml(this.t('modal.nature.neutral'))}</span>`;
        }
        const t = (key: string) => this.t(key);
        const parts: string[] = [];
        if (def.boostStat) {
            parts.push(`<span class="nature-picker-boost">+10% ${escapeHtml(natureStatShortLabel(t, def.boostStat))}</span>`);
        }
        if (def.reduceStat) {
            parts.push(`<span class="nature-picker-reduce">-10% ${escapeHtml(natureStatShortLabel(t, def.reduceStat))}</span>`);
        }
        return `<span class="nature-picker-entry-effect">${parts.join(' <span class="nature-picker-sep">/</span> ')}</span>`;
    };

    GameClass.prototype.showNaturePickerModal = function (this: ThisGame, creatureIndex: number, location: string): void {
        const creature = getCreatureAt(this, location, creatureIndex);
        if (!creature || creature.isEnemy) return;

        const unlocked = unlockedNaturesForCreature(this, creature.name);
        if (unlocked.length === 0) {
            toast.info(this.t('modal.nature.noneTitle'), this.t('modal.nature.noneBody'));
            return;
        }

        const displayName = typeof this.getLocalizedPokemonName === 'function'
            ? this.getLocalizedPokemonName(creature.name)
            : creature.name;
        const currentNature = normalizeNatureId(typeof creature.nature === 'string' ? creature.nature : undefined);

        const renderEntry = (natureId: string): string => {
            const name = this.getLocalizedNatureName(natureId);
            const effectHtml = this.getNatureEffectPickerHtml(natureId);
            const equipped = natureId === currentNature
                ? `<span class="nature-picker-equipped">${this.t('modal.nature.equipped')}</span>`
                : '';
            return `<button type="button" class="btn nature-picker-entry nature-picker-entry-card"
                data-action="equipNature" data-arg="${creatureIndex}" data-arg2="${location}" data-arg3="${encodeURIComponent(natureId)}">
                <span class="nature-picker-entry-body">
                    <span class="nature-picker-entry-name">${escapeHtml(name)}</span>
                    ${effectHtml}
                    ${equipped}
                </span>
            </button>`;
        };

        let html = `
            <div class="stats-header">
                <h2>${this.t('modal.nature.chooseFor', { name: displayName })}</h2>
                <button type="button" class="stats-close" data-action="closeNaturePickerModal">&#10005;</button>
            </div>
            <p class="nature-picker-hint">${this.t('modal.nature.pickerHint', { unlocked: unlocked.length, total: getAllNatureIds().length })}</p>
            <div class="nature-picker-list">
                ${unlocked.map(renderEntry).join('')}
            </div>
        `;

        const existing = document.getElementById('naturePickerModal');
        if (existing) existing.remove();

        const overlay = document.createElement('div');
        overlay.id = 'naturePickerModal';
        overlay.className = 'stats-modal show nature-picker-modal';
        overlay.style.zIndex = '10001';
        const box = document.createElement('div');
        box.className = 'stats-content nature-picker-content';
        box.innerHTML = html;
        overlay.appendChild(box);
        overlay.onclick = (e: MouseEvent) => { if (e.target === overlay) overlay.remove(); };
        document.body.appendChild(overlay);
    };

    GameClass.prototype.closeNaturePickerModal = function (this: ThisGame): void {
        const modal = document.getElementById('naturePickerModal');
        if (modal) modal.remove();
    };

    GameClass.prototype.equipMoveForCreature = function (this: ThisGame, creatureIndex: number, location: string, moveName: string): boolean {
        const creature = getCreatureAt(this, location, creatureIndex);
        if (!creature || !moveName) return false;

        const resolvedMoveName = resolveMoveName(moveName);
        if (!resolvedMoveName || resolvedMoveName === 'Charge') return false;
        if (!hasMoveDefinition(resolvedMoveName)) return false;
        if (!isDamagingMove(resolvedMoveName)) return false;

        const unlocked = unlockedMovesForCreature(this, creature.name);
        if (!unlocked.includes(resolvedMoveName)) {
            toast.error(this.t('modal.moveDeletion.actionImpossible'), this.t('modal.creature.equipNotUnlocked'));
            return false;
        }

        const equippedMoves = equippedMovesForCreature(creature);
        if (equippedMoves.includes(resolvedMoveName)) {
            this.showCreatureModal(creatureIndex, location);
            return false;
        }
        if (equippedMoves.length >= 4) {
            toast.error(this.t('modal.moveDeletion.actionImpossible'), this.t('modal.creature.equipSlotsFull'));
            return false;
        }

        creature.currentMoves = [...equippedMoves, resolvedMoveName];
        creature.movePp = creature.movePp || {};
        const def = getMoveDefinition(resolvedMoveName);
        const basePp = getBasePPForMove(def);
        creature.movePp[resolvedMoveName] = { current: basePp, max: basePp };

        this.registerCreatureMovesForFamily(creature);

        toast.success(
            this.t('modal.creature.moves'),
            this.t('modal.creature.equipSuccess', { move: this.getLocalizedMoveNamePlain(resolvedMoveName) }),
        );

        this.saveGame();
        refreshCreatureDependentUi(this);
        this.showCreatureModal(creatureIndex, location);
        return true;
    };

    GameClass.prototype.canForgetMove = function (
        this: ThisGame,
        creature: CreatureData,
        moveName: string,
        opts?: { choiceBandLocked?: boolean; moveIndex?: number },
    ): CanForgetMoveResult {
        return canForgetMove(creature, moveName, opts);
    };

    GameClass.prototype.getTmEraserCount = function (this: ThisGame): number {
        return Math.max(0, Math.floor(Number(this.items?.[TM_ERASER_ITEM_KEY]) || 0));
    };

    GameClass.prototype.consumeTmEraser = function (this: ThisGame, amount: number = 1): boolean {
        const need = Math.max(1, Math.floor(Number(amount) || 1));
        if (!this.items) this.items = {};
        const have = Math.max(0, Math.floor(Number(this.items[TM_ERASER_ITEM_KEY]) || 0));
        if (have < need) {
            toast.error(this.t('modal.forgetMove.actionImpossible'), this.t('modal.forgetMove.noItem'));
            return false;
        }
        this.items[TM_ERASER_ITEM_KEY] = have - need;
        if (this.items[TM_ERASER_ITEM_KEY] <= 0) delete this.items[TM_ERASER_ITEM_KEY];
        this.updateItemsDisplay();
        return true;
    };

    GameClass.prototype.forgetEquippedMove = function (this: ThisGame, creatureIndex: number, location: string, moveName: string): boolean {
        const creature = getCreatureAt(this, location, creatureIndex);
        if (!creature || !moveName) return false;

        moveName = resolveMoveName(moveName);
        const choiceBandLocked = creature.heldItem === 'choice_band';
        const equipped = equippedMovesForCreature(creature);
        const moveIndex = equipped.indexOf(moveName);
        const forgetCheck = canForgetMove(creature, moveName, {
            choiceBandLocked,
            moveIndex: moveIndex >= 0 ? moveIndex : 0,
        });
        if (!forgetCheck.allowed) {
            const msgKey = forgetCheck.reasonKey ?? 'modal.moveDeletion.atLeastTwoMoves';
            toast.error(this.t('modal.forgetMove.actionImpossible'), this.t(msgKey));
            return false;
        }

        if (!equipped.includes(moveName)) {
            toast.warning(this.t('modal.moveDeletion.alreadyForgottenTitle'), this.t('modal.moveDeletion.alreadyForgottenBody', { move: this.getLocalizedMoveNamePlain(moveName) }));
            this.saveGame();
            this.showCreatureModal(creatureIndex, location);
            return false;
        }
        if (equipped.length <= 1) {
            toast.error(this.t('modal.forgetMove.actionImpossible'), this.t('modal.moveDeletion.atLeastOneMove'));
            return false;
        }

        const resolvedForget = resolveMoveName(moveName);
        creature.currentMoves = (Array.isArray(creature.currentMoves) ? creature.currentMoves : [])
            .filter((m: string) => resolveMoveName(m) !== resolvedForget);
        if (creature.movePp && creature.movePp[moveName]) {
            delete creature.movePp[moveName];
        }
        if (creature.movePp && creature.movePp[resolvedForget]) {
            delete creature.movePp[resolvedForget];
        }

        const displayName = typeof this.getLocalizedPokemonName === 'function'
            ? this.getLocalizedPokemonName(creature.name)
            : creature.name;
        toast.success(this.t('modal.moveDeletion.forgottenTitle'), this.t('modal.moveDeletion.forgottenBody', { move: this.getLocalizedMoveNamePlain(moveName), name: displayName }));
        logMessage(this.t('modal.forgetMove.forgottenLog', { move: this.getLocalizedMoveNamePlain(moveName), name: displayName }));

        this.saveGame();
        refreshCreatureDependentUi(this);
        this.showCreatureModal(creatureIndex, location);
        return true;
    };

    GameClass.prototype.showForgetMoveConfirmModal = function (
        this: ThisGame,
        creatureIndex: number,
        location: string,
        moveName: string,
        onSuccess?: () => void,
    ): void {
        const creature = getCreatureAt(this, location, creatureIndex);
        if (!creature) return;
        moveName = resolveMoveName(moveName);

        const modal = document.createElement('div');
        modal.id = 'forgetMoveModal';
        modal.className = 'stats-modal show';
        modal.style.zIndex = '20000';

        const displayName = typeof this.getLocalizedPokemonName === 'function'
            ? this.getLocalizedPokemonName(creature.name)
            : creature.name;
        const moveLabel = this.getLocalizedMoveNamePlain(moveName);

        const box = document.createElement('div');
        box.className = 'stats-content move-delete-cancel-content';
        box.addEventListener('click', (e) => e.stopPropagation());
        box.innerHTML = `
            <div class="stats-header">
                <h2>${this.t('modal.forgetMove.confirmTitle')}</h2>
                <button type="button" class="stats-close" id="closeForgetMoveModalBtn">&#10005;</button>
            </div>
            <p class="move-delete-cancel-progress">
                ${this.t('modal.forgetMove.confirmBody', { move: moveLabel, name: displayName })}
            </p>
            <div class="move-delete-cancel-actions">
                <button type="button" id="confirmForgetMoveBtn" class="btn move-delete-cancel-submit">
                    ${this.t('modal.forgetMove.confirmYes')}
                </button>
                <button type="button" id="cancelForgetMoveBtn" class="btn move-delete-cancel-keep">
                    ${this.t('modal.forgetMove.confirmNo')}
                </button>
            </div>
        `;

        modal.appendChild(box);
        document.body.appendChild(modal);

        const closeModal = () => {
            if (modal.parentNode) modal.parentNode.removeChild(modal);
        };

        modal.addEventListener('click', (e) => {
            if (e.target === modal) closeModal();
        });

        box.querySelector('#closeForgetMoveModalBtn')?.addEventListener('click', closeModal);
        box.querySelector('#cancelForgetMoveBtn')?.addEventListener('click', closeModal);
        box.querySelector('#confirmForgetMoveBtn')?.addEventListener('click', () => {
            if (!this.consumeTmEraser(1)) return;
            if (this.forgetEquippedMove(creatureIndex, location, moveName)) {
                closeModal();
                if (typeof onSuccess === 'function') onSuccess();
            } else {
                this.addItem(TM_ERASER_ITEM_KEY, 1);
            }
        });
    };

    GameClass.prototype.handleMoveDeletionAction = function (this: ThisGame, creatureIndex: number, location: string, moveName: string) {
        const creature = getCreatureAt(this, location, creatureIndex);
        if (!creature) return;
        moveName = resolveMoveName(moveName);

        if (this.getTmEraserCount() < 1) {
            toast.info(this.t('modal.forgetMove.noItemTitle'), this.t('modal.forgetMove.noItem'));
            return;
        }

        const choiceBandLocked = creature.heldItem === 'choice_band';
        const equipped = equippedMovesForCreature(creature);
        const moveIndex = equipped.indexOf(moveName);
        const forgetCheck = canForgetMove(creature, moveName, {
            choiceBandLocked,
            moveIndex: moveIndex >= 0 ? moveIndex : 0,
        });
        if (!forgetCheck.allowed) {
            const msgKey = forgetCheck.reasonKey ?? 'modal.moveDeletion.atLeastTwoMoves';
            toast.error(this.t('modal.forgetMove.actionImpossible'), this.t(msgKey));
            return;
        }

        this.showForgetMoveConfirmModal(creatureIndex, location, moveName);
    };

    GameClass.prototype.resolveEvolutionConditionItem = function (this: ThisGame, condition: string): string | null {
        return resolveEvolutionConditionItem(condition);
    };

    GameClass.prototype.getAvailableEvolutionOptions = function (this: ThisGame, creature: CreatureData): AvailableEvolutionOption[] {
        return availableEvolutionOptions(this, creature, (c) => resolveEvolutionConditionItem(c));
    };

    GameClass.prototype.showEvolutionChoiceModal = function (this: ThisGame, creatureIndex: number, location: string) {
        const creature = getCreatureAt(this, location, creatureIndex);
        if (!creature) return;
        const options = availableEvolutionOptions(this, creature, (c) => resolveEvolutionConditionItem(c));
        if (options.length === 0) {
            logMessage(this.t('modal.creature.noEvolutionAvailable'));
            return;
        }
        if (options.length === 1) {
            this.evolveCreature(creatureIndex, location, options[0]);
            return;
        }
        showEvolutionChoiceModalUI({
            creatureName: this.getLocalizedPokemonName(creature.name),
            creatureIndex,
            location,
            options,
        });
    };

    GameClass.prototype.evolveCreatureWithOption = function (this: ThisGame, creatureIndex: number, location: string, optionIndex: number) {
        const creature = getCreatureAt(this, location, creatureIndex);
        if (!creature) return;
        const options = availableEvolutionOptions(this, creature, (c) => resolveEvolutionConditionItem(c));
        const option = options[optionIndex];
        if (!option) {
            logMessage(this.t('modal.creature.invalidEvolutionOption'));
            return;
        }
        this.evolveCreature(creatureIndex, location, option);
    };

    // Helper interne : récupère une créature à partir de (index, location).
    function _getPrismTargetCreature(game: ThisGame, creatureIndex: number, location: string) {
        if (location === 'team') return game.playerTeam[creatureIndex];
        if (location === 'storage') return game.storage[creatureIndex];
        if (location === 'pension') return game.pension[creatureIndex];
        return null;
    }

    // LOGIQUE : Ouvre un modal de confirmation avant d'optimiser les IVs.
    // Le clic immédiat sur le bouton Prisme est trop risqué (ressource légendaire)
    // donc on intercale ce modal "propriétaire" stylé comme le reste du jeu.
    GameClass.prototype.optimizeCreatureIVs = function (this: ThisGame, creatureIndex: number, location: string) {
        if (!this.items['prism_iv'] || this.items['prism_iv'] <= 0) {
            toast.error(this.t('modal.creature.prismMissingTitle'), this.t('modal.creature.prismMissingBody'));
            return;
        }

        const creature = _getPrismTargetCreature(this, creatureIndex, location);
        if (!creature) return;

        this.showPrismIvConfirmModal(creatureIndex, location);
    };

    // Construit l'overlay de confirmation prisme. Réutilise les classes "stats-modal"
    // pour le backdrop + animation, et "prism-iv-confirm-*" pour le contenu spécifique.
    // Avec resultContext.priorIVs : mode résultat après optimisation (modal reste ouverte).
    GameClass.prototype.showPrismIvConfirmModal = function (
        this: ThisGame,
        creatureIndex: number,
        location: string,
        resultContext?: { priorIVs: PrismIvPriorIVs },
    ) {
        const creature = _getPrismTargetCreature(this, creatureIndex, location);
        if (!creature) return;

        const existing = document.getElementById('prismIvConfirmModal');
        if (existing) existing.remove();

        const isResultMode = !!resultContext?.priorIVs;
        const priorIVs = resultContext?.priorIVs;

        const escapeForHtml = (value: unknown) => {
            const s = coerceStr(value);
            return escapeHtml(s);
        };

        const overlay = document.createElement('div');
        overlay.id = 'prismIvConfirmModal';
        overlay.className = 'stats-modal show';
        overlay.setAttribute('role', 'dialog');
        overlay.setAttribute('aria-modal', 'true');
        overlay.setAttribute('aria-labelledby', 'prismIvConfirmTitle');
        overlay.addEventListener('click', (e) => {
            if (e.target === overlay) this.closePrismIvConfirmModal();
        });

        const box = document.createElement('div');
        box.className = 'stats-content prism-iv-confirm-content';

        const localizePokemonFn: unknown = this['getLocalizedPokemonName'];
        const localizedName = typeof localizePokemonFn === 'function'
            ? coerceStr((localizePokemonFn as (this: ThisGame, n: string) => string).call(this, creature.name), creature.name)
            : creature.name;
        const safeName = escapeForHtml(localizedName);
        // Note : `t(..., { name })` ré-échappe automatiquement la valeur, donc on
        // passe la version brute (non échappée) pour éviter le double-escape.

        const spriteUrl = getPokemonSpriteUrl(creature.name, !!creature.isShiny, false);

        const remainingAfterUse = Math.max(0, (this.items['prism_iv'] || 0) - 1);

        const prismItemDef = ALL_ITEMS['prism_iv'] as { img?: string } | undefined;
        const prismImg = coerceStr(
            prismItemDef?.img,
            'https://raw.githubusercontent.com/msikma/pokesprite/master/items/key-item/key-stone.png',
        );

        const currentIVs = {
            hp: Number(creature.ivHP) || 0,
            atk: Number(creature.ivAttack) || 0,
            spatk: Number(creature.ivSpAttack) || 0,
            def: Number(creature.ivDefense) || 0,
            spdef: Number(creature.ivSpDefense) || 0,
            spd: Number(creature.ivSpeed) || 0,
        };

        const hasImprovements = isResultMode && priorIVs && (
            currentIVs.hp > priorIVs.hp
            || currentIVs.atk > priorIVs.atk
            || currentIVs.spatk > priorIVs.spatk
            || currentIVs.def > priorIVs.def
            || currentIVs.spdef > priorIVs.spdef
            || currentIVs.spd > priorIVs.spd
        );

        const titleLabel = isResultMode
            ? this.t(hasImprovements ? 'modal.creature.optimizeSuccessTitle' : 'modal.creature.optimizeNoChangeTitle')
            : this.t('modal.creature.optimizeConfirmTitle');
        const introHtml = isResultMode
            ? this.t(
                hasImprovements ? 'modal.creature.optimizeResultIntro' : 'modal.creature.optimizeResultIntroNoChange',
                { name: localizedName },
            )
            : this.t('modal.creature.optimizeConfirmIntro', { name: localizedName });
        const ivsLabel = escapeForHtml(
            isResultMode
                ? this.t('modal.creature.optimizeResultIVs')
                : this.t('modal.creature.optimizeConfirmCurrentIVs'),
        );
        const costLabel = escapeForHtml(this.t('modal.creature.optimizeConfirmCost'));
        const remainingLabel = escapeForHtml(this.t('modal.creature.optimizeConfirmRemaining', { count: remainingAfterUse }));
        const cancelLabel = escapeForHtml(this.t('modal.creature.optimizeConfirmCancel'));
        const ctaLabel = escapeForHtml(this.t('modal.creature.optimizeConfirmCta'));
        const closeLabel = escapeForHtml(this.t('modal.creature.optimizeResultClose'));
        const againLabel = escapeForHtml(this.t('modal.creature.optimizeResultAgain'));
        const prismRemaining = Math.max(0, this.items['prism_iv'] || 0);
        const canChainOptimize = isResultMode && prismRemaining > 0;
        const resultRemainingLabel = escapeForHtml(
            this.t('modal.creature.optimizeResultRemaining', { count: prismRemaining }),
        );

        const ivCell = (label: string, value: unknown) => `
            <div class="prism-iv-confirm-iv-cell">
                <span class="prism-iv-confirm-iv-label">${escapeForHtml(label)}</span>
                <span class="prism-iv-confirm-iv-value">${Number(value) || 0}</span>
            </div>
        `;

        const ivCellResult = (label: string, prior: number, current: number) => {
            const improved = current > prior;
            const valueHtml = improved
                ? `<span class="prism-iv-confirm-iv-values">
                        <span class="prism-iv-confirm-iv-value prism-iv-confirm-iv-value--old">${prior}</span>
                        <span class="prism-iv-confirm-iv-arrow" aria-hidden="true">→</span>
                        <span class="prism-iv-confirm-iv-value prism-iv-confirm-iv-value--new">${current}</span>
                   </span>`
                : `<span class="prism-iv-confirm-iv-value">${current}</span>`;
            return `
                <div class="prism-iv-confirm-iv-cell">
                    <span class="prism-iv-confirm-iv-label">${escapeForHtml(label)}</span>
                    ${valueHtml}
                </div>
            `;
        };

        const labels = {
            hp: this.t('modal.creature.hpFull') || 'HP',
            atk: this.t('modal.creature.atkShort') || 'ATK',
            spatk: this.t('modal.creature.spAtkShort') || 'SP.ATK',
            def: this.t('modal.creature.defShort') || 'DEF',
            spdef: this.t('modal.creature.spDefShort') || 'SP.DEF',
            spd: this.t('modal.creature.speedShort') || 'SPD'
        };

        const ivGridHtml = isResultMode && priorIVs
            ? `
                ${ivCellResult(labels.hp, priorIVs.hp, currentIVs.hp)}
                ${ivCellResult(labels.atk, priorIVs.atk, currentIVs.atk)}
                ${ivCellResult(labels.spatk, priorIVs.spatk, currentIVs.spatk)}
                ${ivCellResult(labels.def, priorIVs.def, currentIVs.def)}
                ${ivCellResult(labels.spdef, priorIVs.spdef, currentIVs.spdef)}
                ${ivCellResult(labels.spd, priorIVs.spd, currentIVs.spd)}
            `
            : `
                ${ivCell(labels.hp, currentIVs.hp)}
                ${ivCell(labels.atk, currentIVs.atk)}
                ${ivCell(labels.spatk, currentIVs.spatk)}
                ${ivCell(labels.def, currentIVs.def)}
                ${ivCell(labels.spdef, currentIVs.spdef)}
                ${ivCell(labels.spd, currentIVs.spd)}
            `;

        const costBlockHtml = isResultMode
            ? (canChainOptimize
                ? `
                <div class="prism-iv-confirm-cost">
                    <div class="prism-iv-confirm-cost-sub">${resultRemainingLabel}</div>
                </div>
            `
                : '')
            : `
                <div class="prism-iv-confirm-cost">
                    <div class="prism-iv-confirm-cost-line">${costLabel}</div>
                    <div class="prism-iv-confirm-cost-sub">${remainingLabel}</div>
                </div>
            `;

        const actionsHtml = isResultMode
            ? `
                <button type="button"
                        class="btn prism-iv-confirm-cancel"
                        data-action="closePrismIvConfirmModal">
                    ${closeLabel}
                </button>
                ${canChainOptimize ? `
                <button type="button"
                        class="btn prism-iv-confirm-submit"
                        data-action="applyOptimizeCreatureIVs"
                        data-arg="${creatureIndex}"
                        data-arg2="${escapeForHtml(location)}">
                    ${againLabel}
                </button>
                ` : ''}
            `
            : `
                <button type="button"
                        class="btn prism-iv-confirm-cancel"
                        data-action="closePrismIvConfirmModal">
                    ${cancelLabel}
                </button>
                <button type="button"
                        class="btn prism-iv-confirm-submit"
                        data-action="applyOptimizeCreatureIVs"
                        data-arg="${creatureIndex}"
                        data-arg2="${escapeForHtml(location)}">
                    ${ctaLabel}
                </button>
            `;

        const closeAriaLabel = isResultMode ? closeLabel : cancelLabel;

        box.innerHTML = `
            <div class="stats-header prism-iv-confirm-header">
                <h2 id="prismIvConfirmTitle">
                    <img src="${prismImg}" alt="" class="prism-iv-confirm-icon" aria-hidden="true">
                    ${escapeForHtml(titleLabel)}
                </h2>
                <button type="button"
                        class="stats-close"
                        data-action="closePrismIvConfirmModal"
                        aria-label="${closeAriaLabel}">&#10005;</button>
            </div>
            <div class="prism-iv-confirm-body">
                <div class="prism-iv-confirm-creature">
                    ${spriteUrl ? `<img src="${spriteUrl}" alt="${safeName}" class="prism-iv-confirm-sprite">` : ''}
                </div>
                <p class="prism-iv-confirm-intro">${introHtml}</p>
                <div class="prism-iv-confirm-iv-block">
                    <div class="prism-iv-confirm-iv-title">${ivsLabel}</div>
                    <div class="prism-iv-confirm-iv-grid">
                        ${ivGridHtml}
                    </div>
                </div>
                ${costBlockHtml}
            </div>
            <div class="prism-iv-confirm-actions">
                ${actionsHtml}
            </div>
        `;

        overlay.appendChild(box);
        document.body.appendChild(overlay);

        const focusBtn = box.querySelector(
            (isResultMode && canChainOptimize) || !isResultMode
                ? '.prism-iv-confirm-submit'
                : '.prism-iv-confirm-cancel',
        );
        if (focusBtn && typeof (focusBtn as HTMLButtonElement).focus === 'function') {
            try { (focusBtn as HTMLButtonElement).focus(); } catch (_) { /* ignore */ }
        }
    };

    // Ferme le modal de confirmation (utilisé par data-action).
    GameClass.prototype.closePrismIvConfirmModal = function (this: ThisGame) {
        const m = document.getElementById('prismIvConfirmModal');
        if (m) m.remove();
        refreshOpenCreatureModalIfVisible(this);
    };

    // LOGIQUE RÉELLE : Optimisation des IVs (Conserve le meilleur)
    // Appelée uniquement après confirmation explicite via le modal.
    GameClass.prototype.applyOptimizeCreatureIVs = function (this: ThisGame, creatureIndex: number, location: string) {
        if (!this.items['prism_iv'] || this.items['prism_iv'] <= 0) {
            toast.error(this.t('modal.creature.prismMissingTitle'), this.t('modal.creature.prismMissingBody'));
            return;
        }

        const creature = _getPrismTargetCreature(this, creatureIndex, location);
        if (!creature) return;

        const priorIVs: PrismIvPriorIVs = {
            hp: Number(creature.ivHP) || 0,
            atk: Number(creature.ivAttack) || 0,
            spatk: Number(creature.ivSpAttack) || 0,
            def: Number(creature.ivDefense) || 0,
            spdef: Number(creature.ivSpDefense) || 0,
            spd: Number(creature.ivSpeed) || 0,
        };

        this.items['prism_iv']--;

        const newHP = Math.floor(Math.pow(Math.random(), 3) * 32);
        const newAtk = Math.floor(Math.pow(Math.random(), 3) * 32);
        const newSpAtk = Math.floor(Math.pow(Math.random(), 3) * 32);
        const newDef = Math.floor(Math.pow(Math.random(), 3) * 32);
        const newSpDef = Math.floor(Math.pow(Math.random(), 3) * 32);
        const newSpd = Math.floor(Math.pow(Math.random(), 3) * 32);

        let improvements = 0;
        if (newHP > creature.ivHP) { creature.ivHP = newHP; improvements++; }
        if (newAtk > creature.ivAttack) { creature.ivAttack = newAtk; improvements++; }
        if (newSpAtk > creature.ivSpAttack) { creature.ivSpAttack = newSpAtk; improvements++; }
        if (newDef > creature.ivDefense) { creature.ivDefense = newDef; improvements++; }
        if (newSpDef > creature.ivSpDefense) { creature.ivSpDefense = newSpDef; improvements++; }
        if (newSpd > creature.ivSpeed) { creature.ivSpeed = newSpd; improvements++; }

        creature.recalculateStats!();
        creature.heal!();
        if (typeof this.tryGrantMegaStone === 'function') this.tryGrantMegaStone(creature, { silent: true });

        this.updateItemsDisplay();
        refreshCreatureDependentUi(this);

        this.showPrismIvConfirmModal(creatureIndex, location, { priorIVs });

        if (improvements > 0) {
            if (!this.stats || typeof this.stats !== 'object') this.stats = {} as GameStats;
            this.stats.ivUpgrades = (this.stats.ivUpgrades || 0) + 1;
            this.checkAchievements('ivUpgrades');
            toast.success(this.t('modal.creature.optimizeSuccessTitle'), this.t('modal.creature.optimizeSuccessBody', { name: creature.name, count: improvements }));
            logMessage(this.t('log.prismImproved', { name: creature.name }));
        } else {
            toast.warning(this.t('modal.creature.optimizeNoChangeTitle'), this.t('modal.creature.optimizeNoChangeBody'));
            logMessage(this.t('log.prismNoChange', { name: creature.name }));
        }
    };

    GameClass.prototype.resetPrestigeAllocations = function (
        this: ThisGame,
        creatureIndex: number,
        location: string,
        anchorEl?: HTMLElement | null,
    ) {
        if (!this.items[DYNITE_ORE_ITEM_KEY] || this.items[DYNITE_ORE_ITEM_KEY] <= 0) {
            toast.error(this.t('modal.creature.dyniteMissingTitle'), this.t('modal.creature.dyniteMissingBody'));
            return;
        }

        const creature = _getPrismTargetCreature(this, creatureIndex, location);
        if (!creature) return;

        if (sumPrestigeBonusesSpent(creature.prestigeBonuses) <= 0) {
            toast.info(this.t('modal.creature.dyniteNothingTitle'), this.t('modal.creature.dyniteNothingBody'));
            return;
        }

        const anchor = anchorEl && typeof (anchorEl as HTMLElement).getBoundingClientRect === 'function'
            ? (anchorEl as HTMLElement)
            : null;
        const existing = document.getElementById('dyniteOreConfirmPopover');
        if (existing && anchor && dyniteOrePopoverAnchorEl === anchor) {
            this.closeDyniteOreConfirmPopover();
            return;
        }

        if (!anchor) return;
        this.showDyniteOreConfirmPopover(anchor, creatureIndex, location);
    };

    GameClass.prototype.closeDyniteOreConfirmPopover = function (this: ThisGame) {
        const pop = document.getElementById('dyniteOreConfirmPopover');
        if (pop) pop.remove();
        if (dyniteOrePopoverOutsideListener) {
            document.removeEventListener('pointerdown', dyniteOrePopoverOutsideListener, true);
            dyniteOrePopoverOutsideListener = null;
        }
        dyniteOrePopoverAnchorEl = null;
    };

    GameClass.prototype.showDyniteOreConfirmPopover = function (
        this: ThisGame,
        anchorEl: HTMLElement,
        creatureIndex: number,
        location: string,
    ) {
        const creature = _getPrismTargetCreature(this, creatureIndex, location);
        if (!creature) return;

        const spent = sumPrestigeBonusesSpent(creature.prestigeBonuses);
        if (spent <= 0) return;

        this.closeDyniteOreConfirmPopover();

        const escapeForHtml = (value: unknown) => escapeHtml(coerceStr(value));
        const safeLocation = escapeForHtml(location);

        const popover = document.createElement('div');
        popover.id = 'dyniteOreConfirmPopover';
        popover.className = 'pension-contribution-popover is-dark dynite-ore-confirm-popover show';
        popover.setAttribute('role', 'dialog');
        popover.setAttribute('aria-modal', 'false');

        const bodyText = escapeForHtml(this.t('modal.creature.dynitePopoverConfirm', { count: spent }));
        const cancelLabel = escapeForHtml(this.t('modal.creature.dyniteConfirmCancel'));
        const ctaLabel = escapeForHtml(this.t('modal.creature.dyniteConfirmCta'));

        popover.innerHTML = `
            <p class="dynite-ore-confirm-text">${bodyText}</p>
            <div class="dynite-ore-confirm-actions">
                <button type="button"
                        class="dynite-ore-confirm-cancel"
                        data-action="closeDyniteOreConfirmPopover">
                    ${cancelLabel}
                </button>
                <button type="button"
                        class="dynite-ore-confirm-submit"
                        data-action="applyResetPrestigeAllocations"
                        data-arg="${creatureIndex}"
                        data-arg2="${safeLocation}">
                    ${ctaLabel}
                </button>
            </div>
        `;

        document.body.appendChild(popover);
        positionDyniteOreConfirmPopover(popover, anchorEl);
        dyniteOrePopoverAnchorEl = anchorEl;

        dyniteOrePopoverOutsideListener = (e: Event) => {
            const target = e.target;
            if (!(target instanceof Node)) return;
            if (popover.contains(target)) return;
            if (anchorEl.contains(target)) return;
            this.closeDyniteOreConfirmPopover();
        };
        document.addEventListener('pointerdown', dyniteOrePopoverOutsideListener, true);
    };

    GameClass.prototype.applyResetPrestigeAllocations = function (this: ThisGame, creatureIndex: number, location: string) {
        this.closeDyniteOreConfirmPopover();

        if (!this.items[DYNITE_ORE_ITEM_KEY] || this.items[DYNITE_ORE_ITEM_KEY] <= 0) {
            toast.error(this.t('modal.creature.dyniteMissingTitle'), this.t('modal.creature.dyniteMissingBody'));
            return;
        }

        const creature = _getPrismTargetCreature(this, creatureIndex, location);
        if (!creature) return;

        const spent = sumPrestigeBonusesSpent(creature.prestigeBonuses);
        if (spent <= 0) {
            toast.info(this.t('modal.creature.dyniteNothingTitle'), this.t('modal.creature.dyniteNothingBody'));
            return;
        }

        this.items[DYNITE_ORE_ITEM_KEY]--;
        if (this.items[DYNITE_ORE_ITEM_KEY] <= 0) delete this.items[DYNITE_ORE_ITEM_KEY];

        creature.prestigeTokens = (creature.prestigeTokens || 0) + spent;
        creature.prestigeBonuses = { ...EMPTY_PRESTIGE_BONUSES };

        creature.recalculateStats!();
        creature.heal!();

        this.updateItemsDisplay();
        refreshCreatureDependentUi(this);

        const localizePokemonFn: unknown = this['getLocalizedPokemonName'];
        const displayName = typeof localizePokemonFn === 'function'
            ? coerceStr((localizePokemonFn as (this: ThisGame, n: string) => string).call(this, creature.name), creature.name)
            : creature.name;

        toast.success(
            this.t('modal.creature.dyniteSuccessTitle'),
            this.t('modal.creature.dyniteSuccessBody', { name: displayName, count: spent }),
        );
        logMessage(this.t('modal.creature.dyniteSuccessBody', { name: displayName, count: spent }));

        this.showCreatureModal(creatureIndex, location);
    };

    GameClass.prototype.canRefundPrestigeLevel = function (this: ThisGame, creature: CreatureData) {
        return getPrestigeRecallRequirements(creature, this.items);
    };

    GameClass.prototype.closePrestigeRecallConfirmPopover = function (this: ThisGame) {
        const pop = document.getElementById('prestigeRecallConfirmPopover');
        if (pop) pop.remove();
        if (prestigeRecallPopoverOutsideListener) {
            document.removeEventListener('pointerdown', prestigeRecallPopoverOutsideListener, true);
            prestigeRecallPopoverOutsideListener = null;
        }
        prestigeRecallPopoverAnchorEl = null;
    };

    GameClass.prototype._toastPrestigeRecallBlock = function (this: ThisGame, reasonKey: string | undefined) {
        switch (reasonKey) {
            case 'missing_armorite_ore':
                toast.error(
                    this.t('modal.creature.prestigeRecallMissingArmoriteTitle'),
                    this.t('modal.creature.prestigeRecallMissingArmoriteBody'),
                );
                break;
            case 'missing_dynite':
                toast.error(
                    this.t('modal.creature.prestigeRecallMissingDyniteTitle'),
                    this.t('modal.creature.prestigeRecallMissingDyniteBody'),
                );
                break;
            case 'no_token':
                toast.error(
                    this.t('modal.creature.prestigeRecallNoTokenTitle'),
                    this.t('modal.creature.prestigeRecallNoTokenBody'),
                );
                break;
            default:
                toast.error(
                    this.t('modal.creature.prestigeRecallNoPrestigeTitle'),
                    this.t('modal.creature.prestigeRecallNoPrestigeBody'),
                );
        }
    };

    GameClass.prototype.refundPrestigeLevel = function (
        this: ThisGame,
        creatureIndex: number,
        location: string,
        anchorEl?: HTMLElement | null,
    ) {
        const creature = _getPrismTargetCreature(this, creatureIndex, location);
        if (!creature) return;

        const req = getPrestigeRecallRequirements(creature, this.items);
        if (!req.canApply) {
            this._toastPrestigeRecallBlock(req.reasonKey);
            return;
        }

        const anchor = anchorEl && typeof (anchorEl as HTMLElement).getBoundingClientRect === 'function'
            ? (anchorEl as HTMLElement)
            : null;
        const existing = document.getElementById('prestigeRecallConfirmPopover');
        if (existing && anchor && prestigeRecallPopoverAnchorEl === anchor) {
            this.closePrestigeRecallConfirmPopover();
            return;
        }

        if (!anchor) return;
        this.showPrestigeRecallConfirmPopover(anchor, creatureIndex, location);
    };

    GameClass.prototype.showPrestigeRecallConfirmPopover = function (
        this: ThisGame,
        anchorEl: HTMLElement,
        creatureIndex: number,
        location: string,
    ) {
        const creature = _getPrismTargetCreature(this, creatureIndex, location);
        if (!creature) return;

        const req = getPrestigeRecallRequirements(creature, this.items);
        if (!req.canApply) return;

        this.closePrestigeRecallConfirmPopover();
        this.closeDyniteOreConfirmPopover();

        const localizePokemonFn: unknown = this['getLocalizedPokemonName'];
        const displayName = typeof localizePokemonFn === 'function'
            ? coerceStr((localizePokemonFn as (this: ThisGame, n: string) => string).call(this, creature.name), creature.name)
            : creature.name;

        const escapeForHtml = (value: unknown) => escapeHtml(coerceStr(value));
        const safeLocation = escapeForHtml(location);
        const bodyText = escapeForHtml(this.t('modal.creature.prestigeRecallPopover', {
            name: displayName,
            stones: req.stones,
        }));
        const cancelLabel = escapeForHtml(this.t('modal.creature.prestigeRecallConfirmCancel'));
        const ctaLabel = escapeForHtml(this.t('modal.creature.prestigeRecallConfirmCta'));

        const popover = document.createElement('div');
        popover.id = 'prestigeRecallConfirmPopover';
        popover.className = 'pension-contribution-popover is-dark dynite-ore-confirm-popover show';
        popover.setAttribute('role', 'dialog');
        popover.setAttribute('aria-modal', 'false');

        popover.innerHTML = `
            <p class="dynite-ore-confirm-text">${bodyText}</p>
            <div class="dynite-ore-confirm-actions">
                <button type="button"
                        class="dynite-ore-confirm-cancel"
                        data-action="closePrestigeRecallConfirmPopover">
                    ${cancelLabel}
                </button>
                <button type="button"
                        class="dynite-ore-confirm-submit"
                        data-action="applyRefundPrestigeLevel"
                        data-arg="${creatureIndex}"
                        data-arg2="${safeLocation}">
                    ${ctaLabel}
                </button>
            </div>
        `;

        document.body.appendChild(popover);
        positionDyniteOreConfirmPopover(popover, anchorEl);
        prestigeRecallPopoverAnchorEl = anchorEl;

        prestigeRecallPopoverOutsideListener = (e: Event) => {
            const target = e.target;
            if (!(target instanceof Node)) return;
            if (popover.contains(target)) return;
            if (anchorEl.contains(target)) return;
            this.closePrestigeRecallConfirmPopover();
        };
        document.addEventListener('pointerdown', prestigeRecallPopoverOutsideListener, true);
    };

    GameClass.prototype.applyRefundPrestigeLevel = function (this: ThisGame, creatureIndex: number, location: string) {
        this.closePrestigeRecallConfirmPopover();

        const creature = _getPrismTargetCreature(this, creatureIndex, location);
        if (!creature) return;

        const req = getPrestigeRecallRequirements(creature, this.items);
        if (!req.canApply) {
            this._toastPrestigeRecallBlock(req.reasonKey);
            return;
        }

        const stonesRefunded = getPrestigeStoneRefundAmount(creature.prestige);

        if (!this.items) this.items = {};
        this.items[DYNITE_ORE_ITEM_KEY] = (this.items[DYNITE_ORE_ITEM_KEY] || 0) - 1;
        if (this.items[DYNITE_ORE_ITEM_KEY] <= 0) delete this.items[DYNITE_ORE_ITEM_KEY];

        const spent = sumPrestigeBonusesSpent(creature.prestigeBonuses);
        if (spent > 0) {
            creature.prestigeTokens = (creature.prestigeTokens || 0) + spent;
            creature.prestigeBonuses = { ...EMPTY_PRESTIGE_BONUSES };
        }

        this.items[ARMORITE_ORE_ITEM_KEY] = (this.items[ARMORITE_ORE_ITEM_KEY] || 0) - 1;
        if (this.items[ARMORITE_ORE_ITEM_KEY] <= 0) delete this.items[ARMORITE_ORE_ITEM_KEY];

        const currentStones = this.items.prestige_stone || 0;
        this.items.prestige_stone = currentStones + stonesRefunded;

        creature.prestige--;
        creature.prestigeTokens = Math.max(0, (creature.prestigeTokens || 0) - 1);

        const maxLevel = 100 + (creature.prestige * 10);
        if (creature.level > maxLevel) creature.level = maxLevel;

        creature.recalculateStats!();
        creature.heal!();
        creature.currentStamina = creature.maxStamina;

        this.calculateTeamStats();
        this.updateTeamDisplay();
        this.updateStorageDisplay();
        this.updatePensionDisplay();
        this.updateItemsDisplay();
        refreshCreatureDependentUi(this);

        const localizePokemonFn: unknown = this['getLocalizedPokemonName'];
        const displayName = typeof localizePokemonFn === 'function'
            ? coerceStr((localizePokemonFn as (this: ThisGame, n: string) => string).call(this, creature.name), creature.name)
            : creature.name;

        toast.success(
            this.t('modal.creature.prestigeRecallSuccessTitle'),
            this.t('modal.creature.prestigeRecallSuccessBody', { name: displayName, stones: stonesRefunded }),
        );
        logMessage(this.t('log.prestigeRecall', { name: displayName, stones: stonesRefunded }));

        this.showCreatureModal(creatureIndex, location);
    };

    GameClass.prototype.buildEvolutionModalPayload = function (
        this: ThisGame,
        oldName: string,
        newName: string,
        isShiny: boolean,
        mode: 'cinematic' | 'fusion-short',
        fusionExtras?: { shards: number; ivImproved: boolean },
    ) {
        const localizeFn: unknown = this['getLocalizedPokemonName'];
        const oldDisplayName = typeof localizeFn === 'function'
            ? coerceStr((localizeFn as (this: ThisGame, n: string) => string).call(this, oldName), oldName)
            : oldName;
        const newDisplayName = typeof localizeFn === 'function'
            ? coerceStr((localizeFn as (this: ThisGame, n: string) => string).call(this, newName), newName)
            : newName;
        const reducedMotion = !!this.reducedMotion
            || (typeof window !== 'undefined'
                && typeof window.matchMedia === 'function'
                && window.matchMedia('(prefers-reduced-motion: reduce)').matches);

        const base = {
            oldName,
            newName,
            oldDisplayName,
            newDisplayName,
            oldSpriteUrl: getPokemonSpriteUrl(oldName, isShiny, false),
            newSpriteUrl: getPokemonSpriteUrl(newName, isShiny, false),
            isShiny,
            reducedMotion,
            whatText: this.t('modal.evolution.what', { name: oldDisplayName }),
            congratsText: this.t('modal.evolution.congrats', { old: oldDisplayName, next: newDisplayName }),
            confirmLabel: this.t('modal.evolution.confirm'),
        };

        if (mode === 'fusion-short') {
            const boostSuffix = fusionExtras?.ivImproved ? ' & Boost stats' : '';
            return {
                ...base,
                mode: 'fusion-short' as const,
                fusionTitle: this.t('modal.evolution.fusionTitle'),
                fusionBody: this.t('modal.evolution.fusionBody', {
                    old: oldDisplayName,
                    next: newDisplayName,
                    shards: fusionExtras?.shards ?? 0,
                    boostSuffix,
                }),
            };
        }

        return { ...base, mode: 'cinematic' as const };
    };

    GameClass.prototype.commitEvolutionMutation = function (
        this: ThisGame,
        creature: CreatureData,
        oldName: string,
        newName: string,
        preservedLearnedMoves: string[],
        location: string,
    ) {
        creature.name = newName;
        creature.type = this.findTypeForPokemon(newName);
        creature.secondaryType = POKEMON_SECONDARY_TYPES[newName] ?? null;

        const syncDpsSnapshotFn: unknown = this['syncDpsMeterSnapshotForCreature'];
        if (typeof syncDpsSnapshotFn === 'function') {
            (syncDpsSnapshotFn as (this: ThisGame, c: CreatureData, o?: { previousName?: string }) => void)
                .call(this, creature, { previousName: oldName });
        }

        preservedLearnedMoves.forEach((moveName: string) => {
            this.unlockMoveForFamily(oldName, moveName);
            this.unlockMoveForFamily(newName, moveName);
        });

        const newPool = getFamilyNaturalMovesPool(newName);
        if (newPool && newPool.length > 0) {
            const newRandomMove = pickRandomFamilyNaturalMove(newName);
            const unlockMoveFn: unknown = this['unlockMoveForFamily'];
            const unlocked = typeof unlockMoveFn === 'function'
                && (unlockMoveFn as (this: ThisGame, n: string, m: string) => boolean).call(this, newName, newRandomMove);
            const assignMoveFn: unknown = this['tryAssignUnlockedMoveToFamily'];
            if (unlocked && typeof assignMoveFn === 'function') {
                (assignMoveFn as (this: ThisGame, n: string, m: string) => number).call(this, newName, newRandomMove);
            }
            if (unlocked) {
                toast.info(this.t('toast.newMoveTitle'), this.t('toast.newMoveFamilyBody', { name: newName, move: this.getLocalizedMoveNamePlain(newRandomMove) }));
            }
        }

        const newRarity = getNaturalRarity(this, newName) ?? creature.rarity;
        if (creature.rarity !== newRarity) {
            creature.rarity = newRarity;
            if (!creature.passiveTalent && (newRarity === RARITY.EPIC || newRarity === RARITY.LEGENDARY)) {
                creature.assignRandomTalent!();
                const talentKey = coerceStr(creature.passiveTalent);
                const talentDef = (PASSIVE_TALENTS as Record<string, { name?: string }>)[talentKey];
                const localizeTalentFn: unknown = this['getLocalizedPassiveTalentName'];
                const unlockedTalentName = typeof localizeTalentFn === 'function'
                    ? (localizeTalentFn as (this: ThisGame, key: string, fallback: string) => string)
                        .call(this, talentKey, coerceStr(talentDef?.name, talentKey))
                    : talentKey;
                logMessage(this.t('log.newTalentUnlocked', { talent: unlockedTalentName }));
            }
        }

        creature.ultimateAbility = resolveUltimateAbility(creature.name, creature.rarity);

        creature.recalculateStats!();
        creature.heal!();

        const dexKeyFull = creature.name + '_' + creature.type + '_' + creature.rarity;
        if (!this.pokedex[dexKeyFull]) {
            this.pokedex[dexKeyFull] = {
                seen: true, caught: true, shinySeen: !!creature.isShiny, shinyCaught: !!creature.isShiny,
                discovered: true,
                count: 1,
                shinyCount: creature.isShiny ? 1 : 0,
                hasShiny: !!creature.isShiny,
                name: creature.name, type: creature.type, rarity: creature.rarity,
                firstDiscoveredAt: Date.now(),
            };
            this.checkSpecialQuests('new_discovery');
        } else {
            this.pokedex[dexKeyFull].count++;
            if (creature.isShiny) {
                this.pokedex[dexKeyFull].shinyCount = (this.pokedex[dexKeyFull].shinyCount || 0) + 1;
                this.pokedex[dexKeyFull].hasShiny = true;
            }
        }

        this.stats.evolutionsCount++;
        if (typeof this.checkSpecialQuests === 'function') {
            this.checkSpecialQuests('evolutionCount');
            this.checkSpecialQuests(
                'species_evolved',
                buildEvolutionQuestEventParams(oldName, newName, creature as Record<string, unknown>),
            );
            if (creature.isStarter) {
                this.checkSpecialQuests('starter_evolved', { baseName: oldName, evolvedName: newName });
            }
        }

        logMessage(
            this.t('log.evolutionBecome', { old: oldName, next: newName })
            + (creature.isShiny ? (' ' + this.t('log.evolutionShinyKept')) : '')
            + (creature.prestige > 0 ? (' ' + this.t('log.evolutionPrestigeKept', { prestige: creature.prestige })) : ''),
        );

        if (location === 'team' && this.currentPlayerCreature === creature) {
            this.updateCombatDisplay();
        }
        refreshCreatureDependentUi(this);
    };

    // LOGIQUE : ?volution S?curis?e (Pr?serve Shiny, IVs, Prestige)
    GameClass.prototype.evolveCreature = function (this: ThisGame, creatureIndex: number, location: string, selectedOption: AvailableEvolutionOption | null = null) {
        let creature: CreatureData | undefined;
        let containerArray: CreatureData[] | undefined;

        // 1. Identification de la cible
        if (location === 'team') {
            creature = this.playerTeam[creatureIndex];
            containerArray = this.playerTeam;
        } else if (location === 'storage') {
            creature = this.storage[creatureIndex];
            containerArray = this.storage;
        } else if (location === 'pension') {
            creature = this.pension[creatureIndex];
            containerArray = this.pension;
        }

        if (!creature) {
            debugError(`[ERROR] Erreur evolution: Creature introuvable [${location}:${creatureIndex}]`);
            return;
        }

        // 2. V?rification des conditions
        const evolutionData = EVOLUTIONS[resolveCanonicalSpeciesName(creature.name)];
        if (!evolutionData) return; // Pas d'?volution

        const availableOptions = availableEvolutionOptions(this, creature, (c) => resolveEvolutionConditionItem(c));
        if (availableOptions.length === 0) {
            logMessage(this.t('log.evolutionConditionsMissing', { name: creature.name }));
            return;
        }

        let chosenOption: AvailableEvolutionOption | null = null;
        if (selectedOption?.evolves_to) {
            chosenOption = availableOptions.find((opt) => (
                opt.evolves_to === selectedOption.evolves_to &&
                (opt.requiredItem ?? null) === (selectedOption.requiredItem ?? null)
            )) ?? null;
        }
        if (!chosenOption) chosenOption = availableOptions[0] ?? null;
        if (!chosenOption) return;

        const oldName = creature.name;
        const newName = chosenOption.evolves_to;
        const preservedLearnedMoves = Array.isArray(creature.currentMoves) ? creature.currentMoves.slice() : [];

        // Consommer l'objet si n?cessaire
        if (chosenOption.requiredItem) {
            const requiredItem = String(chosenOption.requiredItem);
            this.items[requiredItem] = (this.items[requiredItem] ?? 0) - 1;
            if ((this.items[requiredItem] ?? 0) <= 0) {
                delete this.items[requiredItem];
            }
            this.updateItemsDisplay();
        }

        // 3. V?RIFICATION DOUBLON (Fusion)
        // On regarde si on poss?de D?J? la forme ?volu?e (avec le même statut Shiny)
        const existingEvo = findCreatureByName(this, newName, !!creature.isShiny, !!creature.isShadow);

        if (existingEvo) {
            // CAS A : FUSION ?VOLUTIVE (on poss?de d?j? la forme ?volu?e)
            // On fusionne l'actuel (source) DANS celui qui existe d?j? (target)
            const fusionFn: unknown = this['processFusion'];
            const result: FusionResult = typeof fusionFn === 'function'
                ? (fusionFn as (this: ThisGame, s: CreatureData, t: CreatureData) => FusionResult).call(this, creature, existingEvo)
                : { improved: false, ivImproved: false, shards: 0, prestigeUp: false, becameShiny: false, rarityUp: false };
            if (typeof this.registerLoadoutUidRedirect === 'function') {
                this.registerLoadoutUidRedirect(creature.uid, existingEvo.uid);
            }

            // Remettre l'objet tenu par la cr?ature fusionn?e dans l'inventaire (sinon il est perdu)
            if (creature.heldItem) {
                const itemKey = coerceStr(creature.heldItem);
                this.items[itemKey] = (this.items[itemKey] || 0) + 1;
                const heldDef = (HELD_ITEMS as Record<string, { name?: string }>)[itemKey];
                const localizeItemFn: unknown = this['getLocalizedItemName'];
                const itemName = typeof localizeItemFn === 'function'
                    ? coerceStr(
                        (localizeItemFn as (this: ThisGame, key: string, fallback: string, def: Record<string, unknown> | null) => string)
                            .call(this, itemKey, coerceStr(heldDef?.name, itemKey), (heldDef as Record<string, unknown> | undefined) ?? null),
                        itemKey,
                    )
                    : itemKey;
                toast.info(this.t('toast.itemRecoveredTitle'), this.t('toast.itemRecoveredBody', { item: itemName }));
            }

            const sourceWasActive = location === 'team' && creatureIndex === this.activeCreatureIndex;
            const relocateFn: unknown = this['relocateFusionTargetAfterSourceRemoved'];
            if (typeof relocateFn === 'function') {
                (relocateFn as (
                    this: ThisGame,
                    target: CreatureData,
                    sourceLocation: 'team' | 'storage' | 'pension',
                    sourceIndex: number,
                    sourceWasActive: boolean,
                ) => void).call(
                    this,
                    existingEvo,
                    location as 'team' | 'storage' | 'pension',
                    creatureIndex,
                    sourceWasActive,
                );
            } else if (location === 'team') {
                this.playerTeam.splice(creatureIndex, 1);
            } else if (location === 'storage') {
                this.storage.splice(creatureIndex, 1);
            } else if (location === 'pension') {
                this.pension.splice(creatureIndex, 1);
            }

            logMessage(this.t('log.evolutionFusionAbsorbed', { old: oldName, next: existingEvo.name }) + (result.ivImproved ? (' ' + this.t('log.evolutionFusionStats')) : '') + (result.prestigeUp ? (' ' + this.t('log.evolutionFusionPrestige')) : ''));

            const fusionPayload = this.buildEvolutionModalPayload(
                oldName,
                newName,
                !!creature.isShiny,
                'fusion-short',
                { shards: result.shards, ivImproved: result.ivImproved },
            );
            showEvolutionFusionShort(fusionPayload);

            // Qu?te sp?ciale : ?volution Fusion (et ?volution du starter si concern?)
            if (typeof this.checkSpecialQuests === 'function') {
                this.checkSpecialQuests(
                    'evolution_fusion',
                    buildEvolutionQuestEventParams(oldName, newName, existingEvo as Record<string, unknown>),
                );
                if (creature.isStarter) {
                    this.checkSpecialQuests('starter_evolved', { baseName: oldName, evolvedName: newName });
                }
            }

            refreshCreatureDependentUi(this);
            this.closeCreatureModal();
            return;
        }

        // CAS B : mutation immédiate (objet consommé ci-dessus), puis cinématique de célébration
        this.commitEvolutionMutation(creature, oldName, newName, preservedLearnedMoves, location);
        this.closeCreatureModal();
        const cinematicPayload = this.buildEvolutionModalPayload(oldName, newName, !!creature.isShiny, 'cinematic');
        showEvolutionCinematic(cinematicPayload);
    };

    GameClass.prototype.prestigeCreature = function (this: ThisGame, creatureIndex: number, location: string) {
        let creature: CreatureData | undefined;

        // 1. Identifier la cr?ature selon l'endroit
        if (location === 'pension') {
            creature = this.pension[creatureIndex];
        } else if (location === 'storage') {
            creature = this.storage[creatureIndex];
        } else {
            // Par d?faut, ou si location === 'team'
            creature = this.playerTeam[creatureIndex];
        }

        if (!creature) {
            debugError("Erreur Prestige : Créature introuvable à l'index " + creatureIndex + " dans " + location);
            return;
        }

        const maxLevel = 100 + (creature.prestige * 10);
        if (creature.level < maxLevel) {
            logMessage(this.t('log.prestigeNeedLevel', { name: creature.name, level: maxLevel }));
            return;
        }

        const shardKey = getShardKey(creature.name, creature.rarity);
        const prestigeCostFn: unknown = this['getPrestigeCost'];
        const shardsNeeded = typeof prestigeCostFn === 'function'
            ? Number((prestigeCostFn as (this: ThisGame, level: number) => number).call(this, creature.prestige)) || 0
            : 0;
        const prestigeStoneFn: unknown = this['getPrestigeStoneCost'];
        const baseStonesNeeded = typeof prestigeStoneFn === 'function'
            ? Number((prestigeStoneFn as (this: ThisGame, level: number) => number).call(this, creature.prestige)) || shardsNeeded
            : shardsNeeded;
        const catchUpCosts = getAnchorCatchUpPrestigeCosts(creature, this, shardsNeeded, baseStonesNeeded);
        const shardsNeededFinal = catchUpCosts.shards;
        const stonesNeeded = catchUpCosts.stones;

        const currentShards = this.shards[shardKey] || 0;

        if (currentShards < shardsNeededFinal) {
            logMessage(this.t('log.prestigeNeedShards', { current: currentShards, needed: shardsNeededFinal }));
            return;
        }

        if (!this.items) this.items = {};
        const currentPrestigeStones = this.items.prestige_stone || 0;
        if (currentPrestigeStones < stonesNeeded) {
            logMessage(this.t('log.prestigeNeedStones', { current: currentPrestigeStones, needed: stonesNeeded }));
            return;
        }

        this.shards[shardKey] = (this.shards[shardKey] ?? 0) - shardsNeededFinal;
        this.items.prestige_stone = currentPrestigeStones - stonesNeeded;
        if (this.items.prestige_stone <= 0) delete this.items.prestige_stone;
        creature.prestige++;
        // ? GAIN DU TOKEN
        if (!creature.prestigeTokens) creature.prestigeTokens = 0;
        creature.prestigeTokens++;

        creature.level = 1;
        creature.exp = 0;
        creature.expToNext = creature.getExpToNext!();

        creature.recalculateStats!();
        creature.heal!();
        creature.currentStamina = creature.maxStamina;
        creature.level = 1;
        creature.exp = 0;
        creature.expToNext = creature.getExpToNext!();

        creature.recalculateStats!();
        creature.heal!();
        creature.currentStamina = creature.maxStamina;

        invalidateResonanceCache(this);

        this.stats.prestigeCount++;
        this.updateTeamPowerStat();
        this.checkSpecialQuests('prestigeCount');
        this.checkAchievements('prestigeCount');
        this.checkAchievements('team_changed');

        const shinyText = creature.isShiny ? " SHINY" : "";
        logMessage(this.t('log.prestigeUp', { name: creature.name, shiny: shinyText, prestige: creature.prestige }));
        logMessage(this.t('log.prestigeToken', { name: creature.name }));

        this.calculateTeamStats();
        this.updateTeamDisplay();
        this.updateStorageDisplay();
        this.updatePensionDisplay();
        // Mise ? jour des compteurs de shards du recycleur si ouvert
        const recyclerEl = document.getElementById('shop-recycleur');
        if (recyclerEl && recyclerEl.classList.contains('active')) {
            this.updateRecyclerDisplay();
        }
        this.updateItemsDisplay();
        if (typeof this.checkAndShowCollectionBonusModal === 'function') this.checkAndShowCollectionBonusModal();
        const reducedMotion = !!this.reducedMotion || prefersReducedMotion();
        const toastTitle = this.t('toast.prestigeTitle');
        const toastBody = this.t('toast.prestigeBody', { name: creature.name, prestige: creature.prestige });
        const showPrestigeToast = () => {
            toast.success(toastTitle, toastBody);
        };
        const prestigeLevel = creature.prestige;
        void this.showCreatureModal(creatureIndex, location).then(() => {
            void playPrestigeBurst({ prestige: prestigeLevel, reducedMotion }).then(showPrestigeToast);
        });
    };

    // LOGIQUE : D?pense d'un jeton de prestige
    GameClass.prototype.spendPrestigeToken = function (this: ThisGame, creatureIndex: number, location: string, stat: string) {
        let creature: CreatureData | undefined;
        if (location === 'team') creature = this.playerTeam[creatureIndex];
        else if (location === 'storage') creature = this.storage[creatureIndex];
        else if (location === 'pension') creature = this.pension[creatureIndex];

        if (!creature) return;

        if (creature.prestigeTokens > 0) {
            creature.prestigeTokens--;

            if (!creature.prestigeBonuses) creature.prestigeBonuses = { hp: 0, attack: 0, spattack: 0, spdefense: 0, defense: 0, speed: 0 };
            (creature.prestigeBonuses as unknown as Record<string, number>)[stat] = ((creature.prestigeBonuses as unknown as Record<string, number>)[stat] ?? 0) + 1;

            creature.recalculateStats!();

            // Feedback
            const statNames: Record<string, string> = { hp: 'PV', attack: 'ATK', defense: 'DEF', speed: 'VIT' };
            logMessage(this.t('log.prestigeStatBoost', { name: creature.name, stat: statNames[stat] ?? stat }));

            // Rafra?chir le modal pour voir le changement imm?diat
            this.showCreatureModal(creatureIndex, location);

            // Rafra?chir les affichages globaux
            refreshCreatureDependentUi(this);
        }
    };
}
