/**
 * Egg bonus rewards for quests that require capturing Pokémon with IV constraints.
 */

import { AUTO_INCUBATION_DEFAULT_PRIORITY, RARITY } from '../../constants/core.ts';
import type { GameRuntime } from '../types/game.js';
import { speciesRarityForCapture } from './captureSpeciesRarity.ts';

const IV_CAPTURE_STAT_FIELDS = [
    'ivHP',
    'ivAttack',
    'ivDefense',
    'ivSpAttack',
    'ivSpDefense',
    'ivSpeed',
] as const;

const RARITY_RANK: Record<string, number> = Object.fromEntries(
    AUTO_INCUBATION_DEFAULT_PRIORITY.map((rarity, index) => [rarity, index]),
);

type QuestEggRewardTarget = {
    trackingKey?: string;
    requiredSpecies?: string;
    specialParams?: {
        minIvPercent?: unknown;
        obtainSpecies?: string;
        captureRequirements?: Array<Record<string, unknown>>;
        _ivCaptureEggBonus?: Record<string, number>;
    } | null;
    rewards?: {
        eggs?: Record<string, number>;
    } | null;
};

export function captureRequirementHasIvGate(req: Record<string, unknown> | null | undefined): boolean {
    if (!req || typeof req !== 'object') return false;
    const minIvPercent = Number(req.minIvPercent);
    if (Number.isFinite(minIvPercent) && minIvPercent > 0) return true;
    for (let i = 0; i < IV_CAPTURE_STAT_FIELDS.length; i++) {
        const field = IV_CAPTURE_STAT_FIELDS[i];
        if (field === undefined) continue;
        const minKey = `min${field.charAt(0).toUpperCase()}${field.slice(1)}`;
        const minStat = Number(req[minKey]);
        if (Number.isFinite(minStat) && minStat > 0) return true;
    }
    return false;
}

export function questRequiresIvCapture(quest: QuestEggRewardTarget | null | undefined): boolean {
    if (!quest || quest.trackingKey !== 'creature_captured') return false;
    const captureRequirements = quest.specialParams?.captureRequirements;
    if (Array.isArray(captureRequirements) && captureRequirements.length > 0) {
        return captureRequirements.some((req) => captureRequirementHasIvGate(req));
    }
    const minIv = Number(quest.specialParams?.minIvPercent);
    return Number.isFinite(minIv) && minIv > 0;
}

function nextEggRarity(rarity: string): string | null {
    const idx = RARITY_RANK[rarity];
    if (idx === undefined) return null;
    return AUTO_INCUBATION_DEFAULT_PRIORITY[idx + 1] ?? null;
}

function highestSpeciesRarity(game: GameRuntime, speciesNames: string[]): string {
    let bestRarity = RARITY.COMMON;
    let bestRank = RARITY_RANK[bestRarity] ?? 0;
    for (let i = 0; i < speciesNames.length; i++) {
        const name = String(speciesNames[i] || '').trim();
        if (!name) continue;
        const rarity = speciesRarityForCapture(game, name);
        const rank = RARITY_RANK[rarity] ?? 0;
        if (rank > bestRank) {
            bestRank = rank;
            bestRarity = rarity;
        }
    }
    return bestRarity;
}

export function resolveIvCaptureRewardSpecies(quest: QuestEggRewardTarget | null | undefined): string | null {
    if (!quest) return null;
    const captureRequirements = quest.specialParams?.captureRequirements;
    if (Array.isArray(captureRequirements) && captureRequirements.length > 0) {
        const ivSpecies = new Set<string>();
        for (let i = 0; i < captureRequirements.length; i++) {
            const req = captureRequirements[i];
            if (!captureRequirementHasIvGate(req)) continue;
            const species = String(req?.requiredSpecies || '').trim();
            if (species) ivSpecies.add(species);
        }
        if (ivSpecies.size === 0) return null;
        if (ivSpecies.size === 1) return [...ivSpecies][0] ?? null;
        return null;
    }
    const obtainSpecies = String(quest.specialParams?.obtainSpecies || '').trim();
    if (obtainSpecies) return obtainSpecies;
    const requiredSpecies = String(quest.requiredSpecies || '').trim();
    return requiredSpecies || null;
}

export function resolveIvCaptureRewardSpeciesWithRarity(
    game: GameRuntime,
    quest: QuestEggRewardTarget | null | undefined,
): { species: string | null; rarity: string | null } {
    if (!quest) return { species: null, rarity: null };
    const captureRequirements = quest.specialParams?.captureRequirements;
    if (Array.isArray(captureRequirements) && captureRequirements.length > 0) {
        const ivSpecies: string[] = [];
        for (let i = 0; i < captureRequirements.length; i++) {
            const req = captureRequirements[i];
            if (!captureRequirementHasIvGate(req)) continue;
            const species = String(req?.requiredSpecies || '').trim();
            if (species) ivSpecies.push(species);
        }
        if (ivSpecies.length === 0) return { species: null, rarity: null };
        const rarity = highestSpeciesRarity(game, ivSpecies);
        return { species: ivSpecies[0] ?? null, rarity };
    }
    const species = resolveIvCaptureRewardSpecies(quest);
    if (!species) return { species: null, rarity: null };
    return { species, rarity: speciesRarityForCapture(game, species) };
}

export function buildIvCaptureEggRewards(game: GameRuntime, speciesName: string): Record<string, number> {
    const species = String(speciesName || '').trim();
    if (!species) return {};
    const rarity = speciesRarityForCapture(game, species);
    if (rarity === RARITY.LEGENDARY) {
        return { [RARITY.LEGENDARY]: 10 };
    }
    const bonus: Record<string, number> = { [rarity]: 6 };
    const upgraded = nextEggRarity(rarity);
    if (upgraded) bonus[upgraded] = 3;
    return bonus;
}

function removeTrackedEggBonus(quest: QuestEggRewardTarget): void {
    const previous = quest.specialParams?._ivCaptureEggBonus;
    if (!previous || typeof previous !== 'object') return;
    if (!quest.rewards?.eggs) return;
    for (const [rarity, count] of Object.entries(previous)) {
        const safeCount = Math.max(0, Math.floor(Number(count) || 0));
        if (safeCount <= 0) continue;
        const current = Math.max(0, Math.floor(Number(quest.rewards.eggs[rarity]) || 0));
        const next = current - safeCount;
        if (next > 0) quest.rewards.eggs[rarity] = next;
        else delete quest.rewards.eggs[rarity];
    }
}

export function ensureIvCaptureEggRewards(game: GameRuntime, quest: QuestEggRewardTarget): boolean {
    if (!questRequiresIvCapture(quest)) return false;
    const { species, rarity } = resolveIvCaptureRewardSpeciesWithRarity(game, quest);
    if (!species || !rarity) return false;

    const bonus = buildIvCaptureEggRewards(game, species);
    if (Object.keys(bonus).length === 0) return false;

    if (!quest.specialParams || typeof quest.specialParams !== 'object') {
        quest.specialParams = {};
    }
    if (!quest.rewards || typeof quest.rewards !== 'object') {
        quest.rewards = { eggs: {} };
    }
    if (!quest.rewards.eggs || typeof quest.rewards.eggs !== 'object') {
        quest.rewards.eggs = {};
    }

    removeTrackedEggBonus(quest);
    for (const [rarityKey, count] of Object.entries(bonus)) {
        const safeCount = Math.max(0, Math.floor(Number(count) || 0));
        if (safeCount <= 0) continue;
        quest.rewards.eggs[rarityKey] = Math.max(0, Math.floor(Number(quest.rewards.eggs[rarityKey]) || 0)) + safeCount;
    }
    quest.specialParams._ivCaptureEggBonus = { ...bonus };
    return true;
}
