/**
 * @file dynamaxCombat.ts
 * Dynamax activation and combat modifiers (Galar).
 * Account-level timed window — survives wild startCombat waves while remainingMs > 0.
 */

import {
    getDynamaxDamageMult,
    getDynamaxDurationMs,
    getDynamaxHpMult,
} from '../../constants/balance/dynamax.ts';
import { formatNumber } from '../../formatters.ts';
import type { CombatStatKey } from '../types/combat.js';
import type { CreatureData, ICreature } from '../types/creature.js';
import type { GameRuntime } from '../types/game.js';
import type { HudCombatStatDisplay } from './combatStatStageDisplay.ts';
import {
    createDefaultDynamaxCombatState,
    getDynamaxUpgradeLevel,
    isDynamaxBandUnlocked,
    isDynamaxZoneCombat,
} from './dynamaxLogic.ts';

type DynamaxHpCreature = CreatureData & {
    _dynamaxHpBoosted?: boolean;
    _dynamaxHpBoostMult?: number;
};

function scaleCreatureHp(creature: CreatureData, mult: number): void {
    const maxHp = Math.max(1, Number(creature.maxHp) || 1);
    const newMax = Math.max(1, Math.floor(maxHp * mult));
    const ratio = maxHp > 0 ? (Number(creature.currentHp) || maxHp) / maxHp : 1;
    creature.maxHp = newMax;
    creature.currentHp = Math.max(1, Math.min(newMax, Math.floor(newMax * ratio)));
    if (Number.isFinite(creature.mainAccountCurrentHp)) {
        const mainMax = Math.max(1, Number(creature.mainAccountMaxHp) || newMax);
        const mainNewMax = Math.max(1, Math.floor(mainMax * mult));
        creature.mainAccountMaxHp = mainNewMax;
        creature.mainAccountCurrentHp = Math.max(
            1,
            Math.min(mainNewMax, Math.floor(mainNewMax * ratio)),
        );
    }
}

function resolveHpMult(game: GameRuntime): number {
    return getDynamaxHpMult(getDynamaxUpgradeLevel(game));
}

function resolveDamageMult(game: GameRuntime): number {
    return getDynamaxDamageMult(getDynamaxUpgradeLevel(game));
}

function applyDynamaxHpBoost(game: GameRuntime, creature: CreatureData | null | undefined): void {
    if (!creature) return;
    const c = creature as DynamaxHpCreature;
    if (c._dynamaxHpBoosted) return;
    const mult = resolveHpMult(game);
    scaleCreatureHp(c, mult);
    c._dynamaxHpBoosted = true;
    c._dynamaxHpBoostMult = mult;
}

function removeDynamaxHpBoost(creature: CreatureData | null | undefined): void {
    if (!creature) return;
    const c = creature as DynamaxHpCreature;
    if (!c._dynamaxHpBoosted) return;
    const mult = Number(c._dynamaxHpBoostMult) || getDynamaxHpMult(0);
    scaleCreatureHp(c, 1 / mult);
    c._dynamaxHpBoosted = false;
    c._dynamaxHpBoostMult = undefined;
}

function clearAllDynamaxHpBoosts(game: GameRuntime): void {
    const team = game.playerTeam;
    if (!Array.isArray(team)) return;
    for (const member of team) {
        if (member) removeDynamaxHpBoost(member);
    }
    removeDynamaxHpBoost(game.currentPlayerCreature);
}

export function resetDynamaxCombatState(game: GameRuntime): void {
    clearAllDynamaxHpBoosts(game);
    game.dynamaxCombat = createDefaultDynamaxCombatState();
}

export function tryActivateDynamax(game: GameRuntime, now?: number): boolean {
    if (!isDynamaxZoneCombat(game)) return false;
    if (!isDynamaxBandUnlocked(game)) return false;
    if (!game.dynamaxCombat) resetDynamaxCombatState(game);
    const combat = game.dynamaxCombat!;
    if (combat.usedThisCombat || combat.active) return false;
    const creature = game.currentPlayerCreature;
    if (!creature) return false;

    const t = typeof now === 'number' ? now : Date.now();
    const durationMs = getDynamaxDurationMs(getDynamaxUpgradeLevel(game));
    applyDynamaxHpBoost(game, creature);
    combat.active = true;
    combat.usedThisCombat = true;
    combat.durationMs = durationMs;
    combat.remainingMs = durationMs;
    combat.timerLastTickAt = game.combatState === 'fighting' ? t : null;
    return true;
}

export function applyDynamaxOffensiveDamageMod(
    game: GameRuntime,
    attacker: ICreature,
    damage: number,
): number {
    if (!isDynamaxZoneCombat(game)) return damage;
    if (!game.dynamaxCombat?.active) return damage;
    if (attacker.isEnemy) return damage;
    return Math.max(1, Math.floor(damage * resolveDamageMult(game)));
}

/** HUD-only: mirror damage mult on ATK / SpA pills (does not affect combat math). */
export function applyDynamaxOffensiveHudBoost(
    game: GameRuntime | null | undefined,
    stat: CombatStatKey,
    display: HudCombatStatDisplay,
): HudCombatStatDisplay {
    if (!game?.dynamaxCombat?.active) return display;
    if (stat !== 'attack' && stat !== 'spattack') return display;
    const effective = Math.max(1, Math.floor(display.effective * resolveDamageMult(game)));
    return {
        ...display,
        effective,
        tint: 'buff',
        text: formatNumber(effective),
    };
}

export function notifyDynamaxCombatHud(game?: GameRuntime | null): void {
    if (game && typeof game.updateCombatDisplay === 'function') {
        game.updateCombatDisplay();
    }
}

export function isDynamaxActiveInCombat(game: GameRuntime): boolean {
    return game.dynamaxCombat?.active === true;
}

/** Account HP pool multiplier while Dynamax window is active. */
export function getDynamaxAccountHpMult(game: GameRuntime | null | undefined): number {
    if (!game?.dynamaxCombat?.active) return 1;
    return resolveHpMult(game);
}

export function getDynamaxRemainingMs(game: GameRuntime, now?: number): number {
    const combat = game.dynamaxCombat;
    if (!combat?.active) return 0;
    let rem = Math.max(0, Number(combat.remainingMs) || 0);
    const t = typeof now === 'number' ? now : Date.now();
    if (combat.timerLastTickAt != null) {
        rem = Math.max(0, rem - (t - combat.timerLastTickAt));
    }
    return rem;
}

/** Pause Dynamax budget (outside fighting), mirroring Mega. */
export function pauseDynamaxTimer(game: GameRuntime, now?: number): void {
    const combat = game.dynamaxCombat;
    if (!combat?.active || combat.timerLastTickAt == null) return;
    const t = typeof now === 'number' ? now : Date.now();
    combat.remainingMs = Math.max(0, (combat.remainingMs || 0) - (t - combat.timerLastTickAt));
    combat.timerLastTickAt = null;
}

export function resumeDynamaxTimer(game: GameRuntime, now?: number): void {
    const combat = game.dynamaxCombat;
    if (!combat?.active || (combat.remainingMs || 0) <= 0) return;
    const t = typeof now === 'number' ? now : Date.now();
    combat.timerLastTickAt = t;
}

/** Align pause/resume with combatState (fighting = ticking). */
export function syncDynamaxTimerWithCombatState(game: GameRuntime, now?: number): void {
    if (!game.dynamaxCombat?.active) return;
    if (game.combatState === 'fighting') {
        resumeDynamaxTimer(game, now);
    } else {
        pauseDynamaxTimer(game, now);
    }
}

/**
 * Move Dynamax HP scale from outgoing to incoming fighter (account window stays).
 */
export function transferDynamaxHpScale(
    game: GameRuntime,
    prev: CreatureData | null | undefined,
    next: CreatureData | null | undefined,
): void {
    if (!game.dynamaxCombat?.active) return;
    if (!next || prev === next) return;
    removeDynamaxHpBoost(prev);
    applyDynamaxHpBoost(game, next);
}

/** Ensure the active fighter carries the HP boost while Dynamax is active. */
export function ensureDynamaxHpScaleOnActive(game: GameRuntime): void {
    if (!game.dynamaxCombat?.active) return;
    const active = game.currentPlayerCreature;
    if (!active) return;
    const team = game.playerTeam;
    if (Array.isArray(team)) {
        for (const member of team) {
            if (member && member !== active) {
                removeDynamaxHpBoost(member);
            }
        }
    }
    applyDynamaxHpBoost(game, active);
}

export function shouldPreserveDynamaxAcrossCombat(game: GameRuntime, now?: number): boolean {
    return !!(game.dynamaxCombat?.active && getDynamaxRemainingMs(game, now) > 0);
}

/**
 * Called at the start of startCombat (before currentPlayerCreature is cleared).
 * Preserves the account Dynamax window across wild waves; otherwise full reset.
 */
export function prepareDynamaxForNewCombat(game: GameRuntime, now?: number): void {
    if (shouldPreserveDynamaxAcrossCombat(game, now)) {
        pauseDynamaxTimer(game, now);
        return;
    }
    if (game.dynamaxCombat?.active) {
        endDynamaxBattle(game);
    }
    resetDynamaxCombatState(game);
}

/**
 * End Dynamax: reverse HP scale, clear active flag (keeps usedThisCombat).
 * Call while currentPlayerCreature still points at the Dynamaxed fighter when possible.
 */
export function endDynamaxBattle(game: GameRuntime): void {
    const combat = game.dynamaxCombat;
    if (!combat) {
        resetDynamaxCombatState(game);
        return;
    }
    if (combat.active) {
        clearAllDynamaxHpBoosts(game);
    }
    const used = combat.usedThisCombat === true;
    game.dynamaxCombat = {
        ...createDefaultDynamaxCombatState(),
        usedThisCombat: used,
    };
}

/** Tick Dynamax timer while fighting; ends when budget hits 0. */
export function tickDynamaxIfExpired(game: GameRuntime, now?: number): boolean {
    const combat = game.dynamaxCombat;
    if (!combat?.active) return false;
    if (game.combatState !== 'fighting') {
        pauseDynamaxTimer(game, now);
        return false;
    }
    const t = typeof now === 'number' ? now : Date.now();
    if (combat.timerLastTickAt == null) {
        combat.timerLastTickAt = t;
        return false;
    }
    const elapsed = t - combat.timerLastTickAt;
    combat.remainingMs = Math.max(0, (combat.remainingMs || 0) - elapsed);
    combat.timerLastTickAt = t;
    if (combat.remainingMs > 0) return false;
    endDynamaxBattle(game);
    return true;
}
