function isKalosBerryRecipeTutorialActive(game: GameRuntime): boolean {
    if (!Array.isArray(game.quests)) return false;
    return game.quests.some((q) => {
        const quest = q as {
            id?: unknown;
            accepted?: boolean;
            completed?: boolean;
            claimed?: boolean;
        };
        return String(quest.id) === 'story_kalos_berry_recipe'
            && !!quest.accepted
            && !quest.completed
            && !quest.claimed;
    });
}

function isBerryTreeFeatureUnlocked(game: GameRuntime): boolean {
    return !!game.unlockedFeatures?.berryTree;
}

function berryText(
    game: GameRuntime,
    key: string,
    fallbackFr: string,
    fallbackEn: string,
    vars: Record<string, string | number> = {},
): string {
    const lang = game && typeof game.normalizeLanguage === 'function'
        ? game.normalizeLanguage(game.language)
        : 'fr';
    if (typeof game.t === 'function') {
        const out = game.t(key, vars);
        if (out && out !== key) return out;
    }
    const template = lang === 'en' ? fallbackEn : fallbackFr;
    return template.replace(/\{(\w+)\}/g, (_, k: string) => String(vars[k] ?? `{${k}}`));
}

function itemDisplayName(game: GameRuntime, itemKey: string): string {
    const item = ALL_ITEMS[itemKey as keyof typeof ALL_ITEMS] as { name?: string } | undefined;
    if (typeof game.localizeItemName === 'function') {
        return game.localizeItemName(itemKey, item?.name ?? itemKey);
    }
    return item?.name ?? itemKey;
}

function ensureMiltankFarmState(game: GameRuntime): MiltankFarmState {
    if (!game.miltankFarmState) {
        game.miltankFarmState = createDefaultMiltankFarmState(Date.now());
    }
    normalizeMiltankFarmState(game.miltankFarmState);
    return game.miltankFarmState;
}

function ensureBerryTreeState(game: GameRuntime): BerryTreeState {
    const state = ensureMiltankFarmState(game);
    if (!state.berryTree) {
        state.berryTree = createDefaultBerryTreeState();
    }
    state.berryTree = normalizeBerryTreeState(state.berryTree);
    return state.berryTree;
}

function tickBerryFarm(game: GameRuntime): void {
    const state = ensureMiltankFarmState(game);
    const now = Date.now();
    const milkSpeedMult = game.getMasteryBonus?.('miltank_milk_speed_mult') || 0;
    const berryProductionTimeReduction = game.getMasteryBonus?.('berry_production_time_reduction') || 0;
    const masteryOpts = (milkSpeedMult > 0 || berryProductionTimeReduction > 0)
        ? { milkSpeedMult, berryProductionTimeReduction }
        : undefined;
    tickMiltankFarmState(state, now, undefined, masteryOpts);
    processBerryTreePendingLogic(game, now);
    processBerryPlantQueueAutoCycleLogic(game, now);
}

function applyBerryCombineResultLogs(game: GameRuntime, result: TryBerryCombinationResult): void {
    for (const reveal of result.newlyRevealed) {
        const berryName = itemDisplayName(game, reveal.berryKey);
        const itemName = itemDisplayName(game, reveal.itemKey);
        logMessage(berryText(
            game,
            'berryTree.slotRevealed',
            'Indice BerryDex : {item} pour {berry} (slot {slot}).',
            'BerryDex hint: {item} for {berry} (slot {slot}).',
            { item: itemName, berry: berryName, slot: reveal.slotIndex + 1 },
        ));
    }

    for (const berryKey of result.newlyUnlocked) {
        const berryName = itemDisplayName(game, berryKey);
        logMessage(berryText(
            game,
            'berryTree.recipeUnlocked',
            'Recette débloquée : {berry} ! Tu peux la planter sur l\'arbre.',
            'Recipe unlocked: {berry}! You can plant it on the tree.',
            { berry: berryName },
        ));
    }

    if (result.newlyRevealed.length === 0 && result.newlyUnlocked.length === 0) {
        logMessage(berryText(
            game,
            'berryTree.tryFailed',
            'Aucun ingrédient reconnu à ces emplacements.',
            'No ingredients matched at those positions.',
        ));
    }
}

export function processBerryTreePendingLogic(game: GameRuntime, now = Date.now()): boolean {
    const berryTree = game.miltankFarmState?.berryTree;
    if (!berryTree) return false;
    normalizeBerryTreeState(berryTree);
    const resolveAt = isKalosBerryRecipeTutorialActive(game) ? now + 3_600_000 : now;
    const result = resolveBerryPendingCombineIfReady(berryTree, resolveAt);
    if (!result) return false;
    applyBerryCombineResultLogs(game, result);
    if (result.newlyUnlocked.length > 0 && typeof game.checkSpecialQuests === 'function') {
        game.checkSpecialQuests('berry_recipe_unlocked');
    }
    publishMiltankFarmChanged();
    game.saveGame?.({ immediate: true, reason: 'berry_tree_combine_complete' });
    return true;
}

export function processBerryPlantQueueAutoCycleLogic(game: GameRuntime, _now = Date.now()): boolean {
    const berryTree = game.miltankFarmState?.berryTree;
    if (!berryTree) return false;
    normalizeBerryTreeState(berryTree);
    if (berryTree.plantQueueLevel <= 0 || berryTree.plantQueue.length === 0) return false;

    const crop = berryTree.activeCrop;
    if (!crop || crop.storedQty <= 0 || !isBerryCropSessionComplete(crop)) return false;

    const harvest = claimBerryHarvest(berryTree);
    if (!harvest || harvest.qty <= 0) return false;

    grantBerryHarvestToGame(game, harvest);
    if (!berryTree.activeCrop) {
        tryAutoPlantFromQueue(game, berryTree);
    }
    publishMiltankFarmChanged();
    game.saveGame?.({ reason: 'berry_tree_queue_auto_cycle' });
    return true;
}

export async function openBerryTreeModalLogic(game: GameRuntime): Promise<void> {
    if (!isBerryTreeFeatureUnlocked(game)) {
        logMessage(berryText(
            game,
            'berryTree.lockedTutorial',
            'L\'arbre à baies se débloque après la Ligue de Kalos.',
            'The berry tree unlocks after beating the Kalos League.',
        ));
        return;
    }
    if (!game.miltankFarmState?.unlocked && !game.unlockedFeatures?.miltankFarm) {
        logMessage(berryText(game, 'berryTree.locked', 'Ferme verrouillée.', 'Farm locked.'));
        return;
    }
    tickBerryFarm(game);
    publishMiltankFarmChanged(MILTANK_FARM_FORCE_PUBLISH);
    await ensureLazyModalBeforeShowAsync('berryTreeModal');
    const modal = typeof document !== 'undefined'
        ? document.getElementById('berryTreeModal')
        : null;
    if (!modal) return;
    requestAnimationFrame(() => {
        modal.classList.add('show');
        publishModalOpened('berryTreeModal');
    });
}

export function closeBerryTreeModalLogic(): void {
    if (typeof document === 'undefined') return;
    const modal = document.getElementById('berryTreeModal');
    if (modal) modal.classList.remove('show');
    publishModalClosed('berryTreeModal');
}

export function openBagBerriesFromBerryTreeLogic(_game: GameRuntime): void {
    closeBerryTreeModalLogic();
    setInventoryFilter('berries');
    switchTab('sacados');
}

export function setBerryCombineSlotLogic(
    game: GameRuntime,
    arg: string,
): boolean {
    const parts = String(arg).split(':');
    const slotIndex = Math.floor(Number(parts[0]));
    const itemKey = parts[1] ? String(parts[1]) : '';
    if (!Number.isFinite(slotIndex)) return false;
    const berryTree = ensureBerryTreeState(game);
    setBerryCombineDraftSlot(berryTree, slotIndex, itemKey || null);
    publishMiltankFarmChanged();
    game.saveGame?.({ immediate: true, reason: 'berry_tree_draft' });
    return true;
}

export function clearBerryCombineDraftLogic(game: GameRuntime): void {
    const berryTree = ensureBerryTreeState(game);
    clearBerryCombineDraft(berryTree);
    publishMiltankFarmChanged();
    game.saveGame?.({ immediate: true, reason: 'berry_tree_draft' });
}

export function tryBerryTreeCombinationLogic(game: GameRuntime): boolean {
    tickBerryFarm(game);
    const farmState = ensureMiltankFarmState(game);
    const berryTree = ensureBerryTreeState(game);
    if (!game.items || typeof game.items !== 'object') game.items = {};

    const submitted = berryTree.combineDraft.map((s) => s ?? '');
    const result = beginBerryCombination(berryTree, submitted, game.items);
    if (!result.ok) {
        if (result.error === 'empty') {
            logMessage(berryText(game, 'berryTree.errorEmpty', 'Place au moins un objet.', 'Place at least one item.'));
        } else if (result.error === 'missing_items') {
            logMessage(berryText(game, 'berryTree.errorMissing', 'Objets insuffisants.', 'Not enough items.'));
        } else if (result.error === 'in_progress') {
            logMessage(berryText(game, 'berryTree.errorInProgress', 'Une combinaison est déjà en cours.', 'A combination is already in progress.'));
        } else if (result.error === 'queue_full') {
            logMessage(berryText(game, 'berryTree.errorQueueFull', 'File d\'analyses pleine.', 'Analysis queue is full.'));
        } else {
            logMessage(berryText(game, 'berryTree.errorInvalid', 'Objet non utilisable.', 'Item cannot be used.'));
        }
        publishMiltankFarmChanged();
        return false;
    }

    for (const itemKey of result.consumedItems) {
        game.items[itemKey] = Math.max(0, (Number(game.items[itemKey]) || 0) - 1);
    }

    logMessage(result.queued
        ? berryText(game, 'berryTree.combineQueued', 'Combinaison ajoutée à la file.', 'Combination added to queue.')
        : berryText(
            game,
            'berryTree.combineStarted',
            'Combinaison lancée — les résultats arrivent bientôt.',
            'Combination started — results coming soon.',
        ));

    notifyBagChanged(game);
    publishMiltankFarmChanged();
    game.saveGame?.({ immediate: true, reason: 'berry_tree_combine_start' });
    if (isKalosBerryRecipeTutorialActive(game)) {
        processBerryTreePendingLogic(game, Date.now() + 3_600_000);
    }
    return true;
}

function grantBerryHarvestToGame(
    game: GameRuntime,
    harvest: { berryKey: string; qty: number },
    options?: { triggerQuest?: boolean },
): number {
    if (!game.items || typeof game.items !== 'object') game.items = {};
    game.items[harvest.berryKey] = (Number(game.items[harvest.berryKey]) || 0) + harvest.qty;
    logMessage(berryText(
        game,
        'berryTree.claimed',
        '+{qty} {berry} récoltée(s).',
        '+{qty} {berry} harvested.',
        { qty: harvest.qty, berry: itemDisplayName(game, harvest.berryKey) },
    ));
    notifyBagChanged(game);
    if (options?.triggerQuest !== false && typeof game.checkSpecialQuests === 'function') {
        game.checkSpecialQuests('berry_tree_claim', { qty: harvest.qty });
    }
    return harvest.qty;
}

function plantBerryCropWithIngredients(
    game: GameRuntime,
    berryTree: BerryTreeState,
    key: string,
): boolean {
    if (!game.items || typeof game.items !== 'object') game.items = {};
    const afford = canAffordBerryPlant(berryTree, key, game.items);
    if (!afford.ok) {
        if (afford.error === 'missing_items') {
            logMessage(berryText(
                game,
                'berryTree.plantMissingItems',
                'Ingrédients de recette insuffisants pour planter cette baie.',
                'Not enough recipe ingredients to plant this berry.',
            ));
        } else {
            logMessage(berryText(
                game,
                'berryTree.plantFailed',
                'Recette non débloquée pour cette baie.',
                'Recipe not unlocked for this berry.',
            ));
        }
        return false;
    }
    if (!plantBerryCrop(berryTree, key)) {
        logMessage(berryText(
            game,
            'berryTree.plantFailed',
            'Recette non débloquée pour cette baie.',
            'Recipe not unlocked for this berry.',
        ));
        return false;
    }
    for (const itemKey of afford.ingredients) {
        game.items[itemKey] = Math.max(0, (Number(game.items[itemKey]) || 0) - 1);
    }
    notifyBagChanged(game);
    return true;
}

export function plantBerryTreeCropLogic(game: GameRuntime, berryKey: string): boolean {
    tickBerryFarm(game);
    const berryTree = ensureBerryTreeState(game);
    const key = String(berryKey);
    const activeKey = berryTree.activeCrop?.berryKey ?? null;
    if (activeKey === key) {
        logMessage(berryText(
            game,
            'berryTree.alreadyActive',
            'Cette baie est déjà en production.',
            'This berry is already in production.',
        ));
        publishMiltankFarmChanged();
        return false;
    }
    if (activeKey && activeKey !== key) {
        const priorHarvest = claimBerryHarvest(berryTree);
        if (priorHarvest && priorHarvest.qty > 0) {
            grantBerryHarvestToGame(game, priorHarvest);
        }
    }
    if (!plantBerryCropWithIngredients(game, berryTree, key)) {
        publishMiltankFarmChanged();
        return false;
    }
    removeFirstBerryFromPlantQueue(berryTree, key);
    logMessage(berryText(
        game,
        'berryTree.planted',
        '{berry} plantée sur l\'arbre.',
        '{berry} planted on the tree.',
        { berry: itemDisplayName(game, key) },
    ));
    publishMiltankFarmChanged();
    game.saveGame?.({ reason: 'berry_tree_plant' });
    return true;
}

export function applyBerryTreeFertilizerLogic(game: GameRuntime, mulchKey: string): boolean {
    tickBerryFarm(game);
    const berryTree = ensureBerryTreeState(game);
    const key = String(mulchKey);
    const owned = Math.max(0, Number(game.items?.[key]) || 0);
    if (owned < 1) {
        logMessage(berryText(game, 'berryTree.noMulch', 'Pas d\'engrais en sac.', 'No mulch in bag.'));
        return false;
    }
    if (!applyBerryFertilizer(berryTree, key, Date.now())) {
        logMessage(berryText(game, 'berryTree.mulchFailed', 'Engrais invalide.', 'Invalid mulch.'));
        return false;
    }
    game.items![key] = owned - 1;
    logMessage(berryText(
        game,
        'berryTree.mulchApplied',
        'Engrais appliqué sur l\'arbre !',
        'Mulch applied to the tree!',
    ));
    notifyBagChanged(game);
    publishMiltankFarmChanged();
    game.saveGame?.({ reason: 'berry_tree_mulch' });
    return true;
}

function tryAutoPlantFromQueue(
    game: GameRuntime,
    berryTree: BerryTreeState,
    options?: { logActiveCropBlocked?: boolean },
): boolean {
    const key = berryTree.plantQueue[0];
    if (berryTree.plantQueueLevel <= 0 || !key) {
        return false;
    }
    if (berryTree.activeCrop?.berryKey) {
        if (options?.logActiveCropBlocked) {
            logMessage(berryText(
                game,
                'berryTree.plantQueueActiveCrop',
                'Terminez la culture en cours avant de planter la file.',
                'Finish the current crop before planting from queue.',
            ));
        }
        return false;
    }
    if (!plantBerryCropWithIngredients(game, berryTree, key)) {
        return false;
    }
    shiftBerryPlantQueue(berryTree);
    logMessage(berryText(
        game,
        'berryTree.planted',
        '{berry} plantée sur l\'arbre.',
        '{berry} planted on the tree.',
        { berry: itemDisplayName(game, key) },
    ));
    return true;
}

export function claimBerryTreeHarvestLogic(game: GameRuntime): number {
    tickBerryFarm(game);
    const berryTree = ensureBerryTreeState(game);
    const harvest = claimBerryHarvest(berryTree);
    if (!harvest || harvest.qty <= 0) return 0;
    const qty = grantBerryHarvestToGame(game, harvest);
    if (!berryTree.activeCrop) {
        tryAutoPlantFromQueue(game, berryTree);
    }
    publishMiltankFarmChanged();
    game.saveGame?.({ reason: 'berry_tree_claim' });
    return qty;
}

export function cancelBerryTreeCropLogic(game: GameRuntime): boolean {
    tickBerryFarm(game);
    const berryTree = ensureBerryTreeState(game);
    if (!berryTree.activeCrop?.berryKey) {
        publishMiltankFarmChanged();
        return false;
    }
    const harvest = cancelBerryCrop(berryTree);
    if (harvest && harvest.qty > 0) {
        grantBerryHarvestToGame(game, harvest);
    }
    logMessage(berryText(
        game,
        'berryTree.canceled',
        'Production arrêtée.',
        'Production stopped.',
    ));
    tryAutoPlantFromQueue(game, berryTree);
    publishMiltankFarmChanged();
    game.saveGame?.({ reason: 'berry_tree_cancel' });
    return true;
}

export function purchaseBerryCombineQueueUpgradeLogic(game: GameRuntime): boolean {
    tickBerryFarm(game);
    const farmState = ensureMiltankFarmState(game);
    const berryTree = ensureBerryTreeState(game);
    const farmLevel = getMiltankFarmLevelSum(farmState);
    const ownedMilk = getAvailableMoomooMilk(Number(game.items?.moomoo_milk) || 0, farmState);
    if (!canPurchaseBerryCombineQueueUpgrade(berryTree, ownedMilk, farmLevel)) {
        logMessage(berryText(
            game,
            'berryTree.combineQueueUpgradeFailed',
            'Conditions non remplies pour débloquer la file.',
            'Requirements not met to unlock the queue.',
        ));
        publishMiltankFarmChanged();
        return false;
    }
    if (!game.items || typeof game.items !== 'object') game.items = {};
    if (!consumeMoomooMilk(game.items, farmState, getCombineQueueUpgradeCostForNextLevel(berryTree).moomoo_milk)) {
        publishMiltankFarmChanged();
        return false;
    }
    const berryTreeAfterPay = ensureBerryTreeState(game);
    if (!purchaseBerryCombineQueueUpgrade(berryTreeAfterPay)) {
        publishMiltankFarmChanged();
        return false;
    }
    logMessage(berryText(
        game,
        'berryTree.combineQueueUpgradeDone',
        'File d\'analyses niveau {level} !',
        'Analysis queue level {level}!',
        { level: berryTreeAfterPay.combineQueueLevel },
    ));
    notifyBagChanged(game);
    publishMiltankFarmChanged(MILTANK_FARM_FORCE_PUBLISH);
    game.saveGame?.({ reason: 'berry_tree_queue_upgrade' });
    return true;
}

export function setBerryPlantQueueLogic(game: GameRuntime, berryKey: string): boolean {
    tickBerryFarm(game);
    const berryTree = ensureBerryTreeState(game);
    const key = String(berryKey);
    if (!setBerryPlantQueue(berryTree, key)) {
        if (berryTree.plantQueueLevel <= 0) {
            logMessage(berryText(
                game,
                'berryTree.plantQueueLocked',
                'File de plantation non débloquée.',
                'Plant queue not unlocked.',
            ));
        } else {
            logMessage(berryText(
                game,
                'berryTree.plantQueueFailed',
                'Impossible de mettre cette baie en file.',
                'Cannot queue this berry.',
            ));
        }
        publishMiltankFarmChanged();
        return false;
    }
    logMessage(berryText(
        game,
        'berryTree.plantQueued',
        '{berry} en file — récolte et replantation auto tant qu\'une baie suit en attente.',
        '{berry} queued — auto-harvest and replant while another berry is waiting.',
        { berry: itemDisplayName(game, key) },
    ));
    processBerryPlantQueueAutoCycleLogic(game);
    if (!berryTree.activeCrop?.berryKey) {
        tryAutoPlantFromQueue(game, berryTree);
    }
    publishMiltankFarmChanged();
    game.saveGame?.({ reason: 'berry_tree_plant_queue_set' });
    return true;
}

export function plantBerryTreeFromQueueLogic(game: GameRuntime): boolean {
    tickBerryFarm(game);
    const berryTree = ensureBerryTreeState(game);
    if (berryTree.plantQueueLevel <= 0 || !berryTree.plantQueue[0]) {
        publishMiltankFarmChanged();
        return false;
    }
    const planted = tryAutoPlantFromQueue(game, berryTree, { logActiveCropBlocked: true });
    if (planted) {
        game.saveGame?.({ reason: 'berry_tree_plant_from_queue' });
    }
    publishMiltankFarmChanged();
    return planted;
}

export function purchaseBerryPlantQueueUpgradeLogic(game: GameRuntime): boolean {
    tickBerryFarm(game);
    const farmState = ensureMiltankFarmState(game);
    const berryTree = ensureBerryTreeState(game);
    const farmLevel = getMiltankFarmLevelSum(farmState);
    const ownedMilk = getAvailableMoomooMilk(Number(game.items?.moomoo_milk) || 0, farmState);
    if (!canPurchaseBerryPlantQueueUpgrade(berryTree, ownedMilk, farmLevel)) {
        logMessage(berryText(
            game,
            'berryTree.plantQueueUpgradeFailed',
            'Conditions non remplies pour débloquer la file de plantation.',
            'Requirements not met to unlock the plant queue.',
        ));
        publishMiltankFarmChanged();
        return false;
    }
    if (!game.items || typeof game.items !== 'object') game.items = {};
    if (!consumeMoomooMilk(game.items, farmState, getPlantQueueUpgradeCostForNextLevel(berryTree).moomoo_milk)) {
        publishMiltankFarmChanged();
        return false;
    }
    const berryTreeAfterPay = ensureBerryTreeState(game);
    if (!purchaseBerryPlantQueueUpgrade(berryTreeAfterPay)) {
        publishMiltankFarmChanged();
        return false;
    }
    logMessage(berryText(
        game,
        'berryTree.plantQueueUpgradeDone',
        'File de plantation niveau {level} !',
        'Plant queue level {level}!',
        { level: berryTreeAfterPay.plantQueueLevel },
    ));
    notifyBagChanged(game);
    publishMiltankFarmChanged(MILTANK_FARM_FORCE_PUBLISH);
    game.saveGame?.({ reason: 'berry_tree_plant_queue_upgrade' });
    return true;
}

const PLANT_BERRY_DEX_CONFIRM_MODAL_ID = 'confirmPlantBerryFromDexModal';

export function closeConfirmPlantBerryFromDexLogic(): void {
    if (typeof document === 'undefined') return;
    const modal = document.getElementById(PLANT_BERRY_DEX_CONFIRM_MODAL_ID);
    if (modal) modal.remove();
}

export function showConfirmPlantBerryFromDexLogic(game: GameRuntime, berryKey: string): void {
    if (typeof document === 'undefined') return;
    tickBerryFarm(game);
    const berryTree = ensureBerryTreeState(game);
    const key = String(berryKey);
    if (!berryTree.unlockedBerryKeys.includes(key)) return;

    closeConfirmPlantBerryFromDexLogic();

    const berryName = itemDisplayName(game, key);
    const isActive = berryTree.activeCrop?.berryKey === key;
    const hasOtherCrop = !!berryTree.activeCrop?.berryKey && !isActive;
    const hasStored = (berryTree.activeCrop?.storedQty ?? 0) > 0
        || (berryTree.activeCrop?.pendingFraction ?? 0) > 0;

    const overlay = document.createElement('div');
    overlay.id = PLANT_BERRY_DEX_CONFIRM_MODAL_ID;
    overlay.className = 'stats-modal show';
    overlay.addEventListener('click', (e) => {
        if (e.target === overlay) closeConfirmPlantBerryFromDexLogic();
    });

    const bodyParts = [
        berryText(game, 'berryTree.plantFromDexConfirmBody', 'Mettre {berry} en production sur l\'arbre.', 'Start producing {berry} on the tree.', { berry: berryName }),
    ];
    if (isActive) {
        bodyParts.push(berryText(game, 'berryTree.plantFromDexAlreadyActive', 'Cette baie est déjà en production.', 'This berry is already in production.'));
    } else if (hasOtherCrop && hasStored) {
        bodyParts.push(berryText(
            game,
            'berryTree.plantFromDexConfirmReplaceWarning',
            'La culture en cours et son stock seront perdus.',
            'The current crop and its stock will be lost.',
        ));
    }

    const box = document.createElement('div');
    box.className = 'stats-content confirm-pension-storage-content';
    box.innerHTML = `
        <div class="stats-header">
            <h2>${berryText(game, 'berryTree.plantFromDexConfirmTitle', 'Planter cette baie ?', 'Plant this berry?')}</h2>
            <button type="button" class="stats-close" data-action="closeConfirmPlantBerryFromDex">&#10005;</button>
        </div>
        <p class="confirm-pension-storage-text">${bodyParts.join(' ')}</p>
        <div class="confirm-pension-storage-actions">
            <button type="button" class="btn confirm-pension-storage-cancel" data-action="closeConfirmPlantBerryFromDex">
                ${berryText(game, 'berryTree.plantFromDexCancel', 'Annuler', 'Cancel')}
            </button>
            <button type="button" class="btn confirm-pension-storage-submit" data-action="executePlantBerryFromDex" data-arg="${key}" ${isActive ? 'disabled' : ''}>
                ${berryText(game, 'berryTree.plantFromDexConfirmAction', 'Planter', 'Plant')}
            </button>
        </div>
    `;
    overlay.appendChild(box);
    document.body.appendChild(overlay);
}

export function confirmPlantBerryFromDexLogic(game: GameRuntime, berryKey: string): boolean {
    closeConfirmPlantBerryFromDexLogic();
    const ok = plantBerryTreeCropLogic(game, berryKey);
    return ok;
}
