/**
 * @file zoneElitePower.ts
 * Stat scaling for zone Epic and Boss wild encounters.
 */

export interface ZoneElitePowerConfig {
    BOSS_ZONE_MULT?: number;
    EPIC_ZONE_MULT?: number;
    KANTO_BOSS_BOOST?: number;
    JOHTO_BOSS_BOOST?: number;
    HOENN_BOSS_BOOST?: number;
    SINNOH_BOSS_BOOST?: number;
    UNOVA_BOSS_BOOST?: number;
    KALOS_BOSS_BOOST?: number;
    ALOLA_BOSS_BOOST?: number;
    GALAR_BOSS_BOOST?: number;
    PALDEA_BOSS_BOOST?: number;
    KANTO_EPIC_BOOST?: number;
    JOHTO_EPIC_BOOST?: number;
    HOENN_EPIC_BOOST?: number;
    SINNOH_EPIC_BOOST?: number;
    UNOVA_EPIC_BOOST?: number;
    KALOS_EPIC_BOOST?: number;
    ALOLA_EPIC_BOOST?: number;
    GALAR_EPIC_BOOST?: number;
    PALDEA_EPIC_BOOST?: number;
}

type RegionId = 'kanto' | 'johto' | 'hoenn' | 'sinnoh' | 'unova' | 'kalos' | 'alola' | 'galar' | 'paldea';

const DEFAULT_BOSS_ZONE_MULT = 16;
const DEFAULT_EPIC_ZONE_MULT = 8;
const DEFAULT_REGION_BOOST = 1;

const REGION_BOSS_BOOST_KEYS: Record<RegionId, keyof ZoneElitePowerConfig> = {
    kanto: 'KANTO_BOSS_BOOST',
    johto: 'JOHTO_BOSS_BOOST',
    hoenn: 'HOENN_BOSS_BOOST',
    sinnoh: 'SINNOH_BOSS_BOOST',
    unova: 'UNOVA_BOSS_BOOST',
    kalos: 'KALOS_BOSS_BOOST',
    alola: 'ALOLA_BOSS_BOOST',
    galar: 'GALAR_BOSS_BOOST',
    paldea: 'PALDEA_BOSS_BOOST',
};

const REGION_EPIC_BOOST_KEYS: Record<RegionId, keyof ZoneElitePowerConfig> = {
    kanto: 'KANTO_EPIC_BOOST',
    johto: 'JOHTO_EPIC_BOOST',
    hoenn: 'HOENN_EPIC_BOOST',
    sinnoh: 'SINNOH_EPIC_BOOST',
    unova: 'UNOVA_EPIC_BOOST',
    kalos: 'KALOS_EPIC_BOOST',
    alola: 'ALOLA_EPIC_BOOST',
    galar: 'GALAR_EPIC_BOOST',
    paldea: 'PALDEA_EPIC_BOOST',
};

function readPositiveConfigValue(
    cfg: ZoneElitePowerConfig | null | undefined,
    key: keyof ZoneElitePowerConfig,
    fallback: number
): number {
    const raw = Number(cfg?.[key]);
    return Number.isFinite(raw) && raw > 0 ? raw : fallback;
}

export function getRegionBossBoost(
    regionId: string | undefined,
    cfg?: ZoneElitePowerConfig | null
): number {
    const key = regionId && regionId in REGION_BOSS_BOOST_KEYS
        ? REGION_BOSS_BOOST_KEYS[regionId as RegionId]
        : null;
    if (!key) return DEFAULT_REGION_BOOST;
    return readPositiveConfigValue(cfg, key, DEFAULT_REGION_BOOST);
}

export function getRegionEpicBoost(
    regionId: string | undefined,
    cfg?: ZoneElitePowerConfig | null
): number {
    const key = regionId && regionId in REGION_EPIC_BOOST_KEYS
        ? REGION_EPIC_BOOST_KEYS[regionId as RegionId]
        : null;
    if (!key) return DEFAULT_REGION_BOOST;
    return readPositiveConfigValue(cfg, key, DEFAULT_REGION_BOOST);
}

export function resolveZoneBossMultiplier(
    zoneBaseMult: number,
    regionId: string | undefined,
    cfg?: ZoneElitePowerConfig | null
): number {
    const base = Number.isFinite(zoneBaseMult) && zoneBaseMult > 0 ? zoneBaseMult : 1;
    const bossMult = readPositiveConfigValue(cfg, 'BOSS_ZONE_MULT', DEFAULT_BOSS_ZONE_MULT);
    const regionBoost = getRegionBossBoost(regionId, cfg);
    return base * bossMult * regionBoost;
}

export function resolveZoneEpicMultiplier(
    zoneBaseMult: number,
    regionId: string | undefined,
    cfg?: ZoneElitePowerConfig | null
): number {
    const base = Number.isFinite(zoneBaseMult) && zoneBaseMult > 0 ? zoneBaseMult : 1;
    const epicMult = readPositiveConfigValue(cfg, 'EPIC_ZONE_MULT', DEFAULT_EPIC_ZONE_MULT);
    const regionBoost = getRegionEpicBoost(regionId, cfg);
    return base * epicMult * regionBoost;
}
