import type { CreatureData } from '../types/creature.js';

export type OpenCreatureModalContext = {
  index: number;
  location: string;
  creatureUid?: string;
};

type CreatureLocationEntry = {
  location: string;
  index: number;
  creature: CreatureData;
};

/** Minimal game surface for refreshing the open creature modal. */
export type CreatureModalRefreshGame = {
  _openCreatureModal?: OpenCreatureModalContext;
  getCreatureByLocation?: (location: string, creatureIndex: number) => CreatureData | null;
  findCreatureByUid?: (uid: string) => CreatureLocationEntry | null;
  showCreatureModal?: (index: number, location: string) => void | Promise<void>;
};

/** Returns the creature currently shown in the open creature modal, or null. */
export function resolveOpenCreatureModalCreature(
  game: CreatureModalRefreshGame,
): CreatureData | null {
  const ctx = game._openCreatureModal;
  if (!ctx) return null;

  const modal = document.getElementById('creatureModal');
  if (!modal?.classList.contains('show')) return null;

  if (ctx.creatureUid && typeof game.findCreatureByUid === 'function') {
    const found = game.findCreatureByUid.call(game, ctx.creatureUid);
    return found?.creature ?? null;
  }

  const getCreature = game.getCreatureByLocation;
  if (typeof getCreature !== 'function') return null;
  return getCreature.call(game, ctx.location, ctx.index);
}

/** True when modal context still targets the creature being rendered. */
export function openCreatureModalContextMatches(
  ctx: OpenCreatureModalContext | undefined,
  index: number,
  location: string,
  creatureUid?: string,
): boolean {
  if (!ctx) return false;
  if (creatureUid && ctx.creatureUid) return ctx.creatureUid === creatureUid;
  return ctx.index === index && ctx.location === location;
}

/**
 * If the creature detail modal is open, recalculates the viewed creature and re-renders the modal.
 * Safe to call after talent changes, team composition / synergy updates, etc.
 */
export function refreshOpenCreatureModalIfVisible(game: CreatureModalRefreshGame): void {
  const ctx = game._openCreatureModal;
  if (!ctx) return;

  const modal = document.getElementById('creatureModal');
  if (!modal?.classList.contains('show')) return;

  let index = ctx.index;
  let location = ctx.location;
  let creature: CreatureData | null = null;

  if (ctx.creatureUid && typeof game.findCreatureByUid === 'function') {
    const found = game.findCreatureByUid.call(game, ctx.creatureUid);
    if (!found) return;
    index = found.index;
    location = found.location;
    creature = found.creature;
    game._openCreatureModal = { index, location, creatureUid: ctx.creatureUid };
  } else {
    const getCreature = game.getCreatureByLocation;
    if (typeof getCreature !== 'function') return;
    creature = getCreature.call(game, location, index);
    if (!creature) return;
  }

  if (creature && typeof creature.recalculateStats === 'function') {
    creature.recalculateStats();
  }

  if (typeof game.showCreatureModal === 'function') {
    void game.showCreatureModal(index, location);
  }
}
