import type { CreatureData } from './src/types/creature.js';
import type { GameRuntime } from './src/types/game.js';
import { POKE_PELAGO, POKE_PELAGO_ISLAND_IDS } from './constants/balance/pokePelago.ts';
import { ALL_ITEMS } from './constants/balance/shopAndAggregation.ts';
import { getShardKey } from './formatters.ts';
import {
    applyPelagoXp,
    assignPokePelagoIsland,
    clearGhostPelagoAssignees,
    collectPokePelagoIsland,
    countAssignedPelagoSlots,
    countClaimablePelagoIslands,
    createDefaultPokePelagoState,
    getPelagoLevelBonusPercent,
    islandHasClaimable,
    isCreatureAtMaxLevel,
    isIslandUnlocked,
    normalizePokePelagoState,
    tickPokePelagoState,
    type PokePelagoIslandId,
} from './src/lib/pokePelagoLogic.ts';
import { notifyPokePelagoChanged, maybePublishPokePelagoLiveRefresh } from './src/lib/pokePelagoSnapshot.ts';
import { getZRingState } from './src/lib/zRingLogic.ts';
import { logMessage } from './src/ui/modals.ts';
import { publishModalOpened, publishModalClosed } from './src/bus/publishHooks.js';
import { ensureLazyModalBeforeShowAsync } from './src/lib/lazyModalMounts.ts';

type GameCtor = { prototype: Record<string, unknown> };
type ThisGame = GameRuntime;

let lastClaimablePublished = -1;

function isPokePelagoModalDomOpen(): boolean {
    if (typeof document === 'undefined') return false;
    const modal = document.getElementById('pokePelagoModal');
    if (!modal?.classList || typeof modal.classList.contains !== 'function') return false;
    return modal.classList.contains('show');
}

function pelagoText(game: GameRuntime, fr: string, en: string): string {
    const lang = game.normalizeLanguage?.(game.language) ?? 'fr';
    return lang === 'en' ? en : fr;
}

function ensurePelagoState(game: GameRuntime) {
    if (!game.pokePelagoState) {
        game.pokePelagoState = createDefaultPokePelagoState(Date.now());
    }
    game.pokePelagoState = normalizePokePelagoState(game.pokePelagoState);
    return game.pokePelagoState;
}

function buildCreatureUidMap(game: GameRuntime): Map<string, CreatureData> {
    const map = new Map<string, CreatureData>();
    const add = (c: CreatureData | null | undefined) => {
        if (c?.uid) map.set(String(c.uid), c);
    };
    for (const c of game.storage ?? []) add(c);
    for (const c of game.pension ?? []) add(c);
    for (const c of game.playerTeam ?? []) add(c);
    add(game.ultimateSlot ?? undefined);
    return map;
}

function isUidBlockedForPelago(game: GameRuntime, uid: string): boolean {
    if (game.isUidInUltimateSlot?.(uid)) return true;
    if (game.isCreatureRocketLocked) {
        const all = [...(game.storage ?? []), ...(game.pension ?? []), ...(game.playerTeam ?? [])];
        const c = all.find((x) => String(x.uid) === uid);
        if (c && game.isCreatureRocketLocked(c)) return true;
    }
    return false;
}

function unlockedCrystalCount(game: GameRuntime): number {
    return getZRingState(game).unlockedCrystalIds.length;
}

function itemLabel(game: GameRuntime, itemKey: string): string {
    const def = (ALL_ITEMS as Record<string, Record<string, unknown>>)[itemKey];
    if (typeof game.getLocalizedItemName === 'function') {
        return game.getLocalizedItemName(itemKey, String(def?.name ?? itemKey), def);
    }
    return String(def?.name ?? itemKey);
}

function formatClaimSummary(
    game: GameRuntime,
    collected: {
        shards: number;
        xp: number;
        beans?: number;
        prestigeStones?: number;
        items: { itemKey: string; qty: number }[];
    },
): string | null {
    const parts: string[] = [];
    if (collected.shards > 0) {
        parts.push(pelagoText(game, `${collected.shards} éclats`, `${collected.shards} shards`));
    }
    if ((collected.beans ?? 0) > 0) {
        parts.push(pelagoText(game, `${collected.beans} XP Pelago`, `${collected.beans} Pelago XP`));
    }
    if ((collected.prestigeStones ?? 0) > 0) {
        parts.push(pelagoText(
            game,
            `${collected.prestigeStones} Pierre(s) de Prestige`,
            `${collected.prestigeStones} Prestige Stone(s)`,
        ));
    }
    if (collected.xp > 0) {
        parts.push(`${collected.xp} XP`);
    }
    for (const row of collected.items) {
        parts.push(`${itemLabel(game, row.itemKey)} ×${row.qty}`);
    }
    return parts.length ? parts.join(' · ') : null;
}

function applyCollectedRewards(
    game: GameRuntime,
    islandId: PokePelagoIslandId,
    collected: {
        shards: number;
        xp: number;
        beans: number;
        prestigeStones: number;
        items: { itemKey: string; qty: number }[];
    },
    creature: CreatureData | null | undefined,
): { hadReward: boolean; leveledUp: boolean; newLevel: number; restoredCreatureRewards: boolean } {
    const state = game.pokePelagoState!;
    let restoredCreatureRewards = false;

    // Creature-bound rewards must not be silently dropped.
    if ((collected.shards > 0 || collected.xp > 0) && !creature) {
        const slot = state.islands[islandId];
        slot.pendingShards += collected.shards;
        slot.pendingXp += collected.xp;
        collected.shards = 0;
        collected.xp = 0;
        restoredCreatureRewards = true;
    }

    if (collected.shards > 0 && creature) {
        const key = getShardKey(creature.name, creature.rarity);
        game.shards[key] = (game.shards[key] || 0) + collected.shards;
        if (typeof game.checkSpecialQuests === 'function') game.checkSpecialQuests('totalShards');
    }
    if (collected.xp > 0 && creature && typeof creature.gainExp === 'function') {
        creature.gainExp(collected.xp);
        if (islandId === 'evelup' && isCreatureAtMaxLevel(creature)) {
            state.islands.evelup.assignedUid = null;
            logMessage(pelagoText(
                game,
                'Poké Pelago — Evelup : Pokémon au niveau max, retiré de l’île.',
                'Poké Pelago — Evelup: Pokémon at max level, removed from the isle.',
            ));
        }
    }
    for (const row of collected.items) {
        game.items[row.itemKey] = (game.items[row.itemKey] || 0) + row.qty;
    }
    if (collected.prestigeStones > 0) {
        game.items.prestige_stone = (game.items.prestige_stone || 0) + collected.prestigeStones;
    }

    let leveledUp = false;
    let newLevel = state.level;
    if (collected.beans > 0) {
        // Beans convert 1:1 to Pelago XP on claim — no spendable bank.
        const lvl = applyPelagoXp(state, collected.beans);
        leveledUp = lvl.leveledUp;
        newLevel = lvl.newLevel;
    }

    const hadReward = collected.shards > 0
        || collected.xp > 0
        || collected.beans > 0
        || collected.prestigeStones > 0
        || collected.items.length > 0;
    if (hadReward) {
        if (typeof game.checkSpecialQuests === 'function') {
            game.checkSpecialQuests('pelago_claim', { islandId });
        }
    }
    return { hadReward, leveledUp, newLevel, restoredCreatureRewards };
}

function logGhostClaimBlocked(game: GameRuntime): void {
    if (typeof game.t === 'function') {
        const out = game.t('pokePelago.ghostClaimBlocked');
        if (out && out !== 'pokePelago.ghostClaimBlocked') {
            logMessage(out);
            return;
        }
    }
    logMessage(pelagoText(
        game,
        'Poké Pelago — Pokémon introuvable : éclats/XP conservés. Réassignez un Pokémon pour les réclamer.',
        'Poké Pelago — Pokémon missing: shards/XP kept. Reassign a Pokémon to claim them.',
    ));
}

export function unlockPokePelagoLogic(game: GameRuntime): void {
    const state = ensurePelagoState(game);
    if (state.unlocked) return;
    state.unlocked = true;
    state.islandsUnlocked.aphun = true;
    state.lastTickAt = Date.now();
    if (game.unlockedFeatures) game.unlockedFeatures.pokePelago = true;
    logMessage(pelagoText(
        game,
        'Les Îles Pelago sont prêtes ! Assignez depuis le stockage — la production continue même si le Pokémon rejoint l’équipe.',
        'Poké Pelago is ready! Assign from storage — production continues even if the Pokémon joins the team.',
    ));
    notifyPokePelagoChanged(game, { force: true });
}

export function tickPokePelagoLogic(game: GameRuntime, now = Date.now()): void {
    const state = game.pokePelagoState;
    if (!state?.unlocked) return;
    const last = Number(state.lastTickAt) || now;
    let delta = now - last;
    if (delta <= 0) {
        maybePublishPokePelagoLiveRefresh(game, now, isPokePelagoModalDomOpen());
        return;
    }
    delta = Math.min(delta, POKE_PELAGO.offlineCapMs);
    const crystals = unlockedCrystalCount(game);
    const creatures = buildCreatureUidMap(game);
    if (clearGhostPelagoAssignees(state, creatures)) {
        game.saveGame?.();
        notifyPokePelagoChanged(game, { force: true });
    }
    const tickResult = tickPokePelagoState(state, delta, creatures, crystals);
    state.lastTickAt = now;
    if (tickResult.leveledUp) {
        logPelagoLevelUp(game, tickResult.newLevel);
        game.saveGame?.();
    }
    // Avoid per-frame bus spam: republish when claimable badge would change.
    const claimable = countClaimablePelagoIslands(state, crystals);
    if (claimable !== lastClaimablePublished || tickResult.leveledUp) {
        lastClaimablePublished = claimable;
        notifyPokePelagoChanged(game, { force: true });
    } else {
        maybePublishPokePelagoLiveRefresh(game, now, isPokePelagoModalDomOpen());
    }
}

export function catchUpPokePelagoLogic(game: GameRuntime, missedTime: number): void {
    if (!game.pokePelagoState?.unlocked || missedTime <= 0) return;
    tickPokePelagoLogic(game, Date.now());
}

export function assignPokePelagoLogic(
    game: GameRuntime,
    islandId: PokePelagoIslandId,
    uid: string | null,
    source: 'storage',
    index: number,
): boolean {
    const state = ensurePelagoState(game);
    if (!state.unlocked) return false;
    if (uid && source !== 'storage') return false;
    let creature: CreatureData | undefined;
    if (uid) {
        const list = game.storage;
        creature = list?.[index];
        if (!creature || String(creature.uid) !== uid) return false;
        if (isUidBlockedForPelago(game, uid)) return false;
        if (islandId === 'evelup' && isCreatureAtMaxLevel(creature)) {
            logMessage(pelagoText(
                game,
                'Evelup n’accepte que les Pokémon sous le niveau max.',
                'Evelup only accepts Pokémon below max level.',
            ));
            return false;
        }
        for (const id of POKE_PELAGO_ISLAND_IDS) {
            if (id !== islandId && state.islands[id].assignedUid === uid) {
                state.islands[id].assignedUid = null;
            }
        }
    }
    const ok = assignPokePelagoIsland(state, islandId, uid, unlockedCrystalCount(game), creature);
    if (ok) {
        game.saveGame?.();
        notifyPokePelagoChanged(game, { force: true });
    }
    return ok;
}

function logPelagoLevelUp(game: GameRuntime, newLevel: number): void {
    const pct = getPelagoLevelBonusPercent(newLevel);
    const vars = { level: newLevel, pct };
    if (typeof game.t === 'function') {
        const out = game.t('pokePelago.levelUp', vars);
        if (out && out !== 'pokePelago.levelUp') {
            logMessage(out);
            return;
        }
    }
    logMessage(pelagoText(
        game,
        `Poké Pelago niveau ${newLevel} ! (+${pct}% production)`,
        `Poké Pelago level ${newLevel}! (+${pct}% production)`,
    ));
}

export function maybeAnnounceEvelupUnlock(game: GameRuntime): void {
    // Announcement is handled inside notifyPokePelagoChanged / tryAnnounceEvelupUnlock.
    notifyPokePelagoChanged(game, { force: true });
}

export function claimPokePelagoIslandLogic(game: GameRuntime, islandId: PokePelagoIslandId): boolean {
    const state = ensurePelagoState(game);
    if (!state.unlocked) return false;
    tickPokePelagoLogic(game);
    const slot = state.islands[islandId];
    const uid = slot.assignedUid;
    const creature = uid ? buildCreatureUidMap(game).get(uid) : null;
    const collected = collectPokePelagoIsland(state, islandId);
    const result = applyCollectedRewards(game, islandId, collected, creature);

    if (result.restoredCreatureRewards) {
        logGhostClaimBlocked(game);
    }

    if (result.hadReward) {
        const summary = formatClaimSummary(game, collected);
        if (summary) {
            logMessage(pelagoText(
                game,
                `Poké Pelago — récompense : ${summary}`,
                `Poké Pelago — reward: ${summary}`,
            ));
        }
        if (result.leveledUp) logPelagoLevelUp(game, result.newLevel);
        game.saveGame?.();
        lastClaimablePublished = countClaimablePelagoIslands(state, unlockedCrystalCount(game));
        notifyPokePelagoChanged(game, { force: true });
    } else if (result.restoredCreatureRewards) {
        game.saveGame?.();
        notifyPokePelagoChanged(game, { force: true });
    }
    return result.hadReward;
}

export function claimAllPokePelagoLogic(game: GameRuntime): boolean {
    const state = ensurePelagoState(game);
    if (!state.unlocked) return false;
    tickPokePelagoLogic(game);
    const crystals = unlockedCrystalCount(game);
    const creatures = buildCreatureUidMap(game);
    let any = false;
    let anyGhost = false;
    const totals = {
        shards: 0,
        xp: 0,
        beans: 0,
        prestigeStones: 0,
        items: [] as { itemKey: string; qty: number }[],
    };
    let lastLevelUp: number | null = null;

    for (const islandId of POKE_PELAGO_ISLAND_IDS) {
        if (!isIslandUnlocked(state, islandId, crystals)) continue;
        const slot = state.islands[islandId];
        if (!islandHasClaimable(slot)) continue;
        const uid = slot.assignedUid;
        const creature = uid ? creatures.get(uid) : null;
        const collected = collectPokePelagoIsland(state, islandId);
        const result = applyCollectedRewards(game, islandId, collected, creature);
        if (result.restoredCreatureRewards) anyGhost = true;
        if (result.hadReward) {
            any = true;
            totals.shards += collected.shards;
            totals.xp += collected.xp;
            totals.beans += collected.beans;
            totals.prestigeStones += collected.prestigeStones;
            for (const row of collected.items) {
                const existing = totals.items.find((i) => i.itemKey === row.itemKey);
                if (existing) existing.qty += row.qty;
                else totals.items.push({ ...row });
            }
            if (result.leveledUp) lastLevelUp = result.newLevel;
        }
    }

    if (anyGhost) logGhostClaimBlocked(game);

    if (any) {
        const summary = formatClaimSummary(game, totals);
        if (summary) {
            logMessage(pelagoText(
                game,
                `Poké Pelago — tout réclamé : ${summary}`,
                `Poké Pelago — claimed all: ${summary}`,
            ));
        }
        if (lastLevelUp != null) logPelagoLevelUp(game, lastLevelUp);
        game.saveGame?.();
        lastClaimablePublished = countClaimablePelagoIslands(state, crystals);
        notifyPokePelagoChanged(game, { force: true });
    } else if (anyGhost) {
        game.saveGame?.();
        notifyPokePelagoChanged(game, { force: true });
    }
    return any;
}

export async function openPokePelagoModalLogic(game: GameRuntime): Promise<void> {
    if (!game.pokePelagoState?.unlocked && !game.unlockedFeatures?.pokePelago) {
        logMessage(pelagoText(game, 'Îles Pelago verrouillées.', 'Poké Pelago locked.'));
        return;
    }
    tickPokePelagoLogic(game);
    notifyPokePelagoChanged(game, { force: true });
    await ensureLazyModalBeforeShowAsync('pokePelagoModal');
    const modal = typeof document !== 'undefined' ? document.getElementById('pokePelagoModal') : null;
    if (!modal) return;
    requestAnimationFrame(() => {
        modal.classList.add('show');
        publishModalOpened('pokePelagoModal');
    });
}

export function closePokePelagoModalLogic(): void {
    const modal = typeof document !== 'undefined' ? document.getElementById('pokePelagoModal') : null;
    if (modal) modal.classList.remove('show');
    publishModalClosed('pokePelagoModal');
}

export function applyPokePelagoSystem(GameClass: GameCtor): void {
    GameClass.prototype.openPokePelagoModal = function (this: ThisGame) {
        return openPokePelagoModalLogic(this);
    };
    GameClass.prototype.tickPokePelago = function (this: ThisGame) {
        tickPokePelagoLogic(this);
    };
    GameClass.prototype.assignPokePelago = function (
        this: ThisGame,
        islandId: PokePelagoIslandId,
        uid: string | null,
        source: 'storage',
        index: number,
    ) {
        return assignPokePelagoLogic(this, islandId, uid, source, index);
    };
    GameClass.prototype.claimPokePelagoIsland = function (this: ThisGame, islandId: PokePelagoIslandId) {
        return claimPokePelagoIslandLogic(this, islandId);
    };
    GameClass.prototype.claimAllPokePelago = function (this: ThisGame) {
        return claimAllPokePelagoLogic(this);
    };
}

export { countAssignedPelagoSlots, ensurePelagoState };
