import { BERRY_DEX_KEYS } from '../../constants/balance/berryTree.ts';
import { BALLS } from '../../constants/balance/dexAndCapture.ts';
import { DYNITE_ORE_ITEM_KEY, TM_ERASER_ITEM_KEY } from '../../gameEvolutionSystem.ts';

export const TALENT_REROLL_ITEM_KEY = 'talent_reroll';
export const TALENT_CHOICE_ITEM_KEY = 'talent_choice';

const BAG_NON_INTERACTIVE = new Set([
    ...Object.keys(BALLS),
    ...BERRY_DEX_KEYS,
    'prism_iv',
    DYNITE_ORE_ITEM_KEY,
    TM_ERASER_ITEM_KEY,
    TALENT_REROLL_ITEM_KEY,
    TALENT_CHOICE_ITEM_KEY,
]);

/** Items displayed in the bag but used elsewhere (capture, creature sheet). */
export function isBagNonInteractiveItem(itemKey: string): boolean {
    return BAG_NON_INTERACTIVE.has(itemKey);
}

export type BagItemHintKind = 'ball' | 'berry' | 'prism' | 'dyniteOre' | 'eraser' | 'talentPill' | 'talentPatch';

const BERRY_DEX_KEYS_SET = new Set<string>(BERRY_DEX_KEYS);

export function getBagItemHintKind(itemKey: string): BagItemHintKind | null {
    if (itemKey in BALLS) return 'ball';
    if (BERRY_DEX_KEYS_SET.has(itemKey)) return 'berry';
    if (itemKey === 'prism_iv') return 'prism';
    if (itemKey === DYNITE_ORE_ITEM_KEY) return 'dyniteOre';
    if (itemKey === TM_ERASER_ITEM_KEY) return 'eraser';
    if (itemKey === TALENT_REROLL_ITEM_KEY) return 'talentPill';
    if (itemKey === TALENT_CHOICE_ITEM_KEY) return 'talentPatch';
    return null;
}
