/**
 * Regional zone progression: mastery chain, maxReached sync, save repair.
 */
import type { GameRuntime } from '../types/game.js';
import { ZONES } from '../../constants/balance/zonesAndPacing.js';
import { ARENAS, ZONE_ID_TO_ARENA_ID } from '../../constants/balance/arenasTrainers.js';
import { maxReachedZone, maxReachedZoneByRegion, setMaxReachedZone } from '../../gameManager.ts';
import { getProgressionMasteryPokemonInZoneLogic } from '../../zoneMasterySpecies.ts';
import { arrayAt } from './safeAccess.ts';

type ZoneEntry = {
    regionId?: string;
    regionOrder?: number;
    isGym?: boolean;
    isFinal?: boolean;
    leagueId?: string;
    optionalHub?: boolean;
    unlockRequirement?: string;
};

/** Kalos post-league hubs (546–550): unlock from League only, not chained via legendary mastery. */
function usesMainlinePrevForKalosPostLeagueHub(zoneId: number): boolean {
    const z = zones[zoneId];
    if (!z || z.optionalHub !== true) return false;
    return String(z.regionId) === 'kalos' && String(z.unlockRequirement) === 'badge:maitre_kalos';
}

function getPreviousZoneIdForUnlockCheck(zoneId: number): number | null {
    if (zones[zoneId]?.optionalHub) {
        if (usesMainlinePrevForKalosPostLeagueHub(zoneId)) {
            return getPreviousMainlineZoneIdInRegion(zoneId);
        }
        return getPreviousZoneIdInRegion(zoneId);
    }
    return getPreviousMainlineZoneIdInRegion(zoneId);
}

const zones = ZONES as Record<number, ZoneEntry>;
const zoneToArena = ZONE_ID_TO_ARENA_ID as Record<string, string | number>;
const arenas = ARENAS as Record<string, { badge?: string; requiredBadge?: string; requiredZone?: number; regionId?: string }>;

function getZoneRegionId(zoneId: number): string {
    const z = zones[zoneId];
    return z?.regionId ? String(z.regionId) : 'kanto';
}

export function getSortedZoneIdsForRegion(regionId: string): number[] {
    const target = String(regionId || 'kanto');
    return Object.keys(zones)
        .map((id) => Number(id))
        .filter((id) => Number.isFinite(id) && getZoneRegionId(id) === target)
        .sort((a, b) => {
            const za = zones[a];
            const zb = zones[b];
            const oa = Number(za?.regionOrder);
            const ob = Number(zb?.regionOrder);
            if (Number.isFinite(oa) && Number.isFinite(ob) && oa !== ob) return oa - ob;
            return a - b;
        });
}

function getFirstZoneIdForRegion(regionId: string): number | null {
    return arrayAt(getSortedZoneIdsForRegion(regionId), 0) ?? null;
}

function getPreviousZoneIdInRegion(zoneId: number): number | null {
    const ids = getSortedZoneIdsForRegion(getZoneRegionId(zoneId));
    const idx = ids.indexOf(zoneId);
    if (idx <= 0) return null;
    return arrayAt(ids, idx - 1) ?? null;
}

/** Previous zone in regional order, skipping optional side hubs (mainline chain). */
function getPreviousMainlineZoneIdInRegion(zoneId: number): number | null {
    const ids = getSortedZoneIdsForRegion(getZoneRegionId(zoneId));
    const idx = ids.indexOf(zoneId);
    if (idx <= 0) return null;
    for (let i = idx - 1; i >= 0; i--) {
        const prevId = ids[i];
        if (prevId !== undefined && !zones[prevId]?.optionalHub) return prevId;
    }
    return null;
}

function getZoneStoryOrder(zoneId: number): number | null {
    const order = Number(zones[zoneId]?.regionOrder);
    return Number.isFinite(order) ? order : null;
}

/** Zone id further along regional story order (e.g. Johto Route 33 id 145 vs Azalea id 111). */
export function maxZoneIdByRegionalStoryOrder(zoneIdA: number, zoneIdB: number): number {
    const a = zones[zoneIdA];
    const b = zones[zoneIdB];
    if (!a && !b) return Math.max(zoneIdA, zoneIdB);
    if (!a) return zoneIdB;
    if (!b) return zoneIdA;
    if (getZoneRegionId(zoneIdA) !== getZoneRegionId(zoneIdB)) return zoneIdA;
    const oa = getZoneStoryOrder(zoneIdA);
    const ob = getZoneStoryOrder(zoneIdB);
    if (oa != null && ob != null && oa !== ob) return oa > ob ? zoneIdA : zoneIdB;
    return Math.max(zoneIdA, zoneIdB);
}

/** True when candidate is strictly ahead of reference in regional story order. */
export function isZoneStoryAheadOf(candidateZoneId: number, referenceZoneId: number): boolean {
    if (!Number.isFinite(candidateZoneId) || !Number.isFinite(referenceZoneId)) return false;
    if (candidateZoneId === referenceZoneId) return false;
    const cand = zones[candidateZoneId];
    const ref = zones[referenceZoneId];
    if (!cand || !ref) return candidateZoneId > referenceZoneId;
    if (getZoneRegionId(candidateZoneId) !== getZoneRegionId(referenceZoneId)) {
        return candidateZoneId > referenceZoneId;
    }
    const co = getZoneStoryOrder(candidateZoneId);
    const ro = getZoneStoryOrder(referenceZoneId);
    if (co != null && ro != null && co !== ro) return co > ro;
    return candidateZoneId > referenceZoneId;
}

function hasBadgeFlag(game: GameRuntime, badgeKey: string): boolean {
    if (!badgeKey) return false;
    if (typeof game.hasBadge === 'function') return game.hasBadge(badgeKey);
    return !!(game.badges && game.badges[badgeKey]);
}

function getGymZoneIdsForRegion(regionId: string): number[] {
    return getSortedZoneIdsForRegion(regionId).filter((id) => {
        const z = zones[id];
        return !!(z && z.isGym && !z.isFinal);
    });
}

/** Hub sans espèces sauvages (Floccesy, Viridian…) — pas les villes gym. */
function isTransitHubZoneForCap(game: GameRuntime, zoneId: number): boolean {
    const z = zones[zoneId];
    if (!z || z.isGym || z.isFinal) return false;
    return getProgressionMasteryPokemonInZoneLogic(game, zoneId).length === 0;
}

const HOENN_EVER_GRANDE = 261;
const HOENN_VICTORY_ROAD = 262;
const HOENN_LEAGUE = 263;

const SINNOH_VICTORY_ROAD = 344;
const SINNOH_LEAGUE = 345;
const HOENN_EASTERN_ARC_ORDER_MIN = 36;
const HOENN_EASTERN_ARC_ORDER_MAX = 51;
const HOENN_POSTGAME_ORDER_MIN = 52;

const JOHTO_BLACKTHORN = 136;
const JOHTO_DRAGONS_DEN = 137;
const JOHTO_VICTORY_ROAD = 143;
const JOHTO_LEAGUE = 144;
const JOHTO_MT_SILVER = 146;
const JOHTO_POSTGYM_ORDER_MIN = 38;

function isEndgameZoneValidated(game: GameRuntime, zoneId: number): boolean {
    if (typeof game.isZoneMastered === 'function' && game.isZoneMastered(zoneId)) return true;
    return !!(game.zoneProgress && game.zoneProgress[zoneId]);
}

function isHoennEndgameZoneValidated(game: GameRuntime, zoneId: number): boolean {
    return isEndgameZoneValidated(game, zoneId);
}

function isJohtoEndgameZoneValidated(game: GameRuntime, zoneId: number): boolean {
    return isEndgameZoneValidated(game, zoneId);
}

function applyJohtoEndgameCap(game: GameRuntime, capZoneId: number): number {
    if (!hasBadgeFlag(game, 'rising')) {
        return capZoneId;
    }
    if (!isJohtoEndgameZoneValidated(game, JOHTO_DRAGONS_DEN)) {
        return JOHTO_DRAGONS_DEN;
    }
    if (!isJohtoEndgameZoneValidated(game, JOHTO_VICTORY_ROAD)) {
        return JOHTO_VICTORY_ROAD;
    }
    return maxZoneIdByRegionalStoryOrder(capZoneId, JOHTO_LEAGUE);
}

function clampCapBelowHoennEverGrande(capZoneId: number): number {
    const everOrder = Number(zones[HOENN_EVER_GRANDE]?.regionOrder);
    const capOrder = Number(zones[capZoneId]?.regionOrder);
    if (!Number.isFinite(everOrder) || !Number.isFinite(capOrder) || capOrder < everOrder) {
        return capZoneId;
    }
    const prev = getPreviousZoneIdInRegion(HOENN_EVER_GRANDE);
    if (prev != null) return prev;
    const sorted = getSortedZoneIdsForRegion('hoenn');
    let best = capZoneId;
    for (let i = 0; i < sorted.length; i++) {
        const id = sorted[i];
        if (id === undefined) continue;
        const order = Number(zones[id]?.regionOrder);
        if (Number.isFinite(order) && order < everOrder) best = id;
    }
    return best;
}

function applyHoennEndgameCap(game: GameRuntime, capZoneId: number): number {
    if (!hasBadgeFlag(game, 'rain')) {
        return clampCapBelowHoennEverGrande(capZoneId);
    }
    if (!isHoennEndgameZoneValidated(game, HOENN_EVER_GRANDE)) {
        return HOENN_EVER_GRANDE;
    }
    if (!isHoennEndgameZoneValidated(game, HOENN_VICTORY_ROAD)) {
        return HOENN_VICTORY_ROAD;
    }
    return maxZoneIdByRegionalStoryOrder(capZoneId, HOENN_LEAGUE);
}

/** Hoenn eastern + weather arcs (Route 121 → Seafloor) require sequential mastery, not maxReached shortcut. */
export function bypassesHoennEasternArcMapShortcut(zoneId: number): boolean {
    const z = zones[zoneId];
    if (!z || getZoneRegionId(zoneId) !== 'hoenn') return false;
    const order = Number(z.regionOrder);
    return Number.isFinite(order)
        && order >= HOENN_EASTERN_ARC_ORDER_MIN
        && order <= HOENN_EASTERN_ARC_ORDER_MAX;
}

/** Hoenn endgame zones (261–263) use badge/mastery gates, not maxReached regionOrder shortcut. */
export function bypassesHoennEndgameMapShortcut(zoneId: number): boolean {
    const z = zones[zoneId];
    if (!z || getZoneRegionId(zoneId) !== 'hoenn') return false;
    if (zoneId === HOENN_EVER_GRANDE || zoneId === HOENN_VICTORY_ROAD || zoneId === HOENN_LEAGUE) {
        return true;
    }
    if (z.isFinal || z.leagueId) return true;
    const order = Number(z.regionOrder);
    return Number.isFinite(order) && order >= HOENN_POSTGAME_ORDER_MIN;
}

/** Johto endgame zones (137–144) use badge/mastery gates, not maxReached regionOrder shortcut. */
export function bypassesJohtoEndgameMapShortcut(zoneId: number): boolean {
    const z = zones[zoneId];
    if (!z || getZoneRegionId(zoneId) !== 'johto') return false;
    if (
        zoneId === JOHTO_DRAGONS_DEN
        || zoneId === JOHTO_VICTORY_ROAD
        || zoneId === JOHTO_LEAGUE
    ) {
        return true;
    }
    if (z.isFinal || z.leagueId) return true;
    const order = Number(z.regionOrder);
    return Number.isFinite(order) && order >= JOHTO_POSTGYM_ORDER_MIN;
}

/** null = not a Johto endgame gate zone; true/false = gate result for 143/144. */
export function meetsJohtoEndgameZoneGate(game: GameRuntime, zoneId: number): boolean | null {
    if (getZoneRegionId(zoneId) !== 'johto') return null;
    if (zoneId === JOHTO_VICTORY_ROAD) {
        return hasBadgeFlag(game, 'rising')
            && isJohtoEndgameZoneValidated(game, JOHTO_DRAGONS_DEN);
    }
    if (zoneId === JOHTO_LEAGUE) {
        return hasBadgeFlag(game, 'rising')
            && isJohtoEndgameZoneValidated(game, JOHTO_DRAGONS_DEN)
            && isJohtoEndgameZoneValidated(game, JOHTO_VICTORY_ROAD);
    }
    return null;
}

/** Sinnoh zones require sequential mastery, not maxReached shortcut. */
export function bypassesSinnohMapShortcut(zoneId: number): boolean {
    const z = zones[zoneId];
    if (!z || getZoneRegionId(zoneId) !== 'sinnoh') return false;
    return true;
}

const PALDEA_VICTORY_ROAD = 844;
const PALDEA_LEAGUE = 858;

/** Paldea zones require sequential mastery, not maxReached shortcut. */
export function bypassesPaldeaMapShortcut(zoneId: number): boolean {
    const z = zones[zoneId];
    if (!z || getZoneRegionId(zoneId) !== 'paldea') return false;
    return true;
}

/** null = not a Paldea endgame gate zone; true/false = gate result for 844/858. */
export function meetsPaldeaEndgameZoneGate(game: GameRuntime, zoneId: number): boolean | null {
    if (getZoneRegionId(zoneId) !== 'paldea') return null;
    if (zoneId === PALDEA_VICTORY_ROAD) return hasBadgeFlag(game, 'freeze');
    if (zoneId === PALDEA_LEAGUE) {
        return hasBadgeFlag(game, 'freeze') && isEndgameZoneValidated(game, PALDEA_VICTORY_ROAD);
    }
    return null;
}

/** null = not a Sinnoh endgame gate zone; true/false = gate result for 344/345. */
export function meetsSinnohEndgameZoneGate(game: GameRuntime, zoneId: number): boolean | null {
    if (getZoneRegionId(zoneId) !== 'sinnoh') return null;
    if (zoneId === SINNOH_VICTORY_ROAD) return hasBadgeFlag(game, 'beacon');
    if (zoneId === SINNOH_LEAGUE) {
        return hasBadgeFlag(game, 'beacon') && isSinnohEndgameZoneValidated(game, SINNOH_VICTORY_ROAD);
    }
    return null;
}

function isSinnohEndgameZoneValidated(game: GameRuntime, zoneId: number): boolean {
    return isEndgameZoneValidated(game, zoneId);
}

/** null = not an Hoenn endgame gate zone; true/false = gate result for 261/262/263. */
export function meetsHoennEndgameZoneGate(game: GameRuntime, zoneId: number): boolean | null {
    if (getZoneRegionId(zoneId) !== 'hoenn') return null;
    if (zoneId === HOENN_EVER_GRANDE) return hasBadgeFlag(game, 'rain');
    if (zoneId === HOENN_VICTORY_ROAD) {
        return hasBadgeFlag(game, 'rain') && isHoennEndgameZoneValidated(game, HOENN_EVER_GRANDE);
    }
    if (zoneId === HOENN_LEAGUE) {
        return hasBadgeFlag(game, 'rain')
            && isHoennEndgameZoneValidated(game, HOENN_EVER_GRANDE)
            && isHoennEndgameZoneValidated(game, HOENN_VICTORY_ROAD);
    }
    return null;
}

/** True when zoneId is past capZoneId in regional story order. */
export function isZoneBeyondLegitimateCap(zoneId: number, capZoneId: number): boolean {
    const z = zones[zoneId];
    const cap = zones[capZoneId];
    if (!z || !cap) return zoneId > capZoneId;
    const zoneOrder = Number(z.regionOrder);
    const capOrder = Number(cap.regionOrder);
    const sameRegion = getZoneRegionId(zoneId) === getZoneRegionId(capZoneId);
    if (sameRegion && Number.isFinite(zoneOrder) && Number.isFinite(capOrder)) {
        return zoneOrder > capOrder;
    }
    return zoneId > capZoneId;
}

/**
 * Upper bound for maxReachedZoneByRegion (mastery-only regions: no intermediate badge caps).
 */
export function getLegitimateMaxReachedForRegion(game: GameRuntime, regionId: string): number {
    const targetRegion = String(regionId || 'kanto');
    const firstZoneId = getFirstZoneIdForRegion(targetRegion);
    if (!firstZoneId) return 1;

    const masterKey = `maitre_${targetRegion}`;
    if (hasBadgeFlag(game, masterKey)) {
        const ids = getSortedZoneIdsForRegion(targetRegion);
        return arrayAt(ids, ids.length - 1) ?? firstZoneId;
    }

    if (targetRegion === 'kanto' || targetRegion === 'johto' || targetRegion === 'hoenn'
        || targetRegion === 'sinnoh' || targetRegion === 'unova' || targetRegion === 'paldea') {
        return Number.MAX_SAFE_INTEGER;
    }

    let capZoneId = firstZoneId;
    const gymZones = getGymZoneIdsForRegion(targetRegion);

    for (let i = 0; i < gymZones.length; i++) {
        const gymZoneId = gymZones[i];
        if (gymZoneId === undefined) continue;
        const arenaId = zoneToArena[String(gymZoneId)];
        const arena = arenaId != null ? arenas[String(arenaId)] : null;
        const badgeKey = arena?.badge ? String(arena.badge) : '';

        if (!badgeKey || !hasBadgeFlag(game, badgeKey)) {
            const requiredBadge = arena?.requiredBadge ? String(arena.requiredBadge) : '';
            if (requiredBadge && !hasBadgeFlag(game, requiredBadge)) {
                const prev = getPreviousZoneIdInRegion(gymZoneId);
                return Math.max(firstZoneId, prev ?? firstZoneId);
            }
            let cap = firstZoneId;
            const reqZone = Number(arena?.requiredZone);
            if (Number.isFinite(reqZone) && reqZone > 0) {
                cap = maxZoneIdByRegionalStoryOrder(cap, reqZone);
            } else {
                const prev = getPreviousZoneIdInRegion(gymZoneId);
                cap = maxZoneIdByRegionalStoryOrder(cap, prev ?? firstZoneId);
            }
            return Math.max(firstZoneId, cap);
        }

        capZoneId = maxZoneIdByRegionalStoryOrder(capZoneId, gymZoneId);
        const reqZone = Number(arena?.requiredZone);
        if (Number.isFinite(reqZone) && reqZone > 0) {
            capZoneId = maxZoneIdByRegionalStoryOrder(capZoneId, reqZone);
        }
    }

    return capZoneId;
}

/** True when active zone is not reachable via the mastery unlock chain. */
export function shouldClampActiveZoneToCap(game: GameRuntime, zoneId: number, _legitCap?: number): boolean {
    void _legitCap;
    if (!Number.isFinite(zoneId)) return false;
    if (typeof game.isZoneUnlocked !== 'function') return false;
    return !game.isZoneUnlocked(zoneId, true);
}

export type TryAdvanceRegionalMaxReachedResult = {
    advanced: boolean;
    nextZoneId: number | null;
    shouldAnnounce: boolean;
};

/**
 * After zone mastery, maybe raise maxReachedZoneByRegion and decide if a progression toast should fire.
 * Avoids spam when the next zone is already accessible via mastery but badge cap blocks maxReached.
 */
export function tryAdvanceRegionalMaxReachedOnMastery(
    game: GameRuntime,
    regionId: string,
    currentZoneId: number,
): TryAdvanceRegionalMaxReachedResult {
    const noOp: TryAdvanceRegionalMaxReachedResult = {
        advanced: false,
        nextZoneId: null,
        shouldAnnounce: false,
    };

    const zId = Number(currentZoneId);
    if (!Number.isFinite(zId)) return noOp;

    if (typeof game.isZoneMastered !== 'function' || !game.isZoneMastered(zId)) {
        return noOp;
    }

    if (typeof game.getNextProgressionZoneInRegion !== 'function') return noOp;
    const nextZone = game.getNextProgressionZoneInRegion(zId);
    if (nextZone == null || !zones[nextZone]) return noOp;

    if (typeof game.isZoneUnlocked !== 'function') return noOp;
    const isZoneUnlocked = (zone: number, checkPrevious = true) =>
        !!game.isZoneUnlocked!(zone, checkPrevious);

    const wasUnlocked = isZoneUnlocked(nextZone, true);
    const region = String(regionId || 'kanto');
    let advanced = false;

    if (shouldAdvanceMaxReachedOnZoneSelect(game, region, nextZone)) {
        if (maxReachedZoneByRegion && typeof maxReachedZoneByRegion === 'object') {
            const regionReached = Number(maxReachedZoneByRegion[region] || 0);
            if (!Number.isFinite(regionReached) || isZoneStoryAheadOf(nextZone, regionReached)) {
                maxReachedZoneByRegion[region] = nextZone;
                advanced = true;
            }
        } else if (!Number.isFinite(maxReachedZone) || isZoneStoryAheadOf(nextZone, maxReachedZone)) {
            setMaxReachedZone(nextZone);
            advanced = true;
        }
    }

    if (advanced && maxReachedZoneByRegion && typeof maxReachedZoneByRegion === 'object') {
        setMaxReachedZone(Number(maxReachedZoneByRegion[region] || nextZone));
    }

    return {
        advanced,
        nextZoneId: nextZone,
        shouldAnnounce: !wasUnlocked && isZoneUnlocked(nextZone, true),
    };
}

/**
 * Whether visiting targetZoneId may raise maxReachedZoneByRegion (organic progression only).
 */
export function shouldAdvanceMaxReachedOnZoneSelect(
    game: GameRuntime,
    regionId: string,
    targetZoneId: number,
): boolean {
    const region = String(regionId || 'kanto');
    const target = Number(targetZoneId);
    if (!Number.isFinite(target) || !zones[target]) return false;

    const legitCap = getLegitimateMaxReachedForRegion(game, region);
    if (isZoneBeyondLegitimateCap(target, legitCap)) return false;

    const sorted = getSortedZoneIdsForRegion(region);
    const targetIdx = sorted.indexOf(target);
    if (targetIdx < 0) return false;

    if (targetIdx === 0) return true;

    const prevZoneId = getPreviousZoneIdForUnlockCheck(target);
    if (prevZoneId == null) return true;

    if (typeof game.isZoneMastered === 'function' && game.isZoneMastered(prevZoneId)) {
        return true;
    }

    if (isTransitHubZoneForCap(game, prevZoneId)) {
        const hubPrevId = getPreviousZoneIdInRegion(prevZoneId);
        if (hubPrevId != null
            && typeof game.isZoneMastered === 'function'
            && !game.isZoneMastered(hubPrevId)) {
            return false;
        }
        return true;
    }

    return false;
}

/** Hoenn story gym quests that must match a specific badge, not global badge count. */
export const HOENN_ARENA_STORY_BADGE_REPAIR: ReadonlyArray<{ storyId: string; badge: string }> = [
    { storyId: 'story_arena_hoenn_1', badge: 'stone' },
    { storyId: 'story_arena_hoenn_2', badge: 'knuckle' },
    { storyId: 'story_arena_hoenn_3', badge: 'dynamo' },
    { storyId: 'story_arena_hoenn_4', badge: 'heat' },
    { storyId: 'story_arena_hoenn_5', badge: 'balance' },
    { storyId: 'story_arena_hoenn_6', badge: 'feather' },
    { storyId: 'story_arena_hoenn_7', badge: 'mind' },
    { storyId: 'story_arena_hoenn_8', badge: 'rain' },
];

export function repairHoennStoryQuestCompletions(game: GameRuntime): void {
    if (!Array.isArray(game.completedStoryQuests)) return;
    let changed = false;
    for (let i = 0; i < HOENN_ARENA_STORY_BADGE_REPAIR.length; i++) {
        const entry = HOENN_ARENA_STORY_BADGE_REPAIR[i];
        if (!entry) continue;
        const idx = game.completedStoryQuests.indexOf(entry.storyId);
        if (idx === -1) continue;
        if (hasBadgeFlag(game, entry.badge)) continue;
        game.completedStoryQuests.splice(idx, 1);
        changed = true;
    }
    void changed;
}

/** @deprecated Use repairSequentialZoneAccessLogic from zoneSystem.ts */
export function repairRegionalMaxReachedFromZoneProgress(_game: GameRuntime): void {
    void _game;
}

let clampingRegionalMax = false;

export function clampRegionalMaxReachedToLegitimateProgress(game: GameRuntime): void {
    if (!game || typeof game !== 'object') return;
    if (clampingRegionalMax) return;
    clampingRegionalMax = true;
    try {
    const store = (globalThis as { maxReachedZoneByRegion?: Record<string, number> }).maxReachedZoneByRegion;
    if (!store || typeof store !== 'object') return;

    const regionIds = new Set<string>();
    Object.keys(store).forEach((r) => regionIds.add(r));
    Object.keys(zones).forEach((idStr) => {
        const id = Number(idStr);
        if (Number.isFinite(id)) regionIds.add(getZoneRegionId(id));
    });

    } finally {
        clampingRegionalMax = false;
    }
}
