/**
 * @file arenaChampionPower.ts
 * Shared stat scaling for gym-zone trainers, gym leaders, and Elite Four.
 */

export interface ArenaPowerConfig {
    BASE_ADD?: number;
    STEP_ADD?: number;
    GYM_TRAINER_POWER_MULT?: number;
    KANTO_GYM_TRAINER_BOOST?: number;
    JOHTO_GYM_TRAINER_BOOST?: number;
    HOENN_GYM_TRAINER_BOOST?: number;
    SINNOH_GYM_TRAINER_BOOST?: number;
    UNOVA_GYM_TRAINER_BOOST?: number;
    KALOS_GYM_TRAINER_BOOST?: number;
    ALOLA_GYM_TRAINER_BOOST?: number;
    GALAR_GYM_TRAINER_BOOST?: number;
    PALDEA_GYM_TRAINER_BOOST?: number;
    KANTO_CHAMPION_BONUS?: number;
    JOHTO_CHAMPION_BONUS?: number;
    HOENN_CHAMPION_BONUS?: number;
    SINNOH_CHAMPION_BONUS?: number;
    UNOVA_CHAMPION_BONUS?: number;
    KALOS_CHAMPION_BONUS?: number;
    ALOLA_CHAMPION_BONUS?: number;
    GALAR_CHAMPION_BONUS?: number;
    PALDEA_CHAMPION_BONUS?: number;
}

export interface GymArenaEntry {
    badge?: string;
    regionId?: string;
    teamLevel?: number;
}

export interface EliteFourDefLike {
    requiredBadge?: string;
    regionId?: string;
    id?: string;
}

export interface LastGymArenaResult {
    arenaId: number;
    arena: GymArenaEntry;
}

type RegionId = 'kanto' | 'johto' | 'hoenn' | 'sinnoh' | 'unova' | 'kalos' | 'alola' | 'galar' | 'paldea';

const REGION_GYM_BOOST_KEYS: Record<RegionId, keyof ArenaPowerConfig> = {
    kanto: 'KANTO_GYM_TRAINER_BOOST',
    johto: 'JOHTO_GYM_TRAINER_BOOST',
    hoenn: 'HOENN_GYM_TRAINER_BOOST',
    sinnoh: 'SINNOH_GYM_TRAINER_BOOST',
    unova: 'UNOVA_GYM_TRAINER_BOOST',
    kalos: 'KALOS_GYM_TRAINER_BOOST',
    alola: 'ALOLA_GYM_TRAINER_BOOST',
    galar: 'GALAR_GYM_TRAINER_BOOST',
    paldea: 'PALDEA_GYM_TRAINER_BOOST',
};

const REGION_CHAMPION_BONUS_KEYS: Record<RegionId, keyof ArenaPowerConfig> = {
    kanto: 'KANTO_CHAMPION_BONUS',
    johto: 'JOHTO_CHAMPION_BONUS',
    hoenn: 'HOENN_CHAMPION_BONUS',
    sinnoh: 'SINNOH_CHAMPION_BONUS',
    unova: 'UNOVA_CHAMPION_BONUS',
    kalos: 'KALOS_CHAMPION_BONUS',
    alola: 'ALOLA_CHAMPION_BONUS',
    galar: 'GALAR_CHAMPION_BONUS',
    paldea: 'PALDEA_CHAMPION_BONUS',
};

const DEFAULT_REGION_GYM_BOOST = 1;
const DEFAULT_REGION_CHAMPION_BONUS = 1;

function readPositiveConfigValue(
    cfg: ArenaPowerConfig | null | undefined,
    key: keyof ArenaPowerConfig,
    fallback: number
): number {
    const raw = Number(cfg?.[key]);
    return Number.isFinite(raw) && raw > 0 ? raw : fallback;
}

export function getRegionGymBoost(
    regionId: string | undefined,
    arenaPowerCfg?: ArenaPowerConfig | null
): number {
    const key = regionId && regionId in REGION_GYM_BOOST_KEYS
        ? REGION_GYM_BOOST_KEYS[regionId as RegionId]
        : null;
    if (!key) return DEFAULT_REGION_GYM_BOOST;
    return readPositiveConfigValue(arenaPowerCfg, key, DEFAULT_REGION_GYM_BOOST);
}

export function getRegionChampionBonus(
    regionId: string | undefined,
    arenaPowerCfg?: ArenaPowerConfig | null
): number {
    const key = regionId && regionId in REGION_CHAMPION_BONUS_KEYS
        ? REGION_CHAMPION_BONUS_KEYS[regionId as RegionId]
        : null;
    if (!key) return DEFAULT_REGION_CHAMPION_BONUS;
    return readPositiveConfigValue(arenaPowerCfg, key, DEFAULT_REGION_CHAMPION_BONUS);
}

/** Base stat mult shared by gym-zone trainers, factions, champions, and Elite Four. */
export function resolveGymTrainerBaseMult(
    numericArenaId: number,
    arena: GymArenaEntry | null | undefined,
    arenaPowerCfg?: ArenaPowerConfig | null
): number {
    const baseAddRaw = Number(arenaPowerCfg?.BASE_ADD);
    const stepAddRaw = Number(arenaPowerCfg?.STEP_ADD);
    const trainerPowerMultRaw = Number(arenaPowerCfg?.GYM_TRAINER_POWER_MULT);
    const baseAdd = Number.isFinite(baseAddRaw) ? baseAddRaw : 2;
    const stepAdd = Number.isFinite(stepAddRaw) ? stepAddRaw : 1;
    const trainerPowerMult = Number.isFinite(trainerPowerMultRaw) ? trainerPowerMultRaw : 0.62;
    const sharedArenaMult = baseAdd + (numericArenaId * stepAdd);
    const regionBoost = getRegionGymBoost(arena?.regionId, arenaPowerCfg);
    return sharedArenaMult * trainerPowerMult * regionBoost;
}

export function resolveChampionStatMult(
    numericArenaId: number,
    arena: GymArenaEntry | null | undefined,
    arenaPowerCfg?: ArenaPowerConfig | null
): number {
    const baseMult = resolveGymTrainerBaseMult(numericArenaId, arena, arenaPowerCfg);
    const championBonus = getRegionChampionBonus(arena?.regionId, arenaPowerCfg);
    return baseMult * championBonus;
}

export function findLastGymArenaForEliteFour(
    eliteDef: EliteFourDefLike,
    arenas: Record<string, GymArenaEntry>
): LastGymArenaResult | null {
    const requiredBadge = eliteDef.requiredBadge;
    if (!requiredBadge) return null;

    const regionId = eliteDef.regionId;
    let best: LastGymArenaResult | null = null;

    for (const [idStr, arena] of Object.entries(arenas)) {
        if (!arena || arena.badge !== requiredBadge) continue;
        if (regionId && arena.regionId && arena.regionId !== regionId) continue;

        const arenaId = parseInt(idStr, 10);
        if (!Number.isFinite(arenaId)) continue;

        if (!best || arenaId > best.arenaId) {
            best = { arenaId, arena };
        }
    }

    return best;
}

export function resolveEliteFourChampionPower(
    eliteDef: EliteFourDefLike,
    arenas: Record<string, GymArenaEntry>,
    arenaPowerCfg?: ArenaPowerConfig | null
): { teamLevel: number; championStatMult: number; lastArenaId: number } {
    const lastGym = findLastGymArenaForEliteFour(eliteDef, arenas);
    if (lastGym) {
        const teamLevel = Number(lastGym.arena.teamLevel);
        return {
            teamLevel: Number.isFinite(teamLevel) && teamLevel > 0 ? teamLevel : 50,
            championStatMult: resolveChampionStatMult(lastGym.arenaId, lastGym.arena, arenaPowerCfg),
            lastArenaId: lastGym.arenaId,
        };
    }

    const genMatch = typeof eliteDef.id === 'string' ? eliteDef.id.match(/elite_four_gen(\d+)/) : null;
    const fallbackArenaId = genMatch ? parseInt(genMatch[1] ?? '', 10) * 8 : 8;
    const fallbackArena = arenas[String(fallbackArenaId)];
    const teamLevel = Number(fallbackArena?.teamLevel);
    return {
        teamLevel: Number.isFinite(teamLevel) && teamLevel > 0 ? teamLevel : 50,
        championStatMult: resolveChampionStatMult(fallbackArenaId, fallbackArena, arenaPowerCfg),
        lastArenaId: fallbackArenaId,
    };
}
