function tokenShopHasScalingCost(
    item: TokenShopEntry,
): item is TokenShopEntry & { cost: number[]; effect: TokenShopEffect; maxLevel: number } {
    return Array.isArray(item.cost) && item.effect != null && typeof item.maxLevel === 'number';
}

function resolveTokenShopIconHTML(item: TokenShopEntry): string {
    const linkedItemId = item.item || item.itemId;
    if (linkedItemId) {
        const linked = getAllItem(String(linkedItemId));
        if (linked) {
            const linkedIcon = getItemIconHTML(linked);
            if (linkedIcon && linkedIcon !== 'OBJ') return linkedIcon;
        }
    }
    const iconHTML = getItemIconHTML(item);
    return iconHTML && iconHTML !== 'OBJ' ? iconHTML : '';
}

function resolveMartOffers(game: GameRuntime, now: number): MartOfferRow[] {
    if (typeof game.getPokeMartOfferItems === 'function') {
        return game.getPokeMartOfferItems(now) as MartOfferRow[];
    }
    return Object.entries(pokeMartEntries).map(([key, item]) => ({ key, item }));
}

function buildMartBagOwnedLabel(game: GameRuntime, itemId: string): string | null {
    if (!itemId || itemId === '__ct_random__') return null;
    const owned = Math.max(0, Math.floor(Number(game.items?.[itemId]) || 0));
    return uiT(game, 'shop.ownedCount', 'Owned: {count}', { count: formatNumber(owned) });
}

function uiT(
    game: GameRuntime,
    key: string,
    fallback: string | null = null,
    vars: Record<string, unknown> = {},
): string {
    return uiText(key, fallback, vars, game);
}

