export function setInventoryFilter(filter: string): void {
    currentInventoryFilter = filter || 'all';
    if (game) {
        updateItemsDisplayUI(game);
    }
}

export function buildBagItemsSnapshot(game: GameRuntime): BagInventorySnapshot {
    const allItemKeys = Object.keys(game.items).filter(key => {
        if (!((game.items[key] ?? 0) > 0)) return false;
        if (typeof key === 'string' && key.startsWith('ct_') && typeof game.isDamagingCtItemKey === 'function' && !game.isDamagingCtItemKey(key)) {
            return false;
        }
        return true;
    });

    const filteredKeys = allItemKeys.filter(key => {
        if (currentInventoryFilter === 'all') return true;
        const item = getAllItem(key) || {};
        const flags = getBagItemFilterFlags(key, item);

        switch (currentInventoryFilter) {
            case 'key': return flags.isKeyItem;
            case 'held': return flags.isHeldItem;
            case 'permanent': return flags.isPermanent;
            case 'combat': return flags.isCombat && !flags.isKeyItem && !flags.isHeldItem;
            case 'evolution_stones': return flags.isEvolutionStone;
            case 'berries': return flags.isBerry;
            case 'ct': return flags.isCT;
            case 'misc': return flags.isMisc;
            default: return true;
        }
    });

    filteredKeys.sort((a, b) => {
        const itemA = getAllItem(a) || { rarity: 'common' };
        const itemB = getAllItem(b) || { rarity: 'common' };
        const getWeight = (key: string, item: { type?: string; effect?: unknown }) => {
            if (item.type === 'key_item') return 0;
            if (key.includes('ball') || (item.type && item.type === 'ball')) return 1;
            if (hasHeldItem(key)) return 2;
            if (item.effect) return 3;
            return 4;
        };
        return getWeight(a, itemA) - getWeight(b, itemB);
    });

    const itemCards = filteredKeys.map((key) => buildBagItemCardSnapshot(game, key));
    const inventoryEmpty = filteredKeys.length === 0;
    const inventoryEmptyMessage = inventoryEmpty
        ? (currentInventoryFilter === 'berries'
            ? uiT(game, 'bag.inventoryEmptyBerries', 'Aucune baie dans le sac. Récoltez-les à l\'arbre ou débloquez des recettes BerryDex.')
            : uiT(game, 'bag.inventoryEmpty', 'Votre sac est vide.'))
        : '';

    return {
        itemCards,
        inventoryFilter: currentInventoryFilter,
        itemTypesCountLabel: uiT(game,'bag.itemTypesCount', '{count} ITEM TYPES', { count: filteredKeys.length }),
        inventoryEmpty,
        inventoryEmptyMessage,
    };
}

export function buildBagItemCardSnapshot(
    game: GameRuntime,
    key: string,
): BagItemCardSnapshot {
    const fallback: UiItemLike & { type?: string } = {
        name: key,
        description: uiT(game, 'modal.unknownItem', 'Unknown item'),
        icon: '?',
        rarity: 'common',
    };
    const item = getAllItem(key) ?? fallback;
    const count = game.items[key] ?? 0;
    const displayItemName = uiMaybeLocalizeItemName(game, item, key, item.name ?? key);
    const displayItemDesc = uiMaybeLocalizeItemDescription(game, item, key, item.description || "");

    let typeBadgeHtml = '';
    let action: BagItemCardSnapshot['action'] = 'useItem';
    let extraClass = '';

    if (item.type === 'key_item') {
        typeBadgeHtml = `<span class="item-type-badge" style="background:transparent; color:#fbbf24; text-shadow:0 0 4px rgba(251, 191, 36, 0.7);">${uiT(game,'bag.keyShort', 'KEY')}</span>`;
        action = 'toastKeyItem';
    } else if (hasHeldItem(key)) {
        extraClass = ' is-held-item';
        typeBadgeHtml = `<span class="item-type-badge">${uiT(game,'bag.heldShort', 'HOLD')}</span>`;
        action = 'toastHeldItem';
    } else if (isBagNonInteractiveItem(key)) {
        action = 'toastBagItemHint';
    } else if (isEvolutionInventoryItem(key)) {
        action = 'toastEvolutionItem';
    }

    let iconHtml = `<div style="font-size:28px;">${item.icon || 'OBJ'}</div>`;
    if (item.img) {
        const eraserClass = key === 'tm_eraser' ? ' item-sprite-tm-eraser' : '';
        iconHtml = `<img src="${item.img}" class="item-sprite-img${getTimeDustGlowClass(item)}${eraserClass}" alt="${displayItemName}" style="width:40px; height:40px; object-fit:contain;">`;
    }

    const canUseCtrlAll = isBagCtrlAllItem(key, item);

    return {
        itemKey: key,
        cardHtml: buildBagItemCardHtmlFromParts(game, key, item, count, displayItemName, displayItemDesc, typeBadgeHtml, action, extraClass, iconHtml, canUseCtrlAll),
        displayName: displayItemName,
        description: displayItemDesc,
        count,
        rarity: item.rarity || 'common',
        typeBadgeHtml,
        iconHtml,
        extraClass,
        action,
        ctrlAllHint: canUseCtrlAll ? uiT(game,'bag.ctrlAllHint', 'Ctrl: All') : '',
    };
}

function buildBagItemCardHtmlFromParts(
    game: GameRuntime,
    key: string,
    item: ReturnType<typeof getAllItem> & { rarity?: string; icon?: string; img?: string; effect?: { duration?: number | null; type?: string; stat?: string } },
    count: number,
    displayItemName: string,
    displayItemDesc: string,
    typeIcon: string,
    action: string,
    extraClass: string,
    iconHTML: string,
    canUseCtrlAll: boolean,
): string {
    const clickDataAttrs = action === 'useItem'
        ? `data-action="useItem" data-arg="${key}" data-arg2="1"`
        : action === 'toastBagItemHint'
            ? `data-action="toastBagItemHint" data-arg="${key}"`
            : `data-action="${action}"`;
    const safeName = (displayItemName || '').replace(/'/g, "\\'");
    const safeDesc = (displayItemDesc || "").replace(/'/g, "\\'");
    return `
        <div class="inventory-slot rarity-${item.rarity || 'common'}${extraClass}">
            <div class="inventory-slot-content"
                 onmouseenter="game.scheduleTooltip(event, '${safeName}', '${safeDesc}')"
                 onmouseleave="game.hideTooltip()"
                 ${clickDataAttrs}
                 style="width:100%; display:flex; flex-direction:column; align-items:center; justify-content:flex-start; gap:4px;">
                ${typeIcon}
                <div class="item-icon">${iconHTML}</div>
                <div class="item-count">x${count}</div>
                <div class="item-name">${displayItemName}</div>
                <div style="font-size: 9px; color: #94a3b8; margin-top: 2px; opacity: 1; min-height:11px;">${canUseCtrlAll ? uiT(game,'bag.ctrlAllHint', 'Ctrl: All') : ''}</div>
            </div>
        </div>`;
}

function buildBagItemCardHtml(game: GameRuntime, key: string): string {
    return buildBagItemCardSnapshot(game, key).cardHtml;
}


