/**
 * Décompte avant le renouvellement des offres PokéMart (épicerie).
 * Ne reconstruit pas la grille — pour tick 1s sans flicker.
 */
export function buildMartTimerSnapshot(game: GameRuntime): { text: string; label: string } {
    const now = Date.now();
    const timeLeftMs = (typeof game.getPokeMartOfferTimeLeftMs === 'function')
        ? Math.max(0, game.getPokeMartOfferTimeLeftMs(now))
        : 0;
    const timerText = formatTimeString(timeLeftMs);
    return {
        text: timerText,
        label: uiT(game,'shop.martRotationCooldownLabel', 'Offer rotation in:'),
    };
}

