/**
 * Structured PokéMart offers for Svelte ShopMartContent.
 */
export function buildMartOffersSnapshot(game: GameRuntime): {
    offers: MartOfferSnapshot[];
    martEmptyMessage: string | null;
} {
    if (!POKEMART_ITEMS) {
        return { offers: [], martEmptyMessage: null };
    }
    const now = Date.now();
    const offerList = resolveMartOffers(game, now);

    if (!offerList.length) {
        return {
            offers: [],
            martEmptyMessage: uiT(game,'shop.martVendorPreparing', 'The merchant is preparing crates, come back in a moment.'),
        };
    }

    const autoPurchaseKeys = new Set(
        Array.isArray(game.martState?.autoPurchaseKeys) ? game.martState.autoPurchaseKeys : [],
    );
    const autoBadgeLabel = uiT(game, 'shop.martAutoPurchaseBadge', 'Auto');

    const offers = offerList.map(({ key, item: shopEntry }) => {
        const linkedItemId = String(shopEntry.itemId || shopEntry.item || '');
        const realItem = getAllItem(linkedItemId) ?? null;
        const iconHTML = getItemIconHTML(realItem || shopEntry);
        let displayName = uiDataText(game, 'pokeMart', key, 'name', shopEntry.name);
        let displayDescription = uiDataText(game, 'pokeMart', key, 'description', shopEntry.description);
        const isBarter = Array.isArray(shopEntry.costItems) && shopEntry.costItems.length > 0;
        const isDust = !isBarter && Number(shopEntry.dustCost) > 0;
        if (isBarter && shopEntry.costItems?.[0]) {
            const c = shopEntry.costItems[0];
            const costDef = getAllItem(c.itemId) ?? null;
            const costNm = (typeof game.getLocalizedItemName === 'function')
                ? game.getLocalizedItemName(c.itemId, costDef?.name ? costDef.name : c.itemId, costDef)
                : c.itemId;
            displayName = uiT(game,'shop.martBarterPrestigeTitle', 'Trade: {qty}× {item} → 1 Prestige Stone', { qty: c.qty, item: costNm });
            displayDescription = uiT(game,'shop.martBarterPrestigeDesc', 'Pay with evolution items (not Pokédollars).', {});
        }
        const canAfford = (typeof game.canAffordPokeMartItem === 'function')
            ? game.canAffordPokeMartItem(shopEntry)
            : (isDust ? (game.essenceDust >= (shopEntry.dustCost || 0)) : (game.pokedollars >= shopEntry.cost));
        const stock = (typeof game.getPokeMartOfferStock === 'function')
            ? game.getPokeMartOfferStock(key)
            : { purchased: 0, max: 1 };
        const stockRemaining = Math.max(0, stock.max - stock.purchased);
        const isSoldOut = stockRemaining <= 0;
        const canBuy = canAfford && !isSoldOut;
        const costText = isBarter
            ? (shopEntry.costItems || []).map((c: PokeMartCostLine) => {
                const d = getAllItem(c.itemId) ?? null;
                const nm = (typeof game.getLocalizedItemName === 'function')
                    ? game.getLocalizedItemName(c.itemId, d?.name ? d.name : c.itemId, d)
                    : c.itemId;
                return `${c.qty}× ${nm}`;
            }).join(' + ')
            : (isDust ? `<img src="img/essence-dust.png" class="essence-dust-inline" alt=""> ${formatNumber(shopEntry.dustCost || 0)} Dust` : `$ ${formatNumber(shopEntry.cost)}`);
        const cantBuyLabel = isBarter
            ? uiT(game,'shop.martNotEnoughItems', 'Not enough items')
            : (isDust ? uiT(game,'shop.martNotEnoughDust', 'Not enough Essence Dust') : uiT(game,'shop.martNotEnoughMoney', 'Not enough money'));
        const bagOwnedLabel = buildMartBagOwnedLabel(game, linkedItemId);
        return {
            key,
            displayName,
            description: displayDescription,
            stockLabel: uiT(game,'shop.martStock', 'Stock: {value}', { value: `${stockRemaining}/${stock.max}` }),
            stockColor: isSoldOut ? '#c62828' : '#2e7d32',
            stockRemaining,
            stockMax: stock.max,
            bagOwnedLabel,
            costText,
            iconHtml: iconHTML,
            canBuy,
            buttonLabel: isSoldOut
                ? uiT(game,'shop.martSoldOutButton', 'Sold out')
                : (canAfford ? uiT(game,'shop.buy', 'Buy') : cantBuyLabel),
            autoPurchaseBadge: autoPurchaseKeys.has(key) ? autoBadgeLabel : null,
        };
    });

    return { offers, martEmptyMessage: null };
}

/**
 * HTML PokéMart (épicerie).
 */
export function buildMartHtml(game: GameRuntime): string {

    if (!POKEMART_ITEMS) return '';
    const now = Date.now();
    const offers = resolveMartOffers(game, now);

    let html = '';

    if (!offers.length) {
        return html + `<div class="shop-item"><div class="shop-item-description">${uiT(game,'shop.martVendorPreparing', 'The merchant is preparing crates, come back in a moment.')}</div></div>`;
    }

    offers.forEach(({ key, item: shopEntry }) => {
        const linkedItemId = String(shopEntry.itemId || shopEntry.item || '');
        const realItem = getAllItem(linkedItemId) ?? null;
        const iconHTML = getItemIconHTML(realItem || shopEntry);
        let displayName = uiDataText(game, 'pokeMart', key, 'name', shopEntry.name);
        let displayDescription = uiDataText(game, 'pokeMart', key, 'description', shopEntry.description);
        const isBarter = Array.isArray(shopEntry.costItems) && shopEntry.costItems.length > 0;
        const isDust = !isBarter && Number(shopEntry.dustCost) > 0;
        if (isBarter && shopEntry.costItems?.[0]) {
            const c = shopEntry.costItems[0];
            const costDef = getAllItem(c.itemId) ?? null;
            const costNm = (typeof game.getLocalizedItemName === 'function')
                ? game.getLocalizedItemName(c.itemId, costDef?.name ? costDef.name : c.itemId, costDef)
                : c.itemId;
            displayName = uiT(game,'shop.martBarterPrestigeTitle', 'Trade: {qty}× {item} → 1 Prestige Stone', { qty: c.qty, item: costNm });
            displayDescription = uiT(game,'shop.martBarterPrestigeDesc', 'Pay with evolution items (not Pokédollars).', {});
        }
        const canAfford = (typeof game.canAffordPokeMartItem === 'function')
            ? game.canAffordPokeMartItem(shopEntry)
            : (isDust ? (game.essenceDust >= (shopEntry.dustCost || 0)) : (game.pokedollars >= shopEntry.cost));
        const stock = (typeof game.getPokeMartOfferStock === 'function')
            ? game.getPokeMartOfferStock(key)
            : { purchased: 0, max: 1 };
        const stockRemaining = Math.max(0, stock.max - stock.purchased);
        const isSoldOut = stockRemaining <= 0;
        const canBuy = canAfford && !isSoldOut;

        const costHtml = isBarter
            ? `<div class="shop-item-cost" style="color: #333;">${(shopEntry.costItems || []).map((c: PokeMartCostLine) => {
                const d = getAllItem(c.itemId) ?? null;
                const nm = (typeof game.getLocalizedItemName === 'function')
                    ? game.getLocalizedItemName(c.itemId, d?.name ? d.name : c.itemId, d)
                    : c.itemId;
                return `${c.qty}× ${nm}`;
            }).join(' + ')}</div>`
            : (isDust ? `<div class="shop-item-cost" style="color: #333;"><img src="img/essence-dust.png" class="essence-dust-inline" alt=""> ${formatNumber(shopEntry.dustCost || 0)} Dust</div>`
            : `<div class="shop-item-cost" style="color: #333;">$ ${formatNumber(shopEntry.cost)}</div>`);

        const cantBuyLabel = isBarter
            ? uiT(game,'shop.martNotEnoughItems', 'Not enough items')
            : (isDust ? uiT(game,'shop.martNotEnoughDust', 'Not enough Essence Dust') : uiT(game,'shop.martNotEnoughMoney', 'Not enough money'));
        const bagOwnedLabel = buildMartBagOwnedLabel(game, linkedItemId);
        const stockColor = isSoldOut ? '#c62828' : '#2e7d32';
        const stockText = uiT(game,'shop.martStock', 'Stock: {value}', { value: `${stockRemaining}/${stock.max}` });
        const stockLineHtml = bagOwnedLabel
            ? `<div class="shop-item-description" style="font-size:11px; color:${stockColor};">${stockText}<span style="color:#64748b;"> · ${bagOwnedLabel}</span></div>`
            : `<div class="shop-item-description" style="font-size:11px; color:${stockColor};">${stockText}</div>`;

        html += `
        <div class="shop-item">
            <div class="shop-item-name" style="display:flex; align-items:center; gap:10px;">
                ${iconHTML}
                <span>${displayName}</span>
            </div>
            <div class="shop-item-description">${displayDescription}</div>
            ${stockLineHtml}
            ${costHtml}
            <button class="shop-buy-btn" 
                    style="background: ${canBuy ? 'linear-gradient(135deg, #2196f3, #1976d2)' : '#ccc'};"
                    data-action="buyPokeMartItem" data-arg="${key}" 
                    ${!canBuy ? 'disabled' : ''}>
                ${isSoldOut ? uiT(game,'shop.martSoldOutButton', 'Sold out') : (canAfford ? uiT(game,'shop.buy', 'Buy') : cantBuyLabel)}
            </button>
        </div>`;
    });
    return html;
}

