/**
 * HTML améliorations (upgrades).
 */
export function buildUpgradesHtml(game: GameRuntime): string {

    if (!game.upgrades) return '';
    const entries = (Object.entries(game.upgrades))
        .filter(([key]) => key !== 'incubatorSlots' && key !== 'incubatorClickPower' && key !== 'incubatorAutoClick')
        .filter(([key]) => key !== 'ultimateSlotTransfer' || isUltimateSlotUnlocked(game));
    const sorted = entries.slice().sort((a, b) => {
        const aMaxed = a[1].level >= a[1].maxLevel;
        const bMaxed = b[1].level >= b[1].maxLevel;
        if (aMaxed === bMaxed) return 0;
        return aMaxed ? 1 : -1;
    });

    let html = '';
    sorted.forEach(([key, upgrade]: [string, UpgradeState]) => {
        const cost = game.getUpgradeCost(key);
        const canAfford = game.canAffordUpgrade(key);
        const isMaxLevel = upgrade.level >= upgrade.maxLevel;

        let currentEffect = "";
        switch (key) {
            case 'critMastery': currentEffect = uiT(game,'shop.upgradeCurrentCrit', 'Current bonus: +{value}%', { value: (upgrade.level * 1).toFixed(0) }); break;
            case 'expBoost': currentEffect = uiT(game,'shop.upgradeCurrentExpMultiplier', 'Multiplier: x{value}', { value: (game.getExpMultiplier() * 100 / 100).toFixed(1) }); break;
            case 'eggDrop': currentEffect = uiT(game,'shop.upgradeCurrentEggBonus', 'Bonus: +{value}%', { value: (game.getEggDropBonus() * 100).toFixed(0) }); break;
            case 'staminaRegen': currentEffect = uiT(game,'shop.upgradeCurrentStamina', 'Time: {value}s', { value: (game.getStaminaRegenTime() / 1000).toFixed(1) }); break;
            case 'shardBonus': currentEffect = uiT(game,'shop.upgradeCurrentShardChance', 'Chance: {value}%', { value: (game.getShardBonusChance() * 100).toFixed(0) }); break;
            case 'pension': currentEffect = uiT(game,'shop.upgradeCurrentPension', 'Slots: {slots} | Transfer: {transfer}%', { slots: game.getPensionSlots(), transfer: (game.getPensionTransferRate() * 100).toFixed(0) }); break;
            case 'ultimateSlotTransfer': currentEffect = uiT(game, 'shop.upgradeCurrentUltimateSlot', 'Transfer: {value}%', { value: ((typeof game.getUltimateSlotTransferRate === 'function' ? game.getUltimateSlotTransferRate() : 0) * 100).toFixed(0) }); break;
            case 'respawn': currentEffect = uiT(game,'shop.upgradeCurrentRespawn', 'Reduced delay: -{value}ms', { value: upgrade.level * balanceRespawnUpgradeMsPerLevel() }); break;
            case 'recycle': currentEffect = uiT(game,'shop.upgradeCurrentRecycle', 'Savings chance: {value}%', { value: (upgrade.level * 2.5).toFixed(0) }); break;
            case 'second_chance': currentEffect = uiT(game,'shop.upgradeCurrentSecondChance', 'Reroll chance: {value}%', { value: (upgrade.level * 1).toFixed(0) }); break;
            case 'incubatorSlots': currentEffect = uiT(game,'shop.upgradeCurrentIncubators', 'Incubators: {value}/4', { value: (1 + (upgrade.level || 0)) }); break;
            case 'incubationSpeed': currentEffect = uiT(game,'shop.upgradeCurrentIncubation', 'Incubation time: -{value}%', { value: ((upgrade.level || 0) * 10) }); break;
            case 'offlineCombatCap': {
                const maxCombats = computeOfflineCatchupMaxCombats(
                    game.permanentBoosts?.offlineCombatCap ?? 0,
                    upgrade.level || 0,
                );
                currentEffect = uiT(game, 'shop.upgradeCurrentOfflineCombatCap', 'Current cap: {maxCombats} offline fights', { maxCombats });
                break;
            }
        }

        const classList = `upgrade-card ${isMaxLevel ? 'maxed' : ''} ${!canAfford && !isMaxLevel ? 'not-affordable' : ''}`;
        const displayName = uiDataText(game, 'upgrades', key, 'name', upgrade.name);
        const displayDescription = uiDataText(game, 'upgrades', key, 'description', upgrade.description);
        const displayEffect = uiDataText(game, 'upgrades', key, 'effect', upgrade.effect);

        html += `
        <div class="${classList}">
            <div class="upgrade-title">${displayName}</div>
            <div class="upgrade-description">${displayDescription}</div>
            <div class="upgrade-stats">
                <div class="upgrade-level">${uiT(game,'shop.upgradeLevel', 'Lvl {level}/{max}', { level: upgrade.level, max: upgrade.maxLevel })}</div>
                <div class="upgrade-effect">${displayEffect}</div>
            </div>
            ${currentEffect ? `<div style="font-size: 11px; color: rgba(255,255,255,0.7); margin-bottom: 10px; font-weight: 600;">${currentEffect}</div>` : ''}
            <div class="upgrade-cost" style="margin-bottom: 15px;">
                ${isMaxLevel ? uiT(game,'shop.upgradeMaxLevel', 'MAX LEVEL') : `<img src="img/pokedollars.png" class="pokedollars-inline" alt=""> ${formatNumber(cost)}`}
            </div>
            <button class="upgrade-btn" 
                    data-action="buyUpgrade" data-arg="${key}" 
                    ${!canAfford || isMaxLevel ? 'disabled' : ''}>
                ${isMaxLevel ? uiT(game,'shop.upgradeMaxLevel', 'MAX LEVEL') : (canAfford ? uiT(game,'shop.upgradeBuyUpper', 'BUY') : uiT(game,'shop.upgradeNotEnoughFunds', 'NOT ENOUGH FUNDS'))}
            </button>
        </div>`;
    });
    return html;
}

export function bindUpgradeTooltips(container: Element | null, game: GameRuntime): void {
    if (!container || typeof game.scheduleTooltip !== 'function' || typeof game.hideTooltip !== 'function') return;
    const statsRows = container.querySelectorAll('.upgrade-stats');
    statsRows.forEach((row: Element) => {
        const effectNode = row.querySelector('.upgrade-effect');
        const cardNode = row.closest('.upgrade-card');
        const titleNode = cardNode ? cardNode.querySelector('.upgrade-title') : null;
        const effectText = effectNode ? String(effectNode.textContent || '').trim() : '';
        if (!effectText) return;

        const tooltipTitle = titleNode ? String(titleNode.textContent || '').trim() : uiT(game,'shop.upgradeEffectTitle', 'Bonus par niveau');
        row.addEventListener('mouseenter', (event: Event) => {
            game.scheduleTooltip(event, tooltipTitle, effectText, 60);
        });
        row.addEventListener('mouseleave', () => {
            game.hideTooltip();
        });
    });
}

