/**
 * HTML boutique aux jetons.
 */
export function buildTokenShopHtml(game: GameRuntime): string {

    if (!SHOP_ITEMS) return '';

    const isTokenShopItemAllowed = (item: TokenShopEntry, itemKey: string): boolean => {
        if (typeof game.isTokenShopItemAllowed === 'function') {
            return game.isTokenShopItemAllowed(item, itemKey);
        }
        if (item.type === 'boost') return false;
        if (item.type === 'egg') return false;
        if (item.type === 'ct') {
            return itemKey === 'ct_Surf' && isStorySurfQuestActiveForShop(game);
        }
        if (item.type === 'item') {
            const itemId = String(item.item || item.itemId || '').toLowerCase();
            if (itemId.includes('ball')) return false;
        }
        return true;
    };

    let html = '';
    const shopEntries = Object.entries(tokenShopEntries)
        .filter(([key, item]) => isTokenShopItemAllowed(item, key))
        .map(([key, item]) => {
        let currentCost: number = typeof item.cost === 'number' ? item.cost : 0;
        let isMaxed = false;
        let levelInfo = "";

        if (tokenShopHasScalingCost(item)) {
            let storedValue = 0;
            if (item.effect.type === 'pensionSlot') storedValue = game.permanentBoosts.pensionSlots || 0;
            else if (item.effect.type === 'permanentXP') storedValue = game.permanentBoosts.xp || 0;
            else if (item.effect.type === 'permanentPensionXP') storedValue = game.permanentBoosts.pensionXp || 0;
            else if (item.effect.type === 'permanentTowerItemDrop') storedValue = game.permanentBoosts.tower_item_drop_chance || 0;
            else if (item.effect.type === 'permanentTowerBossLoot') storedValue = game.permanentBoosts.tower_boss_loot_bonus || 0;
            else if (item.effect.type === 'rocketAutoSpin') storedValue = game.permanentBoosts.rocketAutoSpin || 0;
            else if (item.effect.type === 'dailyQuestDifficulty') storedValue = game.permanentBoosts.dailyQuestDifficulty || 0;
            else if (item.effect.type === 'offlineCombatCap') storedValue = game.permanentBoosts.offlineCombatCap || 0;

            const currentLevel = Math.round(storedValue / item.effect.value);
            if (currentLevel >= item.maxLevel) {
                isMaxed = true;
                currentCost = 0;
            } else {
                const costTier = item.cost[currentLevel] ?? item.cost[item.cost.length - 1];
                currentCost = costTier ?? 0;
            }
            levelInfo = ` <span style="font-size:11px; color:#666;">${uiT(game,'shop.levelInfo', '(Lvl {level}/{max})', { level: currentLevel, max: item.maxLevel })}</span>`;
        }

        // Achat unique de déblocage de feature : déjà acheté → marqué comme MAX.
        if (item.type === 'feature_unlock' && item.featureKey
            && game.unlockedFeatures?.[item.featureKey as keyof typeof game.unlockedFeatures]) {
            isMaxed = true;
        }

        return { key, item, currentCost, isMaxed, levelInfo };
    });

    if (shopEntries.length === 0) {
        return `<div class="shop-item"><div class="shop-item-description">${uiT(game,'shop.tokenEmpty', 'No item available for now.')}</div></div>`;
    }
    const sortedShop = shopEntries.slice().sort((a, b) => {
        if (a.isMaxed === b.isMaxed) return 0;
        return a.isMaxed ? 1 : -1;
    });
    sortedShop.forEach(({ key, item, currentCost, isMaxed, levelInfo }) => {
        const canAfford = !isMaxed && game.questTokens >= currentCost;
        let displayName = uiDataText(game, 'tokenShop', key, 'name', item.name);
        let displayDescription = uiDataText(game, 'tokenShop', key, 'description', item.description);
        displayName = uiMaybeLocalizeCtName(game, item, key, displayName);
        displayDescription = uiMaybeLocalizeCtDescription(game, item, key, displayDescription);

        let extraInfo = '';
        if (item.type === 'permanent' && item.effect?.type === 'permanentXP') {
            extraInfo = `<div style="font-size: 11px; color: #666; margin-top: 5px;">${uiT(game,'shop.currentXpBonus', 'Current: +{percent}% XP', { percent: ((game.permanentBoosts.xp || 0) * 100).toFixed(0) })}</div>`;
        }
        if (item.type === 'permanent' && item.effect?.type === 'pensionSlot') {
            extraInfo = `<div style="font-size: 11px; color: #666; margin-top: 5px;">${uiT(game,'shop.bonusSlots', 'Bonus slots: {slots}', { slots: game.permanentBoosts.pensionSlots || 0 })}</div>`;
        }
        if (item.type === 'permanent' && item.effect?.type === 'permanentPensionXP') {
            extraInfo = `<div style="font-size: 11px; color: #666; margin-top: 5px;">${uiT(game,'shop.currentPensionXpBonus', 'Current: +{percent}% XP (daycare)', { percent: ((game.permanentBoosts.pensionXp || 0) * 100).toFixed(0) })}</div>`;
        }
        if (item.type === 'permanent' && item.effect?.type === 'permanentTowerItemDrop') {
            extraInfo = `<div style="font-size: 11px; color: #666; margin-top: 5px;">${uiT(game,'shop.currentTowerItemDrop', 'Current: +{percent}% item-drop on Tower relics', { percent: ((game.permanentBoosts.tower_item_drop_chance || 0) * 100).toFixed(0) })}</div>`;
        }
        if (item.type === 'permanent' && item.effect?.type === 'permanentTowerBossLoot') {
            const bonus = game.permanentBoosts.tower_boss_loot_bonus || 0;
            extraInfo = `<div style="font-size: 11px; color: #666; margin-top: 5px;">${uiT(game,'shop.currentTowerBossLoot', 'Current: x{mult} boss loot multiplier', { mult: (1 + bonus).toFixed(2) })}</div>`;
        }
        if (item.type === 'permanent' && item.effect?.type === 'tower_combat_speed') {
            const maxSpeed = 1 + Math.min(
                TOWER_COMBAT_SPEED_MAX_SHOP_LEVEL,
                Math.max(0, Math.floor(Number(game.permanentBoosts.tower_combat_speed) || 0)),
            );
            extraInfo = `<div style="font-size: 11px; color: #666; margin-top: 5px;">${uiT(game, 'shop.currentTowerCombatSpeed', 'Current max speed: x{speed}', { speed: maxSpeed })}</div>`;
        }
        if (item.type === 'permanent' && item.effect?.type === 'offlineCombatCap') {
            const maxCombats = computeOfflineCatchupMaxCombats(
                game.permanentBoosts?.offlineCombatCap ?? 0,
                game.upgrades?.offlineCombatCap?.level ?? 0,
            );
            extraInfo = `<div style="font-size: 11px; color: #666; margin-top: 5px;">${uiT(game, 'shop.currentOfflineCombatCap', 'Current cap: {maxCombats} offline fights', { maxCombats })}</div>`;
        }

        // Auto-spin Rocket : affiche les bonus actuels + cap dynamique lie a la Confiance Rocket.
        let trustLocked = false;
        if (item.type === 'permanent' && item.effect?.type === 'dailyQuestDifficulty') {
            const tier = Math.max(0, Math.min(3, Math.floor(Number(game.permanentBoosts && game.permanentBoosts.dailyQuestDifficulty) || 0)));
            const labels = [
                uiT(game,'shop.dailyQuestTier0', 'Max difficulty: Easy'),
                uiT(game,'shop.dailyQuestTier1', 'Max difficulty: Medium'),
                uiT(game,'shop.dailyQuestTier2', 'Max difficulty: Hard'),
                uiT(game,'shop.dailyQuestTier3', 'Max difficulty: Extreme')
            ];
            extraInfo = `<div style="font-size: 11px; color: #666; margin-top: 5px;">${labels[tier] || labels[0]}</div>`;
        }
        if (item.type === 'permanent' && item.effect?.type === 'rocketAutoSpin') {
            const currentAutoLevel = Math.max(0, Math.floor(Number(game.permanentBoosts && game.permanentBoosts.rocketAutoSpin) || 0));
            const currentSpins = currentAutoLevel * 3;
            const currentSpeedPct = currentAutoLevel * 10;
            const currentTrust = Math.max(1, Math.floor(Number(game.teamRocketState && game.teamRocketState.trustLevel) || 1));
            const maxAllowed = Math.max(0, Math.min(item.maxLevel || 4, currentTrust - 1));
            const requiredTrust = currentAutoLevel + 2;
            if (!isMaxed && currentAutoLevel >= maxAllowed) {
                trustLocked = true;
            }
            extraInfo = `<div style="font-size: 11px; color: #666; margin-top: 5px;">${uiT(game,'shop.currentRocketAutoSpin', 'Current: {spins} auto-spins, +{speed}% animation speed', { spins: currentSpins, speed: currentSpeedPct })}</div>`;
            if (trustLocked) {
                extraInfo += `<div style="font-size: 11px; color: #f59e0b; margin-top: 3px; font-weight: 600;">${uiT(game,'shop.rocketAutoSpinTrustLocked', 'Requires Rocket Trust level {required} (you have {current})', { required: requiredTrust, current: currentTrust })}</div>`;
            }
        }

        const buyDisabled = isMaxed || !canAfford || trustLocked;
        const classList = `shop-item ${isMaxed ? 'maxed' : ''} ${(!canAfford || trustLocked) && !isMaxed ? 'not-affordable' : ''}`;
        const buttonText = isMaxed
            ? uiT(game,'shop.maxed', 'MAXED')
            : (trustLocked
                ? uiT(game,'shop.rocketAutoSpinLockedBtn', 'Trust level too low')
                : (canAfford ? uiT(game,'shop.buy', 'Buy') : uiT(game,'shop.notEnoughTokens', 'Not enough tokens')));
        const formattedCurrentCost = formatNumber(currentCost);
        const costText = isMaxed ? "" : `<img src="https://raw.githubusercontent.com/msikma/pokesprite/master/items/key-item/magma-emblem.png" class="quest-token-inline" alt=""> ${formattedCurrentCost} ${uiT(game,'shop.tokensUnit', 'Tokens')}`;
        const iconHTML = resolveTokenShopIconHTML(item);

        html += `
        <div class="${classList}">
            <div class="shop-item-name" style="display:flex; align-items:center; gap:10px;">
                ${iconHTML}
                <span>${displayName}${levelInfo}</span>
            </div>
            <div class="shop-item-description">${displayDescription}</div>
            ${extraInfo}
            <div class="shop-item-cost">${costText}</div>
            <button class="shop-buy-btn" data-action="buyShopItem" data-arg="${key}" ${buyDisabled ? 'disabled' : ''}>
                ${buttonText}
            </button>
        </div>`;
    });
    return html;
}

