/**
 * HTML boutique Tour (Marques du Triomphe).
 */
export function buildTowerShopHtml(game: GameRuntime): string {
    if (!TOWER_SHOP_ITEMS) return '';

    let html = '';
    Object.entries(towerShopEntries).forEach(([key, item]) => {
        let currentLevel = 0;
        let isMaxLevel = false;
        let costAmount = typeof item.cost === 'number' ? item.cost : 0;
        let levelText = '';
        const displayName = uiDataText(game, 'towerShop', key, 'name', item.name);
        const displayDescription = uiDataText(game, 'towerShop', key, 'description', item.description);

        const permanentBoosts = game.permanentBoosts as unknown as Record<string, number>;
        if (item.effect) {
            currentLevel = getTowerShopPermanentLevel(
                item.effect.type,
                item.effect.value,
                permanentBoosts,
            );
        }
        if (item.maxLevel && item.effect) {
            isMaxLevel = currentLevel >= item.maxLevel;
            levelText = ` ${uiT(game,'shop.towerLevelInfo', '(Lvl {level}/{max})', { level: currentLevel, max: item.maxLevel })}`;
        }
        if (item.effect && (item.maxLevel || typeof item.costMultiplier === 'number')) {
            costAmount = isMaxLevel ? 0 : getTowerShopPurchaseCost(item, currentLevel);
        }

        // Achat unique de déblocage de feature : déjà acheté → marqué comme MAX.
        if (item.type === 'feature_unlock' && item.featureKey
            && game.unlockedFeatures?.[item.featureKey as keyof typeof game.unlockedFeatures]) {
            isMaxLevel = true;
            costAmount = 0;
        }

        const canAfford = !isMaxLevel && game.triumphMarks >= costAmount;

        const formattedTowerCost = isMaxLevel
            ? 'MAX'
            : formatNumber(costAmount);

        html += `
        <div class="shop-item">
            <div class="shop-item-name">${displayName}${levelText}</div>
            <div class="shop-item-description">${displayDescription}</div>
            <div class="shop-item-cost"><img src="https://raw.githubusercontent.com/msikma/pokesprite/master/items/valuable-item/relic-crown.png" class="marque-triomphe-inline" alt=""> ${formattedTowerCost} ${uiT(game,'shop.towerMarksUnit', 'Marks')}</div>
            <button class="shop-buy-btn" data-action="buyTowerShopItem" data-arg="${key}" ${!canAfford || isMaxLevel ? 'disabled' : ''}>
                ${isMaxLevel ? uiT(game,'shop.upgradeMaxLevel', 'MAX LEVEL') : (canAfford ? uiT(game,'shop.buy', 'Buy') : uiT(game,'shop.towerInsufficientMarks', 'Not enough marks'))}
            </button>
        </div>`;
    });
    return html;
}

