const RARITY = (globalThis as { RARITY?: { COMMON?: string } }).RARITY ?? { COMMON: 'common' };

function incubatorLockLabel(game: GameRuntime, slotIndex: number): string {
  if (typeof game.getIncubatorLockLabel === 'function') {
    return game.getIncubatorLockLabel(slotIndex);
  }
  if (slotIndex === MAX_INCUBATOR_SLOTS - 1) {
    const hasMastery = typeof game.hasMasteryIncubatorSlot === 'function' && game.hasMasteryIncubatorSlot();
    if (!hasMastery) return game.t('bag.incubatorMasteryRequired');
    const base = typeof game.getBaseIncubatorSlots === 'function' ? game.getBaseIncubatorSlots() : 4;
    if (base < 4) return game.t('bag.incubatorQuestRequired', { step: 4 });
  }
  return game.t('bag.incubatorQuestRequired', { step: slotIndex + 1 });
}

function incubatorSlotTooltip(game: GameRuntime, slotIndex: number): string {
  if (typeof game.getIncubatorSlotTooltip === 'function') {
    return game.getIncubatorSlotTooltip(slotIndex);
  }
  if (slotIndex === 1) return game.t('bag.incubatorAdvanced');
  if (slotIndex === 2) return game.t('bag.incubatorExpert');
  if (slotIndex === 3) return game.t('bag.incubatorMaster');
  if (slotIndex === 4) return game.t('bag.incubatorParallel');
  return game.t('bag.incubatorClassic');
}

function bagT(game: GameRuntime | null | undefined, key: string, fallback: string): string {
  if (game && typeof game.t === 'function') {
    const translated = game.t(key);
    if (translated && translated !== key) return translated;
  }
  return fallback;
}

