function buildBagAutoCatch(game: GameRuntime): BagAutoCatchSnapshot {
  const normalize = (game as GameRuntime & { normalizeAutoCatcherSettings?: () => {
    enabled: boolean;
    catchShiny: boolean;
    catchRoamer: boolean;
    catchLegendary: boolean;
    minCatchChancePct: number;
    useMasterballActiveTargets: boolean;
    useMasterballShiny: boolean;
    useMasterballRoamer: boolean;
    useMasterballLegendary: boolean;
  } }).normalizeAutoCatcherSettings;
  const s = typeof normalize === 'function'
    ? normalize.call(game)
    : {
        enabled: true,
        catchShiny: true,
        catchRoamer: true,
        catchLegendary: true,
        minCatchChancePct: 75,
        useMasterballActiveTargets: false,
        useMasterballShiny: true,
        useMasterballRoamer: true,
        useMasterballLegendary: false,
      };
  const hasGreatBallMastery = typeof game.getMasteryBonus === 'function'
    && (game.getMasteryBonus('autocatch_great_ball') || 0) > 0;
  const hasMasterBallMastery = typeof game.getMasteryBonus === 'function'
    && (game.getMasteryBonus('autocatch_master_ball') || 0) > 0;
  return {
    panelVisible: !!game.hasAutoCatcher,
    enabled: s.enabled !== false,
    catchShiny: s.catchShiny !== false,
    catchRoamer: s.catchRoamer !== false,
    catchLegendary: s.catchLegendary !== false,
    minChancePct: String(s.minCatchChancePct),
    showBallControls: hasGreatBallMastery,
    showMasterballSetting: hasMasterBallMastery,
    useMasterballActiveTargets: s.useMasterballActiveTargets === true,
    useMasterballShiny: s.useMasterballShiny !== false,
    useMasterballRoamer: s.useMasterballRoamer !== false,
    useMasterballLegendary: s.useMasterballLegendary === true,
  };
}

const EMPTY_EGG_SECTIONS: BagEggSectionsSnapshot = {
  incubators: [],
  displayedSlotCount: 4,
  eggRows: [],
  showEmptyMessage: true,
  emptyTitle: '',
  emptyHint: '',
};

function buildBagEggSections(game: GameRuntime): BagEggSectionsSnapshot {
  const rarities = ['common', 'rare', 'epic', 'legendary'] as const;
  const maxSlots = typeof game.getMaxIncubatorSlots === 'function' ? game.getMaxIncubatorSlots() : 4;
  const displayedSlotCount = (typeof game.getDisplayedIncubatorSlotCount === 'function'
    ? game.getDisplayedIncubatorSlotCount()
    : (typeof game.hasMasteryIncubatorSlot === 'function' && game.hasMasteryIncubatorSlot() ? 5 : 4)) as 4 | 5;
  const incubators = [];
  for (let i = 0; i < displayedSlotCount; i++) {
    const slot = (game.incubators as unknown[])[i] as {
      rarity?: string;
      durationMs?: number;
      startTime?: number;
    } | null;
    const locked = i >= maxSlots;
    const hasEgg = !locked && !!slot;
    const remaining = hasEgg && typeof game.getIncubatorRemainingMs === 'function'
      ? game.getIncubatorRemainingMs(i)
      : 0;
    const ready = hasEgg && remaining === 0;
    const durationMs = hasEgg ? (slot?.durationMs || 1) : 1;
    const progress = hasEgg ? Math.min(1, 1 - remaining / durationMs) : 0;
    const rarity = hasEgg ? String(slot?.rarity || 'common') : 'common';
    let filterClass = '';
    if (rarity === 'rare') filterClass = 'egg-filter-rare';
    else if (rarity === 'epic') filterClass = 'egg-filter-epic';
    else if (rarity === 'legendary') filterClass = 'egg-filter-legendary';
    const autoSettings = typeof game.getAutoIncubationSettings === 'function'
      ? game.getAutoIncubationSettings(i)
      : { enabled: false, priorityOrder: [RARITY.COMMON] };
    const isAutoUnlocked = typeof game.isAutoIncubationUnlockedForSlot === 'function'
      ? game.isAutoIncubationUnlockedForSlot(i)
      : false;
    const priorityCode = autoSettings.priorityOrder?.[0] || RARITY.COMMON;
    incubators.push({
      index: i,
      locked,
      hasEgg,
      ready,
      progress,
      rarity,
      timerText: hasEgg
        ? (ready ? game.t('bag.incubatorReady') : game.formatMsAsTime(remaining))
        : '--:--',
      filterClass,
      tooltip: incubatorSlotTooltip(game, i),
      lockLabel: incubatorLockLabel(game, i),
      autoUnlocked: isAutoUnlocked,
      autoEnabled: !!autoSettings.enabled,
      autoBtnLabel: autoSettings.enabled ? game.t('state.on') : game.t('state.off'),
      priorityLabel: typeof game.getSlotPriorityLabel === 'function' ? game.getSlotPriorityLabel(i) : String(priorityCode),
      priorityClass: `priority-${String(priorityCode || '').toLowerCase()}`,
    });
  }

  const eggs = game.eggs as Record<string, number> | undefined;
  const totalEggs = Object.values(eggs || {}).reduce((sum, count) => sum + (Number(count) || 0), 0);
  const eggRows = rarities.map((rarity) => {
    const count = Number(eggs?.[rarity]) || 0;
    return {
      rarity,
      count,
      visible: count > 0,
      label: typeof game.getRarityLabel === 'function' ? game.getRarityLabel(rarity).toUpperCase() : rarity.toUpperCase(),
      filterClass: rarity === 'rare' ? 'egg-filter-rare' : rarity === 'epic' ? 'egg-filter-epic' : rarity === 'legendary' ? 'egg-filter-legendary' : '',
      eggSpriteUrl: `img/${rarity}-egg.png`,
      alt: game.t('bag.eggAlt', { rarity: typeof game.getRarityLabel === 'function' ? game.getRarityLabel(rarity) : rarity }),
      hint: game.t('bag.placeInIncubator'),
    };
  });

  return {
    incubators,
    displayedSlotCount,
    eggRows,
    showEmptyMessage: totalEggs === 0,
    emptyTitle: game.t('bag.eggsEmptyTitle'),
    emptyHint: game.t('bag.eggsEmptyHint'),
  };
}

function buildBagEggMeta(
  game: GameRuntime,
): Pick<BagSnapshot, 'eggsTotalCount' | 'incubatorBoostText' | 'incubatorBoostTitle' | 'incubatorBoostVisible'> {
  const totalEggs = Object.values(game.eggs || {}).reduce(
    (sum, count) => sum + (Number(count) || 0),
    0,
  );
  const now = Date.now();
  const hatchBoost = (game.activeBoosts || []).find(
    (boost: { type?: string; endTime?: number; value?: number }) =>
      boost && boost.type === 'eggHatchSpeed' && Number(boost.endTime) > now,
  );
  const maternalReduction = typeof game.getMaternalInstinctIncubationReduction === 'function'
    ? game.getMaternalInstinctIncubationReduction()
    : 0;
  const maternalPct = maternalReduction > 0 ? Math.round(maternalReduction * 100) : 0;

  const textParts: string[] = [];
  const titleParts: string[] = [];

  if (hatchBoost) {
    const speedX = Math.max(1, Math.round(1 + (Number(hatchBoost.value) || 0)));
    const remainingMs = Math.max(0, Number(hatchBoost.endTime) - now);
    const timeStr = game.formatMsAsTime(remainingMs);
    textParts.push(`x${speedX} ${timeStr}`);
    titleParts.push(
      game.t('bag.incubatorBoostOvalCharm', { time: timeStr }),
    );
  }

  if (maternalPct > 0) {
    textParts.push(`-${maternalPct}% IM`);
    titleParts.push(
      game.t('bag.incubatorBoostMaternal', { pct: maternalPct }),
    );
  }

  return {
    eggsTotalCount: String(totalEggs),
    incubatorBoostText: textParts.join(' · '),
    incubatorBoostTitle: titleParts.join('\n'),
    incubatorBoostVisible: textParts.length > 0,
  };
}

export function buildBagSnapshot(game: GameRuntime): BagSnapshot {
  return {
    ui: buildBagPanelUi(game),
    autoCatch: buildBagAutoCatch(game),
    ...buildBagItemsSnapshot(game),
    ...buildBagEggMeta(game),
    eggSections: buildBagEggSections(game),
  };
}

let lastBagSnapshot: BagSnapshot | null = null;
let lastBagEggMeta: BagEggMetaSnapshot | null = null;

/** @internal Vitest only */
export function resetBagSnapshotDedupForTests(): void {
  lastBagSnapshot = null;
  lastBagEggMeta = null;
}

export function notifyBagChanged(game: GameRuntime): void {
  const bag = buildBagSnapshot(game);
  if (lastBagSnapshot && !bagSnapshotWouldChange(lastBagSnapshot, bag)) return;
  lastBagSnapshot = bag;
  lastBagEggMeta = pickBagEggMeta(bag);
  publish({ type: Evt.BAG_CHANGED, bag });
}

/** Egg count / boost only — does not rebuild inventory grid. */
function eggSectionsSig(sections: BagEggSectionsSnapshot): string {
  return JSON.stringify(sections);
}

/** Incubators + egg inventory rows (Svelte bag sections). */
export function notifyBagEggSectionsChanged(game: GameRuntime): void {
  const sections = buildBagEggSections(game);
  const eggMeta = buildBagEggMeta(game);
  if (lastBagSnapshot) {
    const prevSig = eggSectionsSig(lastBagSnapshot.eggSections ?? EMPTY_EGG_SECTIONS);
    const nextSig = eggSectionsSig(sections);
    const metaSame = lastBagEggMeta && !bagEggMetaWouldChange(lastBagEggMeta, eggMeta);
    if (prevSig === nextSig && metaSame) return;
    lastBagSnapshot = {
      ...lastBagSnapshot,
      ui: buildBagPanelUi(game),
      autoCatch: buildBagAutoCatch(game),
      ...eggMeta,
      eggSections: sections,
    };
  } else {
    lastBagSnapshot = buildBagSnapshot(game);
  }
  lastBagEggMeta = pickBagEggMeta(lastBagSnapshot);
  publish({ type: Evt.BAG_CHANGED, bag: lastBagSnapshot });
}

export function notifyBagEggMetaChanged(game: GameRuntime): void {
  notifyBagEggSectionsChanged(game);
}

/** @internal Vitest */
export function notifyBagInventoryChanged(game: GameRuntime): void {
  const bag = buildBagSnapshot(game);
  const inv = pickBagInventory(bag);
  if (lastBagSnapshot && !bagInventoryWouldChange(pickBagInventory(lastBagSnapshot), inv)) return;
  lastBagSnapshot = lastBagSnapshot
    ? { ...lastBagSnapshot, ui: buildBagPanelUi(game), autoCatch: buildBagAutoCatch(game), ...inv }
    : bag;
  lastBagEggMeta = pickBagEggMeta(lastBagSnapshot);
  publish({ type: Evt.BAG_CHANGED, bag: lastBagSnapshot });
}
