/**
 * Dynamax Band (Galar) — account window with linear upgrades.
 */

export const DYNAMAX_HP_MULT = 1.1;
export const DYNAMAX_DAMAGE_MULT = 1.1;
/** Base timed power window at upgrade level 0. */
export const DYNAMAX_DURATION_MS = 30000;

export const DYNAMAX_UPGRADE_MAX_LEVEL = 5;
export const DYNAMAX_UPGRADE_MULT_STEP = 0.1;
export const DYNAMAX_UPGRADE_DURATION_STEP_MS = 5000;

/** Money cost to go from level i → i+1 (index = current level). */
export const DYNAMAX_UPGRADE_MONEY_COSTS = [
    1_000_000_000,
    2_500_000_000,
    5_000_000_000,
    10_000_000_000,
    25_000_000_000,
] as const;

/** Evolution items to deposit for level i → i+1 (index = current level). */
export const DYNAMAX_UPGRADE_STONE_COSTS = [1000, 2000, 3000, 4000, 5000] as const;

export function clampDynamaxUpgradeLevel(level: unknown): number {
    const n = Math.floor(Number(level) || 0);
    if (!Number.isFinite(n) || n < 0) return 0;
    return Math.min(DYNAMAX_UPGRADE_MAX_LEVEL, n);
}

export function getDynamaxHpMult(level: number): number {
    const lv = clampDynamaxUpgradeLevel(level);
    return DYNAMAX_HP_MULT + lv * DYNAMAX_UPGRADE_MULT_STEP;
}

export function getDynamaxDamageMult(level: number): number {
    return getDynamaxHpMult(level);
}

export function getDynamaxDurationMs(level: number): number {
    const lv = clampDynamaxUpgradeLevel(level);
    return DYNAMAX_DURATION_MS + lv * DYNAMAX_UPGRADE_DURATION_STEP_MS;
}

export function getDynamaxUpgradeMoneyCost(currentLevel: number): number | null {
    const lv = clampDynamaxUpgradeLevel(currentLevel);
    if (lv >= DYNAMAX_UPGRADE_MAX_LEVEL) return null;
    return DYNAMAX_UPGRADE_MONEY_COSTS[lv] ?? null;
}

export function getDynamaxUpgradeStoneCost(currentLevel: number): number | null {
    const lv = clampDynamaxUpgradeLevel(currentLevel);
    if (lv >= DYNAMAX_UPGRADE_MAX_LEVEL) return null;
    return DYNAMAX_UPGRADE_STONE_COSTS[lv] ?? null;
}

export const GALAR_DYNAMAX_BADGE_IDS = [
    'meadow',
    'stream',
    'furnace',
    'fist',
    'quarry',
    'frost',
    'night',
    'charm',
] as const;

export type GalarDynamaxBadgeId = (typeof GALAR_DYNAMAX_BADGE_IDS)[number];

export function isGalarDynamaxBadgeId(id: string): id is GalarDynamaxBadgeId {
    return (GALAR_DYNAMAX_BADGE_IDS as readonly string[]).includes(id);
}
