/**
 * Prestige level refund (dissipation de prestige) — pure helpers.
 */

import type { CreatureData, PrestigeBonuses } from '../types/creature.js';

export const ARMORITE_ORE_ITEM_KEY = 'armorite_ore';

/** @deprecated Use ARMORITE_ORE_ITEM_KEY */
export const PRESTIGE_RECALL_ITEM_KEY = ARMORITE_ORE_ITEM_KEY;

export const ARMORITE_ORE_IMG_URL =
    'https://raw.githubusercontent.com/msikma/pokesprite/master/items-outline/other-item/armorite-ore.png';

export type PrestigeRecallBlockReason =
    | 'no_prestige'
    | 'missing_armorite_ore'
    | 'missing_dynite'
    | 'no_token';

export interface PrestigeRecallRequirements {
    stones: number;
    canApply: boolean;
    reasonKey?: PrestigeRecallBlockReason;
    tokensAfterDynite: number;
}

function sumPrestigeBonusesSpent(bonuses: PrestigeBonuses | undefined): number {
    if (!bonuses) return 0;
    return (bonuses.hp || 0) + (bonuses.attack || 0) + (bonuses.defense || 0)
        + (bonuses.spattack || 0) + (bonuses.spdefense || 0) + (bonuses.speed || 0);
}

/** Stones returned when lowering prestige from P to P-1 (cost paid at P-1 → P). */
export function getPrestigeStoneRefundAmount(currentPrestige: number): number {
    const p = Math.floor(Number(currentPrestige) || 0);
    if (p < 1) return 0;
    return Math.max(1, p);
}

export function getTokensAfterDyniteStep(creature: CreatureData): number {
    const tokens = Math.max(0, Math.floor(Number(creature.prestigeTokens) || 0));
    const spent = sumPrestigeBonusesSpent(creature.prestigeBonuses);
    return tokens + spent;
}

export function getPrestigeRecallRequirements(
    creature: CreatureData,
    items: Record<string, number> | undefined,
): PrestigeRecallRequirements {
    const prestige = Math.floor(Number(creature.prestige) || 0);
    const stones = getPrestigeStoneRefundAmount(prestige);
    const inv = items ?? {};
    const tokensAfterDynite = getTokensAfterDyniteStep(creature);

    if (prestige < 1) {
        return { stones: 0, canApply: false, reasonKey: 'no_prestige', tokensAfterDynite };
    }
    if ((inv[ARMORITE_ORE_ITEM_KEY] || 0) < 1) {
        return { stones, canApply: false, reasonKey: 'missing_armorite_ore', tokensAfterDynite };
    }
    if ((inv['dynite_ore'] || 0) < 1) {
        return { stones, canApply: false, reasonKey: 'missing_dynite', tokensAfterDynite };
    }
    if (tokensAfterDynite < 1) {
        return { stones, canApply: false, reasonKey: 'no_token', tokensAfterDynite };
    }

    return { stones, canApply: true, tokensAfterDynite };
}
