/**
 * @file regionMapAssets.ts
 * Runtime map URLs / hotspot areas for regions beyond Kanto (populated by *Data.ts register*).
 * Synced to globalThis for legacy scripts; zoneSystem reads this module via ESM.
 */

export type RegionMapAreaHotspot = {
    id: number;
    top: number;
    left: number;
    size?: number;
    width?: number;
    height?: number;
    labelFr?: string;
    labelEn?: string;
    [key: string]: unknown;
};

export const regionMapAssets = {
    JOHTO_MAP_IMAGE_URL: undefined as string | undefined,
    JOHTO_MAP_AREAS: undefined as RegionMapAreaHotspot[] | undefined,
    JOHTO_MAP_AREAS_MOBILE: undefined as RegionMapAreaHotspot[] | undefined,
    HOENN_MAP_IMAGE_URL: undefined as string | undefined,
    HOENN_MAP_AREAS: undefined as RegionMapAreaHotspot[] | undefined,
    HOENN_MAP_AREAS_MOBILE: undefined as RegionMapAreaHotspot[] | undefined,
    SINNOH_MAP_IMAGE_URL: undefined as string | undefined,
    SINNOH_MAP_AREAS: undefined as RegionMapAreaHotspot[] | undefined,
    SINNOH_MAP_AREAS_MOBILE: undefined as RegionMapAreaHotspot[] | undefined,
    UNOVA_MAP_IMAGE_URL: undefined as string | undefined,
    UNOVA_MAP_AREAS: undefined as RegionMapAreaHotspot[] | undefined,
    UNOVA_MAP_AREAS_MOBILE: undefined as RegionMapAreaHotspot[] | undefined,
    KALOS_MAP_IMAGE_URL: undefined as string | undefined,
    KALOS_MAP_AREAS: undefined as RegionMapAreaHotspot[] | undefined,
    KALOS_MAP_AREAS_MOBILE: undefined as RegionMapAreaHotspot[] | undefined,
    ALOLA_MAP_IMAGE_URL: undefined as string | undefined,
    ALOLA_MAP_AREAS: undefined as RegionMapAreaHotspot[] | undefined,
    GALAR_MAP_IMAGE_URL: undefined as string | undefined,
    GALAR_MAP_AREAS: undefined as RegionMapAreaHotspot[] | undefined,
    GALAR_MAP_AREAS_MOBILE: undefined as RegionMapAreaHotspot[] | undefined,
    PALDEA_MAP_IMAGE_URL: undefined as string | undefined,
    PALDEA_MAP_AREAS: undefined as RegionMapAreaHotspot[] | undefined,
    PALDEA_MAP_AREAS_MOBILE: undefined as RegionMapAreaHotspot[] | undefined,
};

export function syncRegionMapAssetsToGlobal(): void {
    const g = globalThis as Record<string, unknown>;
    const w = typeof window !== 'undefined' ? (window as unknown as Record<string, unknown>) : null;
    for (const [key, value] of Object.entries(regionMapAssets)) {
        if (value === undefined) continue;
        g[key] = value;
        if (w) w[key] = value;
    }
}
