/** Coût d'achat boutique Tour (Marques du Triomphe) pour un niveau donné. */
export type TowerShopCostItem = {
    cost?: number | number[];
    costMultiplier?: number;
};

export function getTowerShopPurchaseCost(item: TowerShopCostItem, currentLevel: number): number {
    const cost = item.cost;
    if (Array.isArray(cost)) {
        return Math.floor(Number(cost[currentLevel]) || 0);
    }
    const mult = item.costMultiplier;
    if (typeof mult === 'number' && mult > 0) {
        return Math.floor(Number(cost) * Math.pow(mult, currentLevel));
    }
    return Math.floor(Number(cost) || 0);
}

/** Niveau d'un boost permanent tower shop (ex. pensionSlots pour pensionSlot). */
export function getTowerShopPermanentLevel(
    effectType: string | undefined,
    effectValue: number | undefined,
    permanentBoosts: Record<string, number>,
): number {
    if (!effectType || effectValue == null || effectValue === 0) return 0;
    let readKey = effectType;
    if (readKey === 'pensionSlot') readKey = 'pensionSlots';
    const boostValue = permanentBoosts[readKey] || 0;
    return Math.round(boostValue / effectValue);
}
