/**
 * @file academyCoursesSystem.ts
 * Paldea Academy Courses mixin.
 */

import type { GameRuntime } from './src/types/game.js';
import {
    canInvestAcademyCourse,
    getAcademyCourseEntry,
    getNextAcademyRankCost,
    investAcademyCourse,
    isAcademyAdvancedHubUnlocked,
    migrateAcademyCoursesFromBadges,
    onAcademySubwayWin,
    onAcademyTypeHuntCompleted,
    onPaldeaGymBadgeWon,
    onPaldeaRegionVisited,
    onPaldeaTypedZoneWin,
    type AcademyCourseId,
} from './src/lib/academyCourses.ts';
import { ACADEMY_COURSES } from './constants/balance/academyCourses.ts';
import { logMessage } from './src/ui/modals.ts';
import { notifyAcademyCoursesChanged } from './src/lib/academyCoursesSnapshot.ts';

type GameCtor = { prototype: Record<string, unknown> };
type ThisGame = GameRuntime;

function academyText(game: GameRuntime, fr: string, en: string): string {
    const lang = game && typeof game.normalizeLanguage === 'function'
        ? game.normalizeLanguage(game.language)
        : 'fr';
    return lang === 'en' ? en : fr;
}

export function applyAcademyCoursesSystem(GameClass: GameCtor): void {
    GameClass.prototype.ensureAcademyCourses = function (this: ThisGame): void {
        migrateAcademyCoursesFromBadges(this);
    };

    GameClass.prototype.isAcademyAdvancedHubUnlocked = function (this: ThisGame): boolean {
        return isAcademyAdvancedHubUnlocked(this);
    };

    GameClass.prototype.openAcademyCoursesModal = function (this: ThisGame): void {
        this.ensureAcademyCourses?.();
        const modal = document.getElementById('academyCoursesModal');
        if (modal) modal.classList.add('show');
        notifyAcademyCoursesChanged(this);
    };

    GameClass.prototype.closeAcademyCoursesModal = function (this: ThisGame): void {
        const modal = document.getElementById('academyCoursesModal');
        if (modal) modal.classList.remove('show');
    };

    GameClass.prototype.investAcademyCourse = function (this: ThisGame, courseId: string): boolean {
        if (!ACADEMY_COURSES[courseId as AcademyCourseId]) return false;
        if (!canInvestAcademyCourse(this, courseId as AcademyCourseId)) {
            logMessage(academyText(
                this,
                'Crédits académiques insuffisants pour ce cours.',
                'Not enough academy credits for this course.',
            ));
            return false;
        }
        const ok = investAcademyCourse(this, courseId as AcademyCourseId);
        if (ok) {
            const def = ACADEMY_COURSES[courseId as AcademyCourseId];
            const entry = getAcademyCourseEntry(this, courseId as AcademyCourseId);
            logMessage(academyText(
                this,
                `Cours ${def.nameKey} — rang ${entry.rank} atteint !`,
                `${def.nameKey} course — rank ${entry.rank} reached!`,
            ));
            if (typeof this.saveGame === 'function') this.saveGame();
            notifyAcademyCoursesChanged(this);
        }
        return ok;
    };

    GameClass.prototype.getAcademyCourseInvestCost = function (this: ThisGame, courseId: string): number | null {
        return getNextAcademyRankCost(this, courseId as AcademyCourseId);
    };
}

export function onPaldeaGymBadgeWonAcademy(game: GameRuntime, badgeKey: string): void {
    onPaldeaGymBadgeWon(game, badgeKey);
    notifyAcademyCoursesChanged(game);
}

export function onPaldeaRegionVisitedAcademy(game: GameRuntime): void {
    onPaldeaRegionVisited(game);
    notifyAcademyCoursesChanged(game);
}

export function trackAcademyPaldeaZoneWin(game: GameRuntime): void {
    const lead = game.currentPlayerCreature ?? game.playerTeam?.[game.activeCreatureIndex ?? 0];
    onPaldeaTypedZoneWin(game, lead?.type);
}

export function trackAcademyTypeHunt(game: GameRuntime, requiredType: string): void {
    onAcademyTypeHuntCompleted(game, requiredType);
    notifyAcademyCoursesChanged(game);
}

export function trackAcademySubwayWin(game: GameRuntime): void {
    onAcademySubwayWin(game);
    notifyAcademyCoursesChanged(game);
}

export function ensureAcademyCoursesOnLoad(game: GameRuntime): void {
    migrateAcademyCoursesFromBadges(game);
}
